RG.HK["09"] = [{"id":"09_nikko_toshogu","n":"日光東照宮（家康を神に祀る霊廟）","yomi":"にっこうとうしょうぐう","cat":"寺社","y":1617,"era":["edo"],"sh":"国宝・国の重要文化財（世界遺産«日光の社寺»）","rank":"S","ad":"日光市山内","st":"JR日光駅・東武日光駅からバスで約10分、«西参道»などで降りて歩いて数分","la":36.7581,"lo":139.5989,"hook":"江戸幕府を開いた徳川家康が、死んだあと «神» になった場所。金と極彩色の建物は、«徳川の世はずっと続く» という大きなメッセージ。","lead":"1616年に亡くなった徳川家康は、遺言によって日光にまつられ «東照大権現» という神になりました。いま見られるきらびやかな社殿の多くは、孫の家光がつくり直させたものです。1999年には «日光の社寺» として世界遺産になりました。","story":["1616年、駿府（いまの静岡市）で徳川家康は75歳の生涯を終えようとしていました。そばにいた僧・金地院崇伝の日記には、家康の遺言が書き残されています。«体は久能山に葬り、一周忌が過ぎたら日光山に小さな堂を建てて、わたしをまつれ。関東八州の守り神になろう。» なぜ日光だったのでしょう? 江戸のほぼ真北にあり、古くから山岳信仰の聖地だった日光は、«北から江戸を守る» のにぴったりの場所だったと考えられています。","翌1617年、家康の棺は久能山から日光へ運ばれ、朝廷から «東照大権現» の神号が贈られました。ところが、この神号をめぐっては家康の側近どうしで激しい議論がありました。天海は «権現» を、崇伝は «明神» を主張。«明神» だった豊臣秀吉が死後すぐに一族をほろぼされたことを天海が指摘し、«権現» に決まったと伝わります。","いまの豪華な社殿の多くは、3代将軍・家光による «寛永の大造替» でつくられました。家光は祖父家康を深く尊敬し、「祖父の宮をもっと立派に」と、全国から腕ききの大工や彫刻師、絵師を集めました。完成は1636年、家康の二十一回忌に合わせたものでした。朝廷から «宮» の号が許され、«東照宮» と呼ばれるようになったのは1645年のことです。","境内を歩くと、動物の彫刻がとても多いことに気づきます。神厩舎（しんきゅうしゃ）の «見ざる・言わざる・聞かざる» の三猿は、じつは8枚の板で猿の一生を描いた物語の一場面。«子どものうちは悪いことを見聞きしないように» という教えだといわれます。奥宮へ続く門の上には、有名な «眠り猫»。その裏側では雀が遊んでいます。«猫が眠るほど平和だから、雀も安心していられる» という意味だと説明されます。","陽明門は、一日中見ていても飽きないことから «日暮の門» とも呼ばれます。500を超える彫刻がびっしりと並び、平成の大修理（2017年に完成）で色あざやかによみがえりました。207段の石段をのぼった奥宮には、家康の墓所とされる宝塔が静かに立っています。華やかな表の顔と、杉木立の中の静けさ。その両方を味わうのが、東照宮の歩き方です。"],"tl":[["1616年","徳川家康が駿府で死去。いったん久能山に葬られる"],["1617年","日光に社殿ができ、家康の神霊が移される。«東照大権現» の神号"],["1636年","家光の «寛永の大造替» で、いまの社殿群がほぼ完成"],["1645年","朝廷から宮号をさずかり «東照宮» に"],["1650年","若狭小浜藩主・酒井忠勝が五重塔を寄進（のち焼失し、1818年に再建）"],["1999年","«日光の社寺» として世界文化遺産に登録"],["2017年","陽明門の平成の大修理が完了"]],"who":[["徳川家康","江戸幕府を開いた初代将軍。ここに «東照大権現» としてまつられる"],["徳川家光","3代将軍。祖父をしたい、社殿を大がかりにつくり直させた"],["天海","家康・秀忠・家光に仕えた天台宗の僧。«権現» の神号を主張したと伝わる"],["金地院崇伝","家康の側近の禅僧。日記『本光国師日記』に家康の遺言を書き残した"]],"deep":["家康の遺言は崇伝の日記『本光国師日記』に記されている。«小さな堂» と言い残したのに、孫の代で日本一ともいえる華やかな霊廟になったのは、幕府の権威を見せる政治的な意味が大きかったと考えられる。","«権現» は «仏が仮の姿で神として現れたもの» という神仏習合の考え方。天海の «山王一実神道» にもとづく。明治の神仏分離で、東照宮・二荒山神社・輪王寺の «二社一寺» に分かれた。","陽明門には、柱の渦巻き模様がわざと上下逆になった «逆柱（さかばしら）» がある。«完成したものは崩れ始める。だから一か所だけ未完成にしておく» という魔除けの考えだと説明される。","«眠り猫» は名工・左甚五郎の作と伝わるが、甚五郎その人の実在や作者であることを確かめる史料ははっきりしない。","本地堂（薬師堂）の天井の «鳴竜» は、竜の頭の下で拍子木を打つと、鈴のような反響が返ってくる。1961年の火災で焼け、日本画家・堅山南風が描き直したものが今の竜である。","上神庫の «想像の象» は、狩野探幽が下絵を描いたといわれる。実物の象を見たことのない絵師が想像で描いたため、耳や尾の形がふしぎな姿になっている。"],"look":["陽明門の彫刻と «逆柱»","神厩舎の三猿（8枚の物語を順番に）","眠り猫と、その裏の雀","奥宮へ続く207段の石段と宝塔","本地堂の鳴竜（拝観は別料金のことがある）","上神庫の «想像の象»"],"q":["«眠り猫» の彫刻の裏側には、何の彫刻がある?","雀です。猫が眠っていて雀も安心して遊べる、平和な世の中を表しているといわれます。"],"koji":[{"w":"見ざる言わざる聞かざる","m":"よくないことは見ない・言わない・聞かないほうがよい、という教え。神厩舎の三猿で知られる"}],"myth":"眠り猫が左甚五郎の作であること、逆柱の意味、«権現» か «明神» かの論争のやりとりの細部は伝承・諸説。","img":["陽明門","徳川家康","天海","日光の社寺"],"wp":"日光東照宮","rel":{"ev":["basho"],"grave":[]},"ph":[["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"],["c:2/22/DaidairiPlan.png",720,960,"陽明門"],["c:e/e9/Archbishop_Tenkai_statue_at_Kitain_temple.jpg",2136,2848,"天海"],["c:3/35/Nikko_toshogu_shrine.jpg",6000,4000,"日光の社寺"]]},{"id":"09_taiyuin","n":"輪王寺 大猷院（家光の霊廟）","yomi":"りんのうじ たいゆういん","cat":"寺社","y":1653,"era":["edo","nara"],"sh":"国宝（大猷院霊廟 本殿・相の間・拝殿）ほか重要文化財（世界遺産«日光の社寺»）","rank":"S","ad":"日光市山内","st":"JR日光駅・東武日光駅からバスで約10分、«西参道»で降りて歩いて約7分","la":36.7594,"lo":139.5946,"hook":"«死んでも祖父・家康のそばに仕えたい»。そう願った3代将軍・家光が眠る、黒と金の霊廟。","lead":"大猷院（たいゆういん）は、江戸幕府3代将軍・徳川家光の霊廟です。東照宮のすぐ近くにあり、祖父をしのがないよう控えめにつくられたといわれますが、黒と金の美しさは見事です。大猷院をまもる輪王寺は、奈良時代に勝道上人が開いたと伝わる日光山の中心のお寺です。","story":["徳川家光は、祖父・家康をまるで神さまのように敬っていました。1651年、48歳で亡くなるとき、«死後も東照大権現（家康）のそばにいて仕えたい» と言い残したと伝わります。その願いをかなえるため、息子の4代将軍・家綱が建てたのが大猷院です。完成は1653年。«大猷院» とは家光の死後の名前（院号）なのです。","石段を上るたびに門が現れます。仁王門、二天門、夜叉門、そして唐門。まるで天へのぼっていくような造りです。二天門は日光山の中でいちばん大きな門といわれ、夜叉門には、4体のこわい顔の夜叉が、東西南北をにらんで霊廟をまもっています。«なぜこんなに門が多いの?» それは、将軍の霊が眠る聖なる場所に近づくほど、一歩ずつ気持ちを清めるためだと説明されます。","本殿・相の間・拝殿はまとめて国宝です。東照宮が白や赤の多い «陽» の華やかさだとすると、大猷院は黒漆と金の «陰» の美しさ。家光が «祖父より目立ってはいけない» と考えたから、という話がよく語られます。そのいっぽうで細部の飾りはたいへん豪華で、«控えめ» とは言い切れないところも見どころです。","大猷院をまもる輪王寺は、766年に勝道上人が大谷川のほとりに建てた «四本龍寺» が始まりと伝わる、日光山で最も古いお寺の系譜です。本堂の三仏堂には、日光の三つの山の神を仏の姿で表した、大きな千手観音・阿弥陀如来・馬頭観音がならびます。江戸時代には皇族が «輪王寺宮» として日光山と上野の寛永寺をあわせて治めました。","その輪王寺宮が、幕末に大きな運命を背負います。戊辰戦争のとき、最後の輪王寺宮・公現法親王は旧幕府側に身を寄せ、東北の諸藩が結んだ奥羽越列藩同盟の «盟主» にかつがれました。のちの北白川宮能久親王です。家光の霊が眠る山のお寺は、幕府の終わりにも深くかかわっていたのです。"],"tl":[["766年","勝道上人が四本龍寺を建てたと伝わる（輪王寺の始まり）"],["1651年","徳川家光が江戸で死去。日光に葬られる"],["1653年","4代将軍・家綱のもとで大猷院霊廟が完成"],["1655年","«輪王寺» の寺号と、皇族が住職となる «輪王寺宮» の制度が始まる"],["1868年","戊辰戦争。輪王寺宮・公現法親王が奥羽越列藩同盟の盟主に"],["1871年","神仏分離により、日光山は二社一寺に分かれる"],["1999年","«日光の社寺» として世界文化遺産に登録"]],"who":[["徳川家光","3代将軍。ここに眠る。祖父家康を深く敬った"],["徳川家綱","4代将軍。父家光のために大猷院を完成させた"],["勝道上人","奈良時代の僧。日光山を開いたと伝わる"],["守澄法親王","後水尾天皇の皇子。最初の輪王寺宮"],["公現法親王（北白川宮能久親王）","最後の輪王寺宮。戊辰戦争で奥羽越列藩同盟の盟主となる"]],"deep":["大猷院の拝殿・本殿は、東照宮の方向を向くように配置されているといわれる。«死後も祖父に仕える» という遺言を建物の向きで表したという説明で、確かな設計記録があるわけではない。","家光の墓所である奥の院（宝塔）は、ふだん非公開。その入口の «皇嘉門» は、中国・明の様式をとり入れた «竜宮造» と呼ばれる白い門で、外から眺めることができる。","三仏堂の三体は、男体山＝千手観音、女峰山＝阿弥陀如来、太郎山＝馬頭観音という «日光三所権現» の本地仏。神と仏を一つにみる考え方を、そのまま形にしている。","三仏堂は明治の神仏分離のあと、二荒山神社のそばから今の場所へ移された。これほど大きな木造のお堂を移築したことは、明治の日光の大事件だった。","輪王寺宮は上野の寛永寺にも住み、«皇族を頂点にすえて、東の宗教界を幕府側でまとめる» 役割があったとみられる。戊辰戦争で旧幕府側にかつがれたのも、その立場の重さゆえだった。"],"look":["夜叉門の4体の夜叉","二天門（日光山最大級の門）","黒と金の拝殿（天井の竜の絵も）","皇嘉門（竜宮造。奥の院の入口）","輪王寺三仏堂の三体の大仏"],"q":["輪王寺三仏堂の3体の仏は、何を表している?","日光の三つの山（男体山・女峰山・太郎山）の神さまを、仏の姿で表したものです。"],"koji":[],"myth":"家光の遺言の言葉、東照宮に遠慮して控えめにした話、建物の向きの意味は伝承・解釈。四本龍寺の創建年も伝承。","img":["徳川家光","日光の社寺","北白川宮能久親王"],"wp":"輪王寺","rel":{"ev":["basho"],"grave":[["iemitsu","徳川家光"]]},"ph":[["c:f/f7/JP-Nikko-Sanbutsu-do.JPG",1600,1063,"輪王寺"],["c:b/b7/Iemitu.jpg",3225,2629,"徳川家光"],["c:3/35/Nikko_toshogu_shrine.jpg",6000,4000,"日光の社寺"],["c:c/c9/Prince_Kitashirakawa_Yoshihisa_wearing_court_uniform.jpg",1220,1688,"北白川宮能久親王"]]},{"id":"09_futarasan_nikko","n":"日光二荒山神社（勝道上人以来の山岳信仰）","yomi":"にっこうふたらさんじんじゃ","cat":"寺社","y":767,"era":["nara","heian","edo"],"sh":"国の重要文化財（本殿・神橋など）（世界遺産«日光の社寺»）","rank":"S","ad":"日光市山内","st":"JR日光駅・東武日光駅からバスで約10分、«西参道»で降りて歩いて約5分","la":36.7598,"lo":139.5967,"hook":"«日光» という地名のみなもとをたどると、この神社の山 «二荒山（ふたらさん）» に行き着く。","lead":"日光二荒山神社は、男体山（なんたいさん）を中心とする日光の山々をまつる神社です。奈良時代に勝道上人が開いたと伝わり、境内は日光の山や滝までふくむ、とても広い神域です。山内の本社、中禅寺湖畔の中宮祠、男体山頂の奥宮の三か所からなります。","story":["奈良時代、下野国に生まれた勝道上人は、雪をかぶって北にそびえる高い山を見上げていました。«あの山の頂に登り、仏の世界を確かめたい。» 上人はまず山への入口に社をまつりました。これが767年、二荒山神社の始まりと伝わります。","山へ向かう道の前には、急流の大谷川が立ちはだかりました。上人が祈ると、深沙大王という神が現れて2匹の大蛇を放ち、その背に山菅が生えて橋になった――。これが、いまも朱色にかがやく «神橋（しんきょう）» の起こりだという伝説です。神橋は二荒山神社の建造物で、国の重要文化財になっています。","男体山への挑戦は、一度ではうまくいきませんでした。深い雪、けわしい岩場。上人は何度も引き返し、ついに782年、頂上に立ったと伝わります。山頂からは奈良・平安時代の鏡や仏具、刀などがたくさん見つかり、上人のあとも多くの修行者がこの山を目指したことがわかっています。","«二荒（ふたら）» という名前にも物語があります。観音さまが住む «補陀洛（ふだらく）山» にちなむという説、男体山の «二つの洞窟から吹く荒い風» からという説など、いくつもの説があります。この «二荒» を音読みにすると «にこう»。そこに «日光» という字を当てたのが、今の地名の始まりだといわれます。弘法大師（空海）が名づけたという話もありますが、伝承です。","江戸時代、東照宮が建てられると、二荒山神社も幕府に大切にされました。本殿は2代将軍・徳川秀忠が1619年に寄進したもので、日光の山内に残る建物ではいちばん古いといわれます。華やかな東照宮のとなりで、杉木立の中にしずかにたたずむ本殿は、1200年以上続く山の信仰を今に伝えています。"],"tl":[["767年","勝道上人が大谷川の北に社をまつったと伝わる（創祀）"],["782年","勝道上人が男体山の頂上に登ったと伝わる"],["1292年","境内の «化灯籠» が奉納される（鎌倉時代）"],["1619年","徳川秀忠の寄進で今の本殿が建つ"],["1902年","大洪水で神橋が流され、1904年に再建"],["1999年","«日光の社寺» として世界文化遺産に登録"]],"who":[["勝道上人","日光山を開いた奈良時代の僧。二荒山神社の始まりにかかわると伝わる"],["徳川秀忠","2代将軍。今の本殿を寄進した"],["深沙大王","大蛇の橋をかけて上人を助けたと伝わる神"],["空海","«日光» と名づけたという伝承がある（伝説）"]],"deep":["まつられている神は、大己貴命（男体山）・田心姫命（女峰山）・味耜高彦根命（太郎山）。夫婦と子の神で、«家族の山» として信仰されてきた。","神社の神域は、日光連山や華厳滝、いろは坂のあたりまで広がるといわれ、面積の広さでは全国でも指折りとされる。","境内の銅製の «化灯籠（ばけどうろう）» は、夜に灯りが怪しくゆらめくので、番をしていた武士が斬りつけたという伝説があり、たくさんの刀傷が残っている。","男体山頂遺跡からは、奈良時代から近世までの祭祀の品が大量に見つかっている。山岳信仰の遺跡として全国でもとくに重要なものとされる。","«下野国一宮» は、日光二荒山神社と宇都宮二荒山神社のどちらなのか、古くから議論がある。延喜式に載る «二荒山神社» がどちらかも諸説ある。","毎年夏の «男体山登拝講社大祭» では、夜中に中宮祠から登り、山頂でご来光を拝む。1200年以上前の上人の道を、今も人々が歩いている。"],"look":["秀忠が寄進した本殿（山内最古の建物といわれる）","刀傷の残る «化灯籠»","神橋（渡るには料金が必要なことがある）","御神木の杉や大国殿","時間があれば中禅寺湖畔の中宮祠も"],"q":["«日光» という地名は、もともと何という名前からきたといわれる?","«二荒（ふたら）»。これを音読みして «にこう» になり、«日光» の字を当てたといわれます。"],"koji":[],"myth":"勝道上人の創祀・男体山登頂の年、神橋の大蛇伝説、«日光» の命名者を空海とする話、化灯籠の話は伝承。«二荒» の由来も諸説。","img":["勝道","男体山","神橋","日光の社寺"],"wp":"日光二荒山神社","rel":{"ev":["basho"],"grave":[["ieyasu","徳川家康"]]},"ph":[["c:e/ed/Nikko_Futarasan_Jinja_M3292.jpg",1250,747,"日光二荒山神社"],["c:2/2f/Japan-_Nikko_Statue_of_Sh%C5%8Dd%C5%8D_Sh%C5%8Dnin_2008.jpg",1200,850,"勝道"],["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"男体山"],["c:a/a2/Shinkyo_Sacred_Bridge_%2811284693104%29.jpg",4573,3049,"神橋"],["c:3/35/Nikko_toshogu_shrine.jpg",6000,4000,"日光の社寺"]]},{"id":"09_ashio_dozan","n":"足尾銅山（通洞坑と精錬所跡）","yomi":"あしおどうざん","cat":"産業","y":1884,"era":["edo","meiji","showa"],"sh":"国指定史跡（足尾銅山跡）","rank":"S","ad":"日光市足尾町通洞","st":"わたらせ渓谷鐵道 通洞駅から歩いて約5分（足尾銅山観光）","la":36.6375,"lo":139.4495,"hook":"日本一の銅山は、日本の近代化を支え、同時に «日本の公害の原点» ともよばれる悲しみを生んだ。","lead":"足尾銅山は、江戸時代に見つかり、明治時代には日本一の銅を産み出した鉱山です。いっぽうで、鉱毒や煙の害が渡良瀬川の流域に大きな被害をもたらしました。いまは坑道をトロッコで見学でき、光と影の両方を学べる場所になっています。","story":["江戸時代のはじめ、1610年ごろ、二人の農民が足尾の山で銅の鉱脈を見つけたと伝わります。銅山は幕府の直轄となり、とれた銅は江戸城や日光東照宮、寛永寺などに使われました。江戸時代の中ごろには足尾で «寛永通宝» という銭もつくられ、裏に «足» の字が入っていたことから «足字銭» とよばれました。","やがて掘りつくされ、江戸の終わりには «もう銅は出ない» といわれるほどさびれました。そこへ1877年、古河市兵衛という商人が乗りこみます。周りは «むだな山を買った» と笑ったかもしれません。けれど数年後、大きな鉱脈が次々と見つかり、最新の機械や電気の技術も導入されて、足尾は日本一の銅山へと大変身しました。","しかし、その裏で大きな問題が起きていました。銅を取り出すときに出る鉱毒が渡良瀬川に流れ、魚が死に、洪水のたびに下流の田畑が荒れました。製錬所の煙は山の木々を枯らし、上流の松木村は住めなくなって、村ごと消えてしまいました。«なぜ国は止めないのか?» 地元出身の国会議員・田中正造は、命がけでこの問題を訴えつづけます。","銅山の中でも、きびしい労働がありました。1907年には、待遇に不満をもった坑夫たちの騒動が大きな暴動に広がり、軍隊が出動する事態になりました。«足尾暴動» とよばれるこの事件は、日本の労働運動の歴史でもよく知られています。","銅山は1973年に閉山しました。いまは通洞坑の一部が «足尾銅山観光» として公開され、トロッコ電車で坑内に入り、江戸から昭和までの採掘のようすを人形で見ることができます。はげ山になった周りの山では、何十年もかけて木を植える活動が続いています。«足尾に緑を» ――その言葉には、失ったものを取り戻そうとする人々の願いがこめられています。"],"tl":[["1610年","足尾で銅の鉱脈が見つかったと伝わる"],["江戸時代中ごろ","足尾で «足» の字入りの寛永通宝（足字銭）がつくられる"],["1877年","古河市兵衛が足尾銅山の経営を始める"],["1880年代","大鉱脈が次々と見つかり、日本一の銅山に"],["1891年","田中正造が帝国議会で鉱毒問題を取り上げる"],["1907年","足尾暴動。軍隊が出動する"],["1973年","足尾銅山が閉山"],["2008年","«足尾銅山跡» が国の史跡に指定される"]],"who":[["古河市兵衛","明治の実業家。足尾銅山を買い取り、日本一の銅山に育てた"],["田中正造","栃木県選出の衆議院議員。鉱毒の被害を国に訴え続けた"],["陸奥宗光","明治の外務大臣。次男の潤吉が古河市兵衛の養子となった"],["治部と内蔵","銅を見つけたと伝わる二人の農民（伝承）"]],"deep":["坑道の長さは合計で約1200kmにおよぶといわれ、«東京から博多までの距離» にたとえられる。","古河市兵衛は、もともと生糸の商売をしていた人物。足尾の成功をもとに «古河財閥» がつくられ、いまの古河電気工業などにつながっている。","明治政府にとって銅は大切な輸出品で、外国から機械や軍艦を買うお金になった。このことが、鉱毒問題の解決が遅れた一因だと考えられている。","1897年、政府は鉱毒を防ぐ工事を命じ、古河は短期間で沈殿池などをつくった。しかし被害はすぐにはなくならなかった。","製錬の煙に含まれる亜硫酸ガスは、1950年代に新しい製錬法が入るまで山を枯らし続けた。はげ山の緑化は、今も続く長い取り組みである。","史跡 «足尾銅山跡» には、通洞坑のほか、本山坑、宇都野火薬庫跡、本山動力所跡、本山製錬所跡などがふくまれる。"],"look":["足尾銅山観光のトロッコ電車と坑内展示","坑内の «江戸時代の手掘り» から «近代の削岩機» までの変化","本山製錬所跡の大煙突（遠くから眺める）","周りの山の植林のようす","足字銭の展示（銭座のコーナー）"],"q":["江戸時代に足尾でつくられたお金は、なぜ «足字銭» とよばれた?","裏に «足» の字が入っていたからです。足尾でつくられた寛永通宝でした。"],"koji":[],"myth":"1610年の発見と二人の農民の名は伝承。坑道の総延長は資料により表現が異なる。","img":["古河市兵衛","足尾鉱毒事件","田中正造","わたらせ渓谷鐵道"],"wp":"足尾銅山","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/Ashio_Copper_Mine_circa_1895.JPG",900,632,"足尾銅山"],["c:0/0c/Ichibei_Furukawa.JPG",318,472,"古河市兵衛"],["c:f/f8/Ashio_Seirenjo.jpg",1280,960,"足尾鉱毒事件"],["c:8/8e/Tanaka_Shozo.jpg",834,1207,"田中正造"],["c:2/28/%E5%A4%A7%E9%96%93%E3%80%85%E9%A7%85_%E9%A7%85%E8%88%8E%282023%E5%B9%B48%E6%9C%88%29.jpg",4032,3024,"わたらせ渓谷鐵道"]]},{"id":"09_ashikaga_gakko","n":"足利学校（日本最古の学校）","yomi":"あしかががっこう","cat":"学び","y":1439,"era":["muromachi","edo"],"sh":"国指定史跡（足利学校跡）","rank":"S","ad":"足利市昌平町","st":"JR足利駅から歩いて約10分／東武足利市駅から歩いて約15分","la":36.3368,"lo":139.4522,"hook":"フランシスコ・ザビエルが «坂東の大学» とヨーロッパに紹介した、日本最古の学校。","lead":"足利学校は «日本でいちばん古い学校» として知られます。いつ始まったかは諸説ありますが、室町時代に関東管領の上杉憲実が本を寄付して立て直し、全国から学生が集まりました。いまは江戸時代の姿に復元され、孔子をまつる建物や書院を見学できます。","story":["足利学校の始まりには、いくつもの説があります。平安時代の小野篁がつくったという説、鎌倉時代に足利義兼が建てたという説などです。はっきりしているのは、室町時代の1439年、関東管領・上杉憲実が、中国・宋の時代に刷られた貴重な本を寄付し、鎌倉から快元という僧をまねいて学校を立て直したことです。","学生たちは僧の姿をしていました。«なぜ僧なの?» それは、学ぶことに集中するため、身分をこえて学べるようにするためだと考えられます。学んだのは儒学、とくに «易（えき）» という占いの学問、そして兵学や医学。戦国時代になると、ここで学んだ人が大名に招かれ、合戦の日取りを占う «軍師» のような役目をつとめることもありました。","1549年、日本に来たフランシスコ・ザビエルは、ヨーロッパへの手紙のなかで、日本には大きな大学があり、なかでも «坂東の大学» がいちばん大きく有名だと書きました。この «坂東の大学» が足利学校のことだと考えられています。«学徒三千» ――学生が3000人いた、という言い方も伝わっています。","江戸時代になると、徳川家康も足利学校を大切にしました。9代目の校長（庠主）である閑室元佶は家康に仕え、本の出版にもかかわりました。1668年には孔子をまつる «大成殿» が建てられ、今も学校の中心に立っています。けれど、近代的な学問が広まるとしだいにさびれ、明治初めの1872年に学校としての役目を終えました。","その後、地元の人々が大切に守り、1921年に国の史跡となりました。1990年には、江戸時代の絵図をもとに方丈や書院、庭園が復元されました。今は子どもたちが «論語» を声に出して読む体験もできます。500年以上前の学生たちと同じ言葉を読むと、ふしぎと時間がつながるような気がします。"],"tl":[["平安〜鎌倉時代","小野篁説・足利義兼説など、創建には諸説"],["1439年","上杉憲実が宋版の書物を寄付し、学校を再興"],["1446年","憲実が学校の決まり（学規）を定める"],["1549年","ザビエルが手紙で «坂東の大学» と紹介"],["1668年","孔子をまつる大成殿（孔子廟）が建てられる"],["1872年","学校としての役目を終える"],["1921年","国の史跡に指定"],["1990年","方丈・書院・庭園などが江戸時代の姿に復元"]],"who":[["上杉憲実","関東管領。書物を寄付して足利学校を再興した"],["快元","憲実にまねかれた最初の庠主（校長）"],["フランシスコ・ザビエル","イエズス会の宣教師。«坂東の大学» と紹介した"],["閑室元佶","9代庠主。徳川家康に仕えた学僧"],["小野篁","平安時代の学者。創建者とする伝説がある"]],"deep":["上杉憲実が寄付した宋版の『礼記正義』『尚書正義』などは国宝に指定され、今も足利学校に伝わる。中国でも失われた版が残っている点で、世界的にも貴重。","憲実が定めた学規では、学ぶのは儒学を中心とし、仏教の経典の講義は学校ではしないという方針だったとされる。","学生は卒業すると、学んだ易の知識で各地の大名に仕えた。戦国大名が占いを重んじたことが、足利学校の «就職先» をつくった。","校内の «宥坐之器（ゆうざのき）» は、水が空だと傾き、ほどよく入るとまっすぐになり、いっぱいになるとひっくり返る器。«ほどほどが大切» という教えを体験できる。","2015年、足利学校は «近世日本の教育遺産群» として、日本遺産の一つに認定された。","ザビエルの «坂東の大学» が足利学校を指すことはほぼ定説だが、ザビエル自身は足利を訪れていない。"],"look":["入徳門・学校門・杏壇門と続く門","大成殿（孔子廟）と孔子像","方丈・書院と庭園","宥坐之器（実際に水を入れて試せる）","論語の素読体験"],"q":["ザビエルは足利学校のことを、ヨーロッパへの手紙で何と紹介した?","«坂東の大学»。日本でいちばん大きく有名な大学として紹介しました。"],"koji":[{"w":"虚なれば則ち傾き、中なれば則ち正しく、満つれば則ち覆る","m":"中国の書『荀子』にある言葉。欲ばりすぎず、ほどよさ（中庸）が大切だという教え。宥坐之器の意味"}],"myth":"創建者（小野篁・足利義兼など）は諸説。«学徒三千» は伝承的な表現で、正確な人数ではない。","img":["上杉憲実","フランシスコ・ザビエル","日本遺産"],"wp":"足利学校","rel":{"ev":[],"grave":[]},"ph":[["c:e/e8/Ashikaga_Ashikaga-School_School_Gate_2.JPG",3160,2394,"足利学校"],["c:7/78/Uesugi_Norizane._1535_CE._Ashikaga_Gakko.jpg",815,768,"上杉憲実"],["c:d/db/Franciscus_de_Xabier.jpg",6589,8402,"フランシスコ・ザビエル"],["c:0/0e/260516_Kadocho_Yuasa_Wakayama_pref_Japan05s3.jpg",3600,3600,"日本遺産"]]},{"id":"09_bannaji","n":"鑁阿寺（足利氏の館跡）","yomi":"ばんなじ","cat":"寺社","y":1196,"era":["kamakura","muromachi"],"sh":"国宝（本堂）・国指定史跡（足利氏宅跡）","rank":"S","ad":"足利市家富町","st":"JR足利駅から歩いて約10分／東武足利市駅から歩いて約15分","la":36.3383,"lo":139.4527,"hook":"堀と土塁にかこまれた四角い境内は、室町幕府を開いた足利氏の «ふるさとの館» そのもの。","lead":"鑁阿寺（ばんなじ）は、足利氏の館の中に建てられたお寺です。周りを囲む堀と土塁は、鎌倉時代の武士の館のかたちをよく残していて、«足利氏宅跡» として国の史跡になっています。本堂は2013年に国宝になりました。","story":["平安時代の終わり、源氏の一族である源義康が下野国の足利の地に住み、«足利» を名乗りました。その子・足利義兼は、源頼朝の挙兵にいち早く加わり、頼朝の妻・北条政子の妹を妻にむかえます。義兼は鎌倉幕府のなかでも重く見られる御家人になりました。","1196年、義兼は自分の館の中に持仏堂をつくり、大日如来をまつったと伝わります。これが鑁阿寺の始まりです。義兼はのちに出家して «鑁阿（ばんな）» と名のりました。寺の名前はこの法名から来ています。«鑁» は大日如来をあらわす梵字の音だといわれます。","境内に入ると、ほぼ四角い形で、周りを水堀と土塁がぐるりと囲んでいるのがわかります。«お寺なのに、なぜ堀があるの?» ――それはここがもともと武士の館だったからです。館を寺に変えて守ったおかげで、鎌倉武士の住まいのかたちが、800年以上たった今もはっきり残りました。","足利氏はその後も代々この寺を大切にし、およそ140年後、義兼の子孫である足利尊氏が室町幕府を開きます。将軍家になっても、足利の地は «ご先祖の地» でした。本堂は1299年に建て直されたもので、鎌倉時代の終わりの建築様式を伝え、2013年に国宝に指定されました。","戦国時代が終わると、同じく源氏の流れを名のった徳川家も鑁阿寺を保護しました。境内には、義兼が植えたと伝わる大イチョウがそびえ、秋には黄金色に染まります。足利学校もすぐ近く。二つを歩けば、学問と武士の町だった足利の姿が見えてきます。"],"tl":[["1180年","足利義兼が源頼朝の挙兵に加わる"],["1196年","義兼が館内に持仏堂を建てたと伝わる（鑁阿寺の始まり）"],["1199年","足利義兼が死去"],["1299年","本堂が再建される（今の本堂）"],["1338年","子孫の足利尊氏が征夷大将軍となる"],["1922年","«足利氏宅跡» として国の史跡に指定"],["2013年","本堂が国宝に指定"]],"who":[["足利義兼","足利氏2代目。館内に持仏堂を建て、出家して鑁阿と名のった"],["源頼朝","鎌倉幕府を開いた。義兼は頼朝に従った"],["北条時子","北条政子の妹。義兼の妻"],["足利尊氏","室町幕府の初代将軍。義兼の子孫"]],"deep":["«鑁阿寺» の «鑁（ばん）» は大日如来を表す梵字の読みといわれ、義兼の法名 «鑁阿» がそのまま寺の名になった。","境内は東西・南北とも200mほどの方形で、四方に門を開き、堀と土塁で囲む。中世武士の «方形館» の代表例として教科書的な遺構とされる。","本堂は和様に禅宗様を取り入れた折衷様式の仏堂。鎌倉時代後期に関東で禅宗様がどう広まったかを示す重要な建物とされる。","鐘楼や経堂も国の重要文化財。経堂は室町時代の建物とされ、一切経をおさめる八角の輪蔵がある。","義兼の墓所と伝わる樺崎寺跡（足利市）も国の史跡。義兼がそこで生きたまま入定したという伝説がある。","鑁阿寺は «日本100名城» にも選ばれている。お寺なのに城として選ばれたのは、館の堀と土塁が中世の城の原型だからである。"],"look":["境内を囲む堀と土塁（ぐるりと一周してみよう）","国宝の本堂","楼門（山門）と太鼓橋","義兼手植えと伝わる大イチョウ","近くの足利学校とセットで"],"q":["鑁阿寺の周りに堀と土塁があるのはなぜ?","もともと足利氏の館（武士の家）だったからです。館の中にお堂を建て、寺として守られてきました。"],"koji":[],"myth":"持仏堂の建立年（1196年）、大イチョウを義兼が植えた話、樺崎寺での入定伝説は伝承。","img":["足利義兼","足利氏","足利尊氏","足利学校"],"wp":"鑁阿寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/8e/%E9%91%81%E9%98%BF%E5%AF%BA_%E8%B6%B3%E5%88%A9_-_panoramio_%283%29.jpg",4912,3264,"鑁阿寺"],["c:3/3f/Ashikaga_Yoshikane_Banna-ji.jpg",1735,2412,"足利義兼"],["c:8/83/Ashikaga_Takauji_J%C5%8Ddo-ji.jpg",1770,1770,"足利尊氏"],["c:e/e8/Ashikaga_Ashikaga-School_School_Gate_2.JPG",3160,2394,"足利学校"]]},{"id":"09_kokubunji","n":"下野国分寺跡・国分尼寺跡","yomi":"しもつけこくぶんじあと・こくぶんにじあと","cat":"遺跡","y":741,"era":["nara","heian"],"sh":"国指定史跡","rank":"S","ad":"下野市国分寺","st":"JR小金井駅から車で約10分（しもつけ風土記の丘資料館が目じるし）","la":36.4065,"lo":139.843,"hook":"聖武天皇の «国ごとに寺を» という大号令。その下野版の大伽藍が、野原の中に礎石だけを残している。","lead":"741年、聖武天皇は全国に国分寺と国分尼寺を建てるよう命じました。下野国分寺跡と国分尼寺跡は、その下野国（いまの栃木県）のお寺の跡です。建物は残っていませんが、礎石や基壇が整備され、公園として歩くことができます。","story":["奈良時代、日本では病気のはやりやききん、反乱が続いていました。«仏の力で国を守ろう。» そう考えた聖武天皇は741年、国ごとに僧のための国分寺と、尼のための国分尼寺をつくるよう命じます。都には、その中心として東大寺が建てられました。","下野国でも、国の役所である国府から遠くない、見晴らしのよい台地が選ばれました。大きな金堂や講堂、そして七重塔。«なぜ塔はそんなに高かったの?» ――遠くからでもよく見える塔は、天皇の力と仏の教えがここまで届いていることを人々に示す «しるし» だったのです。","国分寺には20人の僧、国分尼寺には10人の尼がいて、国の平和を祈るお経を読むよう定められていました。正式な名前は、国分寺が «金光明四天王護国之寺»、尼寺が «法華滅罪之寺»。長い名前には «国を守る» «罪をほろぼす» という願いがこめられています。","平安時代の後半になると、国の仕組みがゆるみ、国分寺もしだいにおとろえていきました。建物は失われ、跡は畑や林になりました。しかし地中には、建物の土台や、屋根に使われたたくさんの瓦が残っていました。発掘調査によって、伽藍の配置や塔の位置がわかってきたのです。","今、僧寺跡と尼寺跡は «天平の丘公園» 一帯の史跡として整備されています。春には桜が咲き、家族連れが散歩する野原の下に、1200年以上前の大寺院が眠っていると思うと、少しふしぎな気持ちになります。近くには大きな古墳や資料館もあり、下野の古代をまとめて感じられます。"],"tl":[["741年","聖武天皇が国分寺・国分尼寺の建立を命じる"],["8世紀中ごろ","下野国分寺・国分尼寺の伽藍が整えられていく"],["平安時代後期","国の仕組みのゆるみとともに衰える"],["大正〜昭和","国分寺跡・国分尼寺跡が国の史跡に指定される"],["昭和後期〜","発掘調査が進み、公園として整備される"]],"who":[["聖武天皇","国分寺・国分尼寺の建立を命じた天皇"],["光明皇后","聖武天皇の皇后。国分尼寺の建立に深くかかわったとされる"],["下野の国司","国分寺の造営を進めた、国の役人たち"]],"deep":["国分寺の建立の詔は『続日本紀』に記される。国ごとに七重塔を建て、金字の金光明最勝王経をおさめるよう命じた。","下野国分寺の伽藍は、塔が回廊の外に建つ、東大寺と似た配置だったと考えられている。","国分尼寺跡は僧寺跡の東、数百mのところにあり、僧寺と尼寺がセットで見られる数少ない場所の一つ。","下野国府の跡は栃木市にあり、国分寺からそう遠くない。国府・国分寺・下野薬師寺が近くに集まる、このあたりは古代下野の «中心地» だった。","周辺には琵琶塚古墳や摩利支天塚古墳など、大型の古墳もあり、古墳時代から奈良時代へと続くこの土地の重要さがわかる。","しもつけ風土記の丘資料館には、国分寺跡から出た瓦などが展示されている。"],"look":["金堂・講堂・塔の基壇跡","七重塔が立っていた場所","国分尼寺跡の礎石","しもつけ風土記の丘資料館の出土品","周辺の古墳（琵琶塚古墳・摩利支天塚古墳）"],"q":["国分寺の正式な名前は?","«金光明四天王護国之寺» です。国を守ることを願うお寺でした。"],"koji":[],"myth":"伽藍の細かな配置や建物の規模は、発掘の進み具合で考えが変わることがある。","img":["国分寺","聖武天皇","摩利支天塚古墳"],"wp":"下野国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/04/Shimotsuke-kokubunji_hondou.JPG",3648,2736,"下野国分寺"],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"],["c:8/8c/Marishitenzuka_Kofun%2C_funkyu.jpg",5568,3712,"摩利支天塚古墳"]]},{"id":"09_yakushiji","n":"下野薬師寺跡（天下三戒壇・道鏡左遷の地）","yomi":"しもつけやくしじあと","cat":"寺社","y":761,"era":["asuka","nara"],"sh":"国指定史跡","rank":"S","ad":"下野市薬師寺","st":"JR自治医大駅から車で約5〜10分（下野薬師寺歴史館が目じるし）","la":36.42,"lo":139.869,"hook":"東日本の僧になりたい人は、みんなここを目指した。そして女帝に愛された僧・道鏡が、最後に流された寺でもある。","lead":"下野薬師寺は、奈良時代に東日本でいちばん大切だったお寺の一つです。761年に «戒壇» がおかれ、奈良の東大寺、九州の観世音寺と並ぶ «天下三戒壇» となりました。権力の頂点にいた僧・道鏡が送られた場所としても知られます。","story":["下野薬師寺は、7世紀の終わりごろに建てられたと考えられています。建てたのは、この地方の有力な一族・下毛野氏で、大宝律令づくりにかかわった下毛野古麻呂の名前もあがりますが、はっきりしたことは諸説あります。やがて国が運営する大寺院となりました。","奈良時代、正式な僧になるには «戒壇» で戒律を授かる必要がありました。中国から苦労して来日した鑑真が、そのしくみを伝えたのです。761年、東大寺・筑紫の観世音寺と並び、下野薬師寺にも戒壇がおかれました。«天下三戒壇»。東国で僧を目指す人々は、はるばるこの寺にやってきたのです。","770年、ひとりの僧がこの寺に着きました。道鏡です。道鏡は称徳天皇（女性の天皇）に深く信頼され、太政大臣禅師・法王にまでのぼりつめた人物でした。«道鏡を天皇に» という神のお告げが問題になったこともあります。しかし称徳天皇が亡くなると、道鏡は «下野薬師寺別当» として、都から遠い下野へ送られました。","«都の頂点から、東の果てへ。» 道鏡はこの地で2年後の772年に亡くなり、庶民として葬られたと記録にあります。近くの龍興寺には «道鏡塚» と伝わる塚が残っています。欲ばりな悪僧として語られることが多い道鏡ですが、実際の人柄については、今も研究者の意見が分かれています。","平安時代になり、比叡山に独自の戒壇ができると、下野薬師寺の役目はしだいに小さくなり、寺はおとろえました。いま跡地は史跡公園として整備され、回廊の一部が復元されています。歴史館では、かつての大伽藍の模型を見ることができます。"],"tl":[["7世紀後半","下野薬師寺が建てられたと考えられる（創建者・年代は諸説）"],["754年","鑑真が来日し、戒律を伝える"],["761年","下野薬師寺に戒壇がおかれ «天下三戒壇» の一つに"],["769年","宇佐八幡の神託をめぐる事件（道鏡事件）"],["770年","称徳天皇の死後、道鏡が下野薬師寺別当に"],["772年","道鏡がこの地で死去"],["平安時代","比叡山の戒壇設立などで、しだいに衰える"]],"who":[["道鏡","称徳天皇に重んじられた僧。下野薬師寺に送られ、この地で亡くなった"],["称徳天皇","奈良時代の女性天皇。道鏡を法王にした"],["鑑真","唐から来日した僧。戒壇のしくみを伝えた"],["下毛野古麻呂","下野の有力者。創建にかかわったとする説がある"],["和気清麻呂","宇佐八幡の神託を確かめ、道鏡の即位を阻んだ"]],"deep":["戒律を授けるには本来10人の僧（三師七証）が必要だが、地方では5人（三師二証）でもよいとされたといわれる。","«天下三戒壇» は、東大寺（中央）、観世音寺（西国）、下野薬師寺（東国）。国家が僧になる資格を厳しく管理していたことがわかる。","道鏡の死は『続日本紀』に記録されている。«庶人として葬った» という記述から、罪人扱いというより身分を落とされた形だったと読める。","寺の跡には、室町時代に足利尊氏らが国ごとに建てた «安国寺» の一つが入っており、今も安国寺として続いている。","822年に比叡山延暦寺が独自の大乗戒壇の設立を認められると、国の三戒壇の重みは相対的に下がっていった。","発掘調査で回廊の範囲や大きな建物の跡が確認され、東日本でも最大級の古代寺院だったことがわかっている。"],"look":["復元された回廊の一部","下野薬師寺歴史館の伽藍模型","安国寺の六角堂（戒壇院のなごりと伝わる）","近くの龍興寺の «道鏡塚»"],"q":["«天下三戒壇» とは、どこの寺?","奈良の東大寺、筑紫（福岡）の観世音寺、そして下野薬師寺です。"],"koji":[],"myth":"創建者を下毛野古麻呂とする説、道鏡塚、六角堂を戒壇のなごりとする話は諸説・伝承。道鏡の人物像も評価が分かれる。","img":["道鏡","鑑真","称徳天皇","戒壇"],"wp":"下野薬師寺","rel":{"ev":[],"grave":[]},"ph":[["j:2/2c/%E4%B8%8B%E9%87%8E%E8%96%AC%E5%B8%AB%E5%AF%BA_%E5%BE%A9%E5%85%83%E5%9B%9E%E5%BB%8A.JPG",3648,2736,"下野薬師寺"],["c:0/07/D%C5%8Dky%C5%8D.jpg",500,500,"道鏡"],["c:c/ce/Ganjin_wajyo_portrait.JPG",470,610,"鑑真"],["c:1/17/Empress_K%C5%8Dken_01.jpg",713,1026,"称徳天皇"],["c:7/79/Toshodaiji_Temple_Kaidan.JPG",5129,3419,"戒壇"]]},{"id":"09_nasu_kokuzo_hi","n":"那須国造碑（日本三古碑・笠石神社）","yomi":"なすのくにのみやつこのひ","cat":"遺跡","y":700,"era":["asuka","edo"],"sh":"国宝","rank":"S","ad":"大田原市湯津上（笠石神社）","st":"車が便利（JR西那須野駅から車で約30分）","la":36.7225,"lo":140.156,"hook":"1300年以上前に刻まれた152文字。そこには中国・唐の年号と、ひとりの地方豪族の生涯が記されていた。","lead":"那須国造碑は、700年ごろに建てられた石碑で、日本で最も古い石碑の一つとして国宝になっています。群馬の多胡碑、宮城の多賀城碑とあわせて «日本三古碑» とよばれます。江戸時代に水戸藩主・徳川光圀が保護したことでも有名です。","story":["江戸時代の1676年、那須の湯津上村で、草に埋もれた古い石碑が見つかりました。旅の僧が見つけたといわれ、地元の名主・大金重貞がそれを書き留めます。やがて話は、水戸藩の2代藩主・徳川光圀の耳に届きました。«これは古代の貴重な碑にちがいない。»","碑に刻まれていたのは、8行×19字、あわせて152文字の漢文でした。«永昌元年»、那須国造だった那須直韋提（なすのあたいいで）が «評督» という役職をさずかり、«庚子の年» に亡くなったので、あとを継いだ意斯麻呂らが碑を建てた――という内容です。庚子の年は700年と考えられています。","ふしぎなのは «永昌» という年号です。これは日本の年号ではなく、中国・唐の則天武后の時代の年号（689年）でした。«なぜ日本の地方の石碑に、唐の年号が?» ――この地域には朝鮮半島の新羅から来た人々が住んだ記録があり、渡来人が碑づくりにかかわったのではないか、という説があります。","光圀は家臣の佐々宗淳（すけさぶろう）を送って調べさせ、1692年、碑を守るお堂を建てました。これが今の笠石神社です。«碑に書かれた韋提の墓はどこだ?» 光圀は近くの侍塚古墳まで発掘させましたが、墓の主を示すものは見つかりませんでした。","碑は今も笠石神社の御神体として、社殿の中で大切にまつられています。石の上に笠のような石がのっていることから «笠石» の名がつきました。1952年に国宝に指定。何気ない田園の中の小さな神社に、日本の古代史の大切な1ページが眠っているのです。"],"tl":[["689年","那須直韋提が «評督» をさずかる（碑文の永昌元年）"],["700年","韋提が亡くなる（碑文の庚子年）。その後、碑が建てられる"],["1676年","湯津上村で碑が見つかる"],["1687年","徳川光圀の命で佐々宗淳が調査"],["1692年","光圀が碑堂を建てる（笠石神社）。侍塚古墳も発掘"],["1952年","国宝に指定"]],"who":[["那須直韋提","那須国造・評督。碑に記された人物"],["意斯麻呂","碑を建てたとされる、韋提の後継者"],["徳川光圀","水戸藩2代藩主。碑を保護し、お堂を建てた"],["佐々宗淳","光圀の家臣。碑と侍塚古墳を調べた"],["大金重貞","地元の名主。碑の発見を記録し光圀に伝えた"]],"deep":["碑文の «評督» は、大宝律令（701年）で «郡» ができる前の «評（こおり）» の長官。«評» の時代の実在を示す貴重な文字資料である。","碑の書体は中国・六朝の書風を感じさせ、書道史の面でも高く評価されている。","日本三古碑は、那須国造碑（700年ごろ）、多胡碑（711年）、多賀城碑（762年）。ただし多賀城碑は江戸時代に «偽物では» と疑われたこともあった（今は本物とする説が有力）。","『日本書紀』には、687年ごろ新羅から来た人々を下毛野に住まわせたという記事があり、碑に唐の年号が使われた背景として注目されている。","碑そのものは社殿内にあり、見学には神社への申し込みが必要とされる。訪れる前に最新の見学方法を確かめたい。"],"look":["笠石神社の社殿（碑を納める）","碑の上にのる «笠石»","近くの上侍塚古墳・下侍塚古墳","那珂川沿いの風景"],"q":["那須国造碑に刻まれた «永昌» とは、どこの国の年号?","中国・唐の年号です（則天武后の時代）。"],"koji":[],"myth":"発見者の僧の名や経緯の細部、渡来人が碑をつくったという説は諸説。","img":["多胡碑","多賀城碑","徳川光圀","上侍塚古墳"],"wp":"那須国造碑","rel":{"ev":[],"grave":[]},"ph":[["c:3/34/Nasunokuninomiyatsukonohi-2.jpg",865,1298,"那須国造碑"],["c:0/0a/Monument_of_Tago_%28Tagohi%29.jpg",1845,2460,"多胡碑"],["c:1/18/Tagajo-hi.JPG",3892,5946,"多賀城碑"],["c:e/e8/Kamisamuraizuka_Kofun%2C_funkyu-2.jpg",5568,3712,"上侍塚古墳"]]},{"id":"09_kamisamurai","n":"上侍塚古墳（徳川光圀が発掘した古墳）","yomi":"かみさむらいづかこふん","cat":"遺跡","y":400,"era":["kofun","edo"],"sh":"国指定史跡（侍塚古墳）","rank":"S","ad":"大田原市湯津上","st":"車が便利（JR西那須野駅から車で約30分）","la":36.73,"lo":140.1565,"hook":"水戸黄門こと徳川光圀が «日本で初めての学術的な発掘» を命じたといわれる古墳。掘ったあと、ていねいに元に戻した。","lead":"上侍塚古墳は、那珂川のほとりにある大きな前方後方墳です。江戸時代、徳川光圀が那須国造碑の主の墓をさがすために発掘させ、出土品を記録して埋め戻しました。墳丘に植えられた松が、今も古墳をおおっています。","story":["1692年、那須の湯津上村に、水戸藩の役人たちがやってきました。命じたのは藩主の徳川光圀。«那須国造碑に書かれた韋提の墓が、近くの大きな塚ではないか。確かめよ。» こうして、地元の名主・大金重貞が中心となって、二つの大きな塚の発掘が始まりました。","掘ってみると、鏡や鉄の武器、玉などが出てきました。けれど、韋提の名前を示すものは見つかりません。そこで光圀が命じたことが、今でも高く評価されています。«出てきた品は絵に描いて記録し、松の板の箱に入れて元に戻せ。塚はくずれないよう整え、松を植えよ。»","«なぜ持ち帰らなかったの?» ――光圀は、古いものを勝手に持ち去らず、その場所ごと残すことを大切にしたと考えられます。発掘→記録→保存という流れは、今の考古学にも通じるものです。このため、侍塚古墳の発掘は «日本で最初の学術的な発掘» といわれることがあります。","上侍塚古墳は、前が四角く後ろも四角い «前方後方墳» で、長さは約114m。栃木県内でも最大級の前方後方墳です。つくられたのは古墳時代の前期、4世紀後半から5世紀のはじめごろと考えられており、那須国造碑の韋提よりもずっと前の時代の人の墓だったことになります。","光圀が植えさせた松の子孫が、今も墳丘をおおい、古墳は美しい姿をとどめています。近くには兄弟のような下侍塚古墳もあります。300年以上前、«わからないことは、わからないまま大切に残す» という判断をした光圀の姿勢は、今の私たちにも問いかけてくるものがあります。"],"tl":[["4世紀後半〜5世紀初めごろ","上侍塚古墳がつくられる（推定）"],["1676年","近くで那須国造碑が見つかる"],["1692年","徳川光圀の命で侍塚古墳を発掘。出土品を記録して埋め戻し、松を植える"],["1951年","上・下侍塚古墳が国の史跡に指定"],["令和","大田原市などによる新しい調査が行われる"]],"who":[["徳川光圀","水戸藩2代藩主。発掘を命じ、保存の方法まで指示した"],["大金重貞","地元の名主。発掘の現場を担当した"],["佐々宗淳","光圀の家臣。調査にかかわった"],["被葬者（不明）","那須地方を治めた古墳時代の有力者と考えられる"]],"deep":["光圀の発掘は、出土品の図を残し、松の板の箱に納めて埋め戻すという方法をとった。この図や記録が今も伝わり、当時の出土状況を知る手がかりになっている。","«日本初の学術的発掘» という評価は広く語られているが、何をもって «学術的» とするかには議論もある。","前方後方墳は、前方後円墳にくらべて東日本に多い形。那須地方には、ほかにも前方後方墳が集まっており、この地域の特徴になっている。","光圀の目的は那須国造碑の主の墓をさがすことだったが、古墳の年代は碑よりずっと古く、結果として «墓の主はわからない» という結論になった。","墳丘の松は、発掘のあとに土がくずれないよう植えられたもの。古墳を守る «緑の鎧» の役目を果たしてきた。"],"look":["墳丘の形（前も後ろも四角い前方後方墳）","墳丘をおおう松林","下侍塚古墳との見くらべ","近くの那須国造碑（笠石神社）","なす風土記の丘湯津上資料館"],"q":["光圀は、侍塚古墳から出た品をどうした?","絵に描いて記録し、松の板の箱に入れて元に戻しました。そして塚に松を植えて守りました。"],"koji":[],"myth":"古墳の年代は研究により幅がある。«日本初の学術的発掘» は評価のひとつ。","img":["徳川光圀","那須国造碑","下侍塚古墳","前方後方墳"],"wp":"上侍塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:e/e8/Kamisamuraizuka_Kofun%2C_funkyu-2.jpg",5568,3712,"上侍塚古墳"],["c:3/34/Nasunokuninomiyatsukonohi-2.jpg",865,1298,"那須国造碑"],["c:d/dc/Shimosamuraizuka_Kofun%2C_funkyu-3.jpg",5562,3702,"下侍塚古墳"],["c:0/0b/Shimosamuraizuka_Kofun_2.jpg",4608,3456,"前方後方墳"]]},{"id":"09_utsunomiya_jo","n":"宇都宮城（釣天井伝説と戊辰戦争）","yomi":"うつのみやじょう","cat":"城","y":1622,"era":["heian","edo","meiji"],"sh":"","rank":"S","ad":"宇都宮市本丸町（宇都宮城址公園）","st":"JR宇都宮駅から歩いて約20分／東武宇都宮駅から歩いて約10分","la":36.555,"lo":139.883,"hook":"«将軍を天井でつぶそうとした»――そんな物騒なうわさで有名になった城。でも、その話は後の世の «つくり話» だった。","lead":"宇都宮城は、平安時代の終わりから宇都宮氏の本拠地だった城です。江戸時代には将軍が日光へお参りするときの宿泊の城となり、«釣天井» の伝説で知られるようになりました。戊辰戦争で激しい戦いの舞台となり、今は櫓と土塁が復元された公園になっています。","story":["宇都宮城の歴史は、平安時代の後半、藤原宗円がこの地に来て館をかまえたのが始まりと伝わります。その子孫が «宇都宮氏» を名乗り、約500年もこの地を治めました。しかし1597年、豊臣秀吉によって宇都宮氏はとつぜん領地を取り上げられてしまいます。","江戸時代の1619年、城主になったのは本多正純。家康の側近として力をふるった人物です。正純は城を大きく改修し、町もつくり直しました。宇都宮は、将軍が日光東照宮へお参りする «日光社参» の途中で泊まる、とても大切な城だったのです。","1622年、2代将軍・秀忠が日光からの帰りに宇都宮城に泊まる予定でした。ところが秀忠は急に予定を変え、宇都宮に寄らずに江戸へ帰ります。その後まもなく、正純は領地を取り上げられました。«なぜ?» ――このできごとから、«正純は天井を落として将軍を殺そうとしていた» という «宇都宮釣天井» の物語が生まれました。けれどこれは江戸時代の講談などでつくられた話で、実際に釣天井があった証拠はありません。","時代は下って1868年、戊辰戦争。旧幕府軍を率いた大鳥圭介や土方歳三が宇都宮城を攻め、城は落ちました。数日後、新政府軍が取り返しますが、この戦いで城の建物の多くが焼け、土方も足にけがを負ったといわれます。町の人々も戦火に苦しみました。","明治以降、城の跡は市街地の中に消えていきました。けれど市民の «城を少しでも取り戻したい» という願いから、2007年、清明台櫓と富士見櫓、土塁の一部が復元され、宇都宮城址公園として生まれ変わりました。高い土塁の上に立つと、昔の城の大きさが少しだけ想像できます。"],"tl":[["11世紀後半","藤原宗円がこの地に館をかまえたと伝わる"],["1597年","宇都宮国綱が秀吉により改易される"],["1619年","本多正純が城主となり、城と城下町を大改修"],["1622年","正純が改易される（«宇都宮釣天井» の伝説のもと）"],["1868年","戊辰戦争・宇都宮城の戦い。城の多くが焼ける"],["2007年","清明台櫓・富士見櫓・土塁が復元され、城址公園に"]],"who":[["藤原宗円","宇都宮氏の祖と伝わる人物"],["宇都宮国綱","宇都宮氏22代。秀吉に改易された"],["本多正純","城を大改修した城主。釣天井伝説の主人公にされた"],["徳川秀忠","2代将軍。日光社参の帰りに宇都宮を避けたとされる"],["土方歳三","新選組副長。戊辰戦争で宇都宮城を攻めた"],["大鳥圭介","旧幕府軍の指揮官"]],"deep":["正純の改易の本当の理由は、はっきりしない。幕府内の権力争い、秀忠の側近との対立、城の無断改修の疑いなど、いくつもの説がある。","正純改易の知らせは、正純が山形の最上氏の城受け取りの役目で出かけていたときに届いたといわれる。","«釣天井» の話は、講談や歌舞伎で大人気となり、宇都宮の名を広めた。町では今も話のネタとして親しまれている。","宇都宮城は、日光社参の将軍が泊まる «御成（おなり）の城» だったため、江戸時代を通じて譜代大名が城主をつとめた。","復元された土塁は高さ10m前後もあり、その上に櫓が立つ。石垣ではなく土で守る、関東の城らしいつくりである。"],"look":["復元された清明台櫓と富士見櫓","土塁の上から見る市街地","城址公園内の展示（城の模型など）","近くの宇都宮二荒山神社"],"q":["«宇都宮釣天井» の話は本当にあったこと?","いいえ。江戸時代の講談などでつくられた話で、実際に釣天井があった証拠はありません。"],"koji":[],"myth":"宇都宮釣天井は創作（講談・歌舞伎）。宗円の来住の時期、正純改易の理由は諸説。","img":["本多正純","宇都宮釣天井","宇都宮城の戦い","土方歳三"],"wp":"宇都宮城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b6/Utsunomiya-jo_fujimi-yagura.jpg",2896,1936,"宇都宮城"],["c:3/35/UtsunomiyaCastle.jpg",1051,1087,"宇都宮城の戦い"],["c:e/ee/Hijikata_Toshizo.jpg",528,924,"土方歳三"]]},{"id":"09_oyama_hyogi","n":"小山評定跡（関ヶ原への分かれ道）","yomi":"おやまひょうじょうあと","cat":"事件","y":1600,"era":["azuchi","edo"],"sh":"","rank":"S","ad":"小山市中央町（小山市役所付近）","st":"JR小山駅西口から歩いて約5〜10分","la":36.314,"lo":139.801,"hook":"«石田三成、挙兵!» その知らせを受けて、武将たちは «家康につくか、大坂に戻るか» を決めた――天下分け目の会議の地。","lead":"1600年、徳川家康は上杉景勝を討つため会津へ向かう途中、ここ小山で石田三成が兵をあげたと知りました。家康は従っていた武将たちを集めて話し合い、軍を西へ向けることを決めたといわれます。これが «小山評定» で、2か月後の関ヶ原の戦いへとつながりました。","story":["1600年の夏、徳川家康は大軍を率いて江戸から北へ進んでいました。目指すは会津の上杉景勝。«上杉が戦の準備をしている» ことを口実にした討伐でした。ところが下野国の小山まで来たとき、大坂から急な知らせが届きます。«石田三成が兵をあげた。»","家康に従っていた武将の多くは、豊臣秀吉に取り立てられた大名たちでした。しかも彼らの妻や子どもは、大坂にいたのです。«三成の側につくか、家康につくか。» 家康は7月25日、武将たちを集めて評定（会議）を開いたといわれます。","最初に声をあげたのは福島正則でした。«三成を討つべし。わたしは家康どのにお味方する!» 秀吉の親戚でもある正則のこの一言で、場の空気が決まったといわれます。じつは前もって、黒田長政が正則を説得していたとも伝わります。","つづいて山内一豊が申し出ました。«わたしの掛川城を、家康どのにお明け渡しいたします。» 東海道にある城を差し出すことで、家康軍は西へ安心して進めます。ほかの大名も次々と城を差し出し、この申し出はのちに一豊の大きな手柄として語られました。一豊が土佐一国をもらったのも、このときの判断が評価されたためだといわれます。","軍は西へ向かい、家康自身はいったん江戸に戻って各地の大名に手紙を書き続けました。そして9月15日、関ヶ原。小山での決断が、日本の歴史を大きく動かしたのです。ただし近年は、«こうした会議が本当に開かれたのか» を疑う研究者もいて、議論が続いています。今、小山市役所の近くに «小山評定跡» の碑が立っています。"],"tl":[["1600年6月","家康が上杉討伐のため大坂を出発"],["1600年7月","石田三成らが挙兵"],["1600年7月25日","小山で評定が開かれたといわれる"],["1600年8月","家康が江戸へ戻る"],["1600年9月15日","関ヶ原の戦い。東軍が勝利"],["1603年","家康が征夷大将軍となる"]],"who":[["徳川家康","東軍の総大将。小山で軍を西へ向ける決断をした"],["福島正則","評定で真っ先に家康に味方すると言ったと伝わる"],["山内一豊","掛川城を差し出すと申し出たと伝わる"],["黒田長政","事前に福島正則を説得したと伝わる"],["石田三成","西軍の中心。挙兵の知らせが小山に届いた"],["上杉景勝","会津の大名。討伐の目標だった"]],"deep":["小山評定のようすは、主に江戸時代にまとめられた軍記や家の記録から知られる。同時代の一次史料で会議そのものを確かめるのは難しく、«評定はなかった» «もっと小さな話し合いだった» などの説がある。","山内一豊の «掛川城を差し出す» 案は、もともと堀尾忠氏の考えだったのを一豊が先に言った、という話も伝わる（逸話で、確かではない）。","家康は評定のあとすぐ西へは向かわず、約1か月江戸にとどまった。この間に大名たちの本心を見きわめ、手紙で味方を増やしていたと考えられる。","小山は古くから小山氏の本拠で、城（祇園城）もあった。江戸時代には将軍の日光社参のための休憩所 «小山御殿» も置かれた。","評定のあった場所をめぐる伝承の一つとして、家康が戦勝を祈ったという須賀神社がある。"],"look":["小山評定跡の碑（小山市役所付近）","須賀神社","祇園城跡（城山公園）","思川の流れ"],"q":["小山評定で «掛川城を差し出す» と言ったと伝わる武将は?","山内一豊です。のちに土佐一国の大名になりました。"],"koji":[{"w":"天下分け目","m":"天下を取るか失うかが決まる、大事な分かれ目。関ヶ原の戦いを指してよく使われる"}],"myth":"評定の実在・日付・発言の順番は諸説。黒田長政の事前説得、一豊と堀尾忠氏の逸話は伝承。","img":["関ヶ原の戦い","福島正則","山内一豊","祇園城"],"wp":"小山評定","rel":{"ev":["k_nikko","k_oshu"],"grave":[]},"ph":[["c:9/9f/Sekigaharascreen.jpg",3816,1796,"小山評定"],["c:2/22/Masanori_Fukushima.JPG",517,658,"福島正則"],["c:5/5f/Yamauchi-Kazutoyo.jpg",1833,4000,"山内一豊"],["c:5/5b/Oyama-jo.4.jpg",3072,2304,"祇園城"]]},{"id":"09_sugi_namiki","n":"日光杉並木（松平正綱の寄進）","yomi":"にっこうすぎなみき","cat":"街道","y":1625,"era":["edo"],"sh":"国指定特別史跡・特別天然記念物","rank":"S","ad":"日光市・鹿沼市（日光街道・例幣使街道・会津西街道）","st":"JR今市駅・東武下今市駅の周辺から並木を歩ける区間がある","la":36.728,"lo":139.67,"hook":"«灯籠を寄進するお金がない。ならば杉を植えよう。» ひとりの家臣が約20年かけて植えた木が、世界一長い並木道になった。","lead":"日光杉並木は、日光へ続く三つの街道に沿って、合計約37kmも続く杉の並木道です。徳川家康の家臣だった松平正綱が、東照宮への寄進として植えたものです。国の特別史跡と特別天然記念物の両方に指定されている、日本でただ一つの場所です。","story":["家康が日光にまつられると、多くの大名が東照宮に立派な石灯籠などを寄進しました。家康に長く仕えた松平正綱も、何か捧げものをしたいと考えます。けれど正綱は、大きな大名ほど豊かではありませんでした。そこで考えたのが、«日光への道に杉を植える» ことだったと伝わります。","1625年ごろから、正綱は約20年をかけて、日光街道・例幣使街道・会津西街道に杉の苗を植えていきました。植えた杉は20万本ともいわれます。«夏はすずしい木かげに、冬は風よけに。» 杉並木は、東照宮へ向かう人々のための «道の屋根» になりました。","1648年、家康の三十三回忌に、正綱の子・正信が杉並木を寄進したことを記す石碑を、並木の起点など4か所に建てました。碑には、ほかの大名たちの寄進にくらべてささやかな、しかし心のこもった贈りものであることがうかがえます。«お金ではなく、時間と手間をささげる。» 正綱の寄進は、そんな気持ちの表れだったのかもしれません。","戊辰戦争のとき、この杉並木のそばでも戦いがありました。今市の近くには、そのときの砲弾が当たった跡が残る «砲弾打込杉» があります。静かな木立ちは、歴史の大きな事件も見守ってきたのです。","今、杉は約1万2千本。排気ガスや道路の工事などで少しずつ弱り、数が減っています。栃木県は «杉並木オーナー制度» などで保護を進めています。世界最長の並木道としてギネス世界記録にも認定された杉並木。400年前にひとりの家臣が植えた木を、次の400年へつなぐのは、今を生きる私たちです。"],"tl":[["1617年","家康が日光にまつられる"],["1625年ごろ","松平正綱が杉の植樹を始める"],["1648年","家康三十三回忌に、並木寄進碑が建てられる"],["1868年","戊辰戦争。並木の近くでも戦いがあり、砲弾の跡が残る"],["1952年","国の特別史跡に指定"],["1954年","国の特別天然記念物に指定"],["1992年","世界最長の並木道としてギネスブックに認定"]],"who":[["松平正綱","家康・秀忠・家光に仕えた家臣。杉並木を植えた"],["松平正信","正綱の子。寄進碑を建てた"],["徳川家康","東照宮にまつられる。杉並木はその参道"],["例幣使","朝廷から毎年東照宮へ幣を届けた使い。例幣使街道の名のもと"]],"deep":["«特別史跡» と «特別天然記念物» の二重指定は、日光杉並木だけである。","並木寄進碑は、日光市内の神橋のそばなど、三つの街道の起点に建てられた。","正綱は幕府の財政を担当する勘定頭などをつとめた実務派の家臣。華やかな寄進ではなく、長い年月をかける杉の植樹を選んだところに人柄がうかがえる。","例幣使は1646年から、毎年朝廷から日光東照宮へ遣わされた。京都の公家が通る道として例幣使街道が整えられた。","杉並木オーナー制度は、1本1000万円で杉のオーナーとなり、その資金を保護に充てるしくみ。企業や個人が参加している。","近年は、道路沿いの杉の根が車の振動や舗装で傷む問題があり、並木の外側にバイパスを通すなどの対策がとられている。"],"look":["今市周辺の杉並木公園","並木寄進碑","砲弾打込杉","旧街道を歩ける区間（車の少ない道）"],"q":["日光杉並木が指定されている、日本でここだけの «二重指定» とは?","国の特別史跡と特別天然記念物の両方です。"],"koji":[],"myth":"«お金がないので杉を植えた» という動機は伝承。植えた本数も伝承的な数。","img":["松平正綱","日光街道","例幣使街道","日光東照宮"],"wp":"日光杉並木","rel":{"ev":[],"grave":[]},"ph":[["c:8/8f/%E6%97%A5%E5%85%89%E6%9D%89%E4%B8%A6%E6%9C%A8%E8%A1%97%E9%81%93_20130522_-_panoramio.jpg",2736,1824,"日光杉並木"],["c:1/10/Nikko_kaido_hasui_kawase.jpg",910,1384,"日光街道"],["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"]]},{"id":"09_tanaka_shozo","n":"田中正造旧宅と墓（佐野）","yomi":"たなかしょうぞうきゅうたく","cat":"近代","y":1901,"era":["meiji"],"sh":"","rank":"S","ad":"佐野市小中町（旧宅）／佐野市金井上町・惣宗寺（墓）","st":"車が便利（佐野駅から車で約15分）。惣宗寺（佐野厄除け大師）は佐野駅から歩いて約10分","la":36.356,"lo":139.565,"hook":"«真の文明は、山を荒らさず、川を荒らさず、村を破らず、人を殺さざるべし。» 鉱毒と闘い続けた男の家と墓。","lead":"田中正造は、足尾銅山の鉱毒で苦しむ人々のために、一生をかけて闘った政治家です。佐野市の小中町には、正造が生まれ育った家が残されています。亡くなったあと、遺骨は流域の各地に分けて葬られ、佐野の惣宗寺にもお墓があります。","story":["1841年、田中正造は下野国小中村（いまの佐野市）の名主の家に生まれました。若いころから正義感が強く、領主の不正を訴えて牢に入れられたこともあります。明治になると政治の道に進み、1890年の第1回衆議院議員選挙で当選しました。","そのころ、渡良瀬川の下流では異変が起きていました。魚が浮き、田畑の作物が育たない。原因は上流の足尾銅山から流れ出る鉱毒でした。1891年、正造は国会でこの問題を取り上げます。«なぜ政府は銅山を止めないのか。人の命より銅が大事なのか。»","しかし政府の対応は進みません。1900年、被害民が東京へ向かって陳情に出たところ、警官隊とぶつかる «川俣事件» が起きました。そして1901年12月10日、正造は議員を辞めたうえで、帝国議会の開院式から帰る明治天皇に直訴しようとします。取り押さえられて直訴はかないませんでしたが、この事件は新聞で大きく報じられ、全国の人が鉱毒問題を知ることになりました。","その後、正造は廃村にされようとしていた谷中村に移り住み、村に残った人々と最後までともに暮らしました。1913年、正造は支援者の家で倒れ、71歳で亡くなります。残された信玄袋の中には、日記と聖書、憲法の本、そして河原で拾った小石が入っていたといいます。","正造の遺骨は、ゆかりのある流域の各地に分けて葬られました。佐野の惣宗寺（佐野厄除け大師）もその一つです。生家は «田中正造旧宅» として保存され、正造が暮らした時代の農家のようすを伝えています。«人を殺さざるべし»――100年以上前の言葉は、環境と人間の関係を考える今も、まっすぐに響きます。"],"tl":[["1841年","下野国小中村に生まれる"],["1890年","第1回衆議院議員選挙で当選"],["1891年","帝国議会で足尾銅山の鉱毒問題を質問"],["1900年","川俣事件"],["1901年12月10日","明治天皇への直訴を試みる"],["1904年","谷中村に移り住む"],["1913年","死去。遺骨は流域の各地に分骨される"]],"who":[["田中正造","鉱毒問題と闘った政治家・活動家。ここで生まれ育った"],["幸徳秋水","直訴状の文案を書いた思想家"],["古河市兵衛","足尾銅山の経営者"],["明治天皇","正造が直訴しようとした相手"]],"deep":["直訴状の文案は幸徳秋水が書き、正造が手を入れたとされる。直訴は «不敬» として重い罪になりうる行為だったが、正造は «狂人» として扱われ、罪には問われなかった。","«真の文明は山を荒らさず…» の言葉は、晩年の日記に記されたもの。今も環境問題を語るときによく引用される。","正造の遺骨は、惣宗寺のほか、雲龍寺（群馬県館林市）など、渡良瀬川流域のゆかりの地に分けて葬られた。","正造は名主の家の出身で、若いころに領主の六角家の不正を訴えて投獄された。«権力に対して声をあげる» 姿勢は若いころから一貫していた。","正造の亡くなった地は渡良瀬川のほとりの支援者の家で、最後まで流域の人々とともにあった。"],"look":["田中正造旧宅（公開日を確認して）","惣宗寺（佐野厄除け大師）の墓所","佐野市郷土博物館の田中正造の展示","渡良瀬川の流れ"],"q":["田中正造が亡くなったとき、信玄袋に入っていた石は何を表していた?","河原で拾った小石です。何を意味したかは本人は語っていませんが、川と村を守ろうとした心の象徴として語られます。"],"koji":[{"w":"真の文明は山を荒らさず、川を荒らさず、村を破らず、人を殺さざるべし","m":"田中正造の日記の言葉。自然と人の命を大切にすることこそ本当の文明だ、という意味"}],"myth":"分骨先の数や場所は資料で数え方が異なる。直訴状の起草の分担も諸説。","img":["足尾鉱毒事件","足尾銅山","幸徳秋水","谷中村"],"wp":"田中正造","rel":{"ev":[],"grave":[]},"ph":[["c:8/8e/Tanaka_Shozo.jpg",834,1207,"田中正造"],["c:f/f8/Ashio_Seirenjo.jpg",1280,960,"足尾鉱毒事件"],["c:b/b5/Ashio_Copper_Mine_circa_1895.JPG",900,632,"足尾銅山"],["c:a/a5/Modern-History-of-Women-20.png",518,711,"幸徳秋水"],["c:7/76/Watarase_Retarding_Basin_Former_Yanaka_village_entrance.jpg",5472,3648,"谷中村"]]},{"id":"09_yanaka","n":"谷中村跡（渡良瀬遊水地に沈んだ村）","yomi":"やなかむらあと","cat":"事件","y":1906,"era":["meiji"],"sh":"","rank":"S","ad":"栃木市藤岡町内野（渡良瀬遊水地の中）","st":"東武日光線 藤岡駅から車で約10分（遊水地は広いので歩きやすい靴で）","la":36.224,"lo":139.663,"hook":"ヨシ原の中に、墓石と神社の跡だけが残る。かつてここには、田畑と家々の並ぶ村があった。","lead":"谷中村は、足尾銅山の鉱毒問題と洪水対策のため、明治時代に «遊水地» にするとして廃村にされた村です。村に残った人々の家は強制的に取り壊されました。今は渡良瀬遊水地の中に、共同墓地や神社の跡などが «谷中村史跡» として残されています。","story":["谷中村は、渡良瀬川・思川・巴波川が集まる低い土地にありました。川の恵みで豊かな村でしたが、明治になると足尾銅山の鉱毒を含んだ水が、洪水のたびに村の田畑をおおうようになります。","政府が考えたのは、この低い土地を «遊水地» にして、洪水の水と鉱毒をためるという方法でした。«なぜ銅山を止めるのではなく、村をなくすのか?» 田中正造はそう問い、1904年、谷中村に移り住んで、村の人々とともに反対を続けました。","しかし1906年、谷中村は廃村とされ、隣の町に合併されました。多くの人が村を離れましたが、どうしても土地を捨てられない家々が残りました。1907年、土地収用法によって、残っていた十数戸の家が次々と取り壊されます。家を失った人々は、仮小屋を建てて村に住み続けました。","«村を捨てない» と言い続けた残留民の中には、若い島田宗三もいました。のちに彼は谷中村の記録を書き残し、何が起きたのかを後の世に伝えました。正造は1913年に亡くなりますが、残留民が村を離れたのは、それから数年後のことでした。","今、谷中村の跡は渡良瀬遊水地の中にあります。広いヨシ原の中に、村の共同墓地や、雷電神社・延命院の跡が残り、史跡として守られています。遊水地は2012年にラムサール条約にも登録され、多くの鳥や植物が生きる場所になりました。美しい自然の中に、ふるさとを失った人々の歴史があることを、心にとめて歩きたい場所です。"],"tl":[["1889年","周辺の村が合併して谷中村ができる"],["1890年代","洪水のたびに鉱毒の被害が広がる"],["1904年","田中正造が谷中村に移り住む"],["1906年","谷中村が廃村となり、藤岡町に合併"],["1907年","土地収用法により、残留民の家が強制的に取り壊される"],["1913年","田中正造が死去"],["2012年","渡良瀬遊水地がラムサール条約湿地に登録"]],"who":[["田中正造","谷中村に移り住み、残留民とともに闘った"],["島田宗三","谷中村の残留民。のちに村の記録を書き残した"],["谷中村の残留民","家を壊されても村に残り続けた人々"]],"deep":["渡良瀬遊水地は、関東平野の洪水を防ぐための日本最大級の遊水地。谷中村の廃村は、その整備の出発点となった。","廃村の目的について、政府は洪水対策を強調したが、正造らは «鉱毒問題を、村をなくすことでごまかすものだ» と批判した。","遊水地の中には、人工の湖 «谷中湖» があり、上から見るとハート形に見えることで知られる。","谷中村の跡は «史跡保全ゾーン» として残され、共同墓地には村の人々の墓石が今も並んでいる。","島田宗三の記録『谷中村事件』などは、残留民の側から見た歴史を伝える貴重な資料となっている。","遊水地の中の史跡は、ふだん自由に歩ける場所が多いが、増水時や工事中は立ち入りが制限されることがある。訪れる前に遊水地の案内情報を確かめたい。"],"look":["谷中村の共同墓地跡","雷電神社跡・延命院跡","遊水地のヨシ原と野鳥"],"q":["谷中村の跡がある渡良瀬遊水地は、2012年にどんな国際的な登録をされた?","ラムサール条約湿地です。水鳥などが生きる大切な湿地として登録されました。"],"koji":[],"myth":"残留民の戸数や人数は資料によって数え方が違う。","img":["渡良瀬遊水地","田中正造","足尾鉱毒事件"],"wp":"谷中村","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/Watarase_Retarding_Basin_Former_Yanaka_village_entrance.jpg",5472,3648,"谷中村"],["c:0/05/Watarase-Yusuichi.jpg",5103,3402,"渡良瀬遊水地"],["c:8/8e/Tanaka_Shozo.jpg",834,1207,"田中正造"],["c:f/f8/Ashio_Seirenjo.jpg",1280,960,"足尾鉱毒事件"]]},{"id":"09_oyaji","n":"大谷寺（大谷磨崖仏）","yomi":"おおやじ","cat":"寺社","y":810,"era":["jomon","heian"],"sh":"国指定特別史跡・国の重要文化財（大谷磨崖仏）","rank":"S","ad":"宇都宮市大谷町","st":"JR宇都宮駅からバスで約30分、«大谷観音前»で降りてすぐ","la":36.6045,"lo":139.8265,"hook":"岩のくぼみの奥に、1000年以上前に彫られた千手観音。ここは縄文人が暮らした洞窟でもあった。","lead":"大谷寺は、やわらかい大谷石の岩壁に彫られた «大谷磨崖仏» で知られるお寺です。本尊の千手観音は平安時代の作と考えられ、«日本最古の石仏» といわれることもあります。洞窟からは縄文時代の人の骨も見つかっています。","story":["宇都宮の西、大谷の里には、白っぽい岩山がにょきにょきと立ち並びます。この岩が «大谷石»。火山灰が固まってできた、やわらかく加工しやすい石です。その岩壁の大きなくぼみに、大谷寺の本堂が抱かれるように建っています。","本堂の奥、岩壁そのものに彫られているのが本尊の千手観音です。«大谷観音» とよばれ、坂東三十三観音の第19番札所として、昔から多くの巡礼者がお参りしてきました。ほかにも釈迦三尊、薬師三尊、阿弥陀三尊が彫られ、あわせて10体の磨崖仏が並びます。","«誰が彫ったの?» ――お寺では、弘法大師（空海）が彫ったと伝えています。昔この地の池に毒蛇がすみ、人々を苦しめていたのを大師が退治したという伝説もあります。実際には、仏像の様式などから平安時代につくられたと考えられており、作者はわかっていません。","もともとこの磨崖仏は、石を彫っただけでなく、表面に粘土を塗って形を整え、色をつけて仕上げられていました。今はその多くがはがれ、石のはだが見えていますが、よく見ると赤や金色のあとがかすかに残っています。1000年以上前、極彩色の仏さまが洞窟の中にならんでいた光景を想像してみてください。","さらに驚くのは、この洞窟が縄文時代の人々の住まいでもあったことです。発掘調査で縄文時代の人骨や土器が見つかり、«大谷寺洞穴遺跡» として知られています。人が雨風をしのいだ岩かげは、やがて祈りの場所へと変わっていきました。近くには戦没者の供養のために彫られた大きな «平和観音» もそびえています。"],"tl":[["縄文時代","洞窟に人々が暮らす（大谷寺洞穴遺跡）"],["810年","弘法大師が千手観音を彫ったとお寺では伝える"],["平安時代","磨崖仏がつくられたと考えられる"],["鎌倉〜室町時代","坂東三十三観音の札所として巡礼者が訪れる"],["昭和時代","大谷磨崖仏が国の特別史跡・重要文化財に指定される"],["戦後（昭和）","近くの岩山に平和観音が彫られる"]],"who":[["空海（弘法大師）","千手観音を彫ったとお寺に伝わる（伝承）"],["坂東札所の巡礼者","中世から観音さまを目指して歩いた人々"],["縄文の人々","洞窟に暮らし、骨や土器を残した"]],"deep":["大谷磨崖仏は、国の «特別史跡» と «重要文化財» の二重指定。石仏がこのように両方に指定されるのはめずらしい。","磨崖仏の表面は、石彫りの上に粘土（塑土）を盛って仕上げ、漆や彩色をほどこしたと考えられている。その手法には、中国・アフガニスタンの石窟寺院との共通性を指摘する声もある。","千手観音は «日本最古の石仏» といわれることがあるが、年代には諸説あり、ほかにも古いとされる石仏がある。","大谷石は江戸時代から本格的に掘られるようになり、明治以降は建築材として全国に広まった。フランク・ロイド・ライトの旧帝国ホテル（ライト館）にも使われた。","平和観音は高さ約27m。昭和の戦争で亡くなった人々の供養と世界平和を願って、地元の人々が岩山を彫ってつくった。"],"look":["本堂奥の千手観音（撮影禁止に注意）","釈迦三尊・薬師三尊・阿弥陀三尊","宝物館の縄文人骨や土器の展示","平和観音と周りの大谷石の岩山","近くの大谷資料館（地下の採掘場跡）"],"q":["大谷磨崖仏が彫られている石の名前は?","大谷石です。火山灰が固まってできた、やわらかい石です。"],"koji":[],"myth":"空海作・810年の開基・毒蛇退治は寺の伝承。磨崖仏の年代は諸説。","img":["大谷石","坂東三十三観音","旧帝国ホテル"],"wp":"大谷寺 (宇都宮市)","rel":{"ev":[],"grave":[]},"ph":[["c:9/92/Oya-ji_%28Utsunomiya%29_kan-non-dou-2.jpg",5530,3654,"大谷寺 (宇都宮市)"],["c:1/16/Ooyaishi.jpg",640,480,"大谷石"],["c:7/7f/Imperial_Hotel_Tokyo.JPG",2206,2500,"旧帝国ホテル"]]},{"id":"09_shimosamurai","n":"下侍塚古墳","yomi":"しもさむらいづかこふん","cat":"遺跡","y":400,"era":["kofun","edo"],"sh":"国指定史跡（侍塚古墳）","rank":"A","ad":"大田原市湯津上","st":"車が便利（JR西那須野駅から車で約30分）","la":36.7195,"lo":140.158,"hook":"«日本一美しい古墳» とよばれる、松におおわれた前方後方墳。美しさの理由は、300年前の «保存の決断» にある。","lead":"下侍塚古墳は、那珂川のほとりにある全長約84mの前方後方墳です。江戸時代に徳川光圀が発掘させ、記録したあと元に戻して松を植えました。松林におおわれた整った姿から、«日本一美しい古墳» ともよばれます。","story":["春、下侍塚古墳を訪れると、緑の松におおわれた墳丘が、田んぼの中にくっきりと浮かんで見えます。前も後ろも四角い «前方後方墳»。長さ約84m、4世紀から5世紀ごろにこの地の有力者のために築かれたと考えられています。","1692年、水戸藩主の徳川光圀は、近くで見つかった那須国造碑の主の墓をさがすため、北にある上侍塚古墳とあわせて、この古墳も発掘させました。鏡や鉄の武器、土器などが出てきましたが、碑に書かれた人物の名は見つかりません。","«見つからなかったから、それで終わり?» ――光圀の指示は違いました。出土した品を絵に描いて記録し、松の板で作った箱に入れて、元の場所に埋め戻したのです。そして墳丘がくずれないよう形を整え、松を植えさせました。","このとき植えられた松が育ち、古墳を雨や風から守ってきました。«日本一美しい古墳» という呼び名は、つくられた当時の姿に加え、江戸時代の保存の努力によって生まれたものともいえます。古墳を «こわさずに残す» ことを大切にした光圀の考え方は、300年以上たった今も高く評価されています。","近年も、大田原市などによって新しい調査が行われ、古墳のまわりの溝や、墳丘の形がより正確にわかってきました。上侍塚古墳や那須国造碑とあわせて歩けば、古墳時代から飛鳥時代、そして江戸時代へと、この土地に積み重なった歴史の層を感じることができます。"],"tl":[["4〜5世紀ごろ","下侍塚古墳がつくられる（推定）"],["1692年","徳川光圀の命で発掘。出土品を記録して埋め戻し、松を植える"],["1951年","上・下侍塚古墳が国の史跡に指定"],["令和","新しい発掘調査などが行われる"]],"who":[["徳川光圀","発掘を命じ、保存の方法を指示した水戸藩主"],["大金重貞","地元の名主。発掘の現場を担当した"],["被葬者（不明）","古墳時代の那須地方の有力者と考えられる"]],"deep":["下侍塚古墳は上侍塚古墳（約114m）より小さいが、形が整い、松林とあいまって «美しい古墳» として知られるようになった。","光圀の発掘記録には出土品の図が添えられ、当時どんなものが出たのかを今も知ることができる。","上・下侍塚古墳のまわりには、ほかにも小さな古墳が点在しており、この一帯が古墳時代の那須の中心の一つだったことを示している。","前方後方墳は東日本に多く、とくに那須地方には大型のものが集中している。ヤマト政権との関係を考える手がかりになる。","«日本一美しい古墳» は、地元や案内などで使われる呼び名で、公式な順位ではない。","古墳の上には、松の根や墳丘を守るため登れない（立ち入りが制限される）場合がある。案内に従って見学したい。"],"look":["松におおわれた墳丘の全景（少し離れて見るのがおすすめ）","前方部と後方部の形","近くの上侍塚古墳","那須国造碑（笠石神社）"],"q":["下侍塚古墳の墳丘に松が生えているのはなぜ?","江戸時代に徳川光圀が発掘したあと、墳丘を守るために松を植えさせたからです。"],"koji":[],"myth":"«日本一美しい古墳» は通称。築造年代は研究により幅がある。","img":["上侍塚古墳","徳川光圀","那須国造碑","前方後方墳"],"wp":"下侍塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Shimosamuraizuka_Kofun%2C_funkyu-3.jpg",5562,3702,"下侍塚古墳"],["c:e/e8/Kamisamuraizuka_Kofun%2C_funkyu-2.jpg",5568,3712,"上侍塚古墳"],["c:3/34/Nasunokuninomiyatsukonohi-2.jpg",865,1298,"那須国造碑"],["c:0/0b/Shimosamuraizuka_Kofun_2.jpg",4608,3456,"前方後方墳"]]},{"id":"09_futarayama_utsunomiya","n":"宇都宮二荒山神社（下野国一之宮）","yomi":"うつのみやふたあらやまじんじゃ","cat":"寺社","y":838,"era":["heian","kamakura","edo"],"sh":"","rank":"A","ad":"宇都宮市馬場通り1丁目","st":"JR宇都宮駅から歩いて約20分／東武宇都宮駅から歩いて約10分","la":36.5625,"lo":139.884,"hook":"«宇都宮» という町の名前は、この神社から生まれたといわれる。百人一首の誕生にも、ここの一族がかかわっていた。","lead":"宇都宮二荒山神社は、宇都宮の町の真ん中の丘にある、下野国の一之宮とされる神社です。まつられているのは豊城入彦命。この神社の神職をつとめた一族が «宇都宮氏» を名のり、町の名前も神社にちなむといわれます。","story":["宇都宮の中心街に、石段が高く続く丘があります。その上に立つのが宇都宮二荒山神社です。まつられている豊城入彦命は、崇神天皇の皇子で、東国を治めたと『日本書紀』に語られる人物。古代の東国と都をつなぐ神として、あがめられてきました。","神社はもともと近くの別の山にあり、平安時代の838年に今の場所へ移ったと伝わります。«宇都宮» という地名は、下野国の «一の宮» がなまったという説や、«移しの宮» からという説など、いくつもの説があります。どの説でも、町の名前がこの神社と深く結びついていることは変わりません。","平安時代の終わり、藤原宗円がこの神社の神職となり、その子孫が «宇都宮氏» を名のりました。宇都宮氏は神社を守る一族であり、同時に武士として下野を治める大名でもありました。«神に仕える武士» ――それが宇都宮氏の姿でした。","その宇都宮氏の一人、宇都宮頼綱は、歌を愛した武士でもありました。頼綱は京都・嵯峨の山荘のふすまに貼る色紙を、歌人の藤原定家に書いてもらったといわれます。このとき定家が選んだ歌が、のちの «小倉百人一首» のもとになったという説があります。宇都宮には «宇都宮歌壇» とよばれる歌の世界も生まれました。","神社は戊辰戦争のときに戦火で焼け、今の社殿は明治時代に建て直されたものです。毎年秋の «菊水祭» では、古式ゆかしい行列が町をねり歩きます。ビルの立ち並ぶ中心街で石段を上ると、町の歴史が1000年以上前から続いていることを実感できます。"],"tl":[["古代","豊城入彦命をまつる神社が始まったと伝わる"],["838年","今の場所に移ったと伝わる"],["平安時代後期","藤原宗円が神職となり、のちに宇都宮氏が生まれる"],["鎌倉時代","宇都宮頼綱が藤原定家に色紙を頼む（百人一首のもとになったという説）"],["1868年","戊辰戦争で社殿が焼ける"],["明治時代","社殿が再建される"]],"who":[["豊城入彦命","まつられている神。崇神天皇の皇子とされる"],["藤原宗円","宇都宮氏の祖と伝わる人物"],["宇都宮頼綱","鎌倉時代の武将・歌人。百人一首の成立にかかわったとされる"],["藤原定家","鎌倉時代の歌人。頼綱の頼みで色紙を書いたとされる"]],"deep":["延喜式に載る «二荒山神社» が、宇都宮と日光のどちらを指すのかには諸説がある。下野国一之宮もどちらとするか、昔から議論がある。","宇都宮頼綱（出家して蓮生）の娘は、藤原定家の子・為家の妻となった。この縁が、百人一首の成立の背景の一つと考えられている。","«宇都宮» の語源は «一の宮» «移しの宮» «うつろの宮» など諸説あり、定説はない。","宇都宮氏は神社の社務職（神職）と武家の当主をかねた。この二重の立場が、関東で長く勢力を保てた理由の一つといわれる。","境内の手水舎には «神水» とよばれる湧き水があり、地元で親しまれている。"],"look":["大通りから続く長い石段","本殿と拝殿（明治の再建）","境内から見る宇都宮の町なみ","秋の菊水祭の行列"],"q":["宇都宮頼綱が藤原定家に頼んだ色紙が、何のもとになったといわれる?","«小倉百人一首» のもとになったという説があります。"],"koji":[],"myth":"838年の遷座、«宇都宮» の語源、百人一首の成立と頼綱の関係は伝承・諸説。一之宮論争も諸説。","img":["豊城入彦命","宇都宮氏","小倉百人一首","藤原定家"],"wp":"宇都宮二荒山神社","rel":{"ev":[],"grave":[]},"ph":[["j:e/e4/%E5%AE%87%E9%83%BD%E5%AE%AE%E4%BA%8C%E8%8D%92%E5%B1%B1%E7%A5%9E%E7%A4%BE_%E6%8B%9D%E6%AE%BF.JPG",3648,2736,"宇都宮二荒山神社"],["c:c/c8/Mitsudomoe_1.png",4000,4000,"宇都宮氏"],["c:0/04/Hyakuninisshu_001.jpg",328,458,"小倉百人一首"],["c:2/2d/Teika%283%29.jpg",832,848,"藤原定家"]]},{"id":"09_karasawayama","n":"唐沢山城（藤原秀郷伝説の山城）","yomi":"からさわやまじょう","cat":"城","y":1560,"era":["heian","muromachi","azuchi"],"sh":"国指定史跡","rank":"A","ad":"佐野市富士町（唐沢山神社）","st":"車が便利（佐野駅から車で約20分、山頂近くに駐車場）","la":36.3808,"lo":139.6046,"hook":"上杉謙信が何度攻めても落ちなかったといわれる «関東一の山城»。石垣の上からは東京のビル群まで見わたせる。","lead":"唐沢山城は、佐野市の唐沢山の山頂にあった戦国時代の山城です。平将門を討った藤原秀郷が築いたという伝説があり、戦国時代には佐野氏の城として、上杉謙信や北条氏と激しく争いました。関東では珍しい高い石垣が残り、国の史跡になっています。","story":["唐沢山の城には、古い伝説があります。平安時代の940年、平将門の乱をしずめた藤原秀郷（俵藤太）が、この山に城を築いたというのです。秀郷は大ムカデ退治の伝説でも知られる英雄。のちの佐野氏は秀郷の子孫を名のり、この山を本拠地としました。","戦国時代、関東では越後の上杉謙信と、小田原の北条氏がはげしく争っていました。そのはざまにあった佐野氏は、ときに上杉に、ときに北条について生き残りをはかります。謙信は何度も唐沢山城を攻めましたが、城はなかなか落ちませんでした。«謙信が10回攻めても落ちなかった» という話も伝わっています。","城が強かった理由の一つは、その地形です。けわしい山の上に曲輪（くるわ）が並び、敵は細い道を登ってくるしかありません。さらに山の上には «大炊の井» という大きな井戸があり、水に困ることがなかったといわれます。«山城の弱点は水。» その弱点がない城だったのです。","戦国時代の終わり、佐野氏は豊臣・徳川の世に生き残ります。しかし江戸時代のはじめ、城主の佐野信吉は山を下りて、平地に新しい佐野城を築きました。«山の上から江戸の火事が見えたことを家康に知られ、江戸を見下ろすとは無礼だと言われた» という話がありますが、これは伝承です。唐沢山城はこうして使われなくなりました。","明治時代、本丸の跡には藤原秀郷をまつる唐沢山神社が建てられました。今も残る高い石垣は、関東の山城としては珍しいものです。天気のよい日には、関東平野のかなたに東京の高層ビルまで見えます。戦国武将たちも、この景色を見ながら «次はどこが攻めてくるか» と見張っていたのでしょう。"],"tl":[["940年","藤原秀郷が平将門を討つ。のち唐沢山に城を築いたと伝わる"],["1560年代","上杉謙信がたびたび唐沢山城を攻める"],["1590年","豊臣秀吉の小田原攻め。佐野氏は豊臣方として生き残る"],["1602年ごろ","佐野信吉が平地の佐野城へ移り、唐沢山城は廃城に"],["1883年","本丸跡に唐沢山神社が創建される"],["2014年","国の史跡に指定"]],"who":[["藤原秀郷","平将門を討った英雄。城を築いたと伝わる"],["佐野昌綱","戦国時代の城主。上杉謙信の攻撃に耐えた"],["上杉謙信","越後の戦国大名。唐沢山城をたびたび攻めた"],["佐野信吉","江戸時代初めの城主。平地の佐野城へ移った"]],"deep":["藤原秀郷が築城したという話は伝承で、実際に城が大きく整えられたのは戦国時代と考えられている。","本丸まわりの高石垣は、関東の戦国期の山城ではめずらしく、豊臣政権の時代以降に整えられた可能性が指摘されている。","«大炊の井» は直径も深さも大きな井戸で、今も水をたたえている。籠城に耐えられた理由の一つとして紹介される。","«謙信が10回攻めた» という回数は伝承的な表現で、実際の攻撃の回数やようすは史料によって異なる。","唐沢山城は «続日本100名城» にも選ばれている。","山頂近くには «天狗岩» という見晴らしのよい岩があり、関東平野を一望できる。"],"look":["本丸まわりの高石垣","大炊の井（大きな井戸）","天狗岩からの眺め（晴れた日は東京まで）","唐沢山神社"],"q":["唐沢山城が籠城に強かった理由として、山の上にあった何があげられる?","«大炊の井» という大きな井戸です。山城の弱点である水に困らなかったといわれます。"],"koji":[],"myth":"秀郷の築城、謙信の攻撃回数、«江戸を見下ろす» を理由とした廃城の話は伝承。","img":["藤原秀郷","上杉謙信","佐野氏","佐野城"],"wp":"唐沢山城","rel":{"ev":[],"grave":[]},"ph":[["c:6/63/Karasawayama_Shrine.JPG",4608,3456,"唐沢山城"],["c:c/c0/Yoshitoshi_Fujiwara_no_Hidesato.jpg",1263,1869,"藤原秀郷"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:2/23/Mitsudomoe_2.png",4000,4000,"佐野氏"],["c:f/fc/Sano_Shiroyama_Park.JPG",2048,1536,"佐野城"]]},{"id":"09_sakuramachi","n":"桜町陣屋跡（二宮尊徳の仕法の地）","yomi":"さくらまちじんやあと","cat":"大名屋敷","y":1823,"era":["edo"],"sh":"国指定史跡","rank":"A","ad":"真岡市物井","st":"車が便利（真岡鐵道の駅から車で10〜15分ほど）","la":36.395,"lo":139.988,"hook":"荒れはてた村を、たった一人の農民出身の男が立て直した。«二宮金次郎» の大人になってからの本当の戦いは、ここで始まった。","lead":"桜町陣屋跡は、二宮尊徳（金次郎）が荒れた村の立て直しに取り組んだ拠点です。小田原藩の命で、尊徳は家族とともにここへ移り住み、およそ10年かけて村をよみがえらせました。陣屋の建物が残り、国の史跡になっています。","story":["二宮金次郎といえば、薪を背負って本を読む少年の像で有名です。でも大人になった尊徳の本当の活躍の舞台は、ここ桜町でした。桜町領は、小田原藩主・大久保家の分家、宇津家の領地。帳簿の上では4000石の村ですが、田畑は荒れ、人は減り、実際にはその何分の一しかとれない状態でした。","1822年、小田原で自分の家を立て直した腕を見こまれ、尊徳は桜町の復興を命じられます。翌年、尊徳は小田原の家や田畑を売り払い、家族とともに桜町陣屋に移り住みました。«なぜそこまで?» ――尊徳は、«自分が本気でなければ、村の人は動かない» と考えていたのかもしれません。","尊徳のやり方は «報徳仕法» とよばれます。まず村の本当の力を調べ、無理のない暮らしの範囲 «分度» を決める。そしてよく働き、余ったものを将来や他の人のために差し出す «推譲»。朝早くから夜おそくまで村を歩き、まじめに働く人をほめ、荒れた土地を少しずつ開いていきました。","しかし、すべてが順調だったわけではありません。新しいやり方に反発する村人や役人もいて、尊徳は行きづまります。1829年、尊徳はとつぜん姿を消し、成田山新勝寺にこもって21日間の断食をしたといわれます。戻ってきた尊徳を、村人たちは迎え入れ、それから仕法は大きく進み始めました。","およそ10年で、桜町の村々は立ち直りました。この成功が評判となり、尊徳はのちに各地の村や藩の立て直しを頼まれるようになります。陣屋の建物は、尊徳が家族と暮らし、仕事をした場所として残されています。隣には尊徳をまつる桜町二宮神社があり、«積小為大（小さなことを積み重ねて大きなことをなす）» の教えを今に伝えています。"],"tl":[["1787年","二宮尊徳（金次郎）が相模国の栢山村に生まれる"],["1822年","小田原藩から桜町領の復興を命じられる"],["1823年","家族とともに桜町陣屋に移り住む"],["1829年","成田山にこもり断食をしたと伝わる"],["1830年代","桜町の仕法が成果をあげる"],["1856年","尊徳が日光の今市で死去"]],"who":[["二宮尊徳","農民出身の農政家。桜町の復興を成しとげた"],["大久保忠真","小田原藩主。尊徳の力を見こみ、桜町の復興を任せた"],["宇津家","桜町領の領主（大久保家の分家）"],["二宮なみ","尊徳の妻。家族で桜町に移り住んだ"]],"deep":["尊徳の教えの柱は «至誠・勤労・分度・推譲» の四つ。まごころを持ち、よく働き、身の丈に合った暮らしをし、余りを人や未来にゆずる、という考え方。","桜町領は名目4000石だったが、実際の収穫はその数分の一まで落ちこんでいたといわれる。尊徳は実際の力をもとに «分度» を決めた。","成田山での断食は、弟子の富田高慶が書いた『報徳記』などで語られる有名な場面。","尊徳は桜町に来る前の小田原時代に、武家の奉公人どうしがお金を融通しあう «五常講» という助け合いのしくみをつくったとされる。お金の «しくみ» で人を救う発想は、桜町でも生かされた。","薪を背負って本を読む金次郎像は、明治時代以降の本の挿絵などから広まった姿で、尊徳の実際の姿を写したものではない。"],"look":["桜町陣屋の建物（尊徳の暮らした部屋）","桜町二宮神社","陣屋のまわりの田園風景","二宮尊徳資料館（近くにある）"],"q":["尊徳の教えで、«自分の収入に見合った暮らしをする» ことを何という?","«分度（ぶんど）» です。"],"koji":[{"w":"積小為大","m":"小さなことをこつこつ積み重ねれば、大きなことが成しとげられる、という二宮尊徳の教え"}],"myth":"成田山での断食の日数や経緯は『報徳記』などによる伝え。実際の収穫量の数字も資料で異なる。","img":["二宮尊徳","報徳思想","大久保忠真"],"wp":"桜町陣屋","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/Ruins_of_Sakuramatchi_Jin%27ya_02.JPG",2048,1536,"桜町陣屋"],["c:2/29/Ninomiya-Sontoku.jpg",1000,1500,"二宮尊徳"],["c:7/7c/Front_Gate_Dai_Nippon_Hotokusha.jpg",448,336,"報徳思想"],["c:0/02/%E5%A4%A7%E4%B9%85%E4%BF%9D%E5%BF%A0%E7%9C%9F.jpg",1419,2800,"大久保忠真"]]},{"id":"09_sontoku_haka","n":"二宮尊徳の墓（今市・如来寺）と報徳二宮神社","yomi":"にのみやそんとくのはか","cat":"墓所","y":1856,"era":["edo","meiji"],"sh":"","rank":"A","ad":"日光市今市","st":"JR今市駅・東武下今市駅から歩いて約10分","la":36.7245,"lo":139.686,"hook":"«墓は立派にするな。土を盛って、木を一本植えておけばよい。» そう言い残した人の墓が、日光の町に静かにある。","lead":"二宮尊徳（金次郎）は、晩年に幕府から日光神領の村々の立て直しを命じられ、今市で70歳の生涯を終えました。お墓は今市の如来寺にあり、となりには尊徳をまつる報徳二宮神社があります。尊徳の最後の仕事の地です。","story":["桜町の復興などで名を知られた二宮尊徳は、やがて幕府に仕えるようになりました。1853年、尊徳は日光神領――東照宮を支えるための領地の村々――の立て直しを命じられます。このとき尊徳はすでに60歳をこえ、体も弱っていました。","«それでも、村が荒れていれば放ってはおけない。» 尊徳は弟子たちとともに今市に «報徳役所» を置き、村々をまわって調べ、仕法を進めました。弟子の富田高慶や息子の尊行（弥太郎）も、尊徳を支えて働きました。","尊徳のやり方は、いつも同じでした。まず村の «本当の力» を、古い帳簿や田畑の広さから細かく調べます。そのうえで、無理のない暮らしの範囲を決め、荒れ地を開き、用水を直し、まじめに働く人をほめて励ます。日光神領の村々は山がちで田畑が少なく、そのやり方を一つひとつの村に合わせて考えなければなりませんでした。尊徳は病気がちの体で、それでも計画書を書き続けたといわれます。","しかし1856年、尊徳は今市の報徳役所で亡くなります。70歳でした。尊徳は «わたしを葬るのに身分をこえたことをするな。墓石を立てず、土を盛って松か杉を一本植えておけばよい» という意味のことを言い残したと伝わります。","遺体は近くの如来寺に葬られました。質素なお墓は、尊徳の «分度»（身の丈に合った暮らし）の教えそのもののようです。明治時代になると、尊徳を慕う人々によって、お墓のとなりに報徳二宮神社がつくられました。","尊徳の仕法は、尊徳が亡くなったあとも息子や弟子たちによって日光の村々で続けられました。今市の町を歩くと、報徳の教えが今も «地域の誇り» として語り継がれていることがわかります。«自分の力で、少しずつ» ――尊徳の教えは、最後の地で静かに眠っています。"],"tl":[["1787年","相模国栢山村に生まれる"],["1823年","桜町陣屋に移り、村の復興に取り組む"],["1853年","幕府から日光神領の復興を命じられる"],["1856年","今市の報徳役所で死去。如来寺に葬られる"],["明治時代","お墓のとなりに報徳二宮神社が創建される"]],"who":[["二宮尊徳","農政家。日光神領の復興に取り組み、今市で亡くなった"],["二宮尊行（弥太郎）","尊徳の息子。父の仕法を受けついだ"],["富田高慶","尊徳の弟子。『報徳記』を書き、尊徳の生涯を伝えた"]],"deep":["日光神領は、東照宮の維持のための領地で、村々は山がちで田畑が少なく、たびたびききんに苦しんでいた。","尊徳が日光の仕法のためにつくった計画書（仕法雛形）は、ばく大な量にのぼったといわれる。","尊徳の遺言として伝わる言葉は、弟子たちの記録によるもの。言い回しは資料によって少しずつ違う。","報徳二宮神社のほか、尊徳をまつる神社は小田原（報徳二宮神社）や相馬などにもある。","今市には尊徳の仕法にまつわる史跡がいくつか残り、市の記念館などで紹介されている。","尊徳の死後、日光神領の仕法は息子の尊行が中心となって続けられたが、幕末の混乱や明治維新で幕府の支えがなくなり、やがて打ち切られた。"],"look":["如来寺の尊徳の墓","報徳二宮神社","今市の報徳役所跡","二宮尊徳記念館（今市）","今市の町に残る尊徳ゆかりの碑や案内板"],"q":["二宮尊徳が最後に復興を命じられた地域は?","日光神領（東照宮を支える領地）の村々です。"],"koji":[{"w":"推譲","m":"余った力や物を、将来のためや人のためにゆずること。尊徳の報徳の教えの一つ"}],"myth":"遺言の言葉は伝え。報徳二宮神社の創建年は資料を確認したい。","img":["報徳思想","日光街道"],"wp":"二宮尊徳","rel":{"ev":[],"grave":[["sontoku","二宮尊徳"]]},"ph":[["c:2/29/Ninomiya-Sontoku.jpg",1000,1500,"二宮尊徳"],["c:7/7c/Front_Gate_Dai_Nippon_Hotokusha.jpg",448,336,"報徳思想"],["c:1/10/Nikko_kaido_hasui_kawase.jpg",910,1384,"日光街道"]]},{"id":"09_otawara_jo","n":"大田原城（龍城）","yomi":"おおたわらじょう","cat":"城","y":1545,"era":["muromachi","azuchi","edo"],"sh":"","rank":"A","ad":"大田原市城山（龍城公園）","st":"JR西那須野駅から車で約15分（バスもある）","la":36.8716,"lo":140.0186,"hook":"城を築いた一族が、戦国から明治まで300年以上、同じ城を守り通した。そんな城は全国でもめずらしい。","lead":"大田原城は、戦国時代に大田原資清が築いた山城です。丘の形が龍の寝そべった姿に似ていることから «龍城（たつじょう）» ともよばれます。大田原氏はここを本拠地として、明治時代まで大名として続きました。今は龍城公園として、桜の名所になっています。","story":["戦国時代の1545年、那須氏に仕える武将・大田原資清は、那珂川の支流・蛇尾川のほとりの丘に城を築きました。丘は南北に細長く、龍が寝ているように見えたので «龍城» とよばれたといわれます。大田原氏は «那須七騎» とよばれた那須氏の有力な家臣の一つでした。","1590年、豊臣秀吉が小田原の北条氏を攻めたとき、大田原氏はいちはやく秀吉のもとへかけつけ、領地を認められました。これに対して主家の那須氏は遅れ、領地を大きく減らされます。«誰につくか、いつ動くか。» 戦国の小さな大名にとって、その判断が生き残りを分けました。","1600年、徳川家康が会津の上杉景勝を攻めようとしたとき、大田原城は上杉領に近い «最前線» になりました。家康は大田原城を改修させ、兵を入れて守らせたといわれます。関ヶ原の戦いのあとも、大田原氏は徳川方として領地を守りました。","江戸時代、大田原氏は約1万石の小さな大名でしたが、築城した一族がそのまま明治まで同じ城を守り続けました。これは全国的にもめずらしいことです。幕末の戊辰戦争では、会津方の攻撃を受け、城の一部が焼けたとも伝わります。","明治の廃藩のあと、建物は取り壊されました。今は本丸や土塁、堀の跡が残る龍城公園となり、春には桜が咲きほこります。丘の上から那須の山々を眺めると、この小さな城が、北の強い大名とのはざまで生き抜いてきたことが実感できます。"],"tl":[["1545年","大田原資清が大田原城を築く"],["1590年","秀吉の小田原攻めに参陣し、領地を認められる"],["1600年","上杉への備えとして家康の命で城が改修されたといわれる"],["江戸時代","大田原藩（約1万石）の城として続く"],["1868年","戊辰戦争で会津方の攻撃を受ける"],["明治時代","廃城。のちに龍城公園として整備"]],"who":[["大田原資清","戦国時代の武将。大田原城を築いた"],["大田原晴清","資清の孫。秀吉・家康に従い、家を守った"],["徳川家康","上杉への備えとして大田原城を重視した"],["那須氏","大田原氏がもと仕えた下野北部の名門"]],"deep":["«那須七騎» は、那須氏に従った大田原・大関・芦野・伊王野・千本・福原・岡本の七家をさすとされる（数え方に諸説）。","大田原氏は築城から明治の廃藩まで、同じ城に住み続けた。国替えの多い江戸時代では、とてもめずらしい例である。","城は丘の上に本丸・二の丸・三の丸が南北に連なる連郭式の山城で、今も土塁や空堀の跡がよくわかる。","大田原は奥州街道の宿場町（大田原宿）でもあり、城下町と宿場が一体となって発展した。","近くの那須与一ゆかりの地とあわせ、那須氏の歴史をたどることができる。"],"look":["本丸跡からの眺め","土塁と空堀の跡","春の桜（龍城公園）","城下の大田原宿のなごり"],"q":["大田原城が «龍城（たつじょう）» とよばれたのはなぜ?","城のある丘の形が、龍が寝そべった姿に似ていたからといわれます。"],"koji":[],"myth":"«龍城» の由来、戊辰戦争での被害の範囲は伝え。","img":["大田原藩","那須氏","奥州街道"],"wp":"大田原城","rel":{"ev":["k_oshu"],"grave":[]},"ph":[["c:d/de/Ruins_of_Otawara_Castle%2C_Tochigi%2C_Japan.jpg",800,600,"大田原城"],["c:6/65/%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%88%E4%B8%B8%E3%81%AB%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%89%E7%B4%8B.png",4000,4000,"那須氏"]]},{"id":"09_karasuyama_jo","n":"烏山城","yomi":"からすやまじょう","cat":"城","y":1418,"era":["muromachi","edo"],"sh":"","rank":"A","ad":"那須烏山市城山","st":"JR烏山線 烏山駅から歩いて約20分で登山口","la":36.648,"lo":140.152,"hook":"«金の烏がくわえてきた御幣の落ちた山に城を建てよ»――そんな伝説が名前の由来とされる山城。","lead":"烏山城は、那珂川を見下ろす山の上に築かれた城です。室町時代に那須氏の一族が築いたと伝わり、戦国時代には那須氏の本拠地となりました。江戸時代には烏山藩の城となり、石垣や曲輪の跡が今も山の中に残っています。","story":["烏山城には、名前にまつわる伝説があります。城を築く場所を決めかねていたとき、金色の烏が現れて御幣をくわえて飛び去り、落とした山を城の地に選んだ――そこから «烏山» という名前がついたといわれます。もちろん伝説ですが、山の城にふさわしい、ふしぎな話です。","城は、室町時代の1418年ごろ、那須氏の一族・那須資重が築いたと伝わります。那須氏は、源平の戦いで扇の的を射たことで有名な那須与一の家とされる名門。のちに那須氏は一つにまとまり、烏山城がその本拠地となりました。","戦国時代、那須氏は常陸の佐竹氏や宇都宮氏と争いながら、この山城を守りました。けわしい山の上に曲輪がいくつも並び、谷や堀切で守られた城は、攻めにくい城として知られていました。","しかし1590年、豊臣秀吉の小田原攻めのとき、那須資晴は参陣しなかったため、領地を取り上げられてしまいます。«遅れたこと» が名門の運命を変えたのです。その後、烏山城は江戸時代を通じて、いくつもの大名家が次々と入れかわる城になりました。江戸時代の中ごろから、大久保氏が明治まで城主をつとめました。","明治になり、城は役目を終えました。今は山の中に石垣や曲輪、堀切が静かに残り、ハイキングを楽しみながら城の跡をたどることができます。ふもとの烏山の町は、那珂川の水運と和紙づくりで栄えた町。山と川と町がひとつの物語になっている場所です。"],"tl":[["1418年ごろ","那須資重が烏山城を築いたと伝わる"],["戦国時代","那須氏の本拠地として佐竹氏などと争う"],["1590年","那須資晴が小田原攻めに参陣せず、改易される"],["江戸時代","烏山藩の城として大名が次々と入れかわる"],["1725年","大久保常春が城主となり、以後大久保氏が明治まで続く"],["明治時代","廃城"]],"who":[["那須資重","烏山城を築いたと伝わる那須氏の一族"],["那須資晴","戦国時代の那須氏当主。秀吉に改易された"],["豊臣秀吉","小田原攻めに参陣しなかった那須氏の領地を取り上げた"],["大久保常春","江戸時代中ごろに烏山藩主となった大名"]],"deep":["烏山城は «臥牛城（がぎゅうじょう）» という別名をもつ。山の形が牛の寝そべった姿に見えることからといわれる。","那須氏は那須与一を先祖とする伝承をもつ。与一が実在した人物かについては、史料が少なく議論がある。","那須資晴の改易のあと、那須氏は子の資景が小さな領地をもらって家を保った。","城は山頂部の本城と、それをとりまく多くの曲輪からなる大規模な山城で、石垣は江戸時代に整えられたものと考えられている。","烏山は «程村紙» などの烏山和紙の産地として知られ、城下町の産業を支えた。","山の中の城跡は、道が荒れていたり、クマなどに注意が必要なこともある。案内に従って歩きたい。"],"look":["本丸・二の丸の石垣","大きな堀切","山道から見下ろす那珂川","ふもとの烏山の町なみ"],"q":["烏山城の別名は?","«臥牛城（がぎゅうじょう）» です。山の形が寝ている牛に見えることからといわれます。"],"koji":[],"myth":"金の烏の伝説、1418年の築城年は伝承。那須与一の実在も議論がある。","img":["烏山藩","那須氏","那須与一"],"wp":"烏山城","rel":{"ev":[],"grave":[]},"ph":[["c:1/1d/Ruins_of_Karasuyama_Castle.JPG",2048,1536,"烏山城"],["c:6/65/%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%88%E4%B8%B8%E3%81%AB%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%89%E7%B4%8B.png",4000,4000,"那須氏"],["c:6/64/NasunoYoichi.jpg",1260,961,"那須与一"]]},{"id":"09_kitsuregawa","n":"喜連川陣屋跡（足利公方の末裔・喜連川藩）","yomi":"きつれがわじんやあと","cat":"大名屋敷","y":1590,"era":["azuchi","edo"],"sh":"","rank":"A","ad":"さくら市喜連川（喜連川庁舎付近）","st":"JR氏家駅からバスで約20分、または車","la":36.761,"lo":139.988,"hook":"領地はわずか数千石。なのに «10万石なみ» の扱いで、«御所» とよばれた不思議な小藩。","lead":"喜連川藩は、室町幕府の将軍家・足利氏の血を引く一族が治めた小さな藩です。領地は小さいのに、将軍家の名門として特別な扱いを受け、参勤交代もしなくてよかったといわれます。陣屋の跡は今、市役所の庁舎などになっています。","story":["室町時代、関東は «鎌倉公方» とよばれる足利氏の一族が治めていました。のちにその家は、古河公方と小弓公方という二つに分かれ、争いを続けます。そして戦国時代の終わり、どちらの家も力を失ってしまいました。","1590年、天下を統一した豊臣秀吉は、この名門の血が絶えるのを惜しみました。秀吉は、古河公方の娘・氏姫と、小弓公方の孫・足利国朝を結婚させ、喜連川の地に小さな領地を与えます。争っていた二つの家が、ここで一つになったのです。","ところが国朝は、朝鮮出兵に向かう途中で病気で亡くなってしまいます。弟の頼氏が家をつぎ、氏姫と結婚しました。そして «喜連川» を名字とします。江戸時代になると、徳川家康はこの家を特別に扱いました。«なぜ?» ――徳川家は自分たちを源氏の流れと名のり、同じ源氏の名門である足利の血筋を大切にすることで、自分の権威を高めようとしたと考えられます。","喜連川家の領地はわずか数千石でしたが、格式は «10万石なみ» とされ、参勤交代もしなくてよいとされました。人々は喜連川家を «御所» とよび、特別な家として敬いました。けれど実際の暮らしは楽ではなく、藩の財政はいつも苦しかったといわれます。","明治になると、喜連川家は «足利» の名字に戻りました。陣屋の跡には今、さくら市の喜連川庁舎があり、復元された門が昔の面影を伝えています。奥州街道の宿場町でもあった喜連川。小さな町に、室町将軍家の最後の物語が残っているのです。"],"tl":[["1590年","秀吉が氏姫と足利国朝を結婚させ、喜連川に領地を与える"],["1593年","国朝が朝鮮出兵に向かう途中で病死"],["1590年代","弟の頼氏が家をつぎ、喜連川を名字とする"],["江戸時代","«御所» とよばれる特別な家として続く"],["明治時代","喜連川家が足利の名字に戻る"]],"who":[["氏姫","古河公方・足利義氏の娘。二つの家をつなぐ要となった"],["足利国朝","小弓公方・足利義明の孫。氏姫と結婚した"],["喜連川頼氏","国朝の弟。家をついで喜連川家の初代藩主となった"],["豊臣秀吉","足利の名門を残すため、この家を立てた"],["徳川家康","喜連川家を特別な家格で扱った"]],"deep":["喜連川家は «大名» か «旗本» かがあいまいな、特別な家だった。石高は1万石に届かないのに、大名に近い扱いを受けた。","«10万石の格式» は喜連川家の扱いを表すときによく使われる言い方で、何を基準にした «10万石なみ» かは資料によって説明が異なる。","氏姫は喜連川には住まず、古河の近くで暮らし続けたといわれる。","喜連川は奥州街道の宿場町で、藩主の陣屋と宿場が一体になった町だった。","江戸時代後期の喜連川藩では、財政難をめぐる家臣団の争い（お家騒動）も起きている。"],"look":["喜連川庁舎の門（陣屋のなごり）","喜連川家の菩提寺・龍光寺","お丸山公園（喜連川城跡）","宿場町のなごりのある町なみ"],"q":["喜連川家は、どんな一族の子孫だった?","室町幕府の将軍家・足利氏の流れをくむ、鎌倉公方（古河公方・小弓公方）の子孫です。"],"koji":[],"myth":"«10万石の格式»、参勤交代免除の扱いの細部は資料によって説明が異なる。","img":["古河公方","小弓公方","氏姫"],"wp":"喜連川藩","rel":{"ev":[],"grave":[]},"ph":[["c:e/e0/Kogakubo.jpg",800,600,"古河公方"],["c:4/4d/Minamioumio2.jpg",800,600,"小弓公方"]]},{"id":"09_minagawa_jo","n":"皆川城（法螺貝城）","yomi":"みながわじょう","cat":"城","y":1590,"era":["muromachi","azuchi"],"sh":"","rank":"A","ad":"栃木市皆川城内町","st":"栃木駅から車で約15分","la":36.39,"lo":139.695,"hook":"山全体がぐるぐると曲輪におおわれ、上から見るとまるで法螺貝。戦国の «要塞の山» がそのまま残る。","lead":"皆川城は、戦国時代に皆川氏が本拠地とした山城です。山の斜面が段々の曲輪でぐるりと取り巻かれ、その形が法螺貝のように見えることから «法螺貝城» ともよばれます。木が少なく地形がよく見えるため、戦国の山城の姿を実感できる城跡です。","story":["栃木市の西、皆川の里に小さな山があります。近くで見ると、山の斜面が階段のように削られ、段々になっているのがわかります。これが皆川城の曲輪です。上から見るとぐるぐると巻いた形になっていて、法螺貝にたとえられました。","皆川氏は、戦国時代に宇都宮氏や北条氏、上杉氏といった大きな勢力にはさまれながら、この地を治めた一族です。とくに皆川広照は、情勢を見きわめる力にすぐれた武将として知られています。","1590年、豊臣秀吉が小田原の北条氏を攻めたとき、広照は北条方として小田原城に入っていました。けれど «このままでは家がほろびる» と考えた広照は、城を抜け出して徳川家康の陣に降ったといわれます。この決断によって、皆川氏は生き残ることができました。","その後、広照は平地に栃木城を築いて移り、山の上の皆川城は使われなくなりました。江戸時代の初め、広照は家康の六男・松平忠輝の家老となりますが、忠輝の行いをめぐる問題から、一時領地を失います。のちに許され、家は大名として再び取り立てられました。","使われなくなった皆川城は、長い年月のあいだ、曲輪や堀の形をそのまま残しました。今は整備されて、山を登りながら段々の曲輪をめぐることができます。«なぜこんなに段を重ねたの?» ――それは、どこから攻められても上から迎え撃てるようにするためでした。山全体が、戦国の武士たちの工夫のかたまりなのです。"],"tl":[["室町時代","皆川氏がこの地で力をのばす"],["戦国時代","皆川城が皆川氏の本拠地として整えられる"],["1590年","小田原攻め。皆川広照が小田原城を出て家康に降る"],["1590年代","広照が栃木城を築いて移り、皆川城は使われなくなる"],["1609年","松平忠輝の家老だった広照が改易される（のち許される）"]],"who":[["皆川広照","戦国時代の皆川氏の当主。小田原から脱出して家を守った"],["徳川家康","広照が降った相手。のちに広照を取り立てた"],["松平忠輝","家康の六男。広照が家老として仕えた"],["北条氏政・氏直","小田原の北条氏。広照がはじめ味方していた"]],"deep":["皆川城は «法螺貝城» のほか、山全体が曲輪で埋めつくされた構造から、関東の戦国山城の典型としてしばしば紹介される。","山の斜面の多くは木が少なく、段々の曲輪や堀切の形が外からもよく見える。これは山城としてはめずらしい。","広照が小田原城を出て家康の陣に降ったことは、家の存続を優先した戦国武将の判断の例として語られる。","栃木城は、今の栃木市の町づくりの出発点となった。栃木の町は、のちに巴波川の舟運で栄える商人の町へと育っていく。","広照は改易のあと許され、のちに常陸府中（今の茨城県石岡市）の大名となった。"],"look":["段々に重なる曲輪（ふもとから全体を眺める）","本丸跡からの眺め","堀切と虎口のあと","ふもとの皆川の里"],"q":["皆川城が «法螺貝城» とよばれるのはなぜ?","山の斜面をぐるぐると曲輪が取り巻く形が、法螺貝のように見えるからです。"],"koji":[],"myth":"広照の小田原脱出の経緯の細部は伝え。城の成立時期は諸説。","img":["皆川広照","栃木城","松平忠輝"],"wp":"皆川城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b6/The_Remains_of_Minagawa_castle.jpg",3264,2448,"皆川城"],["c:9/9e/Minagawa_Hiroteru.jpg",1109,1869,"皆川広照"],["c:d/d2/Tochigi_Castle_Park.jpg",3264,2448,"栃木城"],["c:8/8f/Matsudaira_Tadateru.jpg",299,368,"松平忠輝"]]},{"id":"09_gion_jo","n":"祇園城（小山城）","yomi":"ぎおんじょう（おやまじょう）","cat":"城","y":1148,"era":["heian","muromachi","azuchi"],"sh":"国指定史跡（小山氏城跡）","rank":"A","ad":"小山市城山町","st":"JR小山駅西口から歩いて約10分","la":36.3156,"lo":139.7975,"hook":"思川の崖の上、400年以上も «小山氏» を守り続けた城。すぐ近くでは、関ヶ原の運命を決めた «小山評定» も開かれた。","lead":"祇園城は、平安時代の終わりから戦国時代まで下野の名門・小山氏が本拠にした城です。思川に面した高い崖を天然の守りにしていました。いまは «城山公園» になっていて、深い堀や土塁が残り、春は桜の名所としてにぎわいます。","story":["小山氏は、平将門を討ったことで知られる «藤原秀郷» の子孫といわれる一族です。平安時代の終わりごろ、小山政光がこの地に城を築いたと伝わります。城の名前は、守り神として祀られた «祇園社»（いまの須賀神社）から来ているといわれます。思川の流れを見下ろす崖の上は、西からせめる敵にはまさに «天然の壁» でした。","鎌倉時代、小山氏は源頼朝に味方して大きな力を持ち、下野の守護もつとめました。ところが南北朝のあと、小山義政が鎌倉公方の足利氏満と対立します。«なぜ、そこまで争ったのか?» 下野の支配をめぐる宇都宮氏との争いが引き金だったといわれます。義政は «小山義政の乱» で敗れ、小山氏の本家はいったん途絶えてしまいました。","それでも小山の名は消えませんでした。結城氏から養子を迎えて家が再興され、祇園城はふたたび小山氏の本拠となります。戦国時代には、北の佐竹・宇都宮、南の後北条氏という大勢力のあいだで、小山氏は生き残りをかけて揺れ動きました。やがて後北条氏がこの城を押さえ、小山秀綱は城を追われます。","1590年、豊臣秀吉の小田原攻めで後北条氏がほろびると、小山氏も大名として復活することはできませんでした。そして1600年、城のすぐ近くで徳川家康が諸大名を集めて軍議を開きます。これが «小山評定»。«石田三成を討つため、西へ引き返す» という決断が、ここで下されたと伝わります。","江戸時代のはじめには本多正純が小山を治めましたが、正純が宇都宮へ移ると、祇園城は役目を終えて廃城となりました。建物は残っていませんが、公園を歩くと、いくつも重なる空堀と土塁の深さに驚かされます。«ここを攻めるのは大変だったろう» と想像しながら歩くのが、この城の楽しみ方です。"],"tl":[["1148年ごろ","小山政光が城を築いたと伝わる（諸説）"],["1180年代","小山氏が源頼朝に従い、下野で大きな力を持つ"],["1380年","小山義政が鎌倉公方と対立（小山義政の乱の始まり）"],["戦国時代","小山氏が佐竹・宇都宮氏と後北条氏のあいだで揺れ動く"],["1600年","城の近くで徳川家康が «小山評定» を開く"],["1619年","本多正純が宇都宮へ移り、廃城になる"],["1992年","鷲城跡・中久喜城跡とともに «小山氏城跡» として国史跡に"]],"who":[["小山政光","小山氏の祖とされ、城を築いたと伝わる"],["小山義政","鎌倉公方と戦い、敗れた当主"],["小山秀綱","戦国時代の当主。後北条氏に城を追われた"],["徳川家康","城の近くで小山評定を開いた"],["本多正純","江戸時代はじめの小山の領主。宇都宮へ移り城は廃城に"]],"deep":["国の史跡名は «小山氏城跡»。祇園城跡のほか、義政の乱で激戦地となった鷲城跡、中久喜城跡の3つがまとめて指定されています。小山氏の城のネットワークが一度にわかる、めずらしい指定のしかたです。","築城年ははっきりしません。«1148年に小山政光が築いた» という説がよく紹介されますが、確かな同時代の史料で裏づけられたものではなく、伝承として受け取るのが安全です。","城の縄張りは、思川の崖を西側の守りにして、東側に向かって曲輪を並べ、そのあいだを深い空堀で区切る形。平城と山城の中間のような «崖端城» と呼ばれるタイプです。","小山評定の正確な場所は、はっきりわかっていません。家康が本陣を置いたのは、のちに «小山御殿» が建てられたあたり（いまの市役所の近く）とされ、そこに記念碑があります。","小山氏は «藤原秀郷流» の名門で、下野の宇都宮氏・那須氏などと並ぶ有力な武士団でした。小山から分かれた一族には、結城氏や長沼氏があります。"],"look":["深い空堀と土塁（公園の中を歩くとよくわかる）","思川にかかる観晃橋からながめる城の崖","城の守り神だった須賀神社","近くの «小山評定跡» の碑","春の桜（城山公園は桜の名所）"],"q":["関ヶ原の戦いの前、家康が小山で開いた会議を何という?","«小山評定»。ここで西へ引き返して石田三成と戦うことを決めたと伝わります。"],"koji":[],"myth":"築城年（1148年）と小山政光の築城は伝承。小山評定の場所・やりとりの細部も後世の記録による部分が多い。","img":["小山氏","小山評定","藤原秀郷"],"wp":"祇園城","rel":{"ev":["k_nikko","k_oshu"],"grave":[]},"ph":[["c:5/5b/Oyama-jo.4.jpg",3072,2304,"祇園城"],["c:b/b9/Oyama.png",501,501,"小山氏"],["c:9/9f/Sekigaharascreen.jpg",3816,1796,"小山評定"],["c:c/c0/Yoshitoshi_Fujiwara_no_Hidesato.jpg",1263,1869,"藤原秀郷"]]},{"id":"09_tobiyama_jo","n":"飛山城跡（芳賀氏の城）","yomi":"とびやまじょうあと","cat":"城","y":1295,"era":["kamakura","muromachi","nara"],"sh":"国指定史跡","rank":"A","ad":"宇都宮市竹下町","st":"宇都宮ライトライン «飛山城跡» 停留場から歩いて約20分","la":36.534,"lo":139.9445,"hook":"鬼怒川を見下ろす崖の上。中世の城の下から、1000年以上前の «のろし台» の証拠が出てきた。","lead":"飛山城は、宇都宮氏の重臣・芳賀氏が鎌倉時代の終わりごろに築いたといわれる城です。鬼怒川の東の崖の上にあり、深い堀が何重にもめぐります。いまは史跡公園として整備され、建物の一部が復元されています。","story":["宇都宮の町から東へ。鬼怒川をこえた先の台地に、飛山城はあります。城を築いたのは «芳賀氏»。宇都宮氏を支えた有力な家臣で、益子の紀氏とあわせて «紀清両党» と呼ばれ、戦上手で知られました。芳賀高俊が永仁年間（1290年代）に城を築いたと伝わります。","«なぜ、ここに城を?» その答えは、崖の下を流れる鬼怒川です。川は東から宇都宮へ攻めてくる敵をふせぐ大きな堀になり、崖の上からは川の向こうまで見わたせます。飛山城は、宇都宮氏の本拠を東から守る «見張り役» の城だったのです。","南北朝時代、関東は南朝と北朝に分かれて争いました。芳賀氏もその戦いのうずに巻きこまれ、飛山城も攻めたり攻められたりしたといわれます。戦国時代になると、城は堀を深く掘り直して守りを固め、曲輪の数も増えていきました。","1597年、主君の宇都宮氏が豊臣秀吉に領地を取り上げられます。宇都宮氏とともに生きた芳賀氏も運命をともにし、飛山城も役目を終えて廃城となりました。それから長いあいだ、城あとは畑や林の中に静かに眠っていました。","発掘調査で、思いがけない発見がありました。城の中から、平安時代の住居の跡と «烽家» と墨で書かれた土器が見つかったのです。«烽» は、のろし。つまりここは、中世の城ができるよりずっと前、古代の «のろし台» の拠点でもあった可能性があります。見晴らしのよい崖は、いつの時代も «見張る場所» だったのです。"],"tl":[["平安時代","のろしに関わる施設があったとみられる（«烽家» 墨書土器）"],["1290年代（永仁年間）","芳賀高俊が城を築いたと伝わる"],["南北朝時代","関東の争乱のなかで戦いの舞台に"],["戦国時代","堀を掘り直し、守りを強くする"],["1597年","宇都宮氏の改易とともに廃城"],["1977年","国の史跡に指定"],["2000年代","史跡公園として整備、«とびやま歴史体験館» が開館"]],"who":[["芳賀高俊","城を築いたと伝わる芳賀氏の武将"],["芳賀氏","宇都宮氏の重臣。«清党» と呼ばれた武士団"],["宇都宮氏","下野の名門。芳賀氏の主君"],["豊臣秀吉","宇都宮氏の領地を取り上げ、廃城のきっかけをつくった"]],"deep":["«烽家（とぶひや）» と書かれた墨書土器は、古代の烽（のろし）の制度を示す貴重な資料です。律令の時代、のろしは都と地方を結ぶ緊急の通信手段でした。城の名前の «飛山（とびやま）» と «とぶひ» を結びつける説もありますが、確かめられてはいません。","«紀清両党»: 宇都宮氏を支えた益子氏（紀党）と芳賀氏（清党）の二つの武士団。南北朝時代の軍記物にも、その強さが語られています。","城のまわりの空堀は、深いところで数メートルもあり、何本も並んでいます。台地の上をいくつもの曲輪に区切る造りは、戦国時代の改修によるものとみられます。","公園では、発掘でわかった柱の跡をもとに、掘立柱の建物や木の橋が復元されています。資料をもとにした «ここにこういう建物があったかもしれない» という再現で、当時の見た目そのものとは限りません。","すぐ近くを通る宇都宮ライトライン（2023年開業）には «飛山城跡» という停留場があり、史跡の名前が駅名になった例として話題になりました。"],"look":["何重にもめぐる深い空堀","復元された掘立柱の建物と木橋","崖の上からながめる鬼怒川と宇都宮の町","«とびやま歴史体験館» の «烽家» 土器の展示"],"q":["飛山城から見つかった «烽家» と書かれた土器。«烽» とは何のこと?","のろし（煙や火で知らせる通信）のこと。ここが古代ののろしの拠点だった可能性を示しています。"],"koji":[],"myth":"築城者・築城年（芳賀高俊・永仁年間）は伝承。城名と «とぶひ» を結ぶ説は推測。","img":["芳賀氏","宇都宮氏","鬼怒川"],"wp":"飛山城","rel":{"ev":[],"grave":[]},"ph":[["c:e/eb/Tobiyama_Castle_Front_Entrance.jpg",1000,750,"飛山城"],["c:c/c8/Mitsudomoe_1.png",4000,4000,"宇都宮氏"],["c:b/b8/Kinu_River_viewing_from_Akutsu_Ohashi_in_Utsunomiya.jpg",1000,750,"鬼怒川"]]},{"id":"09_kurobane_jo","n":"黒羽城（黒羽藩大関氏）","yomi":"くろばねじょう","cat":"城","y":1576,"era":["azuchi","edo"],"sh":"","rank":"A","ad":"大田原市前田","st":"JR西那須野駅・那須塩原駅からバス（本数少なめ）。車が便利","la":36.8715,"lo":140.124,"hook":"大関氏が明治まで300年近く守った城。松尾芭蕉が «おくのほそ道» でいちばん長く泊まった町は、この城下だった。","lead":"黒羽城は、戦国時代に大関高増が築いた城です。江戸時代は黒羽藩・大関氏の城として、明治維新まで一度も持ち主が変わりませんでした。建物は残っていませんが、城跡は公園になり、初夏にはたくさんのあじさいが咲きます。","story":["那珂川が大きく流れる黒羽の町。その川を見下ろす細長い丘に、黒羽城はありました。1576年、那須氏の家臣だった大関高増が、ここに新しい城を築いたと伝わります。那珂川と支流にはさまれた地形は、城を守るのにぴったりでした。","大関氏は、戦国の世を上手に生きぬいた一族です。豊臣秀吉が小田原を攻めたとき、いち早くかけつけて領地を認められました。関ヶ原の戦いでは徳川家康に味方し、東北の上杉氏に備える役目を果たします。こうして大関氏は小さな大名として、江戸時代を通して黒羽を治めることになりました。","1689年の春、この城下に二人の旅人がやってきました。松尾芭蕉と弟子の曾良です。迎えたのは、黒羽藩の城代家老・浄法寺図書と、その弟の鹿子畑翠桃。二人は芭蕉の弟子筋でした。«どうか、ゆっくりしていってください»。芭蕉はここに十数日も滞在し、近くの寺や神社をめぐりました。«おくのほそ道» の旅で、いちばん長い滞在だったのです。","江戸時代の後半には、学問好きの藩主・大関増業が、藩の政治を立て直そうとしたり、多くの書物を書き残したりしました。幕末の藩主・大関増裕は、幕府の海軍奉行や若年寄をつとめ、西洋式の軍制を取り入れようとした人物です。しかし1867年、狩りの最中に銃の事故で急死しました。その死には今もなぞが残るといわれます。","明治になり、城は役目を終えました。いま、本丸と二の丸のあたりは «黒羽城址公園» となり、土塁や空堀が残っています。6月の終わりごろには、城跡をあじさいが埋めつくし、«くろばね紫陽花まつり» が開かれます。城下には «芭蕉の館» もあり、芭蕉と黒羽の縁を伝えています。"],"tl":[["1576年","大関高増が黒羽城を築いたと伝わる"],["1590年","大関氏が秀吉の小田原攻めに参陣し、領地を認められる"],["1600年","関ヶ原の戦いで家康方につく"],["1689年","松尾芭蕉が黒羽に十数日滞在"],["1867年","藩主・大関増裕が急死"],["1871年","廃藩置県で黒羽藩が終わる"]],"who":[["大関高増","黒羽城を築いた戦国武将"],["大関増業","学問好きで知られる江戸後期の藩主"],["大関増裕","幕末の藩主。幕府の海軍奉行などを務めた"],["浄法寺図書","黒羽藩の城代家老。芭蕉をもてなした"],["松尾芭蕉","おくのほそ道の旅で黒羽に長く滞在した"]],"deep":["大関氏は «那須七騎» と呼ばれた那須氏の家臣団の一つでした。主家の那須氏が秀吉の怒りを買って力を失うなか、大関氏は自立した大名として生き残ります。","黒羽藩は約1万8千石の小藩ですが、江戸時代を通して大関氏が治め続けました。国替えがなかったのは、関東の小藩ではめずらしいことです。","芭蕉の黒羽滞在は、曾良の «旅日記» からもわかります。この間に雲巌寺をたずね、句を残しました。黒羽は «おくのほそ道» の中でも、とくにゆかりの深い町です。","城は «山城» というより、川に面した丘を利用した «平山城»。本丸・二の丸・三の丸が丘の上に一列に並ぶ形でした。天守はなかったといわれます。","大関増裕の死は «事故» とされていますが、幕府の要職にあった人物だったこともあり、暗殺説などがささやかれてきました。はっきりしたことはわかっていません。"],"look":["本丸跡の土塁と空堀","初夏のあじさい（城址公園）","城下の «芭蕉の館»","本丸跡からながめる那珂川と八溝の山々"],"q":["おくのほそ道の旅で、芭蕉がいちばん長く滞在した町はどこ?","黒羽（いまの大田原市）。城代家老の兄弟にもてなされ、十数日も泊まりました。"],"koji":[],"myth":"大関増裕の死因をめぐる暗殺説は推測の域を出ない。築城年は1576年とされるが異説もある。","img":["大関氏","黒羽藩","松尾芭蕉"],"wp":"黒羽城","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"]]},{"id":"09_mibu_jo","n":"壬生城","yomi":"みぶじょう","cat":"城","y":1712,"era":["muromachi","edo"],"sh":"","rank":"A","ad":"下都賀郡壬生町本丸","st":"東武宇都宮線壬生駅から歩いて約10分","la":36.4262,"lo":139.804,"hook":"戦国の壬生氏から、江戸の鳥居氏へ。日光へ向かう道の城下町は、いまもかんぴょうの町として生きている。","lead":"壬生城は、室町時代に壬生氏が築いた城です。江戸時代には壬生藩の城となり、最後は鳥居氏が明治まで治めました。本丸のあたりは «壬生城址公園» になっていて、土塁の一部が残っています。","story":["壬生城を築いたのは、壬生胤業という武将だと伝わります。室町時代の中ごろのことです。壬生氏は宇都宮氏の家臣として力をつけ、やがて鹿沼にも城を持つほどの勢いになりました。黒川の流れを利用した平城で、まわりの低い湿地が守りになっていたといわれます。","戦国時代の終わり、壬生氏は南から勢力をのばす後北条氏に味方しました。«宇都宮氏につくか、北条氏につくか»。その選択は、1590年の豊臣秀吉の小田原攻めで裏目に出ます。当主の壬生義雄は小田原で亡くなり、壬生氏はここで途絶えてしまいました。","江戸時代、壬生は日光へ向かう «壬生通り（日光西街道）» の宿場町になりました。城には次々と大名が入れかわり、1712年、鳥居忠英がやってきます。鳥居氏は、関ヶ原の前に伏見城を守って討ち死にした鳥居元忠の子孫。そのあと明治維新まで、鳥居氏が壬生を治めました。","«壬生といえば、かんぴょう»。その始まりは、鳥居忠英が前の領地の近江・水口からゆうがおの種を取り寄せたことだと伝わります。栃木県はいまも、かんぴょうの生産量が日本一。お城の殿様が、町の名産のきっかけをつくったというわけです。","幕末の戊辰戦争では、壬生藩は新政府側につき、近くの安塚などで旧幕府軍と戦いました。明治になると城の建物は取りこわされましたが、本丸のあたりは公園になり、土塁が昔の姿をしのばせます。公園の中には町の歴史民俗資料館があり、城や壬生の歴史を学べます。"],"tl":[["1460年代ごろ","壬生胤業が城を築いたと伝わる（諸説）"],["1590年","壬生義雄が小田原で亡くなり、壬生氏が断絶"],["江戸時代前期","大名が次々と入れかわる"],["1712年","鳥居忠英が壬生藩主になる"],["1868年","戊辰戦争で壬生藩は新政府側につく"],["1871年","廃藩置県"]],"who":[["壬生胤業","壬生城を築いたと伝わる武将"],["壬生義雄","壬生氏最後の当主。後北条氏に味方した"],["鳥居忠英","1712年に壬生藩主となる。かんぴょうを広めたと伝わる"],["鳥居元忠","鳥居家の先祖。伏見城で討ち死にした家康の忠臣"]],"deep":["壬生氏の出自ははっきりしません。京都の官人・小槻氏の流れをくむという説がありますが、確かではありません。","«壬生通り» は、日光街道の小山の北（喜沢の追分）から分かれ、壬生・鹿沼を通って今市で日光街道・例幣使街道と合流する道。日光へ向かう人たちの近道としても使われました。","かんぴょうの伝来は «鳥居忠英が水口から取り寄せた» という話が広く語られていますが、同時代の確かな記録で細かく確かめられたものではなく、伝承として紹介されることが多い話です。","壬生藩の藩主家・鳥居氏は、伏見城の戦いで討ち死にした鳥居元忠の功績から、徳川家に重く用いられた家でした。","戊辰戦争の «安塚の戦い»（1868年）は、壬生城の北の安塚で、壬生藩などの新政府軍と旧幕府軍がぶつかった戦いです。雨の中の激戦だったと伝わります。"],"look":["本丸跡に残る土塁","城址公園の中の壬生町立歴史民俗資料館","堀の名残をしのばせる地形","城下に残る壬生通りの町並み"],"q":["栃木県が生産量日本一の、ゆうがおの実から作る食べものは?","かんぴょう。壬生藩主・鳥居忠英が広めたと伝わります。"],"koji":[],"myth":"築城年・壬生氏の出自、かんぴょう伝来の話は伝承・諸説。","img":["壬生氏","壬生藩","鳥居元忠"],"wp":"壬生城","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Mibuj%C5%8D_honmaru_entrance.JPG",6016,4000,"壬生城"],["c:c/c8/Mitsudomoe_1.png",4000,4000,"壬生氏"],["c:0/0f/Torii_Mototada.jpg",354,501,"鳥居元忠"]]},{"id":"09_unganji","n":"雲巌寺（芭蕉が仏頂和尚を訪ねた寺）","yomi":"うんがんじ","cat":"寺社","y":1283,"era":["kamakura","edo"],"sh":"","rank":"A","ad":"大田原市雲岩寺","st":"車が便利（JR那須塩原駅・西那須野駅から車で約40〜50分）","la":36.866,"lo":140.214,"hook":"朱色の橋をわたると、山の奥に禅の道場。芭蕉は師の «小さな庵のあと» を探して、この山を登った。","lead":"雲巌寺は、鎌倉時代に開かれた臨済宗の禅寺です。今も修行のための道場で、静かな山の中にあります。松尾芭蕉が «おくのほそ道» の旅で訪れ、禅の師である仏頂和尚の庵のあとをたずねました。","story":["黒羽の町から東へ、八溝山地の奥へと車を走らせると、谷川の向こうに朱色の反り橋が見えてきます。その先の石段を登ると、雲巌寺の山門です。この寺を開いたのは、高峰顕日（仏国国師）という禅僧。鎌倉時代の1283年、北条時宗の支援を受けて寺を整えたと伝わります。","高峰顕日は、後嵯峨天皇の皇子といわれる人物です。その弟子の中には、のちに京都で天龍寺を開いた夢窓疎石もいました。«なぜ、こんな山奥に?» 禅の修行には、町のにぎわいから離れた静けさが必要だったからです。雲巌寺は、日本を代表する禅の道場の一つに数えられてきました。","1689年、黒羽に滞在していた松尾芭蕉が、この寺を訪ねます。目的は、自分の禅の師・仏頂和尚が昔ここで暮らした小さな庵のあとを見ることでした。仏頂は «縦横の五尺にたらぬ草の庵…» と、ほんの小さな庵の歌を残していました。«その庵は、まだあるのだろうか»。","寺の裏山を登った芭蕉は、岩のかげに小さな庵を見つけたと «おくのほそ道» に書いています。そして詠んだのが «木啄も庵はやぶらず夏木立»。«木をつつくキツツキも、この庵だけはこわさずにいる» という意味で、師への深い敬意がこもった一句です。","雲巌寺は今も観光のための寺ではなく、修行僧がきびしい修行を続ける場所です。境内には入れますが、建物の中や修行の場には入れないところがあります。静けさを守ることが、何よりのマナー。新緑や紅葉の季節、朱色の橋と深い緑のコントラストは、息をのむ美しさです。"],"tl":[["1283年","高峰顕日が北条時宗の支援を受けて寺を開いたと伝わる"],["鎌倉時代後期","夢窓疎石が高峰顕日に学ぶ"],["江戸時代前期","仏頂和尚が寺の裏山に庵を結ぶ"],["1689年","松尾芭蕉が訪れ «木啄も庵はやぶらず夏木立» を詠む"],["現在","臨済宗妙心寺派の修行道場として続く"]],"who":[["高峰顕日（仏国国師）","雲巌寺を開いた禅僧"],["北条時宗","寺を支援したと伝わる鎌倉幕府の執権"],["夢窓疎石","高峰顕日の弟子。のちに天龍寺を開く"],["仏頂和尚","芭蕉の禅の師。裏山に庵を結んだ"],["松尾芭蕉","師の庵のあとを訪ねて句を残した"]],"deep":["雲巌寺は «日本四大禅道場» の一つとよく紹介されます（ほかに筑前の聖福寺、越前の永平寺、紀伊の興国寺など）。ただし、この数え方には決まった根拠があるわけではなく、言い方にもばらつきがあります。","寺の起こりには、高峰顕日より前に叟元和尚という僧が開いたという伝えもあり、高峰顕日は «中興» ともいわれます。","仏頂和尚は常陸の鹿島・根本寺の住職で、寺の土地をめぐる訴えのため江戸に滞在していたとき、深川の芭蕉と出会ったといわれます。芭蕉の禅への関心に大きな影響を与えた人物です。","«おくのほそ道» の «木啄も» の句は、仏頂の庵が «夏木立» の中にひっそり残っていたことをたたえたもの。キツツキ（啄木鳥）が寺をつつく、という古い言い伝えを踏まえているとする説もあります。","山門へ続く朱塗りの橋は «瓜鉄橋»。この橋と石段、山門が一直線に並ぶ景色が、雲巌寺の顔になっています。"],"look":["朱塗りの反り橋と山門へ続く石段","山門・仏殿の配置（禅宗の伽藍）","芭蕉の句碑","新緑・紅葉の季節の渓谷"],"q":["芭蕉が雲巌寺で詠んだ句 «〇〇も庵はやぶらず夏木立»。〇〇に入る鳥は?","木啄（きつつき）。師の仏頂和尚の庵だけはキツツキもこわさない、という句です。"],"koji":[],"myth":"開山の経緯（叟元和尚の伝え）や «四大禅道場» の数え方は諸説。境内は修行の場のため立ち入りに制限がある。","img":["高峰顕日","夢窓疎石","おくのほそ道"],"wp":"雲巌寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/ef/Tozan_Unganji_Temple_02.jpg",6000,4000,"雲巌寺"],["c:e/ee/Muso_Soseki.jpg",1297,1584,"夢窓疎石"]]},{"id":"09_sesshoseki","n":"殺生石（九尾の狐伝説）","yomi":"せっしょうせき","cat":"伝承","y":1689,"era":["myth","heian","edo"],"sh":"国指定名勝（おくのほそ道の風景地）","rank":"A","ad":"那須郡那須町湯本","st":"JR黒磯駅・那須塩原駅からバスで «那須湯本温泉» 下車、歩いて約5分","la":37.1116,"lo":139.9716,"hook":"都を惑わせた九尾の狐が石になり、近づく生き物の命をうばった――。その石が2022年、まっぷたつに割れた。","lead":"殺生石は、那須湯本温泉の奥の谷にある大きな岩です。美女に化けた九尾の狐が退治されて石になり、毒を出し続けたという伝説があります。じっさいに火山ガスが出る場所で、昔から生き物が死ぬ «こわい石» として知られてきました。","story":["平安時代の終わり、鳥羽上皇のそばに «玉藻前» という、この世のものとは思えないほど美しく賢い女性がいました。ところが上皇は原因不明の病にかかります。陰陽師が占うと、«玉藻前の正体は、インドや中国の国々をほろぼしてきた九尾の狐です»。正体を見破られた狐は、都から東へ逃げていきました。","狐が逃げこんだのが、那須野でした。朝廷は三浦介・上総介という二人の武士に退治を命じます。広い野原を犬を追って走り回り、弓を射る練習をした――これが «犬追物» の始まりだという話まであります。ついに狐は矢に射られて倒れました。","ところが、狐の執念は消えません。狐は大きな石に姿を変え、近づく人や鳥、けものの命をうばい続けました。人々はこれを «殺生石» と呼んで恐れました。やがて室町時代、源翁（玄翁）という僧がやってきて、杖（あるいは金づち）で石を打ち砕き、狐の魂をしずめたと伝わります。大工道具の «げんのう» の名は、この僧から来たといわれます。","«なぜ、本当に生き物が死んだのか?» 答えは火山です。このあたりでは硫化水素などの火山ガスがわき出しています。1689年にここを訪れた松尾芭蕉も、«石の毒気はまだ消えず、蜂や蝶が砂の色が見えないほど重なって死んでいた» という意味のことを «おくのほそ道» に書いています。","2022年3月、この殺生石が二つに割れているのが見つかり、«封印がとけた?» と大きなニュースになりました。専門家は、しみこんだ雨水の凍結などで以前からあったひびが広がったと考えています。いまは遊歩道から、割れた石や千体地蔵をながめられます。ガスが濃い日は立ち入りが制限されることがあるので、案内にしたがいましょう。"],"tl":[["平安時代後期（伝承）","玉藻前（九尾の狐）が那須野で退治され、石になったと伝わる"],["室町時代（伝承）","源翁心昭が石を砕き、狐の霊をしずめたと伝わる"],["室町時代","能 «殺生石» がつくられる"],["1689年","松尾芭蕉が訪れ、«おくのほそ道» に記す"],["2014年","«おくのほそ道の風景地» の一つとして国の名勝に"],["2022年","殺生石が二つに割れているのが見つかる"]],"who":[["玉藻前","伝説の美女。正体は九尾の狐とされる"],["鳥羽上皇","玉藻前を寵愛したと伝わる上皇"],["三浦介・上総介","狐を退治したと伝わる武士"],["源翁心昭","石を砕いたと伝わる曹洞宗の僧"],["松尾芭蕉","殺生石を訪れ、その様子を書き残した"]],"deep":["九尾の狐の伝説は、中国の古い物語（殷の妲己など）ともつながっています。«インド・中国・日本を渡り歩いた妖狐» という壮大な話は、室町〜江戸時代に形を整えていきました。","玉藻前の話は、室町時代の «御伽草子» や、能の «殺生石» で広く知られるようになりました。江戸時代には読本や浮世絵、歌舞伎にも取り上げられます。","大工道具の «玄翁（げんのう）» の名の由来を源翁和尚とする話は有名ですが、語源の確かな証拠があるわけではなく、«そう伝わる» という話です。","殺生石のまわりでは、今も硫化水素などの火山ガスが出ています。くぼ地や風のない日はガスがたまりやすく、昔の人が «近づくと死ぬ» と感じたのは、じっさいの危険を映したものでした。","2022年に割れた殺生石について、地元では狐の霊をしずめる祈願の神事が行われました。伝説の石が、今も人々の心に生きていることを示す出来事です。"],"look":["二つに割れた殺生石（しめ縄がかけられている）","ずらりと並ぶ «千体地蔵»","教傳地蔵と、その由来の話","芭蕉の句碑","近くの温泉神社と «鹿の湯»"],"q":["殺生石を砕いたと伝わる僧の名が由来ともいわれる大工道具は?","«げんのう»（玄翁）。大きな金づちのことです。"],"koji":[{"w":"狐につままれる","m":"わけがわからず、ぼんやりすること。狐が人をだますという昔の考えから生まれたことば"}],"myth":"九尾の狐・玉藻前・源翁の話はすべて伝説。«げんのう» の語源説も確証はない。ガスの状況で立入制限あり。","img":["玉藻前","九尾の狐","源翁心昭"],"wp":"殺生石","rel":{"ev":[],"grave":[]},"ph":[["c:2/27/180727_Sessho-seki_Nasu_Japan14.JPG",6000,4000,"殺生石"],["c:b/ba/SekienTamamo-no-mae.jpg",391,517,"玉藻前"],["c:0/05/NineTailsFox.JPG",219,209,"九尾の狐"]]},{"id":"09_nasu_jinja","n":"那須神社（那須与一ゆかり）","yomi":"なすじんじゃ","cat":"寺社","y":1185,"era":["heian","edo"],"sh":"国の重要文化財（本殿・楼門など）","rank":"A","ad":"大田原市南金丸","st":"JR野崎駅・西那須野駅から車で約15分。道の駅 «那須与一の郷» のとなり","la":36.829,"lo":140.0485,"hook":"«南無八幡大菩薩…» 波にゆれる扇の的を前に、那須与一が心の中で祈った神さまのひとつが、ここにいると伝わる。","lead":"那須神社は、昔は «金丸八幡宮» と呼ばれた神社です。源平の屋島の戦いで、扇の的を射落とした那須与一がこの神社に戦勝を祈ったと伝わります。江戸時代に黒羽藩主の大関氏が建てた本殿や楼門が残り、国の重要文化財になっています。","story":["1185年、四国の屋島。源氏と平家が海と陸でにらみ合うなか、平家の小舟に若い女性が立ち、竿の先に扇をかかげました。«この扇を射てみよ»。源義経は、下野の若武者・那須与一に命じます。海は風が強く、舟は波にゆれ、扇はくるくると動いていました。","与一は目を閉じて祈ります。«南無八幡大菩薩、わが国の神明、日光権現、宇都宮、那須の湯泉大明神、どうかあの扇の真ん中を射させたまえ»。«平家物語» に描かれた有名な場面です。放たれた矢は見事に扇を射ぬき、扇は夕日の海に舞い落ちました。源平両軍から、どよめきが起こったといいます。","那須神社は、その与一が出陣の前に戦勝を祈ったと伝わる八幡宮です。戦いのあと、与一は感謝をこめて社殿を建てたり、土地を寄進したりしたとも語られています。«なぜ八幡さま?» 八幡神は源氏の守り神。源氏の軍に加わった与一にとって、いちばん頼りにしたい神さまでした。","江戸時代になると、この地を治めた黒羽藩の大関氏が神社をあつく敬いました。いま見ることのできる本殿や楼門は、江戸時代の前期に大関氏が建てたもので、あざやかな彩色や彫刻が残っています。那須の地に、江戸の神社建築の美しさを伝える貴重な建物です。","神社のとなりには道の駅 «那須与一の郷» と «那須与一伝承館» があり、与一の物語を人形劇や展示で楽しめます。杉の大木に囲まれた参道を歩き、朱色の楼門をくぐれば、840年前の弓の名人の緊張が、少しだけ伝わってくるかもしれません。"],"tl":[["平安時代（伝承）","金丸八幡宮として祀られる"],["1185年","屋島の戦い。那須与一が扇の的を射落とす"],["鎌倉時代（伝承）","与一が社殿を寄進したと伝わる"],["江戸時代前期","黒羽藩主・大関氏が本殿・楼門などを建てる"],["明治時代","那須神社と改める"],["現代","本殿・楼門などが国の重要文化財に指定"]],"who":[["那須与一","屋島で扇の的を射落とした下野の武士"],["源義経","与一に扇を射るよう命じた源氏の大将"],["大関氏","黒羽藩主。江戸時代に社殿を整えた"],["那須氏","与一の一族。下野北部を治めた武士団"]],"deep":["«平家物語» では、与一が祈った神々として «日光権現・宇都宮・那須の湯泉大明神» の名があがります。いずれも下野の神々で、与一の故郷への思いが表れています。","那須与一の本名は «那須宗隆»（のちに資隆）とされますが、史料によって名前や生涯のくわしいところには違いがあり、はっきりしないことも多い人物です。","扇の的の場面は «平家物語» の名場面ですが、鎌倉幕府の記録 «吾妻鏡» には与一の活躍が見えず、どこまで史実かは議論があります。","本殿・拝殿・楼門は江戸時代前期の建物とされ、黒羽藩の大関氏が那須の総鎮守としてこの神社を重んじたことがわかります。","大田原市では毎年、与一の伝説にちなんだ催しが開かれ、«与一» は市のシンボルになっています。道の駅の名前も与一から取られました。"],"look":["朱色の楼門（国の重要文化財）","本殿の彫刻と彩色","杉並木の参道","となりの «那須与一伝承館»"],"q":["屋島の戦いで、那須与一が射落としたものは何?","平家の小舟に立てられた «扇の的»。«平家物語» の名場面です。"],"koji":[{"w":"南無八幡大菩薩","m":"«八幡さま、どうかお守りください» という祈りのことば。武士が大事な場面で唱えた"}],"myth":"与一の戦勝祈願・社殿寄進は伝承。扇の的の場面自体も «平家物語» による話で史実性は議論がある。","img":["那須与一","屋島の戦い","那須氏"],"wp":"那須神社","rel":{"ev":[],"grave":[]},"ph":[["c:b/bc/Nasu-jinja%2C_roumon-1.jpg",5552,3690,"那須神社"],["c:6/64/NasunoYoichi.jpg",1260,961,"那須与一"],["c:4/48/Battle_of_Yashima_Folding_Screens_Kano_School.jpg",10969,4896,"屋島の戦い"],["c:6/65/%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%88%E4%B8%B8%E3%81%AB%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%89%E7%B4%8B.png",4000,4000,"那須氏"]]},{"id":"09_shinkyo","n":"神橋（日光山内の入口）","yomi":"しんきょう","cat":"寺社","y":1636,"era":["nara","edo","meiji"],"sh":"国の重要文化財・世界遺産（日光の社寺）","rank":"A","ad":"日光市上鉢石町","st":"東武日光駅・JR日光駅からバスで «神橋» 下車すぐ（歩いて約20分）","la":36.7535,"lo":139.604,"hook":"聖なる山へ渡るための朱の橋。はじまりは、大蛇の背中だったと伝わる。","lead":"神橋は、日光の大谷川にかかる朱塗りの美しい木の橋です。日光二荒山神社の建物で、日光の社寺の入口にあたります。昔は将軍や勅使など特別な人しか渡れませんでしたが、いまは料金を払えば渡ることができます。","story":["奈良時代の終わり、勝道上人という僧が、男体山を目指して日光の山に分け入りました。ところが目の前には、岩をかむように流れる大谷川。とても渡れません。上人が一心に祈ると、川の向こうに赤と青の着物を着た «深沙大王» という神があらわれ、二匹の大蛇を放ちました。","大蛇は川の両岸にかかり、その背中に山菅（やますげ）が生えて橋になりました。上人はその上を渡り、日光の山を開いたと伝わります。そのため神橋は «山菅の蛇橋（じゃばし）» とも呼ばれます。橋のたもとの深沙王堂は、この伝説の神を祀っています。","江戸時代、日光に徳川家康を祀る東照宮ができると、神橋はとても大切な橋になりました。いまのような朱塗りの反り橋の姿になったのは、三代将軍・家光による寛永の大造替のころと考えられています。«なぜ特別な人しか渡れなかったのか?» 神橋は、神の山へ入る «神聖な入口» だったからです。ふつうの人は、そばの仮橋を渡りました。","1902年、日光を大水害がおそいます。濁流が神橋を押し流してしまいました。けれども人々はあきらめず、2年後の1904年に元の姿で再建しました。いま私たちが見ている橋は、この再建された橋を修理しながら守ってきたものです。","1999年、神橋は «日光の社寺» の一つとして世界遺産に登録されました。朱色の橋と、深い緑、そして白く泡立つ大谷川の流れ。その色の組み合わせは、季節ごとに表情を変えます。橋の上から見下ろす川は、勝道上人が見たのと同じ激しさで流れています。"],"tl":[["766年ごろ（伝承）","勝道上人が大蛇の橋を渡り、日光の山を開いたと伝わる"],["1636年ごろ","寛永の大造替のころ、朱塗りの反り橋の姿に整えられる"],["1902年","大水害で流される"],["1904年","元の姿で再建"],["1944年","国の重要文化財に指定"],["1999年","«日光の社寺» として世界遺産に登録"]],"who":[["勝道上人","日光の山を開いた僧。神橋の伝説の主人公"],["深沙大王","大蛇を放って橋をかけたと伝わる神"],["徳川家光","寛永の大造替で日光を大きく整えた三代将軍"]],"deep":["神橋は、橋脚に石の柱を使い、そこから木のはね木を川に向かって段々にせり出させる «刎橋（はねばし）» に近い造りです。川の中に柱を立てにくい急流に合わせた工夫です。","«日本三大奇橋» の一つに数えられることがあります（ほかに山口の錦帯橋、山梨の猿橋など）。どの橋を三つに入れるかには、いくつかの言い方があります。","江戸時代、神橋を渡れたのは将軍や勅使、日光例幣使など限られた人だけだったといわれます。一般の人が渡れるようになったのは、ずっと後のことです。","1902年の水害は、日光の町と中禅寺湖のあたりに大きな被害をもたらしました。同じ水害で、中禅寺も今の場所へ移ることになりました。","橋のたもとには «深沙王堂» があり、勝道上人の像も立っています。伝説と史跡がセットで見られる場所です。"],"look":["朱塗りの反り橋と、石の橋脚","橋の上から見る大谷川の急流","橋のたもとの深沙王堂","勝道上人の像","となりの «日光橋» から見る神橋の全景"],"q":["神橋のもとになったと伝わる、神が放った生き物は?","二匹の大蛇。その背に山菅が生えて橋になったので «山菅の蛇橋» とも呼ばれます。"],"koji":[],"myth":"勝道上人と深沙大王・大蛇の話は伝説。現在の姿になった時期には諸説ある。","img":["日光二荒山神社","勝道","日光の社寺"],"wp":"神橋","rel":{"ev":["k_nikko"],"grave":[]},"ph":[["c:a/a2/Shinkyo_Sacred_Bridge_%2811284693104%29.jpg",4573,3049,"神橋"],["c:e/ed/Nikko_Futarasan_Jinja_M3292.jpg",1250,747,"日光二荒山神社"],["c:2/2f/Japan-_Nikko_Statue_of_Sh%C5%8Dd%C5%8D_Sh%C5%8Dnin_2008.jpg",1200,850,"勝道"],["c:3/35/Nikko_toshogu_shrine.jpg",6000,4000,"日光の社寺"]]},{"id":"09_tamozawa","n":"日光田母沢御用邸","yomi":"にっこうたもざわごようてい","cat":"近代","y":1899,"era":["meiji","taisho","showa"],"sh":"国の重要文化財","rank":"A","ad":"日光市本町","st":"JR日光駅・東武日光駅からバスで «日光田母沢御用邸記念公園» 下車すぐ","la":36.7498,"lo":139.5878,"hook":"江戸・明治・大正、三つの時代の建物がひとつにつながる、部屋数100をこえる皇室の «夏の家»。","lead":"日光田母沢御用邸は、明治時代に大正天皇（当時は皇太子）の静養のために造られた御用邸です。江戸時代の大名屋敷の一部、明治の建物、大正の建物がつながった、全国でもめずらしい建物です。いまは記念公園として公開されています。","story":["明治の中ごろ、日光は外国人や政府の人々に人気の避暑地になっていました。1899年、体の弱かった皇太子（のちの大正天皇）のために、ここに御用邸がつくられます。«涼しい日光で、ゆっくり休んでほしい» という願いがこめられていました。","この御用邸の面白いところは、建物の «生まれ» がばらばらなこと。もとになったのは、日光出身の銀行家・小林年保の別邸でした。そこに、東京・赤坂にあった旧紀州徳川家の江戸中屋敷の一部が運ばれてきて組みこまれました。江戸時代の大名屋敷が、そのまま日光にお引っ越ししてきたのです。","大正天皇は即位したあとも、この御用邸をたいへん気に入って、たびたび訪れました。大正時代には大きく増築され、部屋数は100をこえるほどになります。«なぜこんなに部屋が?» 天皇だけでなく、おつきの人々が暮らし、働く場所も必要だったからです。謁見所、御座所、御食堂、そして女官たちの部屋が、長い廊下でつながっています。","太平洋戦争の終わりごろ、皇太子だった明仁親王（いまの上皇さま）が、空襲を避けて日光へ疎開し、この御用邸でも過ごしました。静かな山の中の御用邸は、戦争の時代とも深くかかわっていたのです。","戦後の1947年、御用邸は廃止されました。その後、栃木県が修理を行い、2000年に «日光田母沢御用邸記念公園» として公開されます。畳の廊下、ビリヤード台のある部屋、美しい庭。三つの時代の空気を、ゆっくりと歩いて味わうことができます。"],"tl":[["江戸時代","旧紀州徳川家の江戸中屋敷（のちに一部が移築される）"],["1899年","皇太子（のちの大正天皇）の静養のため御用邸が造られる"],["大正時代","大規模な増築で今の姿に近づく"],["1944年ごろ","皇太子明仁親王が日光へ疎開"],["1947年","御用邸が廃止される"],["2000年","記念公園として公開"],["2003年","国の重要文化財に指定"]],"who":[["大正天皇","皇太子時代から御用邸を愛用した"],["小林年保","日光出身の銀行家。その別邸が御用邸のもとになった"],["紀州徳川家","江戸屋敷の一部がこの御用邸に組みこまれた"],["明仁親王（上皇）","戦争中、日光へ疎開した"]],"deep":["建物は、江戸時代後期の紀州徳川家の建物、明治の建物、大正の増築部分の三つが組み合わさっています。一つの建物で三つの時代の建築を比べられるのは、とてもめずらしいことです。","部屋の数は100をこえ、現存する明治・大正期の御用邸の中では最大級の規模といわれます。","紀州徳川家の中屋敷は、のちに赤坂離宮のあたりとなった場所にありました。その一部が明治の御用邸に使われ、さらに日光へ移されたと説明されています。","大正天皇はこの御用邸で夏を過ごすことが多く、天皇の静養の様子を伝える品や家具も展示されています。","明治時代の日光には、田母沢のほかに «日光山内御用邸» もありました。外国人の避暑地としても知られた日光は、皇室にとっても大切な静養の地だったのです。"],"look":["紀州徳川家から移された «三階建て» 部分","謁見所・御座所など天皇の部屋","長い畳廊下","ビリヤードの部屋（玉突き所）","季節の庭園（しだれ桜や紅葉）"],"q":["田母沢御用邸は、主にどの天皇のために造られた?","大正天皇（皇太子時代の1899年に造られた）です。"],"koji":[],"myth":"明仁親王の疎開の時期・滞在の細部は資料により説明が異なる。","img":["大正天皇","御用邸","紀州藩"],"wp":"日光田母沢御用邸記念公園","rel":{"ev":[],"grave":[]},"ph":[["c:b/ba/Tamozawa06.jpg",568,426,"日光田母沢御用邸記念公園"],["c:3/33/Emperor_Taish%C5%8D.jpg",1267,1779,"大正天皇"],["c:b/b7/Wakayama_Castle_2011_Kuruwa.jpg",1936,1296,"紀州藩"]]},{"id":"09_chuzenji","n":"中禅寺（立木観音）","yomi":"ちゅうぜんじ（たちきかんのん）","cat":"寺社","y":784,"era":["nara","meiji"],"sh":"国の重要文化財（木造千手観音立像）","rank":"A","ad":"日光市中宮祠（歌ヶ浜）","st":"東武日光駅・JR日光駅からバスで «中禅寺温泉» 下車、湖ぞいに歩いて約20分","la":36.7297,"lo":139.488,"hook":"根を張ったまま立っていた木に、そのまま観音さまを彫った――。湖のほとりに «生きた木の仏さま» が立つ。","lead":"中禅寺は、日光を開いた勝道上人が、中禅寺湖のほとりに開いたと伝わるお寺です。本尊の «立木観音» は、立っている桂の木にそのまま彫られたといわれる千手観音。今は日光山輪王寺の別院で、坂東三十三観音の第18番札所です。","story":["奈良時代の終わり、勝道上人は何度も失敗しながら、ついに男体山の頂上に立ちました。山の上から見下ろすと、青く光る大きな湖。それが中禅寺湖でした。上人はこの湖のほとりに寺を開いたと伝わります。784年のことだとされます。","寺の本尊には、ふしぎな言い伝えがあります。湖の上に千手観音の姿があらわれ、上人はそれを、湖のそばに立っていた桂の大木に彫りつけた――。根が地面にはったままの «立ち木» に彫ったので «立木観音» と呼ばれます。«木が生きたまま仏さまになった» という考え方に、山や木を神聖なものと見る日本人の心が表れています。","もともと中禅寺は、男体山への登り口、いまの二荒山神社中宮祠のあたりにありました。ところが1902年、大雨による山津波（土石流）が寺をおそいます。立木観音は湖に流されましたが、のちに見つけ出されたと伝わります。«なぜ、場所が変わったのか?» この災害をきっかけに、寺は湖の東岸の歌ヶ浜へ移り、今の姿になりました。","境内の五大堂からは、中禅寺湖と男体山が一望できます。天井には大きな龍の絵が描かれ、その迫力に思わず見上げてしまいます。春の新緑、秋の紅葉の季節には、湖の色と山の色が重なって、まるで絵の中にいるようです。","立木観音の高さは、約6メートル。堂の中で見上げると、千本の手（実際には数を略した手）が大きく広がり、静かな顔で湖の方を見守っています。1200年以上前の上人の祈りが、湖畔の森のなかで今も続いています。"],"tl":[["782年","勝道上人が男体山の頂上に立ったと伝わる"],["784年","勝道上人が中禅寺を開いたと伝わる"],["平安時代","立木観音（千手観音立像）がつくられたとみられる"],["1902年","山津波で被害を受ける"],["1904年ごろ","湖の東岸・歌ヶ浜に移る"],["現在","輪王寺の別院として、坂東三十三観音の札所巡りの人々を迎える"]],"who":[["勝道上人","男体山を開き、中禅寺を開いたと伝わる僧"],["千手観音","中禅寺の本尊。立木観音と呼ばれる"],["輪王寺","中禅寺はその別院"]],"deep":["立木観音は木造の千手観音立像で、国の重要文化財です。«勝道上人が彫った» というのは伝承で、美術史の研究からは平安時代の作と考えられています。","«立ち木に彫った仏» という伝えは各地にあり、木に宿る神と仏を重ねる «神仏習合» の考え方をよく表しています。","1902年の山津波は、日光に大水害をもたらし、同じ年に神橋も流されました。中禅寺の移転はこの災害の結果です。","中禅寺は坂東三十三観音の第18番札所。関東をめぐる巡礼の人々が、はるばる奥日光まで足をのばしてきました。","中禅寺湖は、男体山の噴火でせき止められてできた湖と考えられています。湖と山と寺が一つの景色になっているのは、こうした自然の成り立ちのおかげです。"],"look":["本尊・立木観音（千手観音立像）","五大堂の天井の龍の絵と、湖・男体山の眺め","愛染堂や鐘楼","湖畔の歌ヶ浜の景色"],"q":["中禅寺の本尊が «立木観音» と呼ばれるのはなぜ?","根が張ったままの立ち木（桂の木）に彫られたと伝わるからです。"],"koji":[],"myth":"勝道上人の開創年・立木観音を上人が彫った話は伝承。1902年に観音が湖から引き上げられた話も伝え。","img":["中禅寺湖","男体山","坂東三十三箇所"],"wp":"中禅寺 (日光市)","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"中禅寺湖"]]},{"id":"09_utsunomiya_battle","n":"宇都宮城の戦い（戊辰戦争）","yomi":"うつのみやじょうのたたかい","cat":"幕末","y":1868,"era":["edo","meiji"],"sh":"","rank":"A","ad":"宇都宮市本丸町（宇都宮城址公園）","st":"JR宇都宮駅西口から歩いて約20分、東武宇都宮駅から約10分","la":36.5567,"lo":139.884,"hook":"わずか数日のうちに、城は奪われ、奪い返された。炎に包まれた宇都宮で、土方歳三も傷を負った。","lead":"1868年（慶応4年）4月、戊辰戦争のさなか、宇都宮城をめぐって旧幕府軍と新政府軍がはげしく戦いました。旧幕府軍がいったん城を落としましたが、数日後には新政府軍が奪い返します。戦いで城と町の多くが焼けました。いまは城址公園に、土塁と櫓が復元されています。","story":["1868年4月、江戸城が新政府軍に明けわたされました。«このまま終われない»。それを受け入れられない旧幕府の兵たちは江戸を脱け出し、北へ向かいます。その中心にいたのが、幕府の歩兵を率いた大鳥圭介、そして新選組の副長だった土方歳三でした。","旧幕府軍は小山で新政府軍を破ると、宇都宮城に迫りました。4月19日、土方らの隊が城に攻めかかります。城を守っていた宇都宮藩や新政府軍の兵は支えきれず、城は旧幕府軍の手に落ちました。このとき城下では火の手が上がり、町の多くが焼けてしまったといわれます。","«城を取ったのに、なぜすぐ守れなかったのか?» 旧幕府軍は数では少なくなかったものの、弾薬や食料が十分ではありませんでした。一方、新政府軍は薩摩・長州・大垣などの兵を送りこみ、南の壬生の方から反撃を始めます。壬生の近くの安塚でも激しい戦いがありました。","4月23日、新政府軍は宇都宮城を攻め、ふたたび城を取り戻しました。この戦いで土方歳三は足にけがをして、戦線を離れて会津へ向かいます。大鳥圭介の軍も日光へ退き、戦いの舞台はさらに北の会津へと移っていきました。わずか数日間に、城は二度も持ち主を変えたのです。","城下の町と、多くの兵士や町の人々が戦いの犠牲になりました。宇都宮二荒山神社もこのとき焼けたと伝わります。いま、城址公園では本丸の土塁の一部と清明台・富士見櫓が復元され、市内には戊辰戦争で亡くなった人々の墓や碑が残っています。静かな公園を歩くとき、この町が一度炎に包まれたことを思い出してみてください。"],"tl":[["1868年4月11日","江戸城が新政府軍に明けわたされる（旧暦）"],["1868年4月16〜17日","小山周辺で戦い（旧暦）"],["1868年4月19日","旧幕府軍が宇都宮城を攻め落とす（旧暦）"],["1868年4月22日","安塚の戦い（旧暦）"],["1868年4月23日","新政府軍が宇都宮城を奪い返す。土方歳三が負傷（旧暦）"],["2007年","宇都宮城址公園として本丸の一部を復元"]],"who":[["大鳥圭介","旧幕府軍を率いた指揮官。のちに箱館まで戦う"],["土方歳三","新選組副長。宇都宮で城を攻め、奪回戦で負傷"],["伊地知正治","薩摩藩士。新政府軍の指揮にあたった"],["香川敬三","新政府軍の将として宇都宮に入った"],["戸田氏","宇都宮藩主の家。新政府側についた"]],"deep":["旧幕府軍の中心は、フランス式の訓練を受けた «伝習隊»。近代的な歩兵部隊でしたが、補給が弱く、城を長く守ることはできませんでした。","土方歳三が宇都宮の戦いで足を負傷したことは、多くの記録から知られています。その後、土方は会津で療養し、やがて箱館（函館）で最期をむかえました。","宇都宮城は、江戸時代には将軍が日光社参のときに泊まる大切な城でした。«釣天井事件» の伝説（本多正純が将軍をねらったという話）でも知られますが、これは後世の作り話とされています。","戦いの死者の数は資料によって違い、正確にはわかっていません。旧幕府軍・新政府軍の双方の墓や供養碑が、市内の寺などに残されています。","宇都宮城址公園の復元は、発掘調査と江戸時代の絵図をもとにしたもの。土塁の内部は資料館や展示スペースとして利用されています。"],"look":["復元された清明台と富士見櫓","本丸の土塁と堀","公園内の資料展示（土塁の中の展示スペース）","市内に残る戊辰戦争の戦死者の墓や碑"],"q":["宇都宮城の戦いで足を負傷した、新選組の副長はだれ?","土方歳三。このあと会津へ向かい、最後は箱館で戦いました。"],"koji":[],"myth":"日付は旧暦。死者数や焼けた範囲は資料により異なる。釣天井事件は伝説。","img":["宇都宮城","大鳥圭介","土方歳三"],"wp":"宇都宮城の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/UtsunomiyaCastle.jpg",1051,1087,"宇都宮城の戦い"],["c:b/b6/Utsunomiya-jo_fujimi-yagura.jpg",2896,1936,"宇都宮城"],["c:4/4c/Otori_Keisuke.jpg",1024,1327,"大鳥圭介"],["c:e/ee/Hijikata_Toshizo.jpg",528,924,"土方歳三"]]},{"id":"09_ohirasan","n":"太平山神社（天狗党挙兵の地）","yomi":"おおひらさんじんじゃ","cat":"幕末","y":1864,"era":["heian","edo"],"sh":"","rank":"A","ad":"栃木市平井町","st":"JR・東武栃木駅からバスで «国学院前» 下車、あじさい坂を歩いて約30分。車で山上の駐車場へも行ける","la":36.4065,"lo":139.689,"hook":"水戸の若き志士たちが、1か月以上もたてこもった山。境内から見下ろす関東平野は、彼らにどう見えたのだろう。","lead":"太平山神社は、栃木市の太平山の山頂近くにある古い神社です。幕末の1864年、筑波山で挙兵した水戸藩の «天狗党» が、この山に1か月以上とどまりました。いまは «あじさい坂» や桜、眺めのよい «謙信平» で知られる名所です。","story":["太平山神社は、平安時代のはじめに慈覚大師円仁が開いたと伝わる神社です。山の上からは関東平野が一望でき、天気のよい日には富士山や筑波山まで見えます。戦国時代、上杉謙信がここから関東平野の広さに感心したという伝えがあり、その場所は «謙信平» と呼ばれています。","1864年3月、水戸藩の尊王攘夷派の若者たちが、筑波山で兵を挙げました。中心にいたのは、藤田東湖の息子・藤田小四郎。まだ20代前半の若者でした。«外国を打ち払い、幕府に攘夷を実行させる»。彼らは «天狗党» と呼ばれました。","筑波山を出た天狗党は、徳川家康をまつる日光東照宮を目指しました。«家康公の前で、自分たちの志を示したい»。しかし日光での滞在は認められず、彼らは南へ下って太平山に入ります。そして4月から5月にかけて、1か月以上ここにとどまり、仲間を集め、資金を集めました。","«なぜ太平山だったのか?» 山の上は守りやすく、近くの栃木の町は商業で栄えていて、資金や食料を集めやすかったからと考えられています。しかし、資金集めは町の人々にとって大きな負担でした。やがて天狗党の中の一部隊を率いた田中愿蔵が、栃木の町に火を放つ事件を起こし、多くの家が焼けてしまいます。","天狗党はその後、筑波山に戻り、幕府軍との戦いをへて、最後は京都を目指す長い行軍に出ます。そして越前で降伏し、多くの人が処刑されるという悲しい結末をむかえました。太平山の静かな境内には、若者たちの熱い思いと、その陰で苦しんだ町の人々の記憶が重なっています。"],"tl":[["827年（伝承）","慈覚大師円仁が開いたと伝わる"],["戦国時代（伝承）","上杉謙信が山上から関東平野を眺めたと伝わる（謙信平）"],["1864年3月","天狗党が筑波山で挙兵"],["1864年4〜5月","天狗党が太平山に1か月以上とどまる"],["1864年6月","田中愿蔵の隊が栃木の町に火を放つ（愿蔵火事）"],["1865年","天狗党の多くが越前で処刑される"]],"who":[["藤田小四郎","天狗党の中心人物。藤田東湖の息子"],["田中愿蔵","天狗党の一隊を率い、栃木の町を焼いた"],["武田耕雲斎","天狗党の首領として西上を率いた水戸藩士"],["慈覚大師円仁","神社を開いたと伝わる天台宗の僧"],["上杉謙信","謙信平の名の由来となった戦国武将"]],"deep":["天狗党が兵を挙げたのは筑波山で、太平山は «その後の拠点»。«太平山で挙兵した» と紹介されることもありますが、正確には筑波山での挙兵のあと、ここに移ってきたという順番です。","«天狗党» という名前は、水戸藩内で改革派が «天狗» と呼ばれたことから来ているといわれます。«鼻が高い（えらそう）» という悪口だったとも説明されます。","«愿蔵火事» では、栃木の町の多くが焼けたと伝わり、町の人々の記憶に長く残りました。天狗党の中でも、田中愿蔵の隊は乱暴な行いが多く、本隊からも離れて行動するようになったといわれます。","天狗党の西上の旅は、中山道をへて越前（福井県）へ至る長い道のり。降伏した人々のうち、多くが処刑されるという、幕末でも特に悲しいできごとでした。","太平山神社の参道 «あじさい坂» は約1000段の石段といわれ、6月には両側をあじさいが彩ります。山上の茶屋の «玉子焼き・焼き鳥・団子» も名物です。"],"look":["随神門と、そこへ続く «あじさい坂»","山上から関東平野を見わたす «謙信平»","本殿と境内の摂社","春の桜、初夏のあじさい"],"q":["天狗党が最初に兵を挙げた山は、太平山? 筑波山?","筑波山。そのあと日光をへて太平山に移り、1か月以上とどまりました。"],"koji":[{"w":"尊王攘夷","m":"天皇を敬い、外国を打ち払おうという幕末の考え方"}],"myth":"円仁の開創・謙信平の由来は伝承。天狗党の滞在期間や愿蔵火事の被害規模は資料で差がある。","img":["天狗党の乱","藤田小四郎","武田耕雲斎"],"wp":"太平山神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/51/Ohirasan_shrine-haiden%2Ctochigi-city%2Cjapan.jpg",3872,2592,"太平山神社"],["c:e/e1/Tenguto_no_ran.jpg",2116,1034,"天狗党の乱"],["c:4/4b/Takeda_kounsai.jpg",320,612,"武田耕雲斎"]]},{"id":"09_reiheishi","n":"日光例幣使街道","yomi":"にっこうれいへいしかいどう","cat":"街道","y":1647,"era":["edo"],"sh":"国指定特別史跡（日光杉並木街道の一部）","rank":"A","ad":"栃木市（栃木宿）ほか","st":"JR・東武栃木駅から歩いて約15分で旧栃木宿の蔵の町並み","la":36.383,"lo":139.733,"hook":"京都から毎年、天皇の使いが日光へ。その «お使い» のためにできた道が、いまも蔵の町を通っている。","lead":"日光例幣使街道は、中山道の倉賀野宿（群馬県）から日光へ向かう道です。江戸時代、京都の朝廷から日光東照宮へ毎年 «例幣使» という使いが送られ、その一行が通ったことからこの名がつきました。栃木県内には栃木宿や金崎宿などがあり、今も蔵の町並みが残ります。","story":["徳川家康が亡くなり、日光に東照宮がまつられると、幕府は朝廷に «毎年、東照宮に使いを出してほしい» と願いました。こうして1647年から、京都の公家が毎年、日光へ幣帛（神へのささげもの）を運ぶことになります。これが «日光例幣使»。例幣使は中山道を東へ進み、倉賀野宿から分かれて日光へ向かいました。","栃木県に入ると、道は八木・梁田（足利市）、天明・犬伏（佐野市）、富田、栃木、合戦場、金崎を通り、楡木で壬生通りと合流し、今市で日光街道とつながります。一行は毎年、ほぼ同じ時期に同じ道を通りました。沿道の宿場は、その準備と接待に追われたのです。","例幣使は、天皇の使いという立場。道中では «特別な身分» として丁重に扱われました。ところが、評判はあまり良くなかったといわれます。«駕籠をわざとゆらして自分から落ち、宿場の人にお金をせびった» という話まで伝わっていて、これを «入魂（じっこん）» と呼んだとか。どこまで本当かはわかりませんが、宿場の人々の負担の大きさがうかがえます。","街道の宿場の中でも栄えたのが栃木宿です。町のそばを流れる巴波川（うずまがわ）は、江戸へ荷物を運ぶ舟の道でした。材木や麻などが江戸へ送られ、江戸からはさまざまな品が運ばれてきます。商人たちは豊かになり、白壁の蔵を建てました。いまの «蔵の街» の風景は、この時代の繁栄のなごりです。","例幣使の派遣は、1867年まで続きました。明治になると例幣使はなくなりましたが、道は今も国道や県道として生きています。今市のあたりでは、街道の両側に杉の大木が並ぶ «日光杉並木» が続き、江戸時代の旅人と同じ木陰を歩くことができます。"],"tl":[["1617年","徳川家康が日光にまつられる"],["1646年","朝廷が日光東照宮へ奉幣使を送る（翌年から毎年の例幣使が始まったとされる）"],["1647年","毎年の日光例幣使の派遣が始まる"],["江戸時代","栃木宿が巴波川の舟運で栄える"],["1867年","例幣使の派遣が終わる"],["1952年","日光杉並木街道が特別史跡に（例幣使街道の一部を含む）"]],"who":[["例幣使","毎年日光へ幣帛を運んだ朝廷の使い（公家）"],["徳川家康","日光東照宮にまつられた神（東照大権現）"],["松平正綱","日光の杉並木を植えた人物"],["栃木宿の商人","舟運で栄え、蔵を建てた"]],"deep":["例幣使は、ふつう4月1日に京都を出発し、4月15日の東照宮の例祭に合わせて日光に着くように旅をしたといわれます。帰りは江戸を通って東海道で京都へ戻ったとされます。","«入魂（じっこん）» の話は、例幣使のわがままぶりを伝える話として有名ですが、具体的な記録で確かめられたというより、沿道で語り継がれた話と考えたほうがよいでしょう。","例幣使街道は、正式には «日光例幣使道»。五街道（日光道中など）とは別の «脇往還» の一つでした。","日光杉並木は、日光街道・例幣使街道・会津西街道の三つにまたがり、全体で約37kmにおよびます。国の特別史跡と特別天然記念物の «二重指定» を受けている、めずらしい文化財です。","栃木の町の蔵造りは、明治以降に建てられたものも多く含まれます。江戸から明治にかけて、商都・栃木の繁栄が長く続いたことを示しています。"],"look":["栃木宿の蔵の町並みと巴波川","嘉右衛門町の伝統的な町並み","今市付近の日光杉並木","宿場の名残の本陣跡や道標"],"q":["日光例幣使は、毎年どこからどこへ使いに行った?","京都の朝廷から、日光東照宮へ。ささげもの（幣帛）を届けました。"],"koji":[],"myth":"«入魂» の話は伝承。例幣使の開始年は1646年とする説と1647年とする説がある。","img":["日光東照宮","日光杉並木","巴波川"],"wp":"日光例幣使街道","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"],["c:8/8f/%E6%97%A5%E5%85%89%E6%9D%89%E4%B8%A6%E6%9C%A8%E8%A1%97%E9%81%93_20130522_-_panoramio.jpg",2736,1824,"日光杉並木"],["c:9/9e/%E6%A0%83%E6%9C%A8%E5%B8%82%E4%B8%AD%E5%BF%83%E9%83%A8%E3%82%92%E6%B5%81%E3%82%8C%E3%82%8B%E5%B7%B4%E6%B3%A2%E5%B7%9D.JPG",1632,1224,"巴波川"]]},{"id":"09_nikko_kaido","n":"日光街道（宇都宮宿〜鉢石宿）","yomi":"にっこうかいどう","cat":"街道","y":1648,"era":["edo"],"sh":"国指定特別史跡・特別天然記念物（日光杉並木街道）","rank":"A","ad":"日光市今市・瀬川ほか（日光杉並木）","st":"東武下今市駅・JR今市駅から歩いて約10分で杉並木","la":36.724,"lo":139.669,"hook":"一人の大名が20年以上かけて植えた杉が、400年たって世界一長い並木道になった。","lead":"日光街道は、江戸の日本橋から日光へ向かう、五街道の一つです。宇都宮宿で奥州街道と分かれ、徳次郎・大沢・今市をへて、日光の入口の鉢石宿へ至ります。今市の前後には «日光杉並木» が続き、国の特別史跡と特別天然記念物になっています。","story":["江戸時代の宇都宮宿。町の中心の «追分» で、道は二つに分かれました。北へまっすぐ行けば白河へ続く奥州街道、北西へ曲がれば日光へ向かう日光街道です。日光には徳川家康をまつる東照宮があり、将軍や大名、お参りの人々がこの道を行き来しました。","宇都宮を出ると、道は徳次郎宿、大沢宿を通って今市宿へ。今市は、日光街道・例幣使街道・会津西街道が集まる交通の要でした。そして最後の宿場が、神橋の手前の鉢石宿。宿場の名は、鉢を伏せたような形の石があったことに由来するといわれます。","この道を語るのに欠かせないのが、杉並木です。家康の家臣だった松平正綱は、1625年ごろから20年以上をかけて、日光へ向かう道の両側に杉を植え続けました。«なぜ、そこまで?» 正綱は大名としては裕福ではなく、東照宮に豪華な灯籠を寄進することができませんでした。そこで、«お金のかわりに、杉を植えよう» と考えたと伝わります。","正綱が杉並木を東照宮に寄進したのは、家康の33回忌にあたる1648年。その証として、並木の出発点などに «寄進碑» が立てられました。植えた杉はおよそ20万本ともいわれ、日光街道・例幣使街道・会津西街道にまたがる、長い長い並木道になりました。","いま残る杉は約1万2千本。樹齢は約370年をこえ、高さ30メートルをこえる木も少なくありません。けれども自動車の排気ガスや道路工事の影響で、年々少しずつ木が減っています。杉並木公園を歩き、見上げるほどの幹にふれるとき、この並木を未来へ残すことの大切さも感じられるはずです。"],"tl":[["1617年","家康の遺体が日光に移され、東照社がまつられる"],["1625年ごろ","松平正綱が杉を植え始める"],["1636年","家光による東照宮の大造替が完成"],["1648年","正綱が杉並木を東照宮に寄進（家康の33回忌）"],["1952年","日光杉並木街道が特別史跡に"],["1954年","特別天然記念物にも指定"]],"who":[["松平正綱","杉並木を植えて東照宮に寄進した大名"],["徳川家康","東照宮にまつられ、日光街道の目的地となった"],["徳川家光","日光社参を重ね、東照宮を大きく造り替えた"],["日光社参の将軍たち","大行列で日光街道を旅した"]],"deep":["日光杉並木は «世界一長い並木道» としてギネス世界記録に認定されています。全長は約37kmといわれます。","松平正綱の «寄進碑» は、杉並木の起点となる場所など計4か所に建てられたとされます。碑には、並木を寄進した経緯が刻まれています。","将軍の日光社参は江戸時代を通して何度も行われ、大行列が日光街道を進みました。宿場や沿道の村は人や馬を出す大きな負担を負いました。","日光街道の宿場のうち、宇都宮は奥州街道との分岐点で、城下町としても栄えた大きな町でした。今市は日光への «最後の中継地» として重要な宿場でした。","杉並木を守るため、栃木県や日光市は «杉並木オーナー制度» などの取り組みを続けています。木の本数は、昔にくらべて大きく減っていることが心配されています。"],"look":["今市の杉並木公園（旧家の水車も見られる）","松平正綱の寄進碑","今市宿のまちなみと «追分地蔵»","鉢石宿から見る神橋"],"q":["日光杉並木を植え、東照宮に寄進した人物は?","松平正綱。20年以上かけて杉を植え、1648年に寄進しました。"],"koji":[],"myth":"正綱が «灯籠のかわりに杉を» と考えた話や植えた本数（約20万本）は伝承・推定。","img":["日光杉並木","松平正綱","日光東照宮"],"wp":"日光街道","rel":{"ev":[],"grave":[]},"ph":[["c:1/10/Nikko_kaido_hasui_kawase.jpg",910,1384,"日光街道"],["c:8/8f/%E6%97%A5%E5%85%89%E6%9D%89%E4%B8%A6%E6%9C%A8%E8%A1%97%E9%81%93_20130522_-_panoramio.jpg",2736,1824,"日光杉並木"],["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"]]},{"id":"09_oshu_kaido","n":"奥州街道（白沢宿〜芦野宿）","yomi":"おうしゅうかいどう","cat":"街道","y":1689,"era":["edo"],"sh":"","rank":"A","ad":"那須郡那須町芦野（遊行柳）ほか","st":"JR黒田原駅から車で約15分（芦野）。車が便利","la":37.0017,"lo":140.1522,"hook":"西行が足を止め、芭蕉が田植えを見つめた柳。北へ向かう旅人の道は、みちのくの入口へ続いていた。","lead":"奥州街道は、江戸時代の五街道の一つで、宇都宮から白河へ向かう道です。栃木県内には白沢・氏家・喜連川・佐久山・大田原・鍋掛・越堀・芦野などの宿場が並びました。芦野には、西行や芭蕉が歌や句を残した «遊行柳» があります。","story":["宇都宮の追分で日光街道と分かれた奥州街道は、北へ向かいます。最初の宿場は白沢宿。鬼怒川をわたる前の宿で、今は水車のある町並みが整えられています。そこから氏家、喜連川と、道はゆるやかな丘と田んぼの間を進みました。","喜連川宿には、ちょっと変わった大名がいました。喜連川氏です。室町時代の足利将軍家の流れをくむ一族で、石高はとても小さいのに、特別に «10万石の格式» を与えられ、参勤交代もしなくてよいとされました。«なぜ?» 足利という名門の血筋を、徳川家が大切に扱ったからです。","さらに北へ、佐久山、大田原、鍋掛、越堀と宿場が続き、那須の山々が近づいてきます。そして栃木県で最後の宿場が芦野。その先、峠をこえれば陸奥の国（福島県）。国境には «境の明神» がまつられ、旅人はここで «いよいよ奥州だ» と気を引きしめました。","芦野の田んぼの中に、一本の柳が立っています。平安時代の終わり、歌人の西行がこの柳の下で休み、«道の辺に清水流るる柳かげ しばしとてこそ立ちどまりつれ» と詠んだと伝わります。のちに、遊行上人（時宗の僧）の前に柳の精があらわれたという伝説もうまれ、«遊行柳» と呼ばれるようになりました。","1689年、西行をしたう松尾芭蕉がこの柳を訪れます。«田一枚植ゑて立ち去る柳かな»。柳の下で思いにふけっていたら、そのあいだに田が一枚植え終わっていた――そんな一瞬を詠んだ句です。芭蕉が西行の歌をたどって歩いた道を、いまの私たちもたどることができます。"],"tl":[["平安時代後期（伝承）","西行が芦野の柳の下で歌を詠んだと伝わる"],["室町時代","謡曲 «遊行柳» がつくられる"],["1590年","足利氏の流れをくむ喜連川氏が喜連川に領地を得る"],["江戸時代","奥州道中として宿場が整えられる"],["1689年","松尾芭蕉が遊行柳を訪れ、句を詠む"],["2014年","遊行柳が «おくのほそ道の風景地» として国の名勝に"]],"who":[["西行","平安時代の歌人。遊行柳の歌で知られる"],["松尾芭蕉","西行をしたって遊行柳を訪れた俳人"],["遊行上人","時宗の僧。柳の精の伝説に登場する"],["喜連川氏","足利氏の流れをくむ喜連川の大名"]],"deep":["江戸幕府が管理した «奥州道中» は、正式には宇都宮から白河までを指すことが多く、その先の仙台・青森方面へ続く道とは区別されました。","喜連川藩の石高は5千石ほどでしたが、足利氏の子孫として «10万石の格式» を与えられた、とても特別な家でした。","«遊行柳» は、謡曲 «遊行柳» の舞台として室町時代から知られていました。柳の精が遊行上人に念仏の功徳を感謝する、という内容です。","遊行柳は、2014年に «おくのほそ道の風景地» の一つとして国の名勝に指定されました。柳は何度も植え替えられながら、今も同じ場所に立っています。","芦野宿には石の «芦野石» を使った建物や、芦野氏の陣屋跡などが残ります。宿場町の落ち着いた雰囲気を楽しめる場所です。"],"look":["芦野の遊行柳と、西行・芭蕉の歌碑・句碑","県境の «境の明神»","白沢宿の水車と町並み","喜連川の町並み（喜連川藩の城下）"],"q":["芭蕉が遊行柳で詠んだ句 «田一枚植ゑて立ち去る〇〇かな»。〇〇は?","«柳»。西行ゆかりの柳の下で、田植えの一瞬を詠みました。"],"koji":[{"w":"道の辺に清水流るる柳かげ","m":"西行が詠んだと伝わる歌の一節。旅の途中でふと立ち止まる心を表す"}],"myth":"西行が芦野で歌を詠んだという話は伝承（歌そのものは新古今和歌集に収める）。","img":["遊行柳","喜連川藩","西行"],"wp":"奥州街道","rel":{"ev":[],"grave":[]},"ph":[["c:e/ef/PORTRAIT_OF_THE_PRIEST-POET_SAIGYO_-_Google_Art_Project.jpg",1262,2549,"西行"]]},{"id":"09_kabasakidera","n":"樺崎寺跡（足利義兼の廟所）","yomi":"かばさきでらあと","cat":"遺跡","y":1189,"era":["kamakura","muromachi"],"sh":"国指定史跡","rank":"A","ad":"足利市樺崎町","st":"JR足利駅・東武足利市駅から車で約15分","la":36.366,"lo":139.492,"hook":"足利将軍家のルーツの地。池の底から浄土の庭がよみがえり、海の向こうでは «運慶の仏» が大きなニュースになった。","lead":"樺崎寺は、鎌倉時代のはじめに足利義兼が開いたお寺です。義兼が葬られた廟所であり、足利氏の一族を代々まつる寺でした。明治時代に廃寺となり、建物はありませんが、発掘調査で大きな池を持つ浄土庭園がよみがえりました。","story":["足利といえば、室町幕府をひらいた足利氏のふるさとです。その足利氏の礎を築いたのが、足利義兼。源頼朝の親戚にあたり、頼朝と深く結びついた武将でした。1189年、奥州の藤原氏との戦いに勝てるよう祈って、この樺崎の谷に寺を開いたと伝わります。","義兼は晩年、出家して樺崎で暮らしました。1199年に亡くなりますが、«生きたまま土の中に入り、仏になった（生入定）» と伝えられています。その墓の上に建てられたのが、赤く塗られた «赤御堂»。樺崎寺は、足利氏の祖先をまつる大切な場所になりました。","«なぜ、足利の町中の鑁阿寺だけでなく、ここにも寺が?» 鑁阿寺は足利氏の館を寺にしたもの、樺崎寺は義兼の墓所。二つの寺はセットで足利氏の信仰を支えていました。のちの足利尊氏の時代まで、一族の供養塔がここに次々と建てられたと考えられています。","時代が下り、明治時代の神仏分離で寺は廃され、境内には樺崎八幡宮だけが残りました。池は田んぼになり、寺のことは忘れられていきます。ところが1980年代からの発掘調査で、大きな池と中島、建物の跡がつぎつぎと見つかりました。平安〜鎌倉時代にはやった «浄土庭園» だったのです。","さらに、この寺に伝わったと考えられる大日如来像が、鎌倉時代の天才仏師・運慶の作ではないかといわれ、大きな話題になりました。いま史跡は公園として整備され、復元された池のほとりに立つと、800年前の武士が願った «極楽浄土» の風景が目の前に広がります。"],"tl":[["1189年","足利義兼が奥州合戦の戦勝を祈って寺を開いたと伝わる"],["1199年","義兼が亡くなる（生入定の伝承）"],["鎌倉〜室町時代","足利氏一族の廟所として供養塔が建てられる"],["明治時代初め","神仏分離で廃寺、樺崎八幡宮が残る"],["1980年代〜","発掘調査で浄土庭園の池などが見つかる"],["2001年","国の史跡に指定"]],"who":[["足利義兼","樺崎寺を開き、ここに葬られた足利氏の祖"],["源頼朝","義兼と深く結びついた鎌倉幕府の将軍"],["運慶","樺崎寺ゆかりの大日如来像の作者ではないかといわれる仏師"],["足利尊氏","室町幕府を開いた、義兼の子孫"]],"deep":["義兼の «生入定» は、生きたまま地中の穴に入って即身仏となったという言い伝えです。史実かどうかは確かめられていません。","樺崎寺に伝わった足利氏歴代の供養塔（五輪塔など）の多くは、明治の廃寺のあと、足利市内の光得寺に移されたといわれます。","光得寺には、樺崎寺から伝わったとされる小さな大日如来像があり、運慶の作とする説があります。また、2008年に海外のオークションに出品されて話題になった大日如来像も、樺崎寺ゆかりの運慶作ではないかと考えられています。","発掘で見つかった池は、東西に長い大きな池で、中島や石組みが確認されました。平泉の毛越寺や、鎌倉の永福寺と同じ «浄土庭園» の流れをくむものと考えられます。","鑁阿寺（足利氏宅跡）と樺崎寺跡は、どちらも国の史跡。«館の寺» と «墓所の寺» をあわせて見ることで、中世武士の信仰の形がよくわかります。"],"look":["復元された浄土庭園の池と中島","赤御堂（義兼の廟所）の跡","樺崎八幡宮の社殿","近くの鑁阿寺・光得寺とあわせてめぐる"],"q":["樺崎寺を開いた、足利氏の礎を築いた武将はだれ?","足利義兼。ここに葬られ、«生入定» の伝説が残ります。"],"koji":[],"myth":"義兼の生入定は伝承。大日如来像を運慶作とするのは有力な説だが、伝来経路には推定を含む。","img":["足利義兼","鑁阿寺","運慶"],"wp":"樺崎寺","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Kabasaki-dera_garden_remains.jpg",1260,840,"樺崎寺"],["c:3/3f/Ashikaga_Yoshikane_Banna-ji.jpg",1735,2412,"足利義兼"],["c:8/8e/%E9%91%81%E9%98%BF%E5%AF%BA_%E8%B6%B3%E5%88%A9_-_panoramio_%283%29.jpg",4912,3264,"鑁阿寺"],["c:8/88/%E9%81%8B%E6%85%B6.jpg",1284,1616,"運慶"]]},{"id":"09_marishiten","n":"摩利支天塚古墳","yomi":"まりしてんづかこふん","cat":"遺跡","y":500,"era":["kofun"],"sh":"国指定史跡","rank":"A","ad":"小山市飯塚","st":"JR小山駅から車で約15分（バスもあるが本数少なめ）","la":36.391,"lo":139.8,"hook":"墳丘の上に武士の守り神がまつられた、1500年前の王の墓。すぐとなりには «兄弟» のような大古墳が並ぶ。","lead":"摩利支天塚古墳は、古墳時代の後半、5世紀の終わりから6世紀のはじめごろに造られた大きな前方後円墳です。長さは約117メートルで、栃木県でも指折りの大きさ。すぐ近くの琵琶塚古墳とともに、思川流域を治めた有力者の墓と考えられています。","story":["小山市の北、思川と姿川にはさまれた台地の上に、こんもりとした森があります。近づくと、それが巨大な前方後円墳だとわかります。名前の «摩利支天» は、墳丘の上に摩利支天という仏さまをまつる社があることから。摩利支天は、戦いの守り神として武士たちに信仰されました。","«だれの墓なのか?» 名前は伝わっていません。けれども、これだけ大きな墓を造らせることができたのは、この地域を広く治めた «王» のような人物だったはずです。古墳のまわりには堀がめぐり、墳丘にはかつて埴輪が並んでいたと考えられています。","すぐ北には、もう一つの大古墳・琵琶塚古墳があります。長さは約123メートル。摩利支天塚のあと、少し新しい時代に造られたとみられています。まるで親から子へ、王の位が受けつがれたかのように、二つの巨大古墳が並んでいるのです。","このあたりは、のちに下野国の国分寺・国分尼寺が建てられ、近くには国府も置かれました。古墳時代から奈良時代まで、ずっと下野の «中心地» だったことがわかります。«なぜ、ここが中心に?» 川が集まり、水や交通に恵まれた土地だったからと考えられています。","いま、琵琶塚古墳のそばには資料館があり、二つの古墳から見つかった埴輪や、古墳の造り方を学ぶことができます。墳丘の上に立って、まわりに広がる田畑をながめれば、1500年前、ここに暮らした人々が見上げた «王の山» の大きさを実感できるでしょう。"],"tl":[["5世紀末〜6世紀初め","摩利支天塚古墳が造られたと考えられる"],["6世紀前半","となりに琵琶塚古墳が造られる"],["8世紀","近くに下野国分寺・国分尼寺が建てられる"],["江戸時代ごろ","墳丘の上に摩利支天がまつられたとされる"],["昭和時代","国の史跡に指定"],["近年","琵琶塚古墳のそばに資料館が開館"]],"who":[["古墳の主（名は不明）","思川流域を治めた有力者と考えられる"],["摩利支天","墳丘の上にまつられる、武士の守り神"],["琵琶塚古墳の主","摩利支天塚の次の世代の有力者と考えられる"]],"deep":["墳丘長は約117メートル。栃木県の前方後円墳では、吾妻古墳・琵琶塚古墳に次ぐ規模とされ、5世紀末〜6世紀初めの東日本でも有数の大きさです。","摩利支天塚・琵琶塚の二つの古墳は、同じ地域の首長の墓が世代ごとに造られた «首長墓の系譜» と考えられています。","この地域の古墳は、のちに «下野型古墳» と呼ばれる特徴（低い基壇や、石室を前方部に置くなど）を持つようになります。摩利支天塚はその少し前の段階の古墳とみられています。","古墳の上に神社や仏堂がまつられている例は全国に多く、摩利支天塚もその一つ。墳丘が «聖なる山» として大切にされてきたことが、古墳が残った理由の一つです。","古墳の周辺は «しもつけ風土記の丘» の一帯とも近く、国分寺跡・国分尼寺跡などとあわせて古代の下野を一日で体感できます。"],"look":["墳丘の上の摩利支天の社","周りの堀のあと（周溝）","となりの琵琶塚古墳と、そばの資料館","近くの下野国分寺跡・国分尼寺跡"],"q":["摩利支天塚古墳の名前の由来は?","墳丘の上に、戦いの守り神 «摩利支天» がまつられているからです。"],"koji":[],"myth":"被葬者は不明。築造時期は研究者により幅がある。摩利支天がまつられた時期ははっきりしない。","img":["琵琶塚古墳","前方後円墳","下野国分寺跡"],"wp":"摩利支天塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:8/8c/Marishitenzuka_Kofun%2C_funkyu.jpg",5568,3712,"摩利支天塚古墳"],["c:e/eb/Biwazuka_Kofun%2C_funkyu-2.jpg",5568,3712,"琵琶塚古墳"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:c/c6/%E4%B8%8B%E9%87%8E%E5%9B%BD%E5%88%86%E5%AF%BA%E8%B7%A1_%E4%BC%BD%E8%97%8D.jpg",3648,2736,"下野国分寺跡"]]},{"id":"09_azuma_kofun","n":"吾妻古墳（県内最大の前方後円墳）","yomi":"あづまこふん","cat":"遺跡","y":580,"era":["kofun"],"sh":"国指定史跡","rank":"A","ad":"栃木市大光寺町・下都賀郡壬生町藤井","st":"東武宇都宮線国谷駅・壬生駅から車で約10分。車が便利","la":36.4175,"lo":139.787,"hook":"長さ約128メートル、栃木県でいちばん大きな古墳。その石室の入口は、ふつうとは «反対側» にあった。","lead":"吾妻古墳は、6世紀の後半に造られた前方後円墳で、長さは約128メートル。栃木県でいちばん大きな古墳です。低くて広い «基壇» の上に墳丘をのせ、石室を前方部に置くという、この地方独特の «下野型古墳» の代表として知られます。","story":["栃木市と壬生町の境、黒川と思川にはさまれた田園の中に、大きな森のような古墳があります。これが吾妻古墳。«吾妻岩屋» とも呼ばれてきました。長さ約128メートル。近くで見上げると、その大きさに圧倒されます。","«前方後円墳の石室は、ふつう後円部にあるのでは?» ところが吾妻古墳は、石室が前方部に造られています。さらに、墳丘の下に低く広い段（基壇）があるのも特徴です。こうした形は下野の古墳によく見られ、«下野型古墳» と呼ばれています。この地域の豪族たちが、自分たちの «スタイル» を持っていたことがわかります。","石室には、大きな石が使われていました。とくに入口の門にあたる石（玄門）や天井の石は、凝灰岩を切り出した巨大なもの。江戸時代に掘り出され、いまは壬生町側で保管・展示されていると伝えられています。古墳の石は、昔から人々の目をひく «宝» だったのでしょう。","6世紀の後半といえば、中央ではまもなく仏教が伝わり、飛鳥時代が始まろうとするころ。前方後円墳の時代の最後の輝きです。吾妻古墳の主は、下野一帯を治めた最有力の豪族だったと考えられます。やがてこの地域には下野国の国府が置かれ、豪族たちは律令国家の役人へと姿を変えていきました。","墳丘には木が生い茂り、古墳のまわりには周堀のあとがたどれます。静かな田んぼの中にたたずむ巨大な墓は、名前も残らなかった «下野の王» の存在を、いまも無言で伝えています。"],"tl":[["6世紀後半","吾妻古墳が造られたと考えられる"],["江戸時代","石室の石材の一部が掘り出されたと伝わる"],["明治以降","何度か調査が行われる"],["昭和時代","国の史跡に指定"],["現代","周辺の範囲確認調査が進められる"]],"who":[["古墳の主（名は不明）","下野を治めた最有力の豪族と考えられる"],["下野の豪族たち","«下野型古墳» という独自の古墳を造った"],["壬生藩","江戸時代、古墳のあった地域を治めた藩"]],"deep":["墳丘長約128メートルは、栃木県内の前方後円墳で最大。関東でも、6世紀後半の古墳としては大きな部類に入ります。","«下野型古墳» の特徴: ①低く幅の広い基壇を持つ ②石室を前方部に置く ③凝灰岩の切石で石室を造る。吾妻古墳はその代表例で、研究者のあいだで基準となる古墳です。","石室の石材が江戸時代に掘り出されたという話は伝わっていますが、だれが、いつ、どのように運び出したかについては、資料によって説明に違いがあります。","古墳は栃木市と壬生町の境にまたがっていて、二つの自治体が協力して保存にあたっています。","周辺には、摩利支天塚古墳・琵琶塚古墳など大古墳が集まり、5世紀末から6世紀にかけて、思川流域が下野の中心だったことを示しています。"],"look":["墳丘の大きさ（まわりを歩いて実感）","基壇（墳丘の下の低い段）","前方部に開いていた石室のあたり","壬生町側で伝えられる石室の石材"],"q":["吾妻古墳の石室は、前方後円墳のどこにある?","前方部。石室を前方部に置くのが «下野型古墳» の特徴です。"],"koji":[],"myth":"被葬者不明。石材の搬出の経緯や現在の保管場所の細部は資料により説明が異なる。","img":["前方後円墳","摩利支天塚古墳","下野国"],"wp":"吾妻古墳","rel":{"ev":[],"grave":[]},"ph":[["c:5/5a/Azuma-kofun_zenkei.JPG",3648,2736,"吾妻古墳"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:8/8c/Marishitenzuka_Kofun%2C_funkyu.jpg",5568,3712,"摩利支天塚古墳"]]},{"id":"09_kokucho","n":"下野国庁跡","yomi":"しもつけこくちょうあと","cat":"遺跡","y":750,"era":["nara","heian"],"sh":"国指定史跡","rank":"A","ad":"栃木市田村町","st":"JR・東武栃木駅から車で約15分。車が便利","la":36.371,"lo":139.762,"hook":"1300年前、下野の «県庁» はここにあった。田んぼの下から、役所の建物と役人たちの書いた木の札が出てきた。","lead":"下野国庁跡は、奈良時代から平安時代にかけて、下野国（いまの栃木県）の政治の中心だった役所の跡です。発掘調査で、正殿・前殿・脇殿などの建物の配置が明らかになりました。敷地には資料館があり、前殿の一部が復元されています。","story":["奈良時代、日本は国ごとに «国府» という役所を置き、都から «国司» という役人を送って治めました。いまでいえば県庁と知事のようなものです。下野国の国府が置かれたのが、思川のほとりの、ここ栃木市田村町でした。","1970年代、県の発掘調査で、ついに下野国府の中心、«国庁» の跡が見つかりました。四角い区画の中に、正殿、前殿、そして東西の脇殿が «コの字» に並んでいたのです。«なぜ、そんな形?» 都の宮殿をまねた形で、国司が儀式や政治を行うための晴れ舞台でした。","発掘では、たくさんの木簡（字を書いた木の札）も見つかりました。役人たちは、税の記録やお知らせを木の札に書き、使い終わると削って何度も使いました。削りくずにも文字が残っていて、1300年前の役人の仕事ぶりが見えてきます。","近くには、下野国分寺と国分尼寺、そして少し東には、全国に三つしかなかった «戒壇» を持つ下野薬師寺がありました。奈良時代、都を追われた僧・道鏡が送られてきたのも、この下野薬師寺です。下野は、東国を治める上でとても大切な国だったのです。","国庁は、何度か建て替えられながら、平安時代の中ごろまで使われたと考えられています。やがて律令の仕組みがゆるむと、国府の役割もうすれていきました。いまは田んぼの中の静かな史跡ですが、復元された前殿の前に立つと、朝廷の使いを迎える儀式のざわめきが聞こえてきそうです。"],"tl":[["8世紀前半","下野国の国庁が造られたと考えられる"],["761年","下野薬師寺に戒壇が設けられる"],["770年","道鏡が下野薬師寺に送られる"],["9〜10世紀","国庁が建て替えられながら使われる"],["1970年代","発掘調査で国庁の跡が見つかる"],["1982年","国の史跡に指定"]],"who":[["国司（下野守）","都から送られ、国庁で政治を行った役人"],["道鏡","都を追われ、下野薬師寺に送られた僧"],["国府の役人たち","木簡に記録を書き、税や行政を担った"]],"deep":["国庁の区画はおよそ90メートル四方で、正殿の前に前殿、左右に脇殿を置く配置。全国の国庁の発掘の中でも、建物配置がよくわかる例として知られます。","国庁の建物は、少なくとも数回の建て替えがあったことが発掘でわかっています。時期によって建物の大きさや位置が少しずつ変わりました。","見つかった木簡や墨書土器には、役所の仕事や地名が書かれたものがあり、奈良・平安時代の地方行政を知る手がかりになっています。","下野薬師寺の戒壇は、奈良の東大寺、筑紫の観世音寺とならぶ «天下の三戒壇» の一つ。東国で僧になるには、下野まで来る必要がありました。","国庁の中心部には宮野辺神社がまつられており、ここが古くから特別な場所として意識されてきたことがうかがえます。"],"look":["復元された前殿の一部","建物の位置を示した平面表示","敷地内の下野国庁跡資料館（木簡などの展示）","近くの下野国分寺跡・国分尼寺跡"],"q":["国府の中心で、国司が政治や儀式を行った建物のまとまりを何という?","«国庁»。いまの県庁のような役所の中心です。"],"koji":[],"myth":"国庁が使われた期間や建て替えの回数は調査・研究で解釈が分かれる部分がある。","img":["国府","下野国","下野薬師寺"],"wp":"下野国庁跡","rel":{"ev":[],"grave":[]},"ph":[["c:b/b1/Shimotsuke_Kokucho_Ruins_maedono.JPG",3648,2736,"下野国庁跡"],["c:4/49/Musashikokufuato.jpg",1600,1200,"国府"],["j:2/2c/%E4%B8%8B%E9%87%8E%E8%96%AC%E5%B8%AB%E5%AF%BA_%E5%BE%A9%E5%85%83%E5%9B%9E%E5%BB%8A.JPG",3648,2736,"下野薬師寺"]]},{"id":"09_saimyoji_mashiko","n":"西明寺（益子）","yomi":"さいみょうじ","cat":"寺社","y":1538,"era":["nara","muromachi"],"sh":"国の重要文化財（楼門・三重塔・本堂内厨子）","rank":"A","ad":"芳賀郡益子町益子","st":"真岡鐵道益子駅から車で約10分","la":36.446,"lo":140.115,"hook":"山の中腹に、室町時代の三重塔と楼門。その奥では、なぜか «笑っている» えんま様が待っている。","lead":"西明寺は、益子の高館山の中腹にある古いお寺です。奈良時代に行基が開いたと伝わり、坂東三十三観音の第20番札所として巡礼の人々を迎えてきました。室町時代の楼門や三重塔が残り、国の重要文化財になっています。","story":["益子焼の町から少し山へ入ると、杉とシイの森に包まれた長い石段があらわれます。その先に建つのが西明寺。737年、奈良時代の僧・行基がこの地を訪れて開いたと伝わります。行基は、各地で橋や池を造り、人々を助けた僧として知られています。","石段を登りきると、どっしりとした楼門が迎えてくれます。室町時代に建てられたもので、そのさらに奥には、朱色の三重塔がすっと空にのびています。この塔は1538年ごろ、地元の武士・益子氏によって建てられたと伝わります。戦国の世に、これだけの塔を建てた益子氏の信仰と力がうかがえます。","西明寺でいちばん人気なのが、閻魔堂の «笑い閻魔»。ふつう閻魔大王はこわい顔をしていますが、ここの閻魔さまは、口を大きく開けて笑っているように見えるのです。«なぜ笑っているの?» 地獄の裁きを受ける人を安心させるため、とも、じつは怒って口を開けている、ともいわれ、答えは見る人しだい。","境内をおおうシイの森も、この寺の宝物です。古い大木が茂り、夏でもひんやりとした空気が流れています。この森は昔から寺とともに守られてきたもので、自然と信仰が一体になった景色は、訪れる人の心を静めてくれます。","坂東三十三観音めぐりの人々は、観音さまに手を合わせ、御朱印をいただいて、また次の札所へと旅立っていきます。室町時代の建物と深い森、そして笑う閻魔さま。益子に来たら、焼き物だけでなく、この静かな山寺にもぜひ足をのばしてみてください。"],"tl":[["737年（伝承）","行基が寺を開いたと伝わる"],["平安時代","益子氏（紀氏）の保護を受けたとされる"],["1492年ごろ","楼門が建てられる"],["1538年ごろ","三重塔が建てられる"],["江戸時代","閻魔堂が建てられ、«笑い閻魔» がまつられる"],["現在","坂東三十三観音の第20番札所として巡礼者を迎える"]],"who":[["行基","西明寺を開いたと伝わる奈良時代の僧"],["益子氏","益子を治めた武士。寺を保護し、三重塔を建てたと伝わる"],["坂東の巡礼者","観音霊場をめぐって訪れた人々"]],"deep":["楼門と三重塔は室町時代の建物で、ともに国の重要文化財。関東で室町時代の三重塔が残る例は多くなく、貴重です。","本堂の中の厨子（仏像をおさめる屋形）も室町時代のもので、国の重要文化財に指定されています。","«笑い閻魔» は江戸時代の作とされる閻魔大王の像。表情がユーモラスなことで知られ、西明寺の名物になっています。","益子氏は «紀清両党» の «紀党»。宇都宮氏を支えた武士団で、芳賀氏（清党）とならぶ名門でした。","境内のシイの林は県の天然記念物に指定されているといわれ、関東の内陸では珍しい暖かい地方の森の姿を残しています。"],"look":["室町時代の楼門","朱色の三重塔","閻魔堂の «笑い閻魔»","境内をおおうシイの森","本堂と観音さま（坂東20番）"],"q":["西明寺の閻魔堂にいる、ちょっと変わった閻魔さまのニックネームは?","«笑い閻魔»。口を開けて笑っているように見える表情で知られます。"],"koji":[],"myth":"行基開山・737年は伝承。楼門・三重塔の建立年と建立者は伝えによる部分がある。","img":["行基","坂東三十三箇所","益子町"],"wp":"西明寺 (栃木県益子町)","rel":{"ev":[],"grave":[]},"ph":[["c:6/67/Saimyoji_Temple_3.jpg",1280,960,"西明寺 (栃木県益子町)"],["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:e/e6/2023%E5%B9%B4%EF%BC%88%E4%BB%A4%E5%92%8C5%E5%B9%B4%EF%BC%89%E6%98%A5%E3%81%AE%E7%9B%8A%E5%AD%90%E9%99%B6%E5%99%A8%E5%B8%82%E3%80%8C%E7%9B%8A%E5%AD%90%E7%84%BC%E7%AA%AF%E5%85%83%E5%85%B1%E8%B2%A9%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC%E3%80%8D%E3%80%82.jpg",2003,1196,"益子町"]]},{"id":"09_mashiko_yaki","n":"益子焼（濱田庄司の窯）","yomi":"ましこやき","cat":"産業","y":1853,"era":["edo","taisho","showa"],"sh":"国の伝統的工芸品","rank":"A","ad":"芳賀郡益子町益子（濱田庄司記念益子参考館）","st":"真岡鐵道益子駅から歩いて約25分、または車で約5分","la":36.461,"lo":140.09,"hook":"台所の甕やすり鉢を焼いていた小さな焼き物の町が、一人の陶芸家の移住で «世界のMASHIKO» になった。","lead":"益子焼は、江戸時代の終わりに始まった焼き物です。はじめは台所で使う丈夫な道具を作っていましたが、大正時代に陶芸家・濱田庄司が移り住み、«民芸» の器として全国に知られるようになりました。今は春と秋の陶器市に、たくさんの人が集まります。","story":["1853年、ペリーが浦賀に来たその年。益子の大塚啓三郎という人が、となりの笠間で焼き物の技を学び、ふるさとに窯を開きました。これが益子焼の始まりとされます。益子は黒羽藩の領地で、藩も焼き物づくりを支えました。","益子の土は、ざっくりとして、厚く丈夫な器に向いていました。作られたのは、水がめ、すり鉢、土瓶、火鉢など、毎日の暮らしで使う道具。東京に近いこともあって、益子の台所道具は大量に運ばれ、多くの家庭で使われました。","1924年、この町に一人の若い陶芸家がやってきます。濱田庄司です。イギリスで陶芸家バーナード・リーチとともに窯を開き、帰国したばかりでした。«なぜ、有名な焼き物の産地ではなく益子に?» 濱田は、名もない職人たちが作る、飾り気のない日用の器の美しさにひかれていたのです。","濱田は、思想家の柳宗悦らとともに、«民藝（民芸）運動» を進めました。«ふつうの人が、ふつうに使う道具にこそ美しさがある»。その考えのもと、濱田は益子の土と釉薬で、力強く、あたたかい器を作り続けました。1955年、濱田は重要無形文化財 «民芸陶器» の保持者（人間国宝）に認定されます。","濱田の家と工房は、いま «濱田庄司記念益子参考館» になっています。濱田が集めた世界の民芸品や、大きな登り窯が見られます。町には数百の窯元や販売店が並び、春と秋の陶器市には全国から多くの人が集まります。台所の道具から始まった益子焼は、いまも «使ってこそ美しい» 器として、人々の暮らしの中で生きています。"],"tl":[["1853年","大塚啓三郎が益子に窯を開いたとされる"],["明治時代","台所の道具の産地として東京方面へ多く出荷"],["1924年","濱田庄司が益子に移り住む"],["1955年","濱田庄司が人間国宝に認定"],["1966年","益子陶器市が始まる"],["1977年","益子参考館が開館"],["1979年","国の伝統的工芸品に指定"]],"who":[["大塚啓三郎","益子焼を始めたとされる人物"],["濱田庄司","益子に移住し、民芸の器で益子焼を世界に広めた陶芸家"],["柳宗悦","民藝運動を始めた思想家"],["バーナード・リーチ","濱田とイギリスで窯を開いた陶芸家"],["皆川マス","土瓶の絵付けで知られ、民芸の人々に高く評価された職人"]],"deep":["益子焼のもとになった技術は、茨城県の笠間焼から伝わったとされます。笠間と益子は山をはさんで隣り合い、今も «兄弟産地» のような関係です。","濱田庄司が認定されたのは «民芸陶器» の重要無形文化財保持者。民芸の器で人間国宝になったことは、日用の器の価値を見直すきっかけになりました。","益子焼の代表的な釉薬には、柿釉・黒釉・糠白釉などがあります。どっしりとした厚みと、土の味わいを生かした素朴な色合いが特徴です。","皆川マスの «山水土瓶» の絵付けは、すばやい筆さばきで描かれ、柳宗悦らに «民芸の美» の見本として高く評価されました。","2011年の東日本大震災では、益子でも登り窯や作品の多くが大きな被害を受けました。その後、多くの人の支援で窯が直され、焼き物の町は復興を続けています。"],"look":["濱田庄司記念益子参考館の登り窯と展示","町に並ぶ窯元や陶芸店","春・秋の益子陶器市","陶芸体験（ろくろ・絵付け）","益子陶芸美術館"],"q":["益子に移り住み、益子焼を世界に知らせた人間国宝の陶芸家はだれ?","濱田庄司。民藝運動を進め、1955年に人間国宝に認定されました。"],"koji":[{"w":"用の美","m":"ふだん使う道具の中にこそ美しさがあるという、民藝運動の考え方"}],"myth":"益子焼の始まりを1853年・大塚啓三郎とするのが通説。陶器市の開始年には説明の違いがある。","img":["濱田庄司","柳宗悦","笠間焼"],"wp":"益子焼","rel":{"ev":[],"grave":[]},"ph":[["c:b/b6/Taisho-Showa_Period_Ko-Mashiko_Ware_Mado-e_Dobin_Window_Picture_Teapot_Brooklyn_Museum.jpg",1536,1162,"益子焼"],["c:e/e3/Sh%C5%8Dji_Hamada.png",455,641,"濱田庄司"],["c:e/e5/Soetsu.JPG",332,443,"柳宗悦"],["c:7/77/Kasama_Ware%2C_Ibaraki_04.jpg",6000,4000,"笠間焼"]]},{"id":"09_nasu_sosui","n":"那須疏水（明治の三大疏水）","yomi":"なすそすい","cat":"近代","y":1885,"era":["meiji"],"sh":"国の重要文化財（那須疏水旧取水施設）","rank":"A","ad":"那須塩原市西岩崎（那須疏水公園）","st":"JR黒磯駅・那須塩原駅から車で約20分","la":36.969,"lo":139.964,"hook":"水がなく «川が消える» 荒れ野に、わずか5か月で16キロの水路を通した。那須野が原は、明治の人々の執念でよみがえった。","lead":"那須疏水は、明治時代に那珂川から水を引いて、水の少ない那須野が原に届けた用水路です。福島の安積疏水、京都の琵琶湖疏水とならぶ «日本三大疏水» の一つ。この水で原野が開拓され、農地と町が生まれました。","story":["那須野が原は、那珂川と箒川にはさまれた広い扇状地です。«川が消える» といわれるほど水はけがよく、雨が降っても水はすぐに地下にしみこんでしまいます。江戸時代まで、ここは人がほとんど住めない荒れ野でした。飲み水にも困り、遠くから水を運ぶ暮らしだったといいます。","明治になると、この原野を開こうとする人々があらわれます。地元の印南丈作と矢板武です。二人は «那須開墾社» をつくり、国に «那珂川から水を引かせてほしい» と何度も願い出ました。«なぜ、そこまで?» 水さえあれば、この広い土地は豊かな畑や田んぼになると信じていたからです。","願いがかない、1885年、国の事業として工事が始まりました。那珂川の西岩崎で水を取り入れ、那須野が原に向けて本幹水路を掘ります。その長さ約16キロ。工事はおどろくほどの速さで進み、わずか5か月ほどで本幹が完成したといわれます。水が流れてきたとき、人々はどれほど喜んだことでしょう。","那須野が原には、政府の高官や華族たちも大きな農場を開きました。大山巌、西郷従道、松方正義……。明治の国の中心にいた人々が、ここに農場や別荘をかまえたのです。いまも那須塩原市には、洋風の別荘建築など、そのころのなごりが残っています。","取水口は、その後も川の流れの変化に合わせて造り直されました。今、那須疏水公園では、石積みの旧取水口や導水トンネルの入口を見ることができ、国の重要文化財になっています。緑の中を流れる水の音に耳をすませば、荒れ野に水を通した明治の人々の熱い思いが聞こえてくるようです。"],"tl":[["江戸時代まで","那須野が原は水が乏しく、ほとんど人が住めない原野"],["1880年","印南丈作・矢板武らが那須開墾社をつくる"],["1885年","那須疏水の工事が始まり、約5か月で本幹水路が完成"],["明治時代後期","華族・高官の農場が次々と開かれる"],["2006年","旧取水施設が国の重要文化財に"],["2016年","«明治貴族が描いた未来» として日本遺産に"]],"who":[["印南丈作","那須開墾社を起こし、疏水の実現に力をつくした"],["矢板武","印南とともに疏水を実現させた地元の実業家"],["大山巌","那須野が原に農場を開いた明治の軍人"],["松方正義","那須野が原に千本松農場を開いた政治家"]],"deep":["那須野が原の川は、ふだんは水が地下にしみこんで川底が乾いてしまう «水無川» になることがあります。扇状地の砂礫の地盤がその理由です。","«日本三大疏水» は、安積疏水（福島）・琵琶湖疏水（京都）・那須疏水（栃木）。いずれも明治の国づくりの一環として造られました。","本幹水路が約5か月で完成したとされるのは、国の事業として多くの人手を集め、一気に工事を進めたため。日本の近代の土木工事の中でも、スピードの速さで知られています。","那須疏水は、飲み水や田畑の水だけでなく、のちには発電にも使われました。水は今も那須野が原の農業を支えています。","那須塩原市・大田原市などの «那須野が原開拓» のストーリーは、2016年に日本遺産に認定されました。旧青木家那須別邸などの建物も、この物語の一部です。"],"look":["那須疏水公園の旧取水口と石積み","導水トンネルの入口","疏水の流れと遊歩道","那須野が原博物館の開拓の展示"],"q":["那須疏水とならぶ «日本三大疏水» のあと二つは?","福島の安積疏水と、京都の琵琶湖疏水です。"],"koji":[{"w":"我田引水","m":"自分の田にだけ水を引くこと。自分に都合のよいように物事を進めることのたとえ"}],"myth":"本幹完成までの期間（約5か月）や長さは資料により少し違う。取水施設の年代は造り替えごとに異なる。","img":["那須野が原","安積疏水","琵琶湖疏水"],"wp":"那須疏水","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/Nasu-sosui_canal.jpg",800,600,"那須疏水"],["c:0/0c/Yamasina_Lake_Biwa_Canal_and_Cherry_Blossom_Viewing_%285%29.JPG",4320,3240,"琵琶湖疏水"]]},{"id":"09_kanaya","n":"日光金谷ホテル","yomi":"にっこうかなやほてる","cat":"近代","y":1873,"era":["meiji","taisho"],"sh":"国の登録有形文化財","rank":"A","ad":"日光市上鉢石町","st":"東武日光駅・JR日光駅からバスで «神橋» 下車、歩いて約3分","la":36.7515,"lo":139.6025,"hook":"«外国人が泊まれる宿がない»――困っていた宣教師に、日光の楽師が自分の家を貸したことから、日本のホテルの歴史が始まった。","lead":"日光金谷ホテルは、明治時代に開業した、日本に現存する最も古いリゾートホテルの一つです。はじまりは、東照宮の楽師・金谷善一郎が自宅を外国人に貸した «金谷カッテージ・イン»。イギリスの旅行家イザベラ・バードもここに泊まりました。","story":["明治のはじめ、日光を訪れる外国人が増えていました。けれども、外国人が安心して泊まれる宿はほとんどありません。そんなある日、アメリカ人の宣教師で医師のヘボンが日光に来て、宿が見つからず困っていました。助けたのが、東照宮で雅楽を演奏する楽師・金谷善一郎でした。","ヘボンは善一郎に言いました。«あなたの家を、外国人のための宿にしてはどうでしょう»。1873年、善一郎は自宅の武家屋敷を使って «金谷カッテージ・イン» を開きます。畳の部屋に、外国人のためのベッドや食事を用意した、日本と西洋がまじりあった宿でした。","1878年、イギリスの女性旅行家イザベラ・バードがこの宿に泊まりました。彼女は旅行記 «日本奥地紀行» の中で、金谷家の静かな暮らしや、美しい庭を生き生きと書き残しています。«この家は、まるで絵のように美しい»。その評判は、外国人のあいだに広まっていきました。","1893年、善一郎は大谷川を見下ろす高台に、本格的な西洋式ホテルを開業しました。これが今の日光金谷ホテルです。建物は和洋が入りまじった独特のデザインで、日光東照宮の彫刻を思わせる飾りや、木のぬくもりにあふれた内装が特徴です。«なぜ、和風の飾りを?» 外国人客にとって、それこそが «日本らしさ» の魅力だったからです。","その後、多くの国内外の有名人がこのホテルに泊まり、日光は国際的な避暑地になりました。ホテルのレストランで長く受けつがれてきたカレーなどの料理も名物です。いまも営業を続けるホテルであり、最初のカッテージ・インの建物も «金谷ホテル歴史館» として公開されています。"],"tl":[["1873年","金谷善一郎が自宅で «金谷カッテージ・イン» を開く"],["1878年","イザベラ・バードが宿泊"],["1893年","現在地で «金谷ホテル» を開業"],["昭和時代","新館・別館などが増築される"],["現代","本館などが国の登録有形文化財に"],["現在","カッテージ・インの建物が «金谷ホテル歴史館» として公開"]],"who":[["金谷善一郎","東照宮の楽師。ホテルの創業者"],["ヘボン","アメリカ人宣教師・医師。外国人の宿を開くよう勧めた"],["イザベラ・バード","イギリスの旅行家。«日本奥地紀行» に金谷家を書いた"]],"deep":["ヘボンは «ヘボン式ローマ字» で知られる人物。日本語の辞書をつくり、医療でも活躍しました。ホテル誕生のきっかけをつくったのは、このヘボンだと伝えられています。","金谷カッテージ・インに使われた建物は、江戸時代の武家屋敷。«侍屋敷» と呼ばれ、いまも見学できます。","イザベラ・バードは «日本奥地紀行» で、日光から会津、新潟、東北をへて北海道まで旅しました。旅のはじめの日光で、金谷家での滞在はとても印象深いものだったようです。","ホテルの本館は、明治の開業時の建物をもとに増改築を重ねたもの。和洋折衷の意匠は «クラシックホテル» の代表例として知られています。","日光には、明治時代から外国の大使館の別荘が建てられるようになり、中禅寺湖畔は «国際避暑地» として栄えました。金谷ホテルは、その玄関口の役割を果たしました。"],"look":["本館の和洋折衷の外観と内装","東照宮を思わせる彫刻の飾り","金谷ホテル歴史館（旧カッテージ・イン、侍屋敷）","ホテルから見下ろす大谷川と神橋"],"q":["金谷ホテルの前身 «金谷カッテージ・イン» に泊まり、旅行記に書いたイギリスの女性旅行家は?","イザベラ・バード。«日本奥地紀行» に金谷家の様子を書きました。"],"koji":[],"myth":"ヘボンとの出会いの細部は伝えによる。«現存最古のリゾートホテル» という表現には比較の仕方で異論もありうる。","img":["イザベラ・バード","ジェームス・カーティス・ヘボン","日光東照宮"],"wp":"日光金谷ホテル","rel":{"ev":["k_nikko"],"grave":[]},"ph":[["c:b/b6/200730_Nikko_Kanaya_Hotel_Nikko_Japan06s3.jpg",6000,4000,"日光金谷ホテル"],["c:3/36/Isabella_Bird.jpg",788,1048,"イザベラ・バード"],["c:0/04/James_Curtis_Hepburn.jpg",576,720,"ジェームス・カーティス・ヘボン"],["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"]]},{"id":"09_oya_ishi","n":"大谷石採掘場跡（地下工場にもなった石切場）","yomi":"おおやいしさいくつじょうあと","cat":"産業","y":1919,"era":["meiji","showa"],"sh":"","rank":"A","ad":"宇都宮市大谷町（大谷資料館）","st":"JR宇都宮駅からバスで約30分、«資料館入口» 下車、歩いて約5分","la":36.6005,"lo":139.8215,"hook":"地下30メートルに広がる、野球場ほどの巨大な空間。戦争中はここで、ひそかに飛行機の部品が作られていた。","lead":"大谷石は、宇都宮市大谷町のあたりでとれる、やわらかく加工しやすい石です。大谷資料館では、長年石を掘り続けてできた巨大な地下の採掘場跡を見学できます。戦争中は地下工場としても使われました。","story":["およそ1500万年前、このあたりは海の底でした。海底火山から噴き出した火山灰や軽石が積もり、長い年月をかけて固まってできたのが «大谷石» です。やわらかく、火に強く、加工しやすい。この石は江戸時代から、蔵や塀、石垣などに使われてきました。","大谷資料館の地下採掘場は、1919年から1986年まで、石を掘り続けてできた空間です。広さは約2万平方メートル、深さは地下30メートルにもなります。«どうやって掘ったの?» はじめは職人が一本一本つるはしで、石を四角く切り出していました。壁に残る細かい筋は、その手掘りのあとです。","大谷石を世界に知らせたのが、アメリカの建築家フランク・ロイド・ライトです。1923年に完成した東京の帝国ホテル旧本館（ライト館）に、大谷石がたっぷり使われました。完成したその年に関東大震災が起きましたが、ホテルはほとんど被害を受けず、大谷石の名はさらに広まりました。","太平洋戦争の終わりごろ、この地下の空間は、別の目的で使われます。空襲を避けるため、中島飛行機の地下工場として、飛行機の部品づくりが行われたのです。多くの人が、ひんやりと暗い地下で働きました。美しい地下空間は、戦争の記憶も秘めているのです。","いま、採掘場跡は資料館として公開され、コンサートや映画の撮影にも使われています。一方で、1989年には大谷地区で大規模な陥没が起こり、採掘のあとの地下空洞の安全が大きな課題になりました。地下の神殿のような景色の中で、人と石が歩んできた長い歴史に思いをはせてみてください。"],"tl":[["約1500万年前","海底火山の火山灰が積もり、大谷石のもとになる"],["江戸時代","大谷石が蔵や塀などに使われるようになる"],["1919年","大谷資料館の地下採掘場で採掘が始まる"],["1923年","大谷石を使った帝国ホテル旧本館（ライト館）が完成"],["1945年ごろ","採掘場跡が中島飛行機の地下工場として使われる"],["1979年","大谷資料館が開館"],["2018年","大谷石文化が日本遺産に認定"]],"who":[["フランク・ロイド・ライト","帝国ホテル旧本館に大谷石を使った建築家"],["石切職人たち","手掘りで大谷石を切り出した人々"],["中島飛行機","戦争末期に地下工場を置いた航空機メーカー"]],"deep":["大谷石は «軽石凝灰岩»。石の中に «ミソ» と呼ばれる茶色い斑点があるのが特徴で、これが大谷石らしい表情になっています。","手掘りの時代には、1本の石（約18×30×90センチの «五十石» など）を切り出すのに、職人が何千回もつるはしをふるったといわれます。1960年ごろから機械掘りが広まりました。","地下の気温は一年を通して低く、夏でも10度前後といわれます。そのため戦後は、政府の米の貯蔵庫としても使われました。","近くの大谷寺には、岩壁に彫られた «大谷磨崖仏»（千手観音など）があり、国の特別史跡・重要文化財です。石の町・大谷の信仰の古さを物語ります。","1989年の大規模陥没をきっかけに、地下空洞の調査と監視が続けられています。見学のときは、決められた場所以外に立ち入らないことが大切です。"],"look":["大谷資料館の地下採掘場（手掘り・機械掘りのあと）","資料館の石切り道具の展示","大谷寺の磨崖仏（大谷観音）","町のあちこちの大谷石の蔵や塀"],"q":["大谷石を使った東京の帝国ホテル旧本館を設計した建築家は?","フランク・ロイド・ライト。関東大震災でもホテルはほとんど被害を受けませんでした。"],"koji":[],"myth":"地下工場の規模や稼働の実態は資料によって説明が異なる。石の寸法・気温の数値は目安。","img":["帝国ホテル","フランク・ロイド・ライト","中島飛行機"],"wp":"大谷石","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Ooyaishi.jpg",640,480,"大谷石"],["c:7/7f/Imperial_Hotel_Tokyo.JPG",2206,2500,"帝国ホテル"],["c:6/66/Frank_Lloyd_Wright_with_Crystal_Heights_plan.jpg",800,1020,"フランク・ロイド・ライト"],["c:5/58/Nakajima_Aircraft_Company_Head_Office_in_Taisho_era.jpg",750,520,"中島飛行機"]]},{"id":"09_utsunomiya_kushu","n":"宇都宮空襲の跡","yomi":"うつのみやくうしゅうのあと","cat":"昭和","y":1945,"era":["showa"],"sh":"","rank":"A","ad":"宇都宮市中心部（馬場通り・二荒山神社周辺）","st":"JR宇都宮駅西口から歩いて約20分、東武宇都宮駅から約10分","la":36.5605,"lo":139.8835,"hook":"1945年7月12日の夜、焼夷弾の雨が町を焼いた。にぎやかな中心街は、一夜で焼け野原になった。","lead":"太平洋戦争の終わり近くの1945年7月12日の夜から13日の未明にかけて、宇都宮の町はアメリカ軍の大型爆撃機B-29による空襲を受けました。焼夷弾で市街地の多くが焼け、600人をこえる人が亡くなったとされます。いまの中心街は、その焼け跡から復興した町です。","story":["宇都宮は、明治の終わりから陸軍の «第十四師団» が置かれた «軍都» でした。まわりには飛行機を作る工場もあり、戦争が進むにつれて、町の人々も戦争と切りはなせない暮らしを送っていました。1945年になると、日本の各地の都市がつぎつぎと空襲を受けるようになります。","7月12日の夜。空襲警報が鳴り、やがて空を大きな爆撃機B-29が埋めつくしました。落とされたのは焼夷弾。«油の入った爆弾» が落ちると、木造の家々がつぎつぎと燃え上がります。二荒山神社のまわりや、にぎやかな中心街は、あっという間に火の海となりました。","人々は火をさけて、町を流れる釜川や田川のほとり、郊外へと必死に逃げました。«お母さん、どこ?»。家族とはぐれ、煙の中をさまよった子どもたちもいました。夜が明けると、町の中心部の多くが焼け野原になっていました。亡くなった人は600人をこえるとされ、家を失った人はさらにたくさんいました。","«なぜ、宇都宮がねらわれたのか?» 当時、アメリカ軍は日本の大都市だけでなく、地方の中小都市も次々に焼夷弾で攻撃していました。軍の施設や工場のある宇都宮も、その標的の一つになったのです。そして、この空襲からわずか1か月後に、戦争は終わりました。","戦後、宇都宮の人々は焼け跡から町を立て直しました。いま、中心街を歩いても空襲の傷あとはほとんど見えません。けれども、市内には焼け残ったといわれる古い建物や、犠牲者をしのぶ碑があり、毎年、空襲の記憶を伝える展示や催しが行われています。平和な町並みの下に眠る記憶に、静かに手を合わせたいものです。"],"tl":[["1908年ごろ","陸軍第十四師団が宇都宮に置かれる"],["1945年7月12〜13日","B-29による空襲で市街地の多くが焼ける"],["1945年7月下旬","艦載機による攻撃も受けたとされる"],["1945年8月15日","終戦"],["戦後","焼け跡からの復興と区画整理が進む"],["現在","空襲の記憶を伝える展示や催しが続けられている"]],"who":[["宇都宮の市民","空襲で家族や家を失い、戦後の町を立て直した人々"],["第十四師団","宇都宮に置かれた陸軍の師団"],["アメリカ陸軍航空軍（B-29部隊）","空襲を行った爆撃機部隊"]],"deep":["宇都宮空襲の死者数は、資料によって違いがあり、600人あまりとするものが多く見られます。空襲の直後は混乱の中で、正確な数を数えることができませんでした。","焼夷弾は、建物を焼くことを目的とした爆弾です。木造の家が多い日本の町に対して大きな被害を与えるように使われました。","宇都宮は明治時代の終わりに陸軍の第十四師団が置かれてから、軍の町として発展しました。戦争中は、飛行機の工場も周辺に置かれていました。","市内には、空襲で焼けずに残ったといわれる明治時代の商家（旧篠原家住宅など）があり、戦前の町の姿を伝えています。","宇都宮では、市民や市の手で空襲の体験談の記録や、写真・資料の展示が続けられています。体験者が少なくなる中、記憶を引きつぐことが大切になっています。"],"look":["二荒山神社の高台からながめる中心街（焼け跡から復興した町）","焼け残ったといわれる旧篠原家住宅","市内の戦災犠牲者の慰霊碑","空襲の記録を伝える展示（開催時期に合わせて）"],"q":["宇都宮空襲があったのは、終戦のおよそ何か月前?","約1か月前。1945年7月12日の夜から13日の未明にかけてでした。"],"koji":[],"myth":"死者数・被災戸数・来襲機数は資料により異なる。旧篠原家住宅が焼け残ったとする点も要確認。","img":["日本本土空襲","第14師団 (日本軍)","B-29 (航空機)"],"wp":"宇都宮空襲","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/B-29s_dropping_bombs.jpg",576,896,"日本本土空襲"],["c:8/8c/B-29_Bomber_on_a_long_range_mission_in_late_1945.jpg",2048,1492,"B-29 (航空機)"]]},{"id":"09_negoyadai","n":"根古谷台遺跡（縄文の大型建物）","yomi":"ねごやだいいせき","cat":"遺跡","rank":"A","y":-4500,"era":["jomon"],"sh":"国指定史跡","ad":"宇都宮市上欠町","st":"JR宇都宮駅からバスと徒歩で約40分。車が便利（«うつのみや遺跡の広場»に駐車場あり）","la":36.562,"lo":139.811,"hook":"およそ6千年前、ムラのまん中に «ふつうの家よりずっと大きな建物» が建っていた。何に使ったのかは、いまも謎。","lead":"根古谷台遺跡は、縄文時代前期（いまから約6千年前）のムラと墓のあとです。大きな長方形の建物のあとや、300をこえる墓穴が見つかりました。いまは «うつのみや遺跡の広場» として、建物が復元され、だれでも歩いて見学できます。","story":["宇都宮の西、姿川を見下ろす台地の上。1980年代の発掘で、地面の下から «柱の穴» がつぎつぎに姿をあらわしました。ふつうの竪穴住居なら、丸い穴がいくつか並ぶだけ。ところがここでは、長い四角形にずらりと並ぶ大きな柱穴が出てきたのです。«これは家なのか、それとも別のものか?» 調査員たちは首をひねりました。","建物のあとは、ムラのまん中の広場を囲むように並んでいました。そして広場の中心には、たくさんの墓穴。人びとは、亡くなった仲間を «ムラの真ん中» に葬り、そのまわりで暮らしていたことになります。死んだ人が遠くへ行ってしまうのではなく、いつもそばにいる。縄文の人たちの «あの世» の感覚が見えてくるようです。","墓穴からは、耳かざりや首かざりの玉が見つかりました。とくに目をひくのは «玦状耳飾（けつじょうみみかざり）» という、輪の一か所が切れた石の耳かざり。きれいな石をみがいて作るのは大変な手間です。«この人はムラで大切にされていたのかな»«おしゃれは身分のしるし?» 想像がふくらみます。","では、大きな建物は何だったのでしょう。みんなが集まる集会所、まつりの場、共同の作業場、あるいは死者をしのぶための建物。いくつもの説があり、決め手はありません。わかっているのは、ふつうの家とは明らかにちがう «特別な建物» が、何度も建てかえられながら使われたらしい、ということです。","いま遺跡は公園になり、長方形の大型建物や竪穴住居が復元されています。かやぶきの大きな屋根の下に立つと、中はひんやりして薄暗く、6千年前の人びとの話し声が聞こえてきそう。資料館では出土品も見られます。«ここで何をしていたと思う?» と、家族で話し合ってみるのがいちばんの楽しみ方です。"],"tl":[["約6000年前","縄文時代前期。台地の上にムラと墓がいとなまれる"],["1980年代","開発計画にともなう発掘調査で大型建物跡や多数の墓穴が見つかる"],["1988年","国の史跡に指定"],["1990年代","«うつのみや遺跡の広場»として整備・公開"],["現在","復元建物と資料館で縄文のムラを体験できる"]],"who":[["縄文時代前期の人びと","ムラをつくり、中央に仲間を葬った"],["発掘調査にあたった研究者","柱穴の並びから大型建物の存在を明らかにした"],["宇都宮市","遺跡を保存し、公園として公開している"]],"deep":["縄文前期の «大型建物» は全国でも例が多くありません。長方形で柱が規則正しく並ぶ構造は、中期以降の東北・北陸の «ロングハウス» 系の建物と比べて語られることがあります。","ムラの中央に墓域があり、そのまわりを建物が囲む «環状» の配置は、縄文の集落研究で重要なテーマ。生活の場と墓の場が一体になっている点が注目されます。","墓の数は300をこえるとされ、1回に作られたのではなく長い期間にわたって少しずつ増えたと考えられます。同じ時期にムラに住んでいた人数は、墓の数よりずっと少なかったはずです。","玦状耳飾は中国大陸の «玦» と形が似ているため、大陸とのつながりを考える説もありますが、日本列島で独自に作られたとみる意見も強く、決着していません。","大型建物の用途は «集会所»«祭祀の場»«共同作業所»«喪屋（もや）» などの説があり、どれも決定的な証拠はありません。柱穴の深さや建て替えの回数が議論の材料です。","遺跡名の «根古谷（ねごや）» は、中世の城の麓にある家臣の屋敷地をさす «根小屋» に由来する地名と考えられ、縄文とは別の時代の記憶も地名に残っています。"],"look":["復元された長方形の大型建物（中に入ると大きさが実感できる）","ムラの中心にあたる墓域の表示","竪穴住居の復元","資料館の耳かざりなどの出土品","台地の端から見る姿川の谷（ムラが台地を選んだ理由を考えよう）"],"q":["根古谷台遺跡で、墓はムラのどこにあった?","ムラの中央の広場です。まわりを建物が囲み、亡くなった人がいつも身近にいる形でした。"],"koji":[],"myth":"大型建物の用途は諸説あり不明。玦状耳飾の起源（大陸系か列島独自か）も議論中。","img":["縄文時代","竪穴建物","玦状耳飾"],"wp":"根古谷台遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/5f/Negoyadai_ruins.jpg",2800,1757,"根古谷台遺跡"],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴建物"],["c:e/ec/Earrings_with_a_slit.jpg",2747,1457,"玦状耳飾"]]},{"id":"09_teranohigashi","n":"寺野東遺跡（縄文の環状盛土遺構）","yomi":"てらのひがしいせき","cat":"遺跡","rank":"A","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"小山市梁","st":"JR小山駅から車で約20分（«おやま縄文まつりの広場»に駐車場あり）","la":36.328,"lo":139.871,"hook":"直径およそ165m。縄文の人びとが何百年もかけて土を積み、巨大な «土の輪» をつくった。","lead":"寺野東遺跡は、縄文時代の後期から晩期（約4千〜3千年前）に、人びとが土を盛って大きな輪の形にした «環状盛土遺構» の遺跡です。水場で使った木の組み物も見つかりました。いまは «おやま縄文まつりの広場» として公開されています。","story":["1990年代のはじめ、小山市の東部で工業団地をつくる工事が始まりました。その前の発掘で、調査員たちは不思議なものに気づきます。台地の上に、土がドーナツのように輪になって盛り上がっているのです。«自然にできた丘ではない。人が積んだ土だ!» その輪は、直径がおよそ165mもありました。","盛られた土の中からは、土器のかけら、石器、焼けた土や灰、動物の骨などがたくさん出てきました。つまりこの輪は、一度に作った堤防のようなものではなく、何百年ものあいだ、まつりや暮らしの中で出た土や道具を積み重ねてできたと考えられています。«なぜわざわざ輪の形に?» それが最大の謎です。","輪の内側はくぼんだ広場になっていて、中央には石を敷いたような場所もありました。多くの研究者は、ここがムラの人たちが集まって祈りやまつりをした «聖なる広場» だったと考えています。夜、たき火を囲み、土器を割り、祖先に祈る。そんな光景が思い浮かびます。","もうひとつの大発見が、台地の下の谷で見つかった «木組遺構»。丸太や板を組んで、わき水をためる水場を作っていたのです。ここでトチの実やドングリのアクを抜いたと考えられています。«木の実は、そのままでは苦くて食べられない» ——縄文の人びとは、水と手間をかけて主食を作っていました。","発見のあと、遺跡は工業団地の中に残されることになり、国の史跡に指定されました。いまは盛土の輪のすがたが分かるように整備され、木組遺構も復元されています。広場のまん中に立ってぐるりと見回すと、4千年前の人びとが見ていた «輪の世界» を体で感じることができます。"],"tl":[["約4000年前","縄文時代後期。盛土が積まれはじめる"],["約3000年前","縄文時代晩期。環状盛土や水場の利用が続く"],["1990年ごろ","工業団地の造成にともなう発掘調査が始まる"],["1995年","国の史跡に指定"],["2000年代","«おやま縄文まつりの広場»として整備・公開"]],"who":[["縄文時代後期・晩期の人びと","土を積み、広場で祭りをし、水場で木の実を加工した"],["発掘調査にあたった研究者","環状盛土と木組遺構を明らかにした"],["小山市","遺跡を保存し、体験の場として公開している"]],"deep":["«環状盛土遺構» は関東地方の縄文後期・晩期に見られる遺構で、寺野東はその代表例。千葉や埼玉などにも類例があり、関東の縄文社会の特徴を考える手がかりになっています。","盛土がどのようにできたかは諸説あります。祭りのたびに土を盛った «意図的な造成» とみる説と、長い生活の結果として積もったとみる説があり、両方の要素があったとする意見もあります。","木組遺構は、丸太や板を井げたのように組み、水をためて使った施設。トチの実などのアク抜きをした場と考えられ、縄文人が «水を管理する技術» を持っていたことを示します。","環状盛土の内側には石を敷いた部分があり、祭りの場の中心と考えられています。土偶や石棒など、まつりに使われたとみられる道具も出土しています。","遺跡は縄文だけでなく、旧石器時代や古墳時代などの遺構も重なる «複合遺跡» です。同じ台地が、長い時代にわたって人を引きつけてきました。","開発予定地から見つかった遺跡を、計画を変えて保存した例としても知られます。発掘された遺跡の多くは記録だけ残して消えていくので、現地で輪を見られるのは貴重です。"],"look":["環状盛土の高まり（輪の上を歩いて大きさを体感）","輪の内側の広場","谷に復元された木組遺構（水場）","出土品を展示する施設","台地と谷の高低差（ムラと水場の位置関係）"],"q":["寺野東遺跡の «木組遺構» は何に使われたと考えられている?","わき水をためる水場です。トチの実などのアク抜きに使ったと考えられています。"],"koji":[],"myth":"環状盛土が意図的に作られたのか、長年の生活で積もったのかは諸説あり。","img":["縄文時代","トチノキ","小山市"],"wp":"寺野東遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Terahigashi_Site.jpg",1200,872,"寺野東遺跡"],["c:4/4e/Aesculus_turbinata%2C_Barge_walk.jpg",3648,2736,"トチノキ"],["c:8/88/%E5%AE%89%E6%88%BF%E7%A5%9E%E7%A4%BE_.jpg",5472,3648,"小山市"]]},{"id":"09_tochigi_kura","n":"栃木の蔵の街（巴波川と例幣使街道の河岸）","yomi":"とちぎのくらのまち","cat":"町","rank":"A","y":1800,"era":["edo","meiji"],"sh":"嘉右衛門町は国の重要伝統的建造物群保存地区","ad":"栃木市倭町・万町・嘉右衛門町ほか","st":"JR・東武の栃木駅から歩いて約10〜15分","la":36.383,"lo":139.733,"hook":"黒い蔵と白い土蔵が川面にうつる町。ここは «江戸へつながる川の港» だった。","lead":"栃木市の中心部は、江戸時代に巴波川（うずまがわ）の舟運と例幣使街道の宿場町として栄えました。江戸と荷物をやりとりした商人たちが建てた蔵が、今もたくさん残っています。明治のはじめには栃木県の県庁も置かれました。","story":["朝の巴波川。川べりに並ぶ黒塗りの蔵の前で、舟から米や麻の荷が下ろされます。«さあ、江戸行きの荷はこっちだ!» 江戸時代の栃木は、この川から思川・渡良瀬川・利根川を下って江戸へ荷を運ぶ «河岸（かし）» の町でした。舟は江戸から塩や海産物、日用品を運んできて、北関東各地へと届けたのです。","栃木にはもうひとつの顔がありました。京都の朝廷から日光東照宮へ、毎年お供え物を届ける使い «日光例幣使» が通る «例幣使街道» の宿場町です。公家の一行が通る日は、町じゅうが緊張したといわれます。«例幣使さまのお通り» ——そのために道が掃き清められ、宿が準備されました。","川と街道、二つの流れが集まれば、商売も栄えます。麻、木材、米などを扱う豪商たちは、火事に強い土蔵造りの店や蔵を建てました。見世蔵（みせぐら）の重たい扉、白壁、黒漆喰。«火事で全部なくすわけにはいかない» という商人の知恵が、今の町並みをつくりました。","明治に入ると、栃木町に栃木県の県庁が置かれます。ところが明治17年（1884年）、県庁は宇都宮へ移されました。«県庁を返せ» と反発もあったと伝わります。やがて鉄道の時代が来て舟運もおとろえましたが、それゆえに町は大きく作り替えられず、蔵が残ることになりました。","いま、巴波川ぞいには遊覧船が行き来し、蔵を使った資料館やカフェが並びます。北の嘉右衛門町は国の重要伝統的建造物群保存地区に選ばれました。作家・山本有三のふるさとでもあり、記念碑も立っています。川面をすべる鯉のぼりや、秋の «とちぎ秋まつり» の山車も、この町の自慢です。"],"tl":[["1646年","朝廷から日光への例幣使の派遣が始まる（以後、幕末まで毎年）"],["江戸時代中期〜後期","巴波川の舟運で栃木河岸がにぎわい、豪商の蔵が建ち並ぶ"],["1871年","栃木県が置かれ、県庁が栃木町に"],["1884年","県令・三島通庸のもとで県庁が宇都宮へ移る"],["1887年","作家・山本有三が栃木町に生まれる"],["2012年","嘉右衛門町が国の重要伝統的建造物群保存地区に選定"]],"who":[["日光例幣使","京都から日光東照宮へ幣帛を届けた朝廷の使い。この町を通った"],["栃木の豪商たち","舟運で財をなし、蔵造りの店や蔵を建てた"],["三島通庸","栃木県令。県庁を宇都宮に移した"],["山本有三","『路傍の石』などの作家。栃木町の出身"]],"deep":["巴波川の舟は «都賀舟（つがぶね）» などと呼ばれ、栃木河岸から部賀舟に積み替えて下流へ運ぶ仕組みがあったといわれます。水量の少ない上流では小さな舟を使う工夫でした。","例幣使街道は中山道の倉賀野宿（群馬県）から日光へ向かう道。例幣使は帰りは別の道を使うのがならわしで、往路だけこの道を通りました。","例幣使の一行が道中で «入魂（じっこん）» と称してお金をせびったなど、評判の悪い話も伝わりますが、誇張された話も多いとみられます。","県庁移転の理由は、宇都宮が県の中央に近いことなどが挙げられます。三島通庸は各地で強引な土木工事を進めた人物としても知られ、評価は分かれます。","見世蔵は、道に面した店舗兼用の土蔵造り。厚い土壁と観音開きの扉で、江戸の大火の経験から広まった防火建築です。","嘉右衛門町は、江戸時代初めに岡田嘉右衛門が開いたことが名の由来とされ、例幣使街道ぞいに古い町家や蔵が連なっています。"],"look":["巴波川ぞいの黒塀と蔵の並び（遊覧船から見るのもおすすめ）","見世蔵を使った資料館や商家","嘉右衛門町の町並み","山本有三ふるさと記念館","とちぎ山車会館の山車"],"q":["栃木に県庁があったのは明治何年まで?","明治17年（1884年）まで。県令・三島通庸のもとで宇都宮へ移されました。"],"koji":[],"myth":"例幣使の «入魂» のゆすりの話などは誇張を含むとみられる。舟の呼び名や積み替えの仕組みは資料により説明が異なる。","img":["巴波川","例幣使街道","嘉右衛門町","山本有三"],"wp":"栃木市","rel":{"ev":[],"grave":[]},"ph":[["c:f/fb/Tochigi_City_Montage.jpg",3072,4096,"栃木市"],["c:9/9e/%E6%A0%83%E6%9C%A8%E5%B8%82%E4%B8%AD%E5%BF%83%E9%83%A8%E3%82%92%E6%B5%81%E3%82%8C%E3%82%8B%E5%B7%B4%E6%B3%A2%E5%B7%9D.JPG",1632,1224,"巴波川"],["c:5/5e/Yuzo_Yamamoto%2C_1954.jpg",1418,2087,"山本有三"]]},{"id":"09_tokugawa_kouke","n":"日光山内の二社一寺","yomi":"にっこうさんないのにしゃいちじ","cat":"寺社","rank":"A","y":1617,"era":["nara","edo"],"sh":"国宝・国の重要文化財（世界遺産）","ad":"日光市山内","st":"JR日光駅・東武日光駅からバスで約5〜10分、または歩いて約30分","la":36.758,"lo":139.599,"hook":"«日光を見ずして結構と言うなかれ»。1200年の山岳信仰の上に、将軍家の祈りが重なった聖地。","lead":"日光山内には、日光東照宮・日光二荒山神社・日光山輪王寺の «二社一寺» があります。奈良時代に勝道上人が開いた山岳信仰の場に、江戸時代、徳川家康がまつられました。1999年に «日光の社寺» として世界遺産になりました。","story":["奈良時代の終わり、下野の僧・勝道上人は大谷川のほとりに立っていました。激しい流れで向こう岸へ渡れません。すると神が現れ、2匹の蛇を放って橋にしてくれた——これが朱色の «神橋» の起こりと伝わります。勝道は山に入り、苦労の末に男体山の頂上をきわめ、日光を山の修行の聖地にしました。","それから800年以上たった1616年、徳川家康が駿府でなくなります。家康は «一周忌がすぎたら日光に小さな堂を建てて神としてまつれ。関八州の守りとなろう» と言い残したと伝わります。翌年、遺体は久能山から日光へ移され、家康は «東照大権現» という神になりました。","いま見るきらびやかな東照宮は、孫の3代将軍・家光による «寛永の大造替» の姿です。陽明門には500をこえる彫刻がびっしり。一日中見ていても飽きないので «日暮門» とも呼ばれます。«なぜここまで豪華に?» 家光は祖父を深く敬い、将軍家の権威を天下に示そうとしたのです。","東照宮のとなりには、男体山・女峰山・太郎山の神をまつる二荒山神社があり、輪王寺には三仏堂や、家光自身の霊廟 «大猷院» があります。家光は «死んでも家康公に仕えたい» と願い、東照宮より控えめな造りにしたといわれます。神と仏が同じ山に仲よく並ぶ、日本らしい聖地です。","江戸時代、将軍や大名は何度も日光へお参りに行き（日光社参）、朝鮮通信使が訪れたこともありました。明治の神仏分離で二社一寺に分かれましたが、山全体がひとつの信仰の場であることは変わりません。杉並木を歩き、神橋をながめ、眠り猫の下をくぐる——1200年の祈りの重なりを味わってください。"],"tl":[["766年","勝道上人が大谷川の北に四本龍寺を開いたと伝わる"],["782年","勝道上人が男体山の頂上に登る"],["1616年","徳川家康が駿府でなくなる"],["1617年","家康の霊が久能山から日光へ移され、東照社がまつられる"],["1636年","3代将軍家光による寛永の大造替がほぼ完成"],["1653年","家光の霊廟・大猷院が完成"],["1871年","神仏分離により二社一寺の形に"],["1999年","«日光の社寺»が世界遺産に登録"]],"who":[["勝道上人","日光山を開いた奈良時代の僧"],["徳川家康","東照宮にまつられる。«東照大権現»"],["徳川家光","3代将軍。東照宮を大造営し、大猷院に眠る"],["天海","家康の神号や日光改葬を進めた僧"],["左甚五郎","«眠り猫» の作者と伝わる伝説的な彫刻師"]],"deep":["二社一寺の建造物のうち、東照宮の陽明門・本殿など、大猷院の本殿などが国宝、そのほか多数が重要文化財に指定されています。","家康の遺言は『本光国師日記』に記されたものとして知られ、«日光山に小さき堂をたて» といった内容が伝わります。","家康の神号をめぐっては、«明神» を推す金地院崇伝らと、«権現» を推す天海の論争があり、天海の主張が通ったといわれます。","東照宮は日光の北側、江戸城のほぼ真北にあたるとよくいわれ、北極星（北辰）信仰との関係を説く見方もありますが、設計意図としての確証はありません。","陽明門の «魔除けの逆柱»（1本だけ文様を逆さにした柱）は、«完成すると崩れ始める» という考えから、わざと未完成にしたと伝わります。","«眠り猫» の作者・左甚五郎は実在がはっきりしない伝説的な人物で、作者と伝わるにとどまります。","日光社参は将軍が行った一大行事で、江戸時代を通じて十数回行われました。大量の人馬を動員したため、街道の宿場や村々には大きな負担でした。"],"look":["神橋（朱塗りの橋）","陽明門の彫刻と逆柱","眠り猫と奥宮（家康の墓所）","三猿（神厩舎）","輪王寺三仏堂と大猷院の夜叉門"],"q":["陽明門が «日暮門» とも呼ばれるのはなぜ?","彫刻が多く美しいので、一日中見ていても飽きず日が暮れてしまう、といわれるからです。"],"koji":[{"w":"日光を見ずして結構と言うなかれ","m":"日光の美しさを見ないうちは «結構（すばらしい）» と言ってはいけない、という言いならわし"}],"myth":"神橋の蛇の話、眠り猫の作者＝左甚五郎、逆柱の意味、江戸城真北の配置意図は伝承・俗説を含む。","img":["日光東照宮","日光二荒山神社","輪王寺","神橋"],"wp":"日光の社寺","rel":{"ev":["basho"],"grave":[]},"ph":[["c:3/35/Nikko_toshogu_shrine.jpg",6000,4000,"日光の社寺"],["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"],["c:e/ed/Nikko_Futarasan_Jinja_M3292.jpg",1250,747,"日光二荒山神社"],["c:f/f7/JP-Nikko-Sanbutsu-do.JPG",1600,1063,"輪王寺"],["c:a/a2/Shinkyo_Sacred_Bridge_%2811284693104%29.jpg",4573,3049,"神橋"]]},{"id":"09_nasu_kanga","n":"那須官衙遺跡","yomi":"なすかんがいせき","cat":"遺跡","rank":"A","y":700,"era":["asuka","nara","heian"],"sh":"国指定史跡","ad":"那珂川町小川（梅曽）","st":"JR氏家駅・西那須野駅などから車で約30分。公共交通では行きにくい","la":36.74,"lo":140.133,"hook":"焼けた米が土の中から。1300年前、那須の «役所の倉» には税の米がぎっしり積まれていた。","lead":"那須官衙遺跡は、奈良・平安時代に那須郡の役所（郡衙・郡家）があったところです。税として集めた米をしまう «正倉» のあとがたくさん見つかり、焼けた米も出てきました。近くには国宝の «那須国造碑» もあり、古代那須の中心地でした。","story":["那珂川の近く、なだらかな台地の畑。ここを掘ると、黒こげになった米粒が出てくる——昔から地元でそう言われていたそうです。調べてみると、そこは古代の役所の «倉» の跡でした。«米が焼けているのは、倉が火事になったからだ!» 土の中の黒い粒が、1300年前の出来事を語り出しました。","7世紀の終わりから8世紀、国の仕組みがととのうと、全国は «国» と «郡» に分けられ、郡ごとに役所が置かれました。那須郡の役所がここ。郡司と呼ばれる地元の有力者が、税を集め、帳簿をつけ、都からの命令を村々に伝えました。«米はこの倉へ。数を帳簿にしっかり書け!» と声が飛んでいたかもしれません。","発掘では、大きな建物のあとが区画ごとに並んで見つかりました。役人が仕事をする «郡庁»、たくさんの «正倉»。正倉は、湿気やネズミを防ぐため高床にしたり、礎石を置いたりした丈夫な倉です。国全体の «財産» を守る、大切な建物でした。","近くの湯津上（大田原市）には、700年ごろの那須国造・那須直韋提（なすのあたいいで）をしのんで建てられた «那須国造碑» があります。日本最古級の石碑のひとつで、国宝です。碑があること、大きな古墳があること、そして郡の役所があること。那珂川ぞいのこのあたりが、古代那須の «都» だったことがわかります。","いま遺跡は畑と草地の中にあり、案内板が立っています。派手な建物はありませんが、足もとの土が1300年前の役所の床だと思うと、ふしぎな気持ちになります。近くのなす風土記の丘資料館で出土品を見て、那須国造碑や侍塚古墳もめぐると、古代那須の一日旅になります。"],"tl":[["689年","那須国造・那須直韋提が評督に任じられたと那須国造碑に記される"],["700年ごろ","那須国造碑が建てられる"],["7世紀末〜8世紀","那須郡の役所（郡衙）が置かれ、正倉が建ち並ぶ"],["9〜10世紀","役所の機能がしだいに衰えていく"],["1976年","国の史跡に指定"]],"who":[["那須直韋提","那須国造・評督。那須国造碑にしるされた人物"],["那須郡の郡司たち","地元の有力者。役所で税や行政をあつかった"],["徳川光圀","江戸時代に那須国造碑を調べ、侍塚古墳を発掘させた"]],"deep":["«官衙» は古代の役所のこと。郡の役所は «郡家（ぐうけ）» とも呼ばれ、政務をとる郡庁、倉庫群の正倉院、役人の館などからなっていました。","出土した炭化米は、正倉が火災にあった証拠と考えられます。郡の倉が焼ける «神火» 事件は各地で記録され、放火による不正隠しだったとみる説もあります。","那須国造碑には «永昌元年» という中国・唐の年号が使われています。日本の年号ではなく唐の年号を使った理由は、渡来人の関与など諸説あります。","那須国造碑は多胡碑（群馬）・多賀城碑（宮城）とともに «日本三古碑» と呼ばれ、国宝に指定されています。","徳川光圀は那須国造碑の主を確かめるため、1692年ごろ近くの上侍塚・下侍塚古墳を発掘させ、出土品を記録して元に戻しました。日本の考古学調査の先がけとされます。","遺跡のすぐ近くでは、古代寺院の浄法寺廃寺跡も知られ、役所と寺がセットで置かれた古代地方行政の姿がうかがえます。"],"look":["正倉が並んでいた区画の案内板","台地から見る那珂川の流れ","なす風土記の丘資料館（出土品）","那須国造碑（大田原市湯津上・笠石神社）","上侍塚・下侍塚古墳"],"q":["那須官衙遺跡で見つかった «焼けた米» は何を物語る?","税の米をしまっていた正倉（倉）が火事で焼けたことを示すと考えられています。"],"koji":[],"myth":"正倉の火災の原因（事故・放火・«神火»）は不明。国造碑に唐の年号を使った理由は諸説。","img":["那須国造碑","侍塚古墳","郡衙"],"wp":"那須官衙遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:0/06/Nasu_kanga.jpg",3774,2567,"那須官衙遺跡"],["c:3/34/Nasunokuninomiyatsukonohi-2.jpg",865,1298,"那須国造碑"]]},{"id":"09_kegon","n":"華厳滝（藤村操の投身）","yomi":"けごんのたき","cat":"事件","rank":"A","y":1903,"era":["meiji"],"sh":"","ad":"日光市中宮祠","st":"JR日光駅・東武日光駅からバスで約45分、«中禅寺温泉»下車、歩いて約5分","la":36.738,"lo":139.502,"hook":"落差97m。明治の終わり、ひとりの16歳の青年がここで命を絶ち、その言葉が日本じゅうを揺さぶった。","lead":"華厳滝は、中禅寺湖の水が一気に落ちる日本を代表する滝です。1903年（明治36年）、第一高等学校の学生・藤村操がここで亡くなり、滝のそばの木に «巌頭之感» という文を書き残しました。この出来事は当時の若者たちに大きな衝撃を与えました。","story":["中禅寺湖からあふれた水が、岩のがけを97mまっすぐに落ちていきます。ごうごうという音、白い水しぶき、その向こうに虹。奈良時代に日光を開いた勝道上人が見つけ、お経の名から «華厳» と名づけたと伝わります。那智の滝、袋田の滝とともに «日本三名瀑» に数えられます。","1903年5月、この滝の上で、ひとりの青年が命を絶ちました。第一高等学校の学生、藤村操、16歳。滝の近くのナラの木の皮をけずり、そこに «巌頭之感（がんとうのかん）» という文を書き残していました。«万有の真相は唯一言にして悉す、曰く «不可解»»——世界の本当の姿は、«わからない» という一言につきる、と。","このニュースは新聞で大きく報じられ、日本じゅうが驚きました。«なぜ、将来を期待された若者が?» 人びとは、人生や世界の意味に悩む若者の姿に、新しい時代の «心の問題» を見ました。哲学的な悩みから命を絶った、という受け止め方が広まったのです。","影響はそれだけでは終わりませんでした。彼をまねて、この滝で命を絶とうとする若者が相次いだのです。悲しい連鎖を止めるために、見回りが強められました。藤村の英語の先生だった夏目漱石は、直前の授業で彼を叱っていたといわれ、深く心を痛めたと伝わります。","いま、滝の下の観瀑台へはエレベーターで降りられ、真正面から滝を見られます。多くの観光客でにぎわう美しい場所ですが、ここには «生きる意味» に悩んだ若者の記憶も刻まれています。悩みはひとりで抱えず、だれかに話してほしい——滝の音を聞きながら、そう願わずにはいられません。"],"tl":[["奈良時代末","勝道上人が見つけ、名づけたと伝わる"],["1903年5月","第一高等学校生・藤村操が滝で亡くなり、«巌頭之感» を残す"],["1903年以降","新聞報道により社会に大きな反響。後を追う人が相次ぐ"],["1930年","観瀑台へ降りるエレベーターが設けられる"],["現在","日光を代表する観光地。観瀑台から滝を正面に望める"]],"who":[["藤村操","第一高等学校の学生。16歳で亡くなり «巌頭之感» を残した"],["夏目漱石","一高の英語教師。藤村を教えていた"],["勝道上人","日光を開いた僧。滝を見つけ名づけたと伝わる"]],"deep":["«巌頭之感» は «悠々たる哉天壌、遼々たる哉古今» で始まり、«不可解» という言葉で有名になりました。ホレーショ（シェイクスピア『ハムレット』の登場人物）の名も出てきます。","藤村の死は «哲学的煩悶による死» として報じられ、明治の青年たちの «煩悶» ブームの象徴とされました。背景に失恋があったとみる説もあり、理由はひとつに決められません。","夏目漱石が直前の授業で予習をしてこなかった藤村を叱ったという話は、漱石の周辺の回想に見えるもので、細部は確かではありません。漱石の作品に藤村を思わせる記述があるとも指摘されます。","事件後、華厳滝での自殺や未遂が続いたため、社会問題になりました。有名人の死のあとに自殺が増える現象として、今日の報道のあり方を考える例にも挙げられます。","滝は中禅寺湖の唯一の天然の出口にあたり、水量は上流の水門で調節されています。岩壁のすきまから落ちる細い «十二滝» も見どころです。","落ち口の岩は長い年月で少しずつ崩れていて、1986年にも落ち口の一部が崩落しました。滝の姿は少しずつ変わっています。"],"look":["観瀑台からの正面の眺め（エレベーターで下る）","岩壁から落ちる «十二滝»","中禅寺湖の出口と水の流れ","近くの中禅寺湖畔・二荒山神社中宮祠"],"q":["藤村操が «巌頭之感» で、世界の真相を表す一言として書いた言葉は?","«不可解»。世界の本当の姿は «わからない» という意味で使いました。"],"koji":[],"myth":"勝道上人が名づけた話は伝承。漱石が叱った逸話の細部、死の理由（哲学的煩悶か失恋か）は諸説。","img":["藤村操","中禅寺湖","日本三名瀑"],"wp":"華厳滝","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Kegon_Taki.jpg",5996,4002,"華厳滝"],["c:6/69/Misao_Fujimura.JPG",268,430,"藤村操"],["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"中禅寺湖"]]},{"id":"09_senjogahara","n":"戦場ヶ原（神々の戦いの伝説）","yomi":"せんじょうがはら","cat":"伝承","rank":"A","y":782,"era":["myth","nara"],"sh":"","ad":"日光市中宮祠（奥日光）","st":"JR日光駅・東武日光駅からバスで約1時間、«赤沼»«三本松»下車","la":36.788,"lo":139.438,"hook":"大蛇と大ムカデが戦い、矢で決着した——その «神々の戦場» が、いまは花の咲く湿原に。","lead":"戦場ヶ原は、奥日光の標高約1400mに広がる湿原です。男体山の神と赤城山の神が、中禅寺湖をめぐって戦った «戦場» だという伝説からこの名がつきました。いまはラムサール条約に登録された湿原で、木道を歩いて自然と伝説を楽しめます。","story":["むかしむかし、日光の男体山の神と、上野（群馬）の赤城山の神が、美しい中禅寺湖をどちらのものにするかで争いました。話し合いはまとまらず、ついに両方の神が姿を変えて戦うことに。男体山の神は大蛇に、赤城山の神は大ムカデになって、この広い原で激しくぶつかり合ったと伝わります。","戦いは男体山の神に不利でした。«このままでは負けてしまう» と困った神は、弓の名人を呼びます。それが猿丸（さるまる）、または小野猿丸と呼ばれる若者でした。猿丸の放った矢が大ムカデの目を射ぬき、赤城の神は逃げ帰ったといいます。","この伝説は、あちこちの地名に残っています。戦った原が «戦場ヶ原»、流れた血で赤くそまった沼が «赤沼»、勝ったことを祝って歌った浜が中禅寺湖の «歌ヶ浜»。そして «宇都宮» の名や、日光二荒山神社の «武射祭（むしゃさい）» にも、この話がつながると言われています。«地名は伝説の記念碑» なのです。","一方、学問の目で見ると、戦場ヶ原はもともと男体山の噴火でせき止められた湖で、長い年月をかけて土砂や植物が積もり、湿原になったと考えられています。神々の争いの話は、火山や山の神への信仰から生まれたのかもしれません。«なぜ大蛇と大ムカデ?» ——山や川の姿を生き物にたとえたのでしょうか。","いま戦場ヶ原には、木道が通っています。初夏にはワタスゲやホザキシモツケ、秋には草紅葉が一面に広がり、男体山がどっしりと見下ろします。2005年にはラムサール条約の登録湿地にもなりました。風に揺れる草原に立って、遠い昔の神々の戦いを思いうかべてみましょう。"],"tl":[["太古","男体山の噴火でせき止められた湖が、やがて湿原になる"],["782年","勝道上人が男体山の頂上に登り、日光の山岳信仰が広がる"],["中世〜近世","男体山と赤城山の神の «神戦» の伝説が語られる"],["1934年","日光国立公園に指定される"],["2005年","奥日光の湿原としてラムサール条約に登録"]],"who":[["男体山の神（二荒山大神）","大蛇の姿で戦ったと伝わる"],["赤城山の神","大ムカデの姿で戦ったと伝わる"],["猿丸（小野猿丸）","弓の名人。男体山の神を助けたと伝わる"],["勝道上人","男体山に登り、日光を信仰の山にした僧"]],"deep":["神戦の伝説は、日光山の縁起をまとめた『日光山縁起』などに見え、猿丸は有宇中将の子とされるなど、物語はさまざまに語られます。","赤城山側では逆に、赤城の神が大蛇、男体山の神が大ムカデとされる話もあり、どちらが勝ったかも立場によって語りが変わるのが面白い点です。","猿丸を和歌の «猿丸大夫» と結びつける伝えもありますが、同一人物とする根拠ははっきりしません。","日光二荒山神社中宮祠の武射祭は、正月に大ムカデの目に見立てた的を射る神事で、この神戦の伝説にちなむといわれます。","戦場ヶ原の広さは約400haとされ、湿原から草原へと少しずつ乾いて変化しています。シカの食害を防ぐため、周囲に柵が設けられています。","«宇都宮» の地名の由来を、この神戦で勝った «現（うつ）の宮» などと結びつける話もありますが、地名の由来は諸説あります。"],"look":["赤沼から湯滝へ続く木道","戦場ヶ原展望台から見る男体山","赤沼（血で赤くなったと伝わる）","中禅寺湖の歌ヶ浜","湯滝・竜頭ノ滝などあわせてめぐる滝"],"q":["伝説で、男体山の神を助けた弓の名人の名前は?","猿丸（小野猿丸）です。大ムカデの目を射ぬいたと伝わります。"],"koji":[],"myth":"神戦の伝説は複数の版があり、蛇とムカデの割り当ても逆の話がある。地名の由来も伝承。","img":["男体山","赤城山","中禅寺湖","湯滝"],"wp":"戦場ヶ原","rel":{"ev":[],"grave":[]},"ph":[["c:b/ba/Chugushi%2C_Nikko%2C_Tochigi_Prefecture_321-1661%2C_Japan_-_panoramio_%285%29.jpg",1800,1200,"戦場ヶ原"],["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"男体山"],["c:c/c7/MountAkagi.jpg",2152,1426,"赤城山"],["c:d/dd/%E6%B9%AF%E6%BB%9D_-_panoramio_%286%29.jpg",5184,3456,"湯滝"]]},{"id":"09_daichuji","n":"大中寺（七不思議と上杉謙信）","yomi":"だいちゅうじ","cat":"伝承","rank":"A","y":1489,"era":["muromachi","azuchi"],"sh":"","ad":"栃木市大平町西山田","st":"JR・東武の栃木駅から車で約15分。車が便利","la":36.379,"lo":139.692,"hook":"«根のない藤»«開かずの雪隠»……七つの不思議がひそむ山の寺。上田秋成の怪談の舞台ともいわれる。","lead":"大中寺は、太平山のふもとにある曹洞宗のお寺です。«大中寺の七不思議» という怪しい言い伝えで知られ、江戸時代の怪談集『雨月物語』の «青頭巾» のモデルともいわれます。上杉謙信とのかかわりも伝わる、歴史と伝説の寺です。","story":["杉木立にかこまれた石段をのぼると、ひっそりとした山門。大中寺は、もとは真言宗の寺だったのが、戦国時代の少し前に曹洞宗の寺として立て直されたと伝わります。«このお寺には、だれにも説明できないことが七つある» ——そんなうわさが、昔から語られてきました。","七不思議の中身はこうです。根がないのに花を咲かせる «根なしの藤»。馬の首が落ちたと伝わる «馬首の井戸»。開けてはいけない «開かずの雪隠（トイレ）»。寝ているうちに枕の向きが変わる «枕返しの間»。そのほか «油坂»«不断のかまど»«東山の一口拍子木»。どれも悲しい話や怪しい話がついています。","大中寺は、江戸時代の上田秋成が書いた『雨月物語』の «青頭巾» の舞台のモデルとも言われます。お話では、かわいがっていた少年をなくして鬼になった寺の住職を、旅の禅僧・快庵が教えで救います。«江月照らし松風吹く、永夜清宵何の所為ぞ» ——この問いを唱え続けた鬼の僧は、やがて骨だけになって消えた、という不思議な結末です。","もうひとつの伝えが、越後の上杉謙信とのかかわりです。戦国時代、謙信は関東に何度も攻め込みました。このあたりも戦にまきこまれましたが、大中寺の住職が謙信の縁者（叔父）だったため、寺は焼かれずに守られた、と伝わります。«縁者の寺には手を出すな» ——本当かどうかは、たしかな記録では確かめられていません。","江戸時代、大中寺は関東の曹洞宗をまとめる大きな寺のひとつとして重んじられました。いまも境内には七不思議の場所が点々と残り、案内板を頼りにめぐることができます。こわい話が苦手でも大丈夫。春には周りの太平山で桜やあじさいが楽しめる、静かで美しいお寺です。"],"tl":[["平安時代","真言宗の寺として始まったと伝わる"],["1489年ごろ","快庵妙慶が曹洞宗の寺として再興したと伝わる"],["戦国時代","上杉謙信の関東出兵。寺は謙信とのゆかりで守られたと伝わる"],["江戸時代","関東の曹洞宗の中心的な寺のひとつとして重んじられる"],["1776年","上田秋成『雨月物語』刊行。«青頭巾» のモデルとされる"]],"who":[["快庵妙慶","大中寺を曹洞宗として再興したと伝わる僧。«青頭巾» の快庵禅師と名が重なる"],["上杉謙信","越後の戦国大名。寺を守ったと伝わる"],["上田秋成","『雨月物語』の作者"],["皆川氏など地元の領主","戦国期にこの地域を治めた"]],"deep":["七不思議の数え方や中身は資料によって少しずつちがい、«不断のかまど» のかわりに別の話が入ることもあります。","«青頭巾» の舞台は «下野の国富田» の山寺とされ、大中寺の近くの地名と重なることから、大中寺がモデルだといわれるようになりました。","物語の主人公 «快庵禅師» と、大中寺を再興したとされる «快庵妙慶» は名前が同じで、秋成がこの寺の伝えを知っていた可能性が指摘されています。","上杉謙信と大中寺のつながりを示す話は寺伝によるもので、同時代の確かな史料で確かめられているわけではありません。","江戸時代、大中寺は下総の総寧寺・武蔵の龍穏寺とならぶ «関三刹» のひとつとされ、全国の曹洞宗の寺を取りしまる役目をになったといわれます。","境内の «開かずの雪隠» は、昔ここで起きた悲劇にちなむ話が伝わりますが、内容は語り手によって異なります。"],"look":["七不思議の各所（案内板あり）","石段と山門の杉木立","本堂と境内の雰囲気","周辺の太平山（あじさい坂・謙信平の展望）"],"q":["『雨月物語』で大中寺がモデルといわれるお話の題名は?","«青頭巾（あおずきん）» です。鬼になった住職を快庵禅師が救う話です。"],"koji":[{"w":"江月照らし松風吹く 永夜清宵何の所為ぞ","m":"«青頭巾» で快庵禅師が鬼の僧に与えた禅の問い。月が照り風が吹くこの長い夜は何のためにあるのか"}],"myth":"寺の起こり、謙信との縁、七不思議、«青頭巾» のモデル説はいずれも伝承・通説。","img":["雨月物語","上田秋成","上杉謙信","太平山"],"wp":"大中寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Daich%C5%ABji_Temple.jpg",3919,2939,"大中寺"],["c:0/0c/Tales_of_Moonlight_and_Rain_cover.jpg",718,1000,"雨月物語"],["c:0/03/Ueda_Akinari.jpg",300,625,"上田秋成"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"]]},{"id":"09_dokyo","n":"道鏡塚（龍興寺）","yomi":"どうきょうづか","cat":"墓所","rank":"A","y":772,"era":["nara"],"sh":"","ad":"下野市薬師寺（龍興寺境内）","st":"JR自治医大駅から歩いて約30分、または車で約10分","la":36.3985,"lo":139.8595,"hook":"天皇の位に手が届きかけた僧が、流された先の下野でひっそり眠る。","lead":"道鏡は奈良時代の僧で、称徳天皇に深く信頼され、法王という高い位にまでのぼりました。しかし天皇が亡くなると、下野薬師寺へ追いやられ、ここで生涯を終えました。龍興寺の境内にある小さな塚が、道鏡の墓と伝わる «道鏡塚» です。","story":["8世紀の奈良の都。病気の女帝・孝謙上皇を、ひとりの僧が看病して治したといわれます。河内（大阪府）出身の道鏡です。上皇は道鏡を深く信じるようになり、やがて再び天皇の位について称徳天皇となると、道鏡を太政大臣禅師、さらに «法王» という前例のない位につけました。","769年、九州の宇佐八幡宮から «道鏡を天皇にすれば天下は太平になる» というお告げが届きます。«本当だろうか?» 天皇は和気清麻呂を宇佐へ確かめに行かせました。清麻呂が持ち帰った答えは «天皇には必ず皇族を立てよ。道にはずれた者は早くはらいのけよ»。道鏡の即位はなくなり、清麻呂は怒りをかって流されました。","翌770年、称徳天皇が亡くなると、道鏡の運命は一気に変わります。都を追われ、遠い東国・下野の «下野薬師寺» の別当（寺の長）として送られたのです。下野薬師寺は、奈良の東大寺・筑紫の観世音寺とならぶ «天下の三戒壇» のひとつ。大きな寺ではありましたが、事実上の追放でした。","772年、道鏡はこの地でなくなり、身分の低い人として葬られたと記録にあります。«かつては法王、いまは庶人» ——その落差を、人びとはどう見たでしょうか。下野薬師寺の跡のそばにある龍興寺の境内には、こんもりとした塚があり、これが道鏡の墓と伝わっています。","道鏡は長く «天皇の位をねらった悪い僧» として語られてきましたが、近年は、称徳天皇の政治の中で仏教を重んじた政策の担い手だった、と見直す研究もあります。道鏡塚の前に立ち、すぐ近くの下野薬師寺跡を歩けば、奈良の都の大事件が、ここ下野とつながっていたことを実感できます。"],"tl":[["761年","下野薬師寺に戒壇が置かれ、天下の三戒壇のひとつとなる"],["764年","藤原仲麻呂の乱。道鏡が大臣禅師となる"],["766年","道鏡が法王となる"],["769年","宇佐八幡宮神託事件。和気清麻呂が神託を持ち帰り、道鏡の即位は阻まれる"],["770年","称徳天皇が亡くなり、道鏡は下野薬師寺別当として送られる"],["772年","道鏡、下野でなくなる。庶人として葬られたと記録される"]],"who":[["道鏡","奈良時代の僧。法王にまでのぼり、下野で没した"],["称徳天皇（孝謙天皇）","道鏡を重く用いた女帝"],["和気清麻呂","宇佐八幡の神託を確かめ、道鏡の即位を阻んだ"],["鑑真","唐から来た僧。日本に正式な戒律を伝えた。龍興寺の開基と伝わる"]],"deep":["道鏡の下野での死と葬られ方は『続日本紀』に記され、«庶人» の身分で葬られたとされます。","宇佐八幡宮神託事件は、神託を持ちこんだ人物や、称徳天皇が本当に道鏡に位を譲るつもりだったのかなど、解釈がいくつもあり、研究者の議論が続いています。","下野薬師寺の戒壇は761年に設けられ、東国の僧はここで正式な僧になるための戒を受けました。道鏡はその寺の長として送られたわけで、完全な流罪ではないとも言えます。","道鏡塚は直径十数mほどの円墳状の塚で、本当に道鏡の墓かどうかを確かめる発掘などの根拠はなく、«伝承の墓» です。","龍興寺は鑑真の開基と伝わる寺で、下野薬師寺とのつながりを伝えていますが、創建の事情ははっきりしません。","道鏡については、後世に作られた下品なうわさ話が多く伝わりますが、いずれも史実ではなく、政治的な敗者への中傷から生まれたものと考えられます。"],"look":["龍興寺境内の道鏡塚","下野薬師寺跡（回廊などの復元整備）","下野薬師寺歴史館","近くの安国寺（戒壇の伝えを残す寺）"],"q":["道鏡の即位を阻んだ、宇佐八幡宮の神託を確かめに行った人物は?","和気清麻呂です。«天皇には必ず皇族を» という神託を持ち帰りました。"],"koji":[],"myth":"道鏡塚が本当の墓かは不明（伝承）。龍興寺の鑑真開基も伝承。神託事件の真相は諸説。道鏡の俗説は後世の中傷。","img":["下野薬師寺","称徳天皇","和気清麻呂","宇佐八幡宮神託事件"],"wp":"道鏡","rel":{"ev":[],"grave":[]},"ph":[["c:0/07/D%C5%8Dky%C5%8D.jpg",500,500,"道鏡"],["j:2/2c/%E4%B8%8B%E9%87%8E%E8%96%AC%E5%B8%AB%E5%AF%BA_%E5%BE%A9%E5%85%83%E5%9B%9E%E5%BB%8A.JPG",3648,2736,"下野薬師寺"],["c:1/17/Empress_K%C5%8Dken_01.jpg",713,1026,"称徳天皇"],["c:9/9d/Wake_no_Kiyomaro.png",3044,4523,"和気清麻呂"],["c:a/ad/Usa_Shrine_Nanchu_Romon.JPG",3072,2304,"宇佐八幡宮神託事件"]]},{"id":"09_yoichi","n":"那須与一の里（那須氏の本拠）","yomi":"なすのよいちのさと","cat":"伝承","rank":"A","y":1185,"era":["heian","kamakura"],"sh":"","ad":"大田原市南金丸（那須神社・那須与一伝承館）","st":"JR西那須野駅から車で約20分。車が便利","la":36.839,"lo":140.052,"hook":"«南無八幡大菩薩»——波にゆれる扇を一矢で射落とした若武者のふるさと。","lead":"那須与一は、源平の屋島の戦いで、平家の舟に立てられた扇の的を見事に射落としたと『平家物語』に語られる弓の名人です。大田原市の那須神社は、与一が祈ったと伝わる神社で、近くの «那須与一伝承館» では物語と那須氏の歴史を学べます。","story":["1185年2月、四国・屋島。源氏に追われた平家は海の舟に逃れ、夕暮れのなか一艘の小舟をこぎ出しました。舟の上には、竿の先に日の丸の扇。«これを射てみよ» という挑戦です。源義経が弓の上手を探し、選ばれたのが下野国那須の若武者・与一でした。","扇までの距離は遠く、北風が強く吹き、舟は波にゆれて扇も揺れ動いています。«外したら、源氏の恥。生きては帰れぬ» ——与一は目を閉じて祈りました。«南無八幡大菩薩、わが国の神明、日光権現、宇都宮、那須の湯泉大明神、願わくはあの扇のまん中射させてたばせたまえ»。","目を開けると、風が少し弱まっていました。与一は鏑矢をつがえ、ひょうと放ちます。矢は扇の要のきわを射切り、扇は空へ舞い上がって、夕日にかがやきながら海へ落ちました。源氏は箙をたたいてどよめき、平家も舟ばたをたたいてほめたたえた——『平家物語』でもっとも有名な場面のひとつです。","与一の名は «十あまり一»、つまり11番目の男子という意味だといわれます。兄たちが平家方についたため、手柄を立てた与一が那須家を継いだと伝わります。那須氏はその後、この地域の有力な武士として戦国時代まで続き、烏山城などを本拠にしました。","大田原市の那須神社は、与一が屋島に出る前に祈り、帰ってからお礼をしたと伝わる神社です。すぐ近くの道の駅には «那須与一伝承館» があり、扇の的の場面を人形やからくりで楽しめます。ただし与一のことは『平家物語』など軍記物語が中心で、確かな記録は多くありません。物語と歴史の境目を考えながら歩くのも、この里の楽しみです。"],"tl":[["平安時代末","那須資隆の子として与一が生まれたと伝わる"],["1185年2月","屋島の戦い。『平家物語』では与一が扇の的を射落とす"],["鎌倉時代","那須氏が那須の地を治める武士として続く"],["戦国時代","那須氏は烏山城などを本拠に下野北部で勢力をふるう"],["1590年","小田原攻めに遅れた那須資晴が所領を没収される（のち一族は再興）"],["現在","那須神社や那須与一伝承館で与一の伝承が語り継がれる"]],"who":[["那須与一宗隆","屋島で扇の的を射た弓の名人（『平家物語』）"],["源義経","屋島の戦いで与一に扇を射るよう命じた"],["那須資隆","与一の父と伝わる"],["那須資晴","戦国時代の那須氏当主"]],"deep":["与一の活躍を伝えるのは主に『平家物語』や『源平盛衰記』で、鎌倉幕府の記録『吾妻鏡』には見えません。そのため与一の実在や細部を疑問視する見方もあります。","与一の名乗りは «宗隆» とも «資隆» とも伝わり、父の名との関係など系図によってまちまちです。","扇の的までの距離は『平家物語』で «七段ばかり»（約70m余り）とされ、実際にそれほどの距離で射落とせたかは議論の種になってきました。","与一の祈りの言葉に «日光権現»«宇都宮»«那須の湯泉大明神» と下野の神々が並ぶことは、東国武士の信仰を知る手がかりとされます。","与一の墓と伝わる場所は京都の即成院や、兵庫県、那須地方など複数あり、どれが本当かはわかりません。","那須神社の本殿・拝殿・楼門は江戸時代の建物で、近くの藩主の保護を受けて整えられたといわれ、文化財として大切に守られています。"],"look":["那須神社の楼門と本殿","那須与一伝承館（扇の的の再現）","道の駅那須与一の郷","那須氏ゆかりの烏山城跡（那須烏山市）もあわせて"],"q":["那須与一の «与一» という名前の意味は?","«十あまり一»、つまり11番目の男子という意味だといわれます。"],"koji":[{"w":"南無八幡大菩薩","m":"武士が弓矢の神・八幡神に祈るときの言葉。与一が扇を射る前に唱えたと『平家物語』にある"}],"myth":"与一の活躍は軍記物語が主な出典で、実在や細部は不確か。名乗り・墓所・那須神社での祈願も伝承。","img":["那須氏","屋島の戦い","那須神社","平家物語"],"wp":"那須与一","rel":{"ev":[],"grave":[]},"ph":[["c:6/64/NasunoYoichi.jpg",1260,961,"那須与一"],["c:6/65/%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%88%E4%B8%B8%E3%81%AB%E4%B8%80%E6%96%87%E5%AD%97%EF%BC%89%E7%B4%8B.png",4000,4000,"那須氏"],["c:4/48/Battle_of_Yashima_Folding_Screens_Kano_School.jpg",10969,4896,"屋島の戦い"],["c:b/bc/Nasu-jinja%2C_roumon-1.jpg",5552,3690,"那須神社"],["c:7/73/%E5%B9%B3%E5%AE%B6%E7%89%A9%E8%AA%9E%EF%BD%A5%E7%A5%87%E5%9C%92%E7%B2%BE%E8%88%8E%E3%82%B5%E3%83%B3%E3%83%97%E3%83%AB.png",974,732,"平家物語"]]},{"id":"09_kofun_mibu","n":"壬生車塚古墳（大型円墳）","yomi":"みぶくるまづかこふん","cat":"遺跡","rank":"A","y":620,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"壬生町壬生甲","st":"東武宇都宮線 壬生駅から歩いて約20分","la":36.4225,"lo":139.81,"hook":"前方後円墳の時代が終わったあと、下野の王が選んだのは «とびきり大きな丸い墓» だった。","lead":"壬生車塚古墳は、7世紀の前半ごろに造られた大きな円墳です。直径は80mをこえ、三段に土を積み、まわりを堀で囲んでいます。南側には、大きな石を切って組んだ石室があり、下野の有力者が葬られたと考えられています。","story":["壬生の町の東、畑と林の中に、こんもりと大きな丘がそびえています。近づくと、丘は三段の階段のように積まれていて、まわりには広い堀のくぼみ。«これが全部、人の手で積んだ土?» ——そう、壬生車塚古墳は、東日本でも最大級の円墳なのです。","6世紀まで、関東の有力者たちは «前方後円墳» という鍵穴の形の古墳を競って造っていました。ところが7世紀に入ると、前方後円墳はぱったりと造られなくなります。代わりに、下野の有力者たちは大きな円墳や方墳を造るようになりました。«時代が変わった» ことを、古墳の形が教えてくれるのです。","古墳の南側には、横穴式石室があります。凝灰岩という加工しやすい石を、四角くていねいに切りそろえて組み上げた石室です。昔の人は «ここに車が埋められている» と考えたのか、それとも形が車輪に似ているからか、名前の «車塚» の由来ははっきりしません。石室の中に何が納められていたのかも、昔に盗掘されていてよくわかっていません。","この古墳が造られたころ、日本は飛鳥の都を中心に、国の仕組みを大きく変えようとしていました。まもなく古墳を造る時代そのものが終わり、地方の有力者は «郡司» として国の役人に組みこまれていきます。壬生車塚古墳は、下野の «王» たちが最後に見せた力の記念碑だったのかもしれません。","いま古墳は公園のように整えられ、墳丘や堀のまわりを歩くことができます。近くには、牛塚古墳・愛宕塚古墳など、同じころの大型古墳も集まっています。壬生町の歴史民俗資料館とあわせてめぐれば、古墳時代の終わりに起きた «大変化» が、足で感じられるはずです。"],"tl":[["6世紀","下野で大型の前方後円墳が次々に造られる"],["7世紀前半","壬生車塚古墳が造られる（大型円墳の時代へ）"],["7世紀後半","古墳造りがしだいに終わり、律令国家の時代へ"],["大正時代","国の史跡に指定される"],["現在","墳丘と周溝が残り、見学できる"]],"who":[["葬られた下野の有力者","名前は伝わらない。この地域をおさめた人物と考えられる"],["壬生氏など後世の領主","中世には壬生の地を治め、古墳群の近くに城を築いた"],["古墳研究者","石室や墳丘の形から、造られた時代を推定してきた"]],"deep":["墳丘は三段に築かれ、直径80mをこえる大きさで、東日本の円墳としては最大級。まわりを囲む周溝を含めると、さらに広い範囲を占めます。","石室は凝灰岩の切石を組んだ横穴式石室で、玄室・前室などに分かれるていねいな造りです。こうした切石積みの石室は7世紀の下野の有力古墳に多く見られます。","下野の6世紀の前方後円墳には、墳丘のまわりに広い平らな段 «基壇» をめぐらせ、前方部に石室を置く特徴があり «下野型古墳» と呼ばれます。円墳の時代になってもその伝統とのつながりが議論されます。","7世紀に大型の円墳・方墳が造られるのは、前方後円墳をやめるよう中央から求められた、あるいは身分秩序が変わったためなど、いくつかの説があります。","周辺には牛塚古墳（帆立貝形）・愛宕塚古墳（前方後円墳）などがあり、«壬生古墳群» として、6世紀から7世紀への古墳の移り変わりを一か所で追えます。","古墳の名の «車塚» は全国に多く、墳丘の形や言い伝えに由来するとされますが、この古墳での由来ははっきりしていません。"],"look":["三段に積まれた墳丘の姿","墳丘をめぐる周溝のくぼみ","南側の横穴式石室の入口","近くの牛塚古墳・愛宕塚古墳","壬生町立歴史民俗資料館"],"q":["7世紀になると、下野の有力者の墓は前方後円墳から何に変わった?","大きな円墳や方墳です。壬生車塚古墳はその代表です。"],"koji":[],"myth":"«車塚» の名の由来は不明。大型円墳に変わった理由は諸説。","img":["円墳","横穴式石室","壬生町"],"wp":"壬生車塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:d/d7/Mibu_Kurumazuka_Kofun%2C_funkyu-5.jpg",5568,3712,"壬生車塚古墳"],["c:3/37/Hachimanyama_kofun-Aichi02.jpg",712,440,"円墳"],["c:5/59/Monjuin_Nishi_Kofun%2C_sendou-1.jpg",6002,3978,"横穴式石室"],["j:8/8c/Mibu_Toy_Museum_Appearance_1.JPG",4755,3170,"壬生町"]]},{"id":"09_biwazuka","n":"琵琶塚古墳","yomi":"びわづかこふん","cat":"遺跡","rank":"B","y":530,"era":["kofun"],"sh":"国指定史跡","ad":"小山市飯塚","st":"JR小山駅から車で約15分。車が便利","la":36.391,"lo":139.812,"hook":"全長およそ120m。琵琶の形をした、思川のほとりの «王の墓»。","lead":"琵琶塚古墳は、6世紀前半ごろに造られた大きな前方後円墳で、全長は約120mあり、栃木県でもトップクラスの大きさです。形が楽器の琵琶に似ていることから名づけられました。すぐ近くには摩利支天塚古墳もあり、思川ぞいの有力者の墓が並んでいます。","story":["思川が流れる小山市北部の平野。田んぼの中に、長い丘が横たわっています。上から見ると、丸い部分と四角い部分がつながった «鍵穴» の形。前方後円墳です。昔の人は、その姿を楽器の琵琶に見立てて «琵琶塚» と呼びました。«たしかに、ふっくらした琵琶のよう!»","この古墳が造られたのは、6世紀の前半。すぐ北には、少し前に造られた摩利支天塚古墳があります。二つの大きな前方後円墳が近くに並ぶのは、思川ぞいに代々力をもった一族がいて、親から子へと王の座が受けつがれたからだと考えられています。","«なぜこの場所に?» 思川は、昔から人やものが行き来する大切な川の道でした。川を使えば、遠くから石や品物を運べます。川のほとりに大きな墓を築けば、行き交う人びとに一族の力を見せつけることもできます。古墳は、お墓であると同時に «力のアピール» でもあったのです。","古墳のまわりには、周溝という堀がめぐり、墳丘には円筒埴輪などが並べられていたと考えられています。調査では埴輪のかけらが見つかり、どんな人物や動物の埴輪が並んでいたのか、研究者たちは想像をふくらませています。","いま琵琶塚古墳は整備され、近くには出土品を展示する資料館もあります。すぐ南の下野市側には «しもつけ古墳群» と呼ばれる大型古墳が点々と並び、6世紀の下野がとても豊かで力のある地域だったことがわかります。自転車で古墳をめぐるのも楽しいルートです。"],"tl":[["5世紀末ごろ","摩利支天塚古墳が造られる"],["6世紀前半","琵琶塚古墳が造られる"],["6世紀後半","周辺（しもつけ古墳群）で大型古墳の築造が続く"],["昭和〜平成","範囲確認の調査が進み、史跡として整備される"],["現在","墳丘の整備と資料館での展示が行われている"]],"who":[["葬られた思川流域の首長","名前は伝わらない。下野南部を治めた有力者と考えられる"],["摩利支天塚古墳の被葬者","琵琶塚より前の世代の首長と考えられる"],["小山市","古墳を整備し、資料館で紹介している"]],"deep":["全長は約123mとされ、栃木県内では最大級の前方後円墳のひとつ。県内で最も大きいのは壬生町・栃木市にまたがる吾妻古墳とされます。","隣の摩利支天塚古墳（全長約117m）とあわせて国の史跡に指定され、二つの古墳が連続して築かれたことが注目されています。","6世紀の下野の前方後円墳には、墳丘のすそに広い平らな段 «基壇» をもつものが多く、«下野型古墳» と呼ばれます。琵琶塚古墳もこの流れの中で語られます。","墳丘から見つかる円筒埴輪は、近くの窯で作られたものと考えられ、埴輪づくりの工房と古墳造りが地域の中で組織されていたことがうかがえます。","埋葬施設（石室など）は本格的に発掘されておらず、だれがどう葬られたかはわかっていません。","古墳の名前は、形が琵琶に似ていることに由来するといわれます。全国にも «琵琶塚» と呼ばれる古墳がいくつかあります。"],"look":["前方後円墳の全体の形（くびれ部に注目）","墳丘のすそにめぐる平らな段（基壇）","周溝の跡","近くの摩利支天塚古墳","出土品を展示する資料館"],"q":["琵琶塚古墳の名前の由来は?","古墳の形が楽器の琵琶に似ていることからといわれます。"],"koji":[],"myth":"被葬者は不明。摩利支天塚との親子関係は推定。","img":["前方後円墳","摩利支天塚古墳","思川"],"wp":"琵琶塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:e/eb/Biwazuka_Kofun%2C_funkyu-2.jpg",5568,3712,"琵琶塚古墳"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:8/8c/Marishitenzuka_Kofun%2C_funkyu.jpg",5568,3712,"摩利支天塚古墳"]]},{"id":"09_kabutozuka","n":"甲塚古墳（機織り形埴輪）","yomi":"かぶとづかこふん","cat":"遺跡","rank":"B","y":570,"era":["kofun"],"sh":"","ad":"下野市国分寺","st":"JR小金井駅から車で約10分（しもつけ風土記の丘周辺）","la":36.4135,"lo":139.841,"hook":"1500年前の女性が、埴輪の中でいまも «はた» を織っている。","lead":"甲塚古墳は、6世紀後半ごろに造られた古墳です。2004年の発掘調査で、はた織りをする女性の埴輪が見つかり、大ニュースになりました。古墳時代に布を織る道具が、埴輪としてはっきり形に残っている、とても珍しい例です。","story":["下野国分寺跡の近く、しもつけ風土記の丘。ここにある甲塚古墳は、長いあいだ «ふつうの古墳» と思われていました。ところが2004年の発掘で、墳丘のまわりの平らな段から、埴輪が並んだままの状態で見つかったのです。«倒れて埋もれた埴輪が、ほとんどそのままの位置に!» 調査員は息をのみました。","埴輪の列の中に、こしかけて手を動かす女性の姿がありました。その前には、はた織りの道具。糸を張り、横糸を通して布を織るための «機（はた）» です。しかも2体あり、それぞれ形のちがう機を使っていました。古墳時代の機織りの道具が、こんなにはっきり分かる埴輪は、ほかにほとんどありません。","«なぜ、お墓に機織りの埴輪を?» 布は、古墳時代の人にとってとても大切な宝でした。王に仕える女性たちが布を織ったり、神へのささげものにしたりしたのかもしれません。埴輪の列は、王の生前のくらしや儀式の場面を再現した «ジオラマ» だったと考えられています。","甲塚古墳の埴輪にはほかにも、馬や人物、ついた色の残るものがあり、1500年前の «色» まで伝えてくれます。赤や白などで塗り分けられた埴輪は、完成したときには、いまよりずっと華やかだったはずです。","出土した埴輪は、近くの «しもつけ風土記の丘資料館» で見ることができます。古墳そのものも、国分寺跡や国分尼寺跡とともに歩いてめぐれます。1500年前の女性の手もとをじっと見つめると、«カタン、カタン» と機の音が聞こえてきそうです。"],"tl":[["6世紀後半","甲塚古墳が造られ、墳丘まわりに埴輪が並べられる"],["8世紀","近くに下野国分寺・国分尼寺が建てられる"],["2004年","発掘調査で機織り形埴輪などが並んだ状態で見つかる"],["その後","出土埴輪が高く評価され、文化財に指定される"],["現在","しもつけ風土記の丘資料館で埴輪を展示"]],"who":[["葬られた地域の有力者","名前は伝わらない"],["機を織る女性の埴輪","王に仕え、布を織った人びとの姿を表すと考えられる"],["発掘調査にあたった研究者","埴輪列を記録し、機の構造を明らかにした"]],"deep":["甲塚古墳は、円墳に小さな張り出しがつく «帆立貝形古墳» とされ、墳丘のまわりに広い平らな段（基壇）がめぐる、下野らしい形をしています。","機織り形埴輪は2体あり、一方は腰で経糸を張る «原始機（地機に近いもの）»、もう一方は台をもつ機と考えられ、古墳時代の機の構造を知る貴重な資料です。","埴輪は基壇の上に列をなして並んでいて、倒れたままの状態で見つかったため、もとの並べ方を復元できた点が大きな成果とされます。","埴輪には赤などの彩色が残るものがあり、完成時の色づかいを知る手がかりになっています。","甲塚古墳の出土埴輪は、その重要性から国の重要文化財に指定されたと報じられています。","すぐ近くの下野国分寺・国分尼寺は8世紀の寺で、古墳時代の有力者の地が、のちに国の中心施設の地になった流れもたどれます。"],"look":["甲塚古墳の墳丘と基壇","しもつけ風土記の丘資料館の機織り形埴輪","下野国分寺跡・国分尼寺跡","周辺の古墳群"],"q":["甲塚古墳の埴輪で、女性は何をしている?","はた織り（機で布を織ること）をしています。古墳時代の機の形がわかる珍しい埴輪です。"],"koji":[],"myth":"機の種類の呼び方や、埴輪列が何の場面を表すかは研究者により解釈が分かれる。","img":["埴輪","下野国分寺","しもつけ風土記の丘"],"wp":"甲塚古墳 (下野市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/34/Kabutozuka_Kofun_%28Shimotsuke%29_zenkei.JPG",6016,4000,"甲塚古墳 (下野市)"],["c:e/e4/%E5%A1%9A%E5%BB%BB%E3%82%8A%E5%8F%A4%E5%A2%B3_-_panoramio.jpg",1280,960,"埴輪"],["c:0/04/Shimotsuke-kokubunji_hondou.JPG",3648,2736,"下野国分寺"]]},{"id":"09_hoshino","n":"星野遺跡（旧石器論争の遺跡）","yomi":"ほしのいせき","cat":"遺跡","rank":"B","y":-30000,"era":["kyuseki","jomon"],"sh":"","ad":"栃木市星野町","st":"JR・東武の栃木駅から車で約30分。公共交通では行きにくい","la":36.455,"lo":139.645,"hook":"«これは人が作った石器か、自然に割れた石か»——日本の旧石器研究をゆさぶった山里の遺跡。","lead":"星野遺跡は、栃木市北部の山あいにある遺跡です。1960〜70年代、考古学者の芹沢長介が発掘し、とても古い時代の «石器» が見つかったと発表しました。しかし «自然に割れた石ではないか» という反論も出て、大きな論争になりました。","story":["栃木の町から北へ、山あいの小さな集落・星野。1960年代、ここの地層から、割れた石がたくさん見つかりました。東北大学の芹沢長介は、それを «人が作った石器» だと考え、何度も発掘を重ねます。«日本列島には、ずっと古い時代から人がいたのだ!» 芹沢はそう主張しました。","当時、日本の旧石器時代の研究は始まったばかりでした。群馬県の岩宿遺跡で、関東ローム層から石器が見つかったのが1949年。それよりはるかに古い «前期旧石器» が日本にもあるのかどうか——星野遺跡は、その答えを握る遺跡として注目を集めました。","ところが、反論も強く出ます。«その石は、がけ崩れや川の流れで自然に割れたものでは?» 石器か、自然の石か。見分けるのは、専門家でもとても難しいのです。割れ口の形、打ったあとのへこみ、石の種類。研究者たちは、同じ石を見て、ちがう結論を出しました。","さらに2000年、別の研究者による «旧石器ねつ造事件» が明らかになり、日本の前期旧石器の研究全体が大きくゆらぎました。星野遺跡はねつ造とは関係がありませんが、«とても古い石器» について、より慎重に確かめる必要があると、あらためて考えられるようになりました。","星野遺跡では、縄文時代の住まいの跡なども見つかっていて、長いあいだ人が暮らした場所であることは確かです。近くには地層を観察できる施設もあり、何万年もの時間が積み重なった土を目の前で見られます。«石器か、石か» ——あなたの目で確かめてみてください。"],"tl":[["1949年","群馬県・岩宿遺跡で旧石器が確認され、日本の旧石器研究が始まる"],["1965年ごろ","芹沢長介らによる星野遺跡の発掘が始まる"],["1960〜70年代","数次の発掘で古い地層から石片が見つかり、前期旧石器説が唱えられる"],["同じころ","«自然に割れた石»とする反論が出て論争に"],["2000年","別件の旧石器ねつ造事件が発覚し、前期旧石器研究全体が見直される"]],"who":[["芹沢長介","考古学者。星野遺跡を発掘し、前期旧石器の存在を主張した"],["反論した研究者たち","石片を自然の破砕によるものと考えた"],["星野の地元の人びと","発掘に協力し、遺跡を伝えてきた"]],"deep":["星野遺跡では、何層もの地層から石片が見つかったとされ、下の層ほど古い «石器» だと主張されました。石の多くは珪岩などで、割れ方の判定が難しい石材でした。","«石器か自然石か» の論争は、大分県の早水台遺跡など、同じ時期に芹沢が主張した遺跡にも共通するもので、日本の前期旧石器論争の中心テーマでした。","2000年に発覚した旧石器ねつ造事件は、藤村新一による一連のねつ造で、宮城県などの遺跡が対象でした。星野遺跡とは別の事件です。","ねつ造事件のあと、日本考古学協会などが前期・中期旧石器の遺跡を検証し、日本列島に人が住み始めた時期は、確実なところでは約4万年前前後とする見方が一般的になりました。","星野遺跡の石片が人工物かどうかについては、今も結論が出ていません。«確かめられない» ことを正直に認めることも、科学の大切な態度です。","遺跡の周辺は «星野の里» として知られ、早春にはセツブンソウの群生地としても人気があります。"],"look":["遺跡周辺の地層観察施設（地層の重なり）","星野の山あいの地形（石が割れやすい環境を考える）","縄文時代の遺構・遺物の展示","早春のセツブンソウ群生地"],"q":["星野遺跡の論争で問題になったのは、どんなこと?","見つかった石が «人が作った石器» か «自然に割れた石» か、ということです。"],"koji":[],"myth":"前期旧石器説は未確定。石片の年代・人工性は諸説で、現在は慎重な見方が一般的。","img":["芹沢長介","岩宿遺跡","旧石器捏造事件"],"wp":"星野遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:2/29/Iwajuku-A.jpg",4608,3456,"岩宿遺跡"]]},{"id":"09_washi_jo","n":"鷲城（小山義政の乱）","yomi":"わしじょう","cat":"古戦場","rank":"B","y":1381,"era":["muromachi"],"sh":"国指定史跡","ad":"小山市外城","st":"JR小山駅から車で約10分、または歩いて約40分","la":36.296,"lo":139.805,"hook":"鎌倉公方に逆らった名門・小山氏。思川のがけの上で、最後の籠城戦が始まった。","lead":"鷲城は、南北朝時代の終わりに下野の名門・小山義政が、鎌倉公方の大軍を相手に立てこもった城の跡です。«小山義政の乱» の舞台で、思川をのぞむ台地の上に、土塁や堀がよく残っています。国の史跡 «小山氏城跡» のひとつです。","story":["小山氏は、平安時代の藤原秀郷の子孫といわれる、下野きっての名門武士でした。南北朝時代の終わり、当主の小山義政は、となりの宇都宮氏と領地をめぐって対立します。1380年、両者は裳原（茂原）でぶつかり、宇都宮基綱が討ち死にしました。«宇都宮を倒したぞ!» しかし、これが大きな災いを招きます。","関東を治める鎌倉公方・足利氏満は、勝手な戦をした義政を許しませんでした。«小山を討て» ——関東の武士たちに命令が下り、大軍が小山へ押し寄せます。義政はいったん降参しますが、やがて再び兵を挙げ、思川ぞいの鷲城に立てこもりました。","鷲城は、思川のけわしいがけを背にした台地の城です。何重にも掘られた堀と、高く盛られた土塁。攻める側は、堀を越えるたびに矢を浴びたことでしょう。«ここを落とすのは容易ではない» ——籠城戦は長く続きました。","しかし1381年の暮れ、義政はついに鷲城を明け渡し、出家して降伏します。それでもあきらめきれず、翌年また兵を挙げ、山あいの粕尾（現在の鹿沼市）で追いつめられて自害しました。子の若犬丸もその後、父の無念を晴らそうと各地で戦いましたが、やはり敗れました。名門小山氏は、ここで大きく傾いたのです。","いま鷲城跡には鷲神社がまつられ、林の中に土塁と堀がくっきり残っています。すぐ北には、小山氏の本城だった祇園城（小山城）跡もあります。小山氏の城跡は «小山氏城跡» として国の史跡になりました。静かな林の中で、600年以上前の籠城の日々を思いうかべてみてください。"],"tl":[["1380年","小山義政が裳原の戦いで宇都宮基綱を討つ"],["1380年","鎌倉公方・足利氏満が小山討伐を命じる。義政いったん降伏"],["1381年","義政が再び挙兵し鷲城に籠城。年末に開城し降伏・出家"],["1382年","義政が再挙兵し、粕尾で自害"],["1397年ごろ","子の若犬丸の抵抗も終わる"],["平成","鷲城跡が «小山氏城跡» として国の史跡に"]],"who":[["小山義政","小山氏の当主。鎌倉公方に反乱を起こし鷲城に籠城"],["足利氏満","鎌倉公方。小山討伐を命じた"],["宇都宮基綱","宇都宮氏の当主。裳原の戦いで討ち死に"],["小山若犬丸","義政の子。父の死後も抵抗を続けた"]],"deep":["«小山義政の乱» は、鎌倉公方が関東の有力武士の力を抑えようとした動きの中で起きたとされ、関東の室町時代史の重要な事件です。","戦いの経過や年月は史料によって細部が異なり、義政の降伏・再挙兵の回数や時期には諸説あります。","鷲城は思川の河岸段丘の端に築かれた «崖端城»。本丸にあたる内城と外城の二つの区画があり、地名 «外城（とじょう）» にその名残があります。","国の史跡 «小山氏城跡» は、鷲城跡・祇園城跡・中久喜城跡の三つからなり、小山氏の城の変遷をたどれる史跡として指定されています。","小山氏はこの乱で大きく力を失いましたが、のちに結城氏の一族が名跡を継いで再興し、戦国時代まで続きます。","藤原秀郷（俵藤太）の子孫とされる小山氏は、鎌倉幕府の成立期に源頼朝を支えた小山政光・朝政らを出した家として知られます。"],"look":["鷲神社と城跡の林","内城・外城を分ける堀と土塁","思川へ落ちるがけ（崖端城の地形）","北の祇園城（小山城）跡（城山公園）"],"q":["鷲城に立てこもった小山義政が戦った相手の中心は?","鎌倉公方・足利氏満の軍勢です。"],"koji":[],"myth":"乱の経過（降伏・再挙兵の時期）や若犬丸の最期は史料により異なる。","img":["小山義政","小山氏","祇園城","足利氏満"],"wp":"鷲城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Oyama.png",501,501,"小山氏"],["c:5/5b/Oyama-jo.4.jpg",3072,2304,"祇園城"],["c:6/6c/Ashikaga_Ujimitsu.jpg",1095,1465,"足利氏満"]]},{"id":"09_nishikata_jo","n":"西方城","yomi":"にしかたじょう","cat":"城","rank":"B","y":1580,"era":["muromachi","azuchi"],"sh":"","ad":"栃木市西方町本城","st":"東武日光線 東武金崎駅から歩いて約30分、または車で約10分。登山道を歩く","la":36.505,"lo":139.675,"hook":"山の上に、戦国の «土の城» がまるごと眠る。堀切の深さに、息をのむ。","lead":"西方城は、戦国時代にこの地を治めた西方氏の山城です。宇都宮氏の一族といわれる西方氏が、山の尾根を削って曲輪（平らな場所）や堀切をつくり、守りを固めました。石垣や建物は残っていませんが、土の城のかたちがよく残っています。","story":["栃木市の北西、西方町。田畑の向こうに、こんもりとした山が見えます。その山の上に、戦国時代の城が眠っています。«城» といっても、天守閣も石垣もありません。あるのは、山を削り、土を掘って造った «土の城» です。","西方氏は、下野の大名・宇都宮氏の一族といわれ、鎌倉時代からこの地を治めたと伝わります。戦国時代、北関東は、小田原の北条氏、常陸の佐竹氏、宇都宮氏などがぶつかり合う «最前線» でした。«いつ攻められるかわからない» ——山の上の城は、そんな時代の不安から生まれたのです。","山道をのぼっていくと、尾根をばっさりと断ち切った深い溝があらわれます。«堀切（ほりきり）» です。敵が尾根づたいに攻めてきても、ここで足止めされます。さらに進むと、平らに削られた曲輪がいくつも続き、いちばん高いところが本丸。まわりには土塁がめぐり、兵がそこに身をかくして弓を射たのでしょう。","城の造り方をよく見ると、何度も手を加えた跡があるといわれます。«最初は小さな砦だったのが、戦国の終わりに大きく改修されたのでは?» という見方もあります。北条氏との戦いが激しくなった天正年間ごろに、守りが強化されたと考えられています。","豊臣秀吉が天下を統一したあと、1597年に宇都宮氏がとりつぶされると、西方氏も力を失い、城は使われなくなりました。いま、城跡には案内板や登山道が整えられ、戦国の山城の姿を歩いて体験できます。すべりにくい靴で、ゆっくり登ってみましょう。"],"tl":[["鎌倉時代","宇都宮氏の一族が西方の地に入り、西方氏を名乗ったと伝わる"],["室町〜戦国時代","西方氏が山上に城を築き、本拠とする"],["天正年間","北条氏との抗争の中で城が改修されたと考えられる"],["1597年","宇都宮氏の改易にともない、西方氏も没落し城は廃される"],["現在","登山道と案内板が整備され、遺構を見学できる"]],"who":[["西方氏","宇都宮氏の一族といわれる西方の領主"],["宇都宮国綱","戦国時代の宇都宮氏当主。1597年に改易される"],["北条氏","小田原の戦国大名。北関東へ勢力を広げた"]],"deep":["西方城は山頂部の本丸を中心に、尾根に沿って曲輪を連ねる «連郭式» の山城で、尾根を断ち切る堀切がいくつも見られます。","城の東側の麓には «本城» という地名があり、城と領主の館が一体だった中世の在地支配の姿を伝えています。","西方氏の系譜は宇都宮頼綱の子孫とする説などがありますが、家の歴史を示す確かな史料は多くなく、はっきりしない点が多い一族です。","北関東の山城には、北条氏の築城技術の影響を受けたとされる大きな空堀や枡形の出入口をもつものがあり、西方城の改修にもそうした影響を考える研究者がいます。","1597年の宇都宮氏改易は、豊臣政権の検地の報告の不正などが理由とされ、宇都宮氏の一族や家臣の城が一斉に使われなくなりました。","近年の調査・整備により城跡は見学しやすくなり、地元の保存会の活動も行われています。"],"look":["尾根を断ち切る深い堀切","本丸を囲む土塁","段々に続く曲輪","山頂からの西方の町の眺め"],"q":["山城で、尾根を断ち切って敵の侵入を防ぐ深い溝を何という?","«堀切（ほりきり）» です。西方城でもいくつも見られます。"],"koji":[],"myth":"西方氏の出自・築城年・改修時期は諸説で、確かな史料が少ない。","img":["山城","宇都宮氏","堀切"],"wp":"西方城 (下野国)","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Nishikata_Castle_01.jpg",3264,2448,"西方城 (下野国)"],["c:3/3d/Marksburg1900.jpg",3526,2628,"山城"],["c:c/c8/Mitsudomoe_1.png",4000,4000,"宇都宮氏"]]},{"id":"09_katsuyama_jo","n":"勝山城（氏家）","yomi":"かつやまじょう","cat":"城","rank":"B","y":1200,"era":["kamakura","muromachi"],"sh":"","ad":"さくら市氏家","st":"JR宇都宮線 氏家駅から歩いて約25分","la":36.679,"lo":139.944,"hook":"鬼怒川のがけを背に、400年近く «宇都宮の北の守り» をつとめた城。","lead":"勝山城は、鎌倉時代に宇都宮氏の一族・氏家氏が築いたといわれる城です。鬼怒川の高いがけの上にあり、堀と土塁がよく残っています。すぐ隣には «さくら市ミュージアム» があり、城跡と一緒に地域の歴史を学べます。","story":["さくら市の西の端。鬼怒川の流れを見下ろす高いがけの上に、勝山城の跡があります。がけの下はすぐ川。«西側から攻めるのは、まず無理だ» ——自然の地形をたくみに利用した城でした。","城を築いたのは、宇都宮氏の一族である氏家氏と伝わります。鎌倉時代、宇都宮朝綱の孫にあたる公頼が氏家の地に入り、«氏家» を名乗ったといわれます。この地は、奥州へ向かう道と鬼怒川が交わる交通の要所。宇都宮氏の北の守りとして、重要な役目をになっていました。","城は、本丸を中心に、東側に二の丸・三の丸が広がっていたと考えられています。本丸のまわりには、いまも深い堀と高い土塁が残っています。堀の底に立って見上げると、«ここを上ろうとしたら、上から矢や石が降ってくる» という怖さがよくわかります。","戦国時代、北関東は北条氏や那須氏などとの争いが続き、勝山城は宇都宮氏の拠点として何度も戦いの舞台になったといわれます。しかし1597年、主家の宇都宮氏が豊臣秀吉によってとりつぶされると、勝山城もその役目を終えました。","いま、城跡は公園として整備され、春には桜が咲きます。隣のさくら市ミュージアムでは、城や氏家の歴史、この町ゆかりの日本画家・荒井寛方の作品を見ることができます。鬼怒川のがけの上から川を見下ろして、中世の武士が見ていた景色を想像してみてください。"],"tl":[["鎌倉時代","宇都宮氏の一族・氏家公頼が氏家の地に入り、城を築いたと伝わる"],["南北朝〜室町時代","氏家氏・宇都宮氏の拠点として使われる"],["戦国時代","北関東の抗争の中で宇都宮氏の北の守りとなる"],["1597年","宇都宮氏の改易にともない廃城"],["現在","城跡公園として整備され、さくら市ミュージアムが隣接"]],"who":[["氏家公頼","宇都宮氏の一族。氏家氏の祖と伝わる"],["宇都宮氏","下野の有力大名。勝山城を北の守りとした"],["荒井寛方","さくら市出身の日本画家。隣のミュージアムで作品を展示"]],"deep":["勝山城は鬼怒川の河岸段丘の端に築かれた城で、西側を川のがけ、東側を堀で守る典型的な «崖端城» の形です。","本丸を囲む堀と土塁は保存状態がよく、堀の深さと土塁の高さを組み合わせた高低差は、実際に歩くと迫力があります。","氏家公頼を宇都宮朝綱の孫とするのは系図にもとづく伝えで、築城の年代ははっきりしていません。","氏家は江戸時代には奥州街道の «氏家宿» として栄え、城の近くを街道が通っていました。","戦国時代の城主については、宇都宮氏の重臣・芳賀氏とのかかわりなど諸説があります。","1597年の宇都宮氏改易で廃城となった城は、下野に多数あり、北関東の中世の城の多くがこの年に一斉に役目を終えました。","城の名の «勝山» は縁起のよい名として各地の城に使われており、全国に同名の城がいくつもあります。混同しないよう «氏家の勝山城» と呼ばれることもあります。"],"look":["本丸を囲む深い堀と土塁（堀の底から土塁を見上げると高さを実感できる）","鬼怒川を見下ろすがけ（川との高低差に注目）","さくら市ミュージアム（荒井寛方の作品と郷土の歴史）","春の桜"],"q":["勝山城が西側から攻めにくかったのはなぜ?","西側が鬼怒川の高いがけになっていて、自然の守りになっていたからです。"],"koji":[],"myth":"築城者・築城年、戦国期の城主は伝承・諸説を含む。","img":["氏家氏","鬼怒川","荒井寛方"],"wp":"勝山城 (下野国)","rel":{"ev":[],"grave":[]},"ph":[["c:b/b8/Kinu_River_viewing_from_Akutsu_Ohashi_in_Utsunomiya.jpg",1000,750,"鬼怒川"]]},{"id":"09_sano_jo","n":"佐野城（春日岡城）","yomi":"さのじょう","cat":"城","rank":"B","y":1602,"era":["edo"],"sh":"","ad":"佐野市若松町（城山公園）","st":"JR両毛線・東武佐野線 佐野駅のすぐ北、歩いて約3分","la":36.317,"lo":139.578,"hook":"«江戸を見下ろす山城は許さぬ»——そんな伝説とともに生まれ、わずか十数年で消えた城。","lead":"佐野城は、江戸時代のはじめに佐野信吉が、山の上の唐沢山城から平地近くの春日岡に移って築いた城です。しかし信吉が改易されたため、完成からまもなく廃城となりました。いまは佐野駅のすぐ北の «城山公園» になっています。","story":["佐野氏は、平安時代の藤原秀郷の子孫といわれ、長く唐沢山城を本拠にしてきました。唐沢山城は、標高240mほどの山の上にある、関東屈指の堅い城。戦国時代には、上杉謙信の攻撃を何度もはね返したと伝わります。","江戸時代のはじめ、佐野氏の当主・佐野信吉は、この唐沢山城を出て、麓の春日岡という小高い丘に新しい城を築きはじめます。«なぜ、あんなに堅い城を捨てたのか?» 地元にはこんな話が伝わっています。«江戸で火事があったとき、信吉は唐沢山から江戸の火を見て、いち早く駆けつけた。すると家康は «江戸を見下ろす山に城を置くとは» と、山城を捨てるように命じた»。","本当のところは、戦のない時代になり、山の上よりも城下町をつくりやすい平地の近くに移るほうが便利だったから、と考えられています。春日岡にはもともと惣宗寺というお寺があり、寺を移して城を建てたといわれます。","ところが1614年、信吉は兄の事件に連座して改易されてしまいます。城の主はいなくなり、佐野城は完成して間もなく廃城に。わずか十数年の «幻の城» となりました。その後、この地は幕府や他の大名の領地になり、町は例幣使街道ぞいの商業の町として栄えていきます。","いま城跡は «城山公園» として整備され、駅のすぐそばに、本丸や二の丸の平らな地形と堀の跡が残っています。移されたお寺・惣宗寺は «佐野厄除け大師» として多くの参拝者でにぎわいます。唐沢山城跡とセットで訪ねれば、山城から平山城への «時代の変わり目» がよくわかります。"],"tl":[["戦国時代","佐野氏が唐沢山城を本拠に、上杉・北条の間で生き残る"],["1602年ごろ","佐野信吉が春日岡で新しい城（佐野城）の築城を始めたとされる"],["1614年","佐野信吉が改易され、佐野城は廃城に"],["江戸時代","佐野は例幣使街道ぞいの町として栄える"],["現在","城跡が城山公園として整備されている"]],"who":[["佐野信吉","佐野氏の当主。佐野城を築き、のちに改易された"],["徳川家康","山城を捨てさせたという伝説に登場する"],["藤原秀郷","佐野氏の祖とされる平安時代の武将。唐沢山城を築いたと伝わる"]],"deep":["«江戸の火事を唐沢山から見て駆けつけ、家康に山城を捨てさせられた» という話は江戸時代以来の伝説で、確かな史料による裏づけはありません。","佐野信吉は富田一白の子で、佐野氏の養子になって家を継いだとされます。改易は、兄・富田信高の事件に連座したためといわれます。","春日岡には惣宗寺（春日岡山転法輪院惣宗寺）があり、築城にあたって現在地に移されたと伝わります。この寺が今の «佐野厄除け大師» です。","唐沢山城は石垣を多用した山城として知られ、関東の山城としては珍しく高い石垣が残ります。佐野城との比較が興味深い点です。","佐野城は完成直前に廃されたとも、ほぼ完成していたとも言われ、どこまで建物ができていたかははっきりしません。","城山公園では、発掘調査などで本丸・二の丸・三の丸の配置が確かめられ、地形に城の区画が残っています。"],"look":["城山公園の本丸・二の丸の平坦地","堀の跡と高低差","佐野厄除け大師（惣宗寺）","唐沢山城跡（あわせて訪ねたい）"],"q":["佐野城ができる前、佐野氏が本拠にしていた山城は?","唐沢山城です。関東屈指の堅い山城として知られます。"],"koji":[],"myth":"«江戸を見下ろす山城» の話は伝説。築城開始の年や完成度は諸説。","img":["唐沢山城","佐野厄除け大師","佐野氏"],"wp":"佐野城","rel":{"ev":[],"grave":[]},"ph":[["c:f/fc/Sano_Shiroyama_Park.JPG",2048,1536,"佐野城"],["c:6/63/Karasawayama_Shrine.JPG",4608,3456,"唐沢山城"],["c:a/a0/Soshu-ji_Temple.JPG",2048,1536,"佐野厄除け大師"],["c:2/23/Mitsudomoe_2.png",4000,4000,"佐野氏"]]},{"id":"09_kamikawa_jo","n":"上三川城","yomi":"かみのかわじょう","cat":"城","rank":"B","y":1235,"era":["kamakura","azuchi"],"sh":"","ad":"上三川町上三川（上三川城址公園）","st":"JR宇都宮線 石橋駅から車で約15分","la":36.439,"lo":139.911,"hook":"宇都宮一族の家臣争いに巻きこまれ、最後の城主は城とともに散った。","lead":"上三川城は、鎌倉時代に宇都宮氏の一族・横田氏が築いたといわれる平城です。のちに同じ一族の今泉氏が城主となりました。戦国時代の終わりに宇都宮家中の争いで落城し、いまは «上三川城址公園» として、堀や土塁が残っています。","story":["上三川町の中心部。住宅地の中に、こんもりと木が茂る一角があります。ぐるりと水をたたえた堀、その内側に土塁。ここが上三川城の跡です。«平地にある城は、堀と土塁が命» ——山がない代わりに、深い堀で守りを固めた城でした。","城を築いたのは、宇都宮氏の一族・横田氏だと伝わります。鎌倉時代の中ごろ、宇都宮頼綱の子孫が上三川のあたりを与えられ、城をかまえたといわれます。その後、横田氏の流れをくむ今泉氏が城主となり、戦国時代まで宇都宮氏の重臣としてこの地を治めました。","戦国時代の終わり、宇都宮氏の家中では、跡つぎをめぐって大きな争いが起こります。宇都宮国綱に子がなく、養子を迎える話が持ち上がったのです。城主の今泉高光はこの養子話を進める側に立ったといわれ、反対する同じ宇都宮家の重臣・芳賀高武と激しく対立しました。","1597年、芳賀高武の軍勢が上三川城に攻め寄せ、今泉高光は城とともに命を落としたと伝わります。«同じ家の者どうしが討ち合うとは……»。そして同じ年、宇都宮氏そのものが豊臣秀吉によってとりつぶされ、上三川城は二度と使われることはありませんでした。","いま城跡は公園になり、本丸をかこむ堀と土塁がよく残っています。堀の水面に木々がうつる静かな場所で、散歩や花見を楽しむ人も多くいます。戦国の最後の悲劇を思いながら、堀のまわりを一周してみましょう。"],"tl":[["1235年ごろ","宇都宮氏一族の横田氏が上三川に城を築いたと伝わる"],["室町〜戦国時代","今泉氏が城主となり、宇都宮氏の重臣として続く"],["1597年","宇都宮家中の争いで芳賀高武に攻められ落城、今泉高光が死去したと伝わる"],["1597年","宇都宮氏が改易され、城は廃される"],["現在","上三川城址公園として整備"]],"who":[["横田氏","宇都宮氏の一族。上三川城を築いたと伝わる"],["今泉高光","上三川城の最後の城主と伝わる"],["芳賀高武","宇都宮氏の重臣。上三川城を攻めたと伝わる"],["宇都宮国綱","宇都宮氏の当主。1597年に改易される"]],"deep":["上三川城は平地に築かれた «平城» で、本丸を方形の堀と土塁で囲む形。堀に水をたたえた姿が今も見られるのは貴重です。","宇都宮国綱の養子問題は、豊臣政権の重臣・浅野長政の子を迎える話だったとされ、家中の賛否が分かれて内紛に発展したといわれます。","今泉高光の最期や上三川城の落城の詳しい経過は、後の時代にまとめられた記録に頼る部分が大きく、細部には諸説あります。","宇都宮氏の改易は、この内紛や、検地での石高の報告の問題などが原因とされますが、理由ははっきりしない部分もあります。","横田氏・今泉氏はいずれも宇都宮氏の一族で、宇都宮氏は一族を周辺の城に配置して勢力を固めていました。","上三川は、江戸時代には周辺の藩や旗本の領地が入り組む農村となり、城下町としては発展しませんでした。"],"look":["本丸をめぐる水堀","堀の内側に残る土塁","公園内の案内板","春の桜並木"],"q":["上三川城の最後の城主と伝わる人物は?","今泉高光です。1597年に宇都宮家中の争いで城とともに亡くなったと伝わります。"],"koji":[],"myth":"築城年、落城の経過、養子問題の中身は伝承・諸説を含む。","img":["宇都宮氏","芳賀氏","平城"],"wp":"上三川城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/Kaminokawa_Castle_Ruins_Park.jpg",4608,3456,"上三川城"],["c:c/c8/Mitsudomoe_1.png",4000,4000,"宇都宮氏"],["c:b/bc/Old_Nagoya_Castle.JPG",900,559,"平城"]]},{"id":"09_koyama_jo","n":"児山城","yomi":"こやまじょう","cat":"城","rank":"B","y":1340,"era":["muromachi"],"sh":"県指定史跡","ad":"下野市下古山","st":"JR宇都宮線 石橋駅から車で約10分","la":36.446,"lo":139.86,"hook":"田んぼの中に、ほぼ真四角の «土の要塞» がそのまま残る。","lead":"児山城は、南北朝時代に宇都宮氏の一族・児山氏が築いたといわれる平城です。四角い形の本丸を、高い土塁と深い堀が囲み、中世の «館の城» のすがたをよく伝えています。栃木県の史跡に指定されています。","story":["下野市の北のはずれ。田畑の中に、四角く林が茂る場所があります。近づくと、林のふちは高い土手、その外側には深い堀。«まるで土でできた箱みたい!» ——これが児山城の跡です。","児山城を築いたのは、宇都宮氏の一族の児山氏だと伝わります。南北朝時代、宇都宮氏は一族や家臣を領地のあちこちに置いて、国を守らせました。児山氏もそのひとつで、宇都宮の南の守りとして、この城をかまえたのです。","城の形はとてもシンプルです。ほぼ正方形の本丸を、ぐるりと土塁と堀が取り囲むだけ。けれど、その土塁は背の高い大人の何倍もの高さがあり、堀も深く、簡単には越えられません。«平らな土地で守るには、土を高く積むしかない» ——中世の武士の工夫です。","戦国時代に入ると、宇都宮氏と北条氏などとの争いが激しくなり、児山城も宇都宮方の城として使われたといわれます。そして1597年、宇都宮氏がとりつぶされると、城もその役目を終えました。その後、城跡は大きく壊されることなく、今日まで残りました。","いま城跡は、四角い形の土塁と堀がほぼ完全に残り、中世の平城の姿を知る貴重な史跡になっています。土塁の上を歩いて一周すると、城の大きさと守りのかたさが体でわかります。夏は草が茂るので、歩きやすい服装で訪ねましょう。"],"tl":[["南北朝時代","宇都宮氏一族の児山氏が城を築いたと伝わる"],["室町〜戦国時代","宇都宮氏の南の守りとして使われる"],["1597年","宇都宮氏の改易にともない廃城"],["昭和","栃木県の史跡に指定される"],["現在","土塁と堀がほぼ完全に残る"]],"who":[["児山氏","宇都宮氏の一族。城を築き、この地を治めたと伝わる"],["宇都宮氏","下野の有力大名。一族を各地の城に配置した"],["宇都宮国綱","戦国時代の宇都宮氏当主。1597年に改易される"]],"deep":["児山城は、方形の本丸を土塁と堀で囲む «方形館（ほうけいやかた）» から発展した平城とされ、関東の中世武士の館の典型として評価されています。","土塁の四隅や出入口（虎口）の形に注目すると、ただの館ではなく、戦いを意識して手が加えられたことが読みとれるといわれます。","児山氏の系譜や築城年は、宇都宮氏の系図などにもとづく伝えで、確かな史料は多くありません。","周囲の開発で多くの中世の館跡が消えた中、土塁と堀がほぼ一周残る児山城は、県内でも保存状態がよい例です。","下野市周辺には、同じように宇都宮氏や小山氏の一族が築いた館や城の跡が点在し、両氏の境目の地域だったことがわかります。","城跡の土塁は高さがあり、中から外は見えにくく、外から中も見えにくい造り。平城の «見せない守り» の工夫です。","児山氏は宇都宮氏の家臣団の中で、南の小山氏・結城氏方面への備えを受け持ったと考えられ、城の位置もその役割をよく示しています。","土塁の角が少し外へ張り出す部分は、角に近づく敵を横から射るための工夫（横矢）と考える見方もあります。"],"look":["ほぼ一周残る方形の土塁","外側をめぐる堀","出入口（虎口）の形","土塁上から見る周囲の平野"],"q":["児山城の本丸はどんな形?","ほぼ正方形で、まわりを高い土塁と深い堀が囲んでいます。"],"koji":[],"myth":"築城者・築城年・児山氏の系譜は伝承。指定年など細部は要確認。","img":["宇都宮氏","平城","土塁"],"wp":"児山城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7e/First_Moat_in_Koyama_castle.jpg",4608,3456,"児山城"],["c:c/c8/Mitsudomoe_1.png",4000,4000,"宇都宮氏"],["c:b/bc/Old_Nagoya_Castle.JPG",900,559,"平城"],["c:b/b3/%E5%B1%B1%E4%B8%8B%E5%9F%8E7.jpg",2048,1536,"土塁"]]},{"id":"09_kugeta_jo","n":"久下田城","yomi":"くげたじょう","cat":"城","rank":"B","y":1549,"era":["muromachi","azuchi"],"sh":"","ad":"真岡市久下田（旧二宮町）","st":"真岡鐵道 久下田駅から歩いて約15分","la":36.334,"lo":139.969,"hook":"常陸と下野の国境に、結城家の猛将が築いた «にらみの城»。","lead":"久下田城は、戦国時代に結城氏の家臣・水谷正村（蟠龍斎）が、下野と常陸の国境近くに築いた城です。宇都宮方の芳賀氏などと向き合う最前線の城でした。台地の上に、曲輪や空堀の跡が残っています。","story":["真岡市の南、茨城県との県境に近い久下田。五行川が流れる低地を見下ろす台地の上に、久下田城の跡があります。戦国時代、ここは下総の結城氏の勢力と、下野の宇都宮氏・芳賀氏の勢力がにらみ合う «境目» でした。","城を築いたのは、結城氏の重臣・水谷正村。のちに出家して «蟠龍斎» と名乗りました。武勇にすぐれ、何度も戦いで手柄を立てた猛将と伝わります。1549年ごろ、正村は «ここに城を置けば、芳賀勢の動きを押さえられる» と考え、この台地に城を築いたといわれます。","城は、台地の地形をいかして、いくつもの曲輪を空堀で区切った造りです。台地のふちはがけになっていて、低地から攻め上がるのは大変。敵が近づけば、城から一目で見わたせます。«境目の城» には、見張り台としての役目も大きかったのです。","水谷氏は、主家の結城氏を支えながら、戦国の荒波を生きぬきました。豊臣秀吉の天下統一後、結城氏には徳川家康の子・秀康が養子に入り、やがて越前へ移ります。水谷氏は下野・常陸の地に残り、のちに常陸の下館を本拠とする大名になりました。久下田城は江戸時代のはじめにその役目を終えたと考えられています。","いま城跡は、林や畑の中に空堀や土塁の跡が残り、台地の上から五行川の低地を見わたせます。«ここから芳賀勢の動きを見張っていたのか» ——国境の緊張を思いうかべながら歩いてみましょう。真岡鐵道のSLに乗って訪ねるのも楽しい旅です。"],"tl":[["1549年ごろ","結城氏の家臣・水谷正村（蟠龍斎）が久下田城を築いたと伝わる"],["戦国時代","芳賀氏・宇都宮氏との境目の城として使われる"],["1590年","豊臣秀吉の小田原攻め。結城氏は秀吉に従う"],["江戸時代初め","水谷氏が下館を本拠とし、城はしだいに使われなくなる"],["現在","空堀や土塁の跡が残る"]],"who":[["水谷正村（蟠龍斎）","結城氏の重臣。久下田城を築いたと伝わる猛将"],["水谷勝俊","正村の弟で後継者といわれる。のちに下館を本拠とした"],["結城晴朝","結城氏の当主。水谷氏の主君"],["芳賀氏","宇都宮氏の重臣。久下田城と向き合った"]],"deep":["久下田城は、台地の先端を空堀で区切って曲輪を並べる «連郭式» の城とされ、東の低地側を自然のがけで守る地形になっています。","築城年を1549年とするのは伝えによるもので、同時代の史料で確かめられているわけではありません。","水谷正村は «蟠龍斎» の号で知られ、結城氏の軍事を支えた人物として、結城氏関係の記録や軍記に多く登場します。","水谷氏は江戸時代、下館藩（常陸）の藩主となり、のちに備中松山（岡山県）へ移りました。備中松山城を今の姿に整えたのも水谷氏とされます。","久下田は、下野（栃木）と常陸（茨城）の境目にあたり、城の位置は «国境の見張り» という役割をよく示しています。","城跡の一部は私有地や林になっており、見学は案内板のある範囲にとどめるのがマナーです。"],"look":["台地を区切る空堀","曲輪の平坦地と土塁","台地から見下ろす五行川の低地","真岡鐵道・久下田駅（SLの運行日もある）"],"q":["久下田城を築いたと伝わる結城氏の家臣は?","水谷正村（蟠龍斎）です。"],"koji":[],"myth":"築城年・正村と勝俊の関係・廃城時期は伝承・諸説を含む。","img":["水谷正村","結城氏","下館藩","真岡鐵道"],"wp":"久下田城","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/Ruins_of_Kugeta_Castle_01.JPG",2560,1920,"久下田城"]]},{"id":"09_nakakuki_jo","n":"中久喜城","yomi":"なかくきじょう","cat":"城","rank":"B","y":1400,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"小山市中久喜","st":"JR小山駅から車で約15分","la":36.315,"lo":139.855,"hook":"小山氏と結城氏、二つの名門の運命が交わった城。","lead":"中久喜城は、小山氏の城のひとつで、のちに結城氏とのかかわりも深かった平城です。鷲城・祇園城とともに国の史跡 «小山氏城跡» に指定され、堀や土塁がよく残っています。","story":["小山市の東部、鬼怒川と思川のあいだの台地。畑や林の中に、中久喜城の跡があります。«中久喜» という不思議な地名の場所で、何重もの堀と土塁が、今も静かに残っています。","この城は、下野の名門・小山氏の城のひとつとして築かれたといわれます。«小山義政の乱» のころに使われたという伝えもあり、小山氏が鎌倉公方と戦ったとき、鷲城や祇園城とともに守りを固めたと考えられています。","小山氏は乱のあと大きく力を落とし、やがて同じ秀郷流の一族である結城氏の家から当主を迎えて家を立て直しました。小山と結城は、となり合う «親せき» のような家。中久喜城は、その二つの家の境目にある城として、重要な役目を果たしたといわれます。","戦国時代の終わりには、結城氏の当主・結城晴朝が徳川家康の子・秀康を養子に迎えたあと、この城に移り住んだという伝えもあります。«家を守るため、跡つぎを天下人の一族に託した» ——晴朝の決断は、結城家の運命を大きく変えました。","城跡には、本丸を囲む堀と土塁、いくつもの曲輪の区切りが残っています。訪れる人は多くありませんが、そのぶん中世の城の空気がよく残る場所です。鷲城・祇園城とあわせてめぐれば、小山氏の城の移り変わりがよくわかります。"],"tl":[["室町時代","小山氏の城として使われたと伝わる"],["1380年代","小山義政の乱。小山氏の諸城が戦いの舞台となる"],["戦国時代","結城氏とのかかわりが深まる"],["1590年代","結城晴朝が秀康を養子に迎えたのち、中久喜城に移ったと伝わる"],["平成","«小山氏城跡»のひとつとして国の史跡に指定"]],"who":[["小山氏","下野の名門武士。城を築いたと伝わる"],["結城晴朝","結城氏の当主。晩年ここに移ったと伝わる"],["結城秀康","徳川家康の子。結城氏の養子となった"],["小山義政","小山氏の当主。乱を起こし鎌倉公方と戦った"]],"deep":["中久喜城は台地の上に築かれた平山城で、本丸・二の丸などの曲輪を堀と土塁で区切った構造です。","国の史跡 «小山氏城跡» は鷲城跡・祇園城跡・中久喜城跡の三つからなり、中世の小山氏の拠点のあり方を示しています。","小山氏は乱ののち、結城氏から当主を迎えて再興したとされ、以後、小山氏と結城氏は深く結びつきました。","結城晴朝が秀康を養子とした後に中久喜城へ移ったという話は伝えによるもので、その時期や期間ははっきりしていません。","結城秀康はのちに越前（福井県）へ移り、結城の地を離れました。晴朝も秀康に従って越前へ移り、そこで亡くなったとされます。","城の名前の «中久喜» は地名に由来しますが、その語源ははっきりしていません。","小山氏の本城は祇園城（小山城）で、鷲城は乱の際の籠城の城、中久喜城は東側の守りの城と、三つの城が役割を分けていたと考えられています。"],"look":["本丸をめぐる堀と土塁（林の中でも形がよくわかる）","曲輪を区切る空堀","台地のへりの地形と周囲の低地","鷲城跡・祇園城跡もあわせてめぐると城の役割のちがいがわかる"],"q":["中久喜城と同じく «小山氏城跡» として国の史跡になっている城は?","鷲城跡と祇園城跡です。"],"koji":[],"myth":"築城年や、晴朝が移り住んだ話は伝承。小山義政の乱での役割も推定を含む。","img":["小山氏","結城晴朝","結城秀康","祇園城"],"wp":"中久喜城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Oyama.png",501,501,"小山氏"],["c:b/bb/Yuuki_Harutomo.jpg",3029,3043,"結城晴朝"],["c:c/ca/Yuki_Hideyasu.jpg",1000,1474,"結城秀康"],["c:5/5b/Oyama-jo.4.jpg",3072,2304,"祇園城"]]},{"id":"09_take_jo","n":"多気城（宇都宮氏の詰城）","yomi":"たげじょう","cat":"城","rank":"B","y":1585,"era":["azuchi"],"sh":"","ad":"宇都宮市田下町（多気山）","st":"JR宇都宮駅からバスで約30分、«多気山入口»付近から歩いて登る。車が便利","la":36.607,"lo":139.813,"hook":"北条の大軍が迫る。宇都宮氏は平地の城を出て、山ひとつを丸ごと要塞に変えた。","lead":"多気城は、戦国時代の終わりに宇都宮国綱が、小田原の北条氏の攻撃にそなえて本拠を移した、多気山の大きな山城です。山のあちこちに曲輪や堀が造られ、関東でも有数の規模をほこりました。山の中腹には多気不動尊（持宝院）があります。","story":["宇都宮の町の北西に、こんもりとした山がそびえています。標高377m、多気山。戦国時代の終わり、この山が丸ごと城になりました。«宇都宮城では守りきれない。山にこもるのだ!» ——宇都宮国綱の決断です。","そのころ、小田原の北条氏は関東をほとんど手中におさめ、北へ北へと勢力を広げていました。宇都宮氏は、常陸の佐竹氏と手を組んで北条氏に立ち向かいます。1584年には、沼尻で両軍がにらみ合う大合戦もありました。しかし北条の勢いは止まらず、平地にある宇都宮城は危険になっていきました。","そこで国綱は、1585年ごろ、多気山に本拠を移したといわれます。山の頂上から中腹にかけて、たくさんの曲輪が造られ、山のすそには長い堀と土塁がめぐらされました。城の中には家臣たちの屋敷もあったと考えられ、«山の上の城下町» のような規模だったのです。","1590年、豊臣秀吉が小田原の北条氏を滅ぼすと、北関東の緊張はとけました。秀吉は宇都宮城に入って «宇都宮仕置» を行い、東北・関東の大名の処分を決めます。国綱も宇都宮城にもどり、多気城は役目を終えました。そのわずか7年後、宇都宮氏そのものが改易されてしまいます。","いま多気山には、ハイキングコースがあり、山の中を歩くと、あちこちに平らな曲輪や堀の跡が見つかります。中腹の多気不動尊は、平安時代から信仰を集めてきたといわれる古いお寺です。お参りをしてから、戦国の «山の要塞» を探検してみましょう。"],"tl":[["1584年","沼尻の合戦。宇都宮・佐竹連合と北条氏が対陣"],["1585年ごろ","宇都宮国綱が本拠を多気山に移したとされる"],["1590年","豊臣秀吉が北条氏を滅ぼし、宇都宮仕置を行う"],["1590年ごろ","国綱が宇都宮城に戻り、多気城は使われなくなる"],["1597年","宇都宮氏が改易される"]],"who":[["宇都宮国綱","宇都宮氏の当主。多気山に本拠を移した"],["北条氏直","小田原北条氏の当主。北関東に攻め入った"],["佐竹義重","常陸の戦国大名。宇都宮氏と同盟した"],["豊臣秀吉","北条氏を滅ぼし、宇都宮仕置を行った"]],"deep":["多気城は山頂の本丸を中心に、山全体に曲輪群を配し、山麓を長い堀と土塁で囲んだとされる、関東有数の大規模な山城です。","本拠を多気山に移した年は1585年とされることが多いですが、はっきりした史料が少なく、時期には諸説があります。","多気山麓をめぐる堀と土塁は «総構え» と呼ばれる考え方に近く、城の中に家臣団を住まわせる戦国末期の城の特徴とみる研究者もいます。","多気不動尊（持宝院）は、宇都宮氏の信仰も受けたといわれる古い寺で、城と寺が同じ山にあることも中世の山城の特徴です。","秀吉の «宇都宮仕置» は1590年に宇都宮城で行われ、奥州の大名の処分などが決められました。宇都宮が東国支配の拠点とされたことを示します。","宇都宮氏の改易（1597年）の理由は、家中の争いや石高報告の問題などが挙げられますが、はっきりしない部分もあります。"],"look":["山頂の本丸跡","山腹に段々に続く曲輪","山麓の堀と土塁","多気不動尊（持宝院）","山頂からの宇都宮市街の眺め"],"q":["宇都宮国綱が多気山に本拠を移したのは、どの大名の攻撃にそなえるため?","小田原の北条氏です。"],"koji":[],"myth":"移転の年や城の完成度、総構えの範囲は諸説。","img":["宇都宮国綱","宇都宮城","多気山","宇都宮仕置"],"wp":"多気城 (下野国)","rel":{"ev":[],"grave":[]},"ph":[["c:6/6f/%E5%A4%9A%E6%B0%97%E5%9F%8E%E8%B7%A1%E7%A2%91_-_panoramio.jpg",3456,4608,"多気城 (下野国)"],["c:b/b6/Utsunomiya-jo_fujimi-yagura.jpg",2896,1936,"宇都宮城"],["c:3/31/Mt_Tage_viewing_from_Tochikubo.jpg",1000,750,"多気山"]]},{"id":"09_numajiri","n":"沼尻の合戦跡（北条対佐竹・宇都宮）","yomi":"ぬまじりのかっせんあと","cat":"古戦場","rank":"B","y":1584,"era":["azuchi"],"sh":"","ad":"栃木市藤岡町・岩舟町周辺","st":"東武日光線 藤岡駅、またはJR両毛線 岩舟駅から車で約10〜15分。正確な場所は特定されていない","la":36.298,"lo":139.657,"hook":"小牧・長久手の戦いと同じ年、関東でも «もう一つの天下分け目» が110日もにらみ合っていた。","lead":"沼尻の合戦は、1584年に下野南部の沼尻で、小田原の北条氏と、常陸の佐竹氏・下野の宇都宮氏などの連合軍が、長く向かい合った戦いです。同じ年に中部地方では豊臣秀吉と徳川家康が戦っており、二つの戦いは遠くでつながっていました。","story":["1584年、関東は北条氏の勢いにのみこまれようとしていました。«このままでは、北関東は北条のものになる» ——危機を感じた常陸の佐竹義重、下野の宇都宮国綱らは手を組み、北条氏直の大軍と向き合います。その場所が、沼や湿地の多い下野南部の «沼尻» でした。","両軍は、沼をはさんで陣を張り、にらみ合いました。沼や湿地は、大軍が一気に攻めこむのをはばみます。«先に動いたほうが負ける» ——小さな戦いはあったものの、決定的な戦いにはなりません。にらみ合いは、およそ110日も続いたといわれます。","同じころ、中部地方では羽柴（豊臣）秀吉と徳川家康が «小牧・長久手の戦い» をくり広げていました。北条氏は家康と手を組み、佐竹氏は秀吉と連絡をとっていたといわれます。つまり沼尻の合戦は、遠く離れた «天下の争い» と結びついた戦いだったのです。","戦いの流れを変えたのは、近くの岩船山の城でした。北条方がこの城を落とすと、連合軍は不利になり、やがて両軍は和睦して兵を引きました。«決着がつかないまま» 終わったこの戦いのあと、北条氏は北関東への進出をさらに強め、宇都宮氏は多気山に城を移していきます。","いま、沼尻の合戦の正確な場所ははっきりしていません。昔の沼の多くは干拓され、田んぼや町になりました。けれど、三毳山や岩船山を望む平野に立つと、沼をはさんで大軍が向き合った光景が目に浮かびます。«天下の争いは、ここにもあった»——そう思うと、何気ない景色がちがって見えるはずです。"],"tl":[["1584年春","北条氏直と、佐竹義重・宇都宮国綱らの連合軍が沼尻で対陣を始める"],["1584年","同じ時期に中部地方で小牧・長久手の戦い"],["1584年夏","北条方が岩船山の城を攻め落とす"],["1584年夏","両軍が和睦し、兵を引く"],["1585年ごろ","宇都宮国綱が多気山に本拠を移したとされる"],["1590年","秀吉の小田原攻めで北条氏が滅びる"]],"who":[["北条氏直","小田原北条氏の当主。北条軍を率いた"],["佐竹義重","常陸の戦国大名。反北条連合の中心"],["宇都宮国綱","下野の戦国大名。佐竹氏と同盟した"],["徳川家康","北条氏と同盟していた。小牧・長久手で秀吉と対戦"],["羽柴秀吉","佐竹氏と連絡をとっていたといわれる"]],"deep":["沼尻の合戦は、長く «知られざる戦い» でしたが、近年の研究で、小牧・長久手の戦いと連動した «東国の天下分け目» として注目されるようになりました。","対陣の期間は «約110日» とされることが多いですが、始まりと終わりの日付には史料により幅があります。","岩船山（現在の栃木市岩舟町）の城が北条方に落とされたことが、和睦の大きなきっかけになったといわれます。","連合軍には、佐竹・宇都宮のほか、結城氏や下野・上野の武将も加わったとされ、北関東の反北条勢力が結集した戦いでした。","戦場の «沼尻» の位置は、現在の栃木市藤岡町付近とする説が有力ですが、陣所の場所などは特定されていません。","この戦いの後、北条氏は上野・下野での攻勢を強めましたが、6年後の1590年に秀吉に滅ぼされ、関東の勢力図は一変しました。"],"look":["三毳山から見下ろす下野南部の平野","岩船山（北条方が攻め落とした城のあった山）","渡良瀬遊水地（昔の沼や湿地の姿を想像できる）","藤岡・岩舟の町並み"],"q":["沼尻の合戦と同じ1584年に、中部地方で起きていた戦いは?","小牧・長久手の戦い（羽柴秀吉と徳川家康の戦い）です。"],"koji":[],"myth":"合戦地の正確な場所、対陣期間、秀吉・家康とのつながりの程度は研究途上で諸説あり。","img":["北条氏直","佐竹義重","小牧・長久手の戦い","岩船山"],"wp":"沼尻の合戦","rel":{"ev":[],"grave":[]},"ph":[["c:2/2c/Hojo_Ujinao.jpg",466,745,"北条氏直"],["c:7/74/Komaki_Nagakute_Kassen_Zu_Byoubu%2C_Toyota.jpg",3274,1426,"小牧・長久手の戦い"],["c:a/ab/Mt.Iwafune.jpg",2728,2045,"岩船山"]]},{"id":"09_yasuzuka","n":"安塚の戦い跡（戊辰戦争）","yomi":"やすづかのたたかいあと","cat":"古戦場","rank":"B","y":1868,"era":["edo","meiji"],"sh":"","ad":"壬生町安塚","st":"東武宇都宮線 安塚駅から歩いて約10〜20分","la":36.454,"lo":139.815,"hook":"雨の夜明け、旧幕府軍と新政府軍が田んぼの中でぶつかった。宇都宮をめぐる攻防の «もう一つの戦場»。","lead":"安塚の戦いは、1868年（慶応4年）、戊辰戦争のさなかに、壬生町の安塚で旧幕府軍と新政府軍が戦った戦いです。宇都宮城をめぐる一連の戦いのひとつで、両軍に多くの死者が出ました。現地には戦死者をとむらう墓や碑が残っています。","story":["1868年春、江戸城が新政府軍に明け渡されると、それに納得できない旧幕府の兵たちは江戸を脱け出し、北へ向かいました。大鳥圭介らが率いる旧幕府軍は、下野に入って宇都宮城を攻め落とします。«ここで新政府軍を食い止めるのだ!» 北関東が戦場になりました。","新政府軍は、宇都宮の南の壬生城に集まり、反撃の準備をします。旧幕府軍は、先手を打って壬生城を攻めようと南へ進みました。その途中、姿川のほとりの安塚で、両軍がぶつかります。夜明け前から雨が降り、ぬかるんだ田んぼや林の中での、はげしい撃ち合いになったと伝わります。","はじめは旧幕府軍が優勢だったといわれます。しかし新政府軍に援軍が加わると形勢は逆転し、旧幕府軍は宇都宮方面へ退きました。«ぬかるみに足をとられ、弾はしけり……»。雨の戦場の苦しさは、どちらの兵にとっても同じだったでしょう。","この戦いのあと、新政府軍は宇都宮城を取りもどし、旧幕府軍は日光、そして会津へと退いていきます。安塚の戦いは、宇都宮をめぐる攻防の分かれ目のひとつになりました。そのかげで、両軍の多くの若い兵たちが、故郷から遠く離れたこの地で命を落としたのです。","いま安塚には、戦いで亡くなった人びとの墓や碑が残り、地元の人びとによって大切に守られています。敵味方に分かれて戦った人たちも、ここでは同じようにとむらわれています。静かな田園の中で手を合わせ、150年余り前の出来事に思いをはせてください。"],"tl":[["1868年1月","鳥羽・伏見の戦い。戊辰戦争が始まる"],["1868年4月","江戸城が新政府軍に明け渡される"],["1868年4月","大鳥圭介らの旧幕府軍が宇都宮城を攻め落とす"],["1868年4月","安塚で旧幕府軍と新政府軍が激突"],["1868年4月","新政府軍が宇都宮城を奪い返す"],["1868年9月","会津藩が降伏"]],"who":[["大鳥圭介","旧幕府軍を率いた指揮官"],["土方歳三","新選組の副長。宇都宮をめぐる戦いに加わった"],["壬生藩","新政府側についた地元の藩"],["両軍の戦死者","この地で命を落とした兵たち。今も墓でとむらわれている"]],"deep":["安塚の戦いは慶応4年4月22日（旧暦）に行われたとされ、宇都宮城の戦いと一連の戦闘として扱われます。","旧幕府軍には伝習隊などの洋式訓練を受けた部隊が加わっていたとされ、新政府軍には壬生藩のほか、各藩の兵が援軍として加わりました。","当日は雨だったと伝わり、銃の火薬がしけって撃てなくなるなど、苦しい戦いだったといわれます。","戦いの経過や両軍の死者数は記録によってまちまちで、正確な数ははっきりしていません。","安塚には両軍の戦死者をとむらう墓や碑が残り、敵味方を区別せずに供養されていることが特徴です。","旧幕府軍は宇都宮を失った後、日光・今市方面で新政府軍と戦い、やがて会津へと向かいました。"],"look":["戦死者の墓・慰霊碑","姿川周辺の地形（戦場のようす）","壬生城跡（新政府軍の拠点）","宇都宮城址公園（あわせて訪ねたい）"],"q":["安塚の戦いは何という戦争の一部?","戊辰戦争です。宇都宮城をめぐる戦いのひとつでした。"],"koji":[],"myth":"戦いの日付・経過・死者数・雨の描写は記録により異なり、伝承を含む。","img":["宇都宮城の戦い","大鳥圭介","壬生藩"],"wp":"戊辰戦争","rel":{"ev":[],"grave":[]},"ph":[["c:4/46/Monument_of_Meijiishin_Fushimi_no_senseki.jpg",3024,3780,"戊辰戦争"],["c:3/35/UtsunomiyaCastle.jpg",1051,1087,"宇都宮城の戦い"],["c:4/4c/Otori_Keisuke.jpg",1024,1327,"大鳥圭介"],["c:5/52/Mibuj%C5%8D_honmaru_entrance.JPG",6016,4000,"壬生藩"]]},{"id":"09_imaichi_battle","n":"今市の戦い（板垣退助の日光防衛）","yomi":"いまいちのたたかい","cat":"古戦場","rank":"B","y":1868,"era":["edo","meiji"],"sh":"","ad":"日光市今市（旧今市宿と日光杉並木の周辺）","st":"東武下今市駅・JR今市駅から歩いて約10〜15分（杉並木の «砲弾打込杉» は下今市駅から歩いて約20分）","la":36.725,"lo":139.688,"hook":"東照宮まであと少しの宿場で、土佐の兵と旧幕府軍がぶつかった。杉並木の幹には、いまも砲弾の傷が残る。","lead":"1868年（慶応4年）、戊辰戦争のさなかに、日光街道の今市宿で2度の戦いがありました。守ったのは板垣退助が率いる土佐藩などの新政府軍、攻めたのは大鳥圭介らの旧幕府軍と会津藩の兵です。日光の社寺が戦場にならなかったことと結びつけて語られる戦いです。","story":["1868年の春、江戸城が明け渡されても、戦いは終わりませんでした。幕府の歩兵を率いた大鳥圭介は北へ向かい、宇都宮城をめぐる戦いのあと、兵を日光へ入れます。日光には家康をまつる東照宮があります。«徳川の聖地で最後まで戦うべきだ» と考えた者もいたでしょう。けれど、そこで戦えば、社殿が焼けてしまうかもしれません。","新政府軍の側で北関東の戦いを受け持ったのが、土佐藩の板垣退助でした。のちに «自由民権運動» で知られる人物ですが、このころは30歳を少し過ぎた軍の指揮官です。板垣は日光の旧幕府軍に使いを送り、山を下りるよう説いたと伝わります。«東照宮を戦火で焼けば、敵も味方も後の世に顔向けできない» ——そんな思いがあったのかもしれません。旧幕府軍は日光を離れ、会津方面へ退きました。","そのあと新政府軍は、日光と宇都宮・会津方面を結ぶ分かれ道にあたる今市宿に陣を置きます。今市は日光街道・会津西街道・例幣使街道が集まる交通の要。ここを押さえれば、会津から日光へ出る道をふさげます。なぜ今市だったのか？ 地図を広げると、道が一つに集まる «のど» の位置にあることがよくわかります。","閏4月、旧幕府軍が今市を攻めました。杉並木の間を通る街道は見通しが悪く、両軍は木々を盾にして撃ち合ったといいます。新政府軍は陣地を守りきり、攻撃は退けられました。5月にも会津藩の兵などが再び攻めかかりましたが、これも退けられています。杉並木の一本には、このとき飛んできた砲弾が当たった跡と伝わる裂け目が残り、«砲弾打込杉» と呼ばれています。","戦いでは両軍に死傷者が出ました。街道沿いには、倒れた兵をとむらう墓や碑が点々と残っています。日光の神橋近くには板垣退助の銅像が立ち、«日光を戦火から守った人» として顕彰されています。ただ、実際に日光から兵を引かせたのは誰の説得だったのか、どこまでが板垣の手柄なのかは、史料の読み方によって見方が分かれます。"],"tl":[["1868年（慶応4年）4月","宇都宮城をめぐる戦い。旧幕府軍の一部が日光へ入る"],["1868年閏4月","旧幕府軍が日光から退き、新政府軍が今市に陣を置く"],["1868年閏4月","旧幕府軍が今市を攻撃。新政府軍が退ける（第1次）"],["1868年5月","会津藩兵などが再び今市を攻撃。これも退けられる（第2次）"],["1868年8月以降","戦いの中心は会津若松へ移る（会津戦争）"],["昭和・平成","杉並木の «砲弾打込杉»、戦死者の墓碑が今市の史跡として伝えられる"]],"who":[["板垣退助","土佐藩の指揮官。新政府軍を率いて今市を守った"],["大鳥圭介","旧幕府軍（伝習隊など）の指揮官。日光から会津方面へ転戦"],["会津藩の兵","旧幕府側。今市を2度目に攻めた軍の中心"],["二宮尊徳","戦いの十数年前に今市で亡くなった農政家。今市には尊徳をまつる報徳二宮神社がある"]],"deep":["今市は日光街道・会津西街道・日光例幣使街道の合流点。会津藩からみれば、日光と関東平野へ出る出口で、新政府軍からみれば会津への入口。戦略上の «要の宿» でした。","日光杉並木は、松平正綱が約20年かけて植えたと伝わる並木で、国の特別史跡・特別天然記念物の二重指定。そのなかに戊辰戦争の砲弾痕と伝わる «砲弾打込杉» があります。","板垣退助の銅像は日光の神橋近くに立っています。戦時中の金属供出でいったん失われ、のちに再建されたといわれ、台座の文にも «日光を戦火から守った» という評価が刻まれています。","日光から旧幕府軍を退かせた経緯については、板垣の説得、日光の僧侶たちの働きかけ、大鳥側の判断など、いくつもの要素が語られ、誰の功績かは諸説があります。","今市の戦いは、宇都宮城の戦いと会津戦争のあいだの «つなぎ» の戦い。ここで日光口が固められたことで、会津藩は南側の守りに兵を割き続けることになりました。","戦死者の墓碑は、新政府軍側・旧幕府軍側の両方が今市周辺に残ります。どちらの側の人も、それぞれの故郷を遠く離れて亡くなった人たちでした。"],"look":["日光杉並木の «砲弾打込杉»（案内板あり）","今市宿の町並みと、街道が分かれる追分の位置","報徳二宮神社と二宮尊徳の墓","足をのばして、日光・神橋近くの板垣退助銅像"],"q":["今市の杉並木にある、戊辰戦争の傷跡と伝わる杉を何と呼ぶ？","«砲弾打込杉»。戦いのとき砲弾が当たった跡と伝わる裂け目が幹に残ります。"],"koji":[],"myth":"板垣退助が日光を戦火から救ったという話は広く知られるが、日光撤退の経緯や功績の範囲については諸説ある。","img":["戊辰戦争","板垣退助","大鳥圭介","日光杉並木"],"wp":"今市の戦い","rel":{"ev":[],"grave":[["sontoku","二宮尊徳"]]},"ph":[["c:4/46/Monument_of_Meijiishin_Fushimi_no_senseki.jpg",3024,3780,"戊辰戦争"],["c:2/26/ITAGAKI_Taisuke.jpg",1024,1335,"板垣退助"],["c:4/4c/Otori_Keisuke.jpg",1024,1327,"大鳥圭介"],["c:8/8f/%E6%97%A5%E5%85%89%E6%9D%89%E4%B8%A6%E6%9C%A8%E8%A1%97%E9%81%93_20130522_-_panoramio.jpg",2736,1824,"日光杉並木"]]},{"id":"09_hatsuishi","n":"鉢石宿（日光街道最後の宿）","yomi":"はついしじゅく","cat":"街道","rank":"B","y":1617,"era":["edo"],"sh":"","ad":"日光市上鉢石町・中鉢石町・下鉢石町","st":"東武日光駅・JR日光駅から歩いて約15分（神橋の手前まで）","la":36.749,"lo":139.606,"hook":"江戸・日本橋から歩きつづけた日光街道。その最後の宿場が、神橋の手前の坂道にあった。","lead":"鉢石宿は、江戸と日光を結ぶ日光街道の «ゴール» にあたる宿場です。宿場のすぐ先に神橋があり、その向こうが東照宮などの社寺。将軍の日光社参や、全国からの参拝客を迎えた門前町でした。","story":["日本橋を出て、千住・草加・越谷……と宿場をたどると、最後にたどり着くのが鉢石宿です。宿場の先には大谷川が流れ、朱色の神橋がかかっています。旅人はここで身なりを整え、いよいよ «お山» へ向かいました。なぜ宿場は神橋の手前で終わるのでしょう？ 橋の向こうは神仏の領域。人が泊まり、商いをする «俗» の町は、川のこちら側に置かれたのです。","«鉢石（はついし）» という名前は、日光を開いた勝道上人が腰かけたという、鉢を伏せたような形の石に由来すると伝わります。町の中にはその石と伝わるものがまつられ、宿場の名の由来を今に伝えています。","1617年、家康の遺骸が久能山から日光へ移され、東照社（のちの東照宮）がまつられると、日光は幕府にとって特別な場所になりました。将軍みずからが参拝する «日光社参» のときは、大名や家臣の大行列が街道を進み、鉢石の町はその最後の宿泊地・準備の場として大いににぎわいました。","宿場には本陣・脇本陣があり、参拝客向けの旅籠や茶屋、みやげ物屋が坂道にそって並びました。«ようかん» はいまも日光の名物ですが、参拝の行き帰りの人々に甘いものが喜ばれたことと関係があるといわれます。","明治になると、外国人の避暑客や観光客がやってくるようになり、坂の上には洋風のホテルも建てられました。いまの国道119号はほぼ昔の街道のあと。車の多い通りですが、古い商家の構えや、坂の途中の寺社を探しながら歩くと、宿場の雰囲気がよみがえってきます。"],"tl":[["766年ごろ","勝道上人が大谷川を渡り、日光の山に入ったと伝わる"],["1617年","家康の遺骸が日光へ移され、東照社がまつられる"],["1636年","家光のもとで東照社の大造替（いまの社殿の多く）が完成"],["江戸時代","将軍の日光社参のたびに、最後の宿として大行列を迎える"],["明治時代","外国人観光客が増え、坂の上に洋風ホテルが建つ"],["現在","国道沿いに老舗の商店が続く門前町として残る"]],"who":[["勝道上人","日光を開いた僧。«鉢石» の名の由来になった石に座ったと伝わる"],["徳川家康","東照宮にまつられる。鉢石宿がにぎわう理由をつくった"],["徳川家光","日光社参を多く行い、東照宮を今の姿に造り替えた将軍"],["日光を訪れた外国人","明治以降、避暑や観光で鉢石の坂を上った"]],"deep":["日光街道は宇都宮まで奥州街道と道を共有し、宇都宮から分かれて今市・鉢石へ向かいます。鉢石は日光道中の最終宿で、ここから先に宿場はありません。","日光社参は江戸時代に将軍自身が19回行ったとされる大行事。行列は数日かけて進み、沿道の宿場には人馬の負担が重くのしかかりました。","鉢石宿は上鉢石・中鉢石・下鉢石など町ごとに分かれていました。坂の上ほど神橋に近く、参拝客向けの店が集まりました。","宿場の坂の上にある日光金谷ホテルは、明治のはじめに外国人向けの宿として始まった金谷家の事業から発展したもので、現存する日本最古級のリゾートホテルとして知られます。","門前町の «ようかん» の老舗は複数あり、日光ようかんは水のよさと、参拝客・観光客の需要に支えられて名物になったといわれます。"],"look":["«鉢石» の名の由来と伝わる石","神橋と大谷川（宿場の終点）","坂道に並ぶ老舗の商家やようかん屋","坂の上の洋風ホテルの建物（外観）"],"q":["日光街道の最後の宿場・鉢石宿の名前は、何に由来すると伝わる？","勝道上人が腰かけたという、鉢を伏せたような形の石に由来すると伝わります。"],"koji":[{"w":"日光を見ずして結構と言うなかれ","m":"日光のすばらしさを見ないうちは «結構» という言葉を使うな、という古くからの言い回し"}],"myth":"«鉢石» の石の由来は伝承。","img":["日光街道","日光東照宮","神橋","日光金谷ホテル"],"wp":"鉢石宿","rel":{"ev":["k_nikko"],"grave":[]},"ph":[["c:0/05/Town_Hachiishi_LACMA_M.91.377.55.jpg",2100,1660,"鉢石宿"],["c:1/10/Nikko_kaido_hasui_kawase.jpg",910,1384,"日光街道"],["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"],["c:a/a2/Shinkyo_Sacred_Bridge_%2811284693104%29.jpg",4573,3049,"神橋"],["c:b/b6/200730_Nikko_Kanaya_Hotel_Nikko_Japan06s3.jpg",6000,4000,"日光金谷ホテル"]]},{"id":"09_ashino","n":"芦野宿と遊行柳","yomi":"あしのじゅくとゆぎょうやなぎ","cat":"街道","rank":"B","y":1689,"era":["muromachi","edo"],"sh":"国の名勝（おくのほそ道の風景地・遊行柳）","ad":"那須郡那須町芦野","st":"JR黒田原駅から車で約15分（町営バスあり・本数少なめ）","la":37.004,"lo":140.145,"hook":"西行が «しばし» のつもりで立ち止まり、芭蕉が田植えを見届けて去った一本の柳。","lead":"芦野宿は、奥州街道の栃木県最北の宿場のひとつです。町はずれの田んぼの中に «遊行柳» という柳があり、西行・松尾芭蕉・与謝蕪村が歌や句を残しました。能の物語の舞台にもなった、文学の名所です。","story":["奥州街道を北へ進むと、那須の山々のすそ、白河の関の手前に芦野の宿があります。江戸時代、この一帯は芦野氏という旗本が治め、宿場の近くの山に館を構えていました。宿場には本陣があり、白河を越えて東北へ向かう大名や旅人が泊まりました。","宿のはずれ、田んぼの中に一本の柳があります。昔、平安時代末の歌人・西行がこの柳の下で «道のべに清水流るる柳かげ しばしとてこそ立ちどまりつれ» と詠んだと伝わります。«ほんの少しのつもりが、つい長居してしまった»——清水と柳の涼しさが伝わる歌です。","室町時代になると、この柳は能の «遊行柳» の舞台になりました。念仏の旅を続ける遊行上人の前に一人の老人が現れ、古い柳の道を教えます。その正体は柳の精で、念仏の力で救われて消えていく……。なぜ柳が «成仏» するのでしょう？ 草木にも心があり、仏の教えで救われる、という中世の人々の考え方が物語に込められています。","1689年、松尾芭蕉は «おくのほそ道» の旅でこの柳を訪ねました。芭蕉は西行を深く慕っていました。ここで詠んだのが «田一枚植ゑて立ち去る柳かな»。柳の下にたたずんでいるうちに、目の前の田が一枚植え終わってしまった——西行の «しばし» をふまえた、あこがれの人の足あとに立つ感動の句です。のちに与謝蕪村も芭蕉をしのんでこの地を訪れ、句を残しました。","いまの柳は何代も植えつがれたものですが、2014年に «おくのほそ道の風景地» の一つとして国の名勝に指定されました。宿場の近くには芦野石を使った石の美術館もあり、古い街道と現代の建築が同じ町で出会います。"],"tl":[["平安時代末","西行がこの地で柳の歌を詠んだと伝わる"],["室町時代","能 «遊行柳» がつくられ、柳の精の物語が広まる"],["江戸時代","芦野氏が治め、奥州街道の宿場として整う"],["1689年","松尾芭蕉が訪れ «田一枚植ゑて立ち去る柳かな» を詠む"],["18世紀","与謝蕪村が訪れて句を残す"],["2014年","«おくのほそ道の風景地» の一つとして国の名勝に指定"]],"who":[["西行","平安時代末の歌人。柳の歌の作者とされる"],["松尾芭蕉","«おくのほそ道» の旅で訪れ、句を詠んだ"],["与謝蕪村","芭蕉を慕い、この地で句を残した"],["遊行上人","時宗の念仏僧。能 «遊行柳» の主人公"],["芦野氏","江戸時代に芦野を治めた旗本"]],"deep":["西行の歌は «新古今和歌集» に入っていますが、どこで詠まれたかは歌自体には書かれていません。この柳の下で詠んだというのは後世の伝承で、能や芭蕉の句によって «ここ» の話として定着しました。","能 «遊行柳» は室町時代の観世信光の作とされる作品。西行の歌を下敷きにし、老いた柳の精が遊行上人の念仏で救われる筋立てです。","芭蕉の «田一枚» の句は、誰が植えて誰が立ち去ったのかをめぐって解釈が分かれる名句として有名。早乙女が植えて去った、芭蕉自身が去った、など諸説あります。","芦野氏は那須氏の一族で、江戸時代は旗本（交代寄合）として芦野を治めました。宿場近くの丘に館跡があります。","芦野は良質な安山岩 «芦野石» の産地。建築家・隈研吾が設計した石の美術館 «STONE PLAZA» は、古い石蔵を生かしてつくられています。"],"look":["田んぼの中の遊行柳と、そばの句碑・歌碑","芦野宿の町並み（本陣跡などの案内板）","芦野氏の館跡のある丘","芦野石を使った石の美術館（外観）"],"q":["芭蕉が遊行柳で詠んだ句は？","«田一枚植ゑて立ち去る柳かな»。西行の «しばし» の歌をふまえた句といわれます。"],"koji":[{"w":"田一枚植ゑて立ち去る柳かな","m":"芭蕉の句。あこがれの西行の跡に立ち、時を忘れた感動が込められているとされる"}],"myth":"西行がこの柳で歌を詠んだという話は伝承。芭蕉の句の解釈は諸説あり。","img":["遊行柳","松尾芭蕉","西行","奥の細道"],"wp":"芦野宿","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"],["c:e/ef/PORTRAIT_OF_THE_PRIEST-POET_SAIGYO_-_Google_Art_Project.jpg",1262,2549,"西行"]]},{"id":"09_mamada","n":"間々田宿","yomi":"ままだしゅく","cat":"街道","rank":"B","y":1650,"era":["edo"],"sh":"","ad":"小山市間々田","st":"JR宇都宮線間々田駅から歩いて約10分","la":36.254,"lo":139.815,"hook":"江戸と日光の «ちょうどまん中»。名前そのものが道のりを語る宿場。","lead":"間々田宿は、日光街道で江戸から数えて11番目の宿場です。江戸と日光のほぼ中間にあることから «間の田» と呼ばれたのが名の始まりという説があります。いまも間々田八幡宮の «じゃがまいた» という蛇の祭りが続く町です。","story":["日光街道を北へ、古河・野木を過ぎると、思川のそばに間々田の宿があります。«ままだ» とは変わった名前ですね。なぜこの名前？ 江戸からも日光からもおよそ同じくらいの距離にあり、«あいだの宿» という意味で «間田» と呼ばれたのが始まり——そんな説が地元で語られています。","江戸時代の間々田宿には本陣・脇本陣、旅籠が並びました。大きな宿場ではありませんでしたが、日光社参の行列や、奥州へ向かう大名、商人が行き来し、人と馬の継ぎ立てを担いました。宿場の人々にとって、将軍の社参は名誉であると同時に、人や馬を大量に出さなければならない大仕事でした。","宿場のそばを流れる思川は、江戸へ荷を運ぶ舟の道でもありました。川沿いには河岸（かし・舟の荷の積みおろし場）がつくられ、米や木材などが江戸へ運ばれました。陸の街道と川の道、二つの流れが交わる場所だったのです。","間々田八幡宮では、毎年5月に «間々田のじゃがまいた» という祭りが行われます。わらや竹で作った長い蛇を子どもたちや町の人がかつぎ、«じゃがまいた、じゃがまいた» と声をあげて町をねり歩きます。蛇は水の神。田植えの前に雨と豊作を願い、疫病を追いはらう祭りだといわれます。","いまの間々田は住宅地ですが、街道の道筋はそのまま残り、八幡宮の森や古い家並みに宿場の記憶が見つかります。駅から歩いて «江戸と日光のまん中» を体感してみるのも楽しい散歩です。"],"tl":[["江戸時代初め","日光街道が整えられ、間々田が宿場になる"],["1617年","家康が日光にまつられ、街道の往来が増える"],["江戸時代","将軍の日光社参の行列が通る。思川の河岸も利用される"],["1885年","日本鉄道の路線（いまの宇都宮線）が通る"],["1894年","間々田駅が開業"],["現在","間々田八幡宮で毎年5月に «じゃがまいた» が行われる"]],"who":[["徳川将軍家","日光社参の行列で宿場を通った"],["宿場の問屋・本陣の人々","人馬の継ぎ立てや大名の宿泊を担った"],["間々田の子どもたち","«じゃがまいた» で蛇をかつぐ主役"]],"deep":["«間々田» の名の由来は、江戸と日光の中間にあたるから «間の田»、という説が有名ですが、ほかにも地形に由来する説などがあり、確定していません。","日光街道は日本橋から千住・草加・越ヶ谷・粕壁・杉戸・幸手・栗橋・中田・古河・野木と続き、間々田はその次の宿場です。","宿場は人馬の継ぎ立ての義務を負い、足りないときは周辺の村々から «助郷» として人や馬を出させました。社参のときは負担が特に重くなりました。","«じゃがまいた» は «蛇が参った» がなまったものといわれます。蛇をかつぐ祭りは各地にありますが、町中を大蛇がねり歩き、池で水を飲ませる所作があるのが特徴です。","思川沿いの河岸は、江戸と北関東を結ぶ舟運の拠点でした。鉄道ができると、物流の主役は川から線路へ移っていきます。"],"look":["間々田八幡宮の森と境内","旧日光街道の道筋（宿場の案内板）","思川の流れと河岸があったあたり","5月の «じゃがまいた» の日に訪れると大蛇が見られる"],"q":["間々田八幡宮の祭りでかつがれる大きな生き物は何？","蛇（じゃ）。わらや竹で作った大蛇をかつぎ、豊作や厄よけを願う «じゃがまいた» です。"],"koji":[],"myth":"«間々田» の名の由来は諸説ある。","img":["日光街道","間々田駅","思川","小山市"],"wp":"間々田宿","rel":{"ev":[],"grave":[]},"ph":[["c:1/10/Nikko_kaido_hasui_kawase.jpg",910,1384,"日光街道"],["c:e/e0/JR_East_Mamada_Station_East_Exit_in_Oyama_City%2C_Tochigi_Pref_20240608.jpg",6000,4000,"間々田駅"],["c:8/88/%E5%AE%89%E6%88%BF%E7%A5%9E%E7%A4%BE_.jpg",5472,3648,"小山市"]]},{"id":"09_sessho_onsen","n":"那須温泉神社（与一が祈った社）","yomi":"なすゆぜんじんじゃ","cat":"寺社","rank":"B","y":1185,"era":["asuka","heian","edo"],"sh":"","ad":"那須郡那須町湯本","st":"JR黒磯駅から那須湯本方面行きバスで約35〜40分、«那須湯本» 下車すぐ","la":37.096,"lo":139.969,"hook":"«南無八幡大菩薩……那須の湯泉大明神»。扇の的の前で、那須与一が名を呼んだ神さま。","lead":"那須温泉神社は、那須湯本の温泉のそばにある古い神社です。平安時代の «延喜式» にも名がのる格式ある社で、屋島の戦いで那須与一が扇の的を射るとき、この神に祈ったことで知られます。すぐ上には九尾の狐の伝説が残る «殺生石» があります。","story":["社の伝えによると、昔、狩野三郎行広という狩人が白い鹿を追って山に入り、その鹿に導かれて湯の湧く場所を見つけました。これが那須の温泉の始まりで、温泉の神をまつったのが神社の起こりだといわれます。舒明天皇の時代（7世紀）のことと伝わります。","時代はくだって1185年、四国・屋島の海辺。平家の舟に立てられた扇を射よ、と命じられたのは下野の若武者・那須与一でした。波は高く、扇はゆれています。外せば一門の恥。«平家物語» の与一は目を閉じて祈ります。«南無八幡大菩薩、わが国の神々、日光権現、宇都宮、那須の湯泉大明神、どうかあの扇のまん中を射させてください»。放たれた矢は扇のかなめ近くを射切り、扇は夕日に舞って海に落ちました。","なぜ与一は、たくさんの神々のなかで «那須の湯泉大明神» の名をあげたのでしょう？ それは故郷の神だったからです。いちばん大事なときに、ふるさとの山の湯の神を思い出した——物語はそう語っています。神社には、与一が願いがかなったお礼に奉納したと伝わる品や鳥居の話が残っています。","1689年、松尾芭蕉も «おくのほそ道» の旅でこの神社に参り、与一ゆかりの宝物を見たと書いています。そのあと芭蕉が向かったのが、神社の奥の殺生石でした。","殺生石は、有毒なガスが出て近づく鳥や獣が死ぬことから、九尾の狐が化けた石だという伝説が生まれた場所です。2022年にはこの石が二つに割れて話題になりました。湯けむりと硫黄のにおいの中、古い社と伝説の石がならぶ風景は、昔の人が «神のすむ山» と感じた気持ちを想像させてくれます。"],"tl":[["7世紀（伝）","狩野三郎行広が白鹿に導かれ温泉を発見し、神をまつったと伝わる"],["927年","«延喜式» の神名帳に名がのる（完成年）"],["1185年","屋島の戦いで那須与一が «那須の湯泉大明神» に祈ったと «平家物語» に語られる"],["1689年","松尾芭蕉が参拝し、殺生石を訪ねる"],["2014年","殺生石などが «おくのほそ道の風景地» として国の名勝に"],["2022年","殺生石が二つに割れているのが見つかる"]],"who":[["那須与一","那須氏の武将。屋島の扇の的で祈った"],["狩野三郎行広","温泉を見つけたと伝わる狩人"],["松尾芭蕉","«おくのほそ道» の旅で参拝した"],["玄翁和尚","殺生石の毒気を鎮めたと伝わる僧（«げんのう» の語源とも）"]],"deep":["«延喜式» 神名帳に «温泉神社» の名で記された神社は東北・関東に複数あり、那須の温泉神社はその代表格とされます。温泉そのものを神としてあがめた古い信仰の形を伝えています。","«平家物語» の与一の祈りの言葉には異なる写本があり、神々の並べ方や表記に違いがあります。«湯泉大明神» の読みも «ゆぜん» とされることが多いです。","与一が奉納したと伝わる品については、伝承と史実を区別して見る必要があります。与一自身の生涯も、確かな史料は多くありません。","殺生石の九尾の狐伝説は、室町時代の能 «殺生石» で広まりました。僧・玄翁が石を割って霊を鎮めたとされ、大きな金づちを «げんのう» と呼ぶ由来の一つとされます。","殺生石のまわりでは、いまも火山ガス（硫化水素など）が出ることがあり、立入が規制される区域があります。"],"look":["鳥居と参道の石段、湯けむりの見える境内","与一ゆかりの話を伝える案内","神社の奥の殺生石と «千体地蔵»","芭蕉の句碑"],"q":["那須与一が扇の的を射る前に祈った神々のうち、故郷・那須の神は何と呼ばれている？","«那須の湯泉大明神»。那須温泉神社の神のことです。"],"koji":[{"w":"南無八幡大菩薩","m":"武士が戦のときに唱えた言葉。八幡神（武運の神）に身をゆだねるという意味"}],"myth":"温泉発見の話、与一の奉納品の話、殺生石の九尾の狐は伝承・物語。","img":["那須与一","殺生石","屋島の戦い","那須温泉"],"wp":"那須温泉神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/fa/Nasuyuzen.jpg",800,600,"那須温泉神社"],["c:6/64/NasunoYoichi.jpg",1260,961,"那須与一"],["c:2/27/180727_Sessho-seki_Nasu_Japan14.JPG",6000,4000,"殺生石"],["c:4/48/Battle_of_Yashima_Folding_Screens_Kano_School.jpg",10969,4896,"屋島の戦い"]]},{"id":"09_kobunji_sano","n":"惣宗寺（佐野厄除け大師）","yomi":"そうしゅうじ（さのやくよけだいし）","cat":"寺社","rank":"B","y":944,"era":["heian","edo","taisho"],"sh":"","ad":"佐野市金井上町","st":"JR両毛線・東武佐野線佐野駅から歩いて約10分","la":36.314,"lo":139.579,"hook":"正月には «厄よけ» の参拝客でうまる寺。その境内に、足尾鉱毒と闘った田中正造も眠る。","lead":"惣宗寺は «佐野厄除け大師» の名で親しまれる天台宗の寺です。平安時代に藤原秀郷が建てたと伝わり、厄よけの仏さま・元三大師をまつります。足尾鉱毒事件と闘った田中正造の本葬が行われ、墓の一つがあることでも知られます。","story":["寺の伝えでは、平安時代の中ごろ、944年に藤原秀郷がこの寺を建てたといわれます。秀郷は平将門を討ったことで名高い武将で、佐野や足利の一帯には秀郷ゆかりの話がたくさん残っています。はじめ寺は、いまの佐野城跡のある春日岡という丘の上にありました。","江戸時代のはじめ、佐野氏が春日岡に城を築くことになり、寺は丘のふもと、いまの場所へ移されました。«山号» が春日岡山なのは、その名残です。寺が城に場所をゆずった——なぜでしょう？ 丘は見晴らしのよい要地。戦国の世が終わりかけても、城を置くには一番の場所だったのです。","この寺でまつられているのが元三大師（良源）。平安時代の比叡山の高僧で、正月三日に亡くなったので «元三（がんざん）» 大師と呼ばれます。疫病神を追いはらったという話から、厄よけの仏として関東でも信仰を集めました。いまでは初詣や厄年のお参りで、正月の境内は大勢の人でにぎわいます。","1913年、足尾銅山の鉱毒で苦しむ村人のために一生をささげた田中正造が亡くなりました。持ち物はわずかで、袋の中には新約聖書や小石、日記などしかなかったと伝わります。その本葬が惣宗寺で行われ、たくさんの人が見送りました。正造の遺骨は、ゆかりの地に分けて葬られ、この寺にも墓があります。","«真の文明は山を荒らさず、川を荒らさず、村を破らず、人を殺さざるべし»。正造が残したこの言葉は、100年以上たったいまも読み継がれています。厄よけのにぎわいの中で、正造の墓の前に立つと、この土地の人々が何を大事にしてきたのかが見えてくる気がします。"],"tl":[["944年（伝）","藤原秀郷が春日岡に寺を建てたと伝わる"],["江戸時代初め","佐野氏の築城で、寺が丘のふもとの現在地へ移る"],["江戸時代","元三大師の信仰が広まり «厄除け大師» として親しまれる"],["1913年","田中正造が亡くなり、惣宗寺で本葬が行われる"],["現在","初詣・厄よけの寺として関東各地から参拝客が訪れる"]],"who":[["藤原秀郷","寺を建てたと伝わる平安時代の武将"],["元三大師（良源）","本尊としてまつられる比叡山の高僧"],["田中正造","足尾鉱毒事件と闘った政治家。本葬が行われ、墓がある"],["佐野氏","春日岡に城を築き、寺の移転のきっかけをつくった"]],"deep":["元三大師は正月三日の命日にちなむ呼び名。«角大師» と呼ばれる、鬼のような姿の護符が厄よけとして各地の家に貼られてきました。","佐野城は江戸時代のはじめに佐野信吉が春日岡に築いた城ですが、佐野氏が改易されたことで短い期間で廃城になりました。城跡はいま城山公園になっています。","田中正造の遺骨は、惣宗寺のほか渡良瀬川流域のゆかりの地など複数か所に分けて葬られたことで知られます。人々が «自分たちの土地にも» と願った結果でした。","正造が亡くなったとき持っていた袋の中身は、聖書・憲法の本・日記・小石などと伝わります。財産を運動にささげきった人生を物語る話です。","関東で «厄除け大師» と呼ばれる寺は複数あり、佐野・川崎・西新井などがよく知られています。"],"look":["本堂と元三大師の信仰を伝える境内","田中正造の墓","厄よけの護符（角大師）","近くの城山公園（佐野城跡）"],"q":["元三大師の «元三» とは何を表している？","正月三日（元三）。良源がこの日に亡くなったことに由来します。"],"koji":[{"w":"真の文明は山を荒らさず、川を荒らさず、村を破らず、人を殺さざるべし","m":"田中正造の日記にある言葉。自然と人を壊す開発を戒めた"}],"myth":"藤原秀郷による創建は寺の伝え。","img":["田中正造","藤原秀郷","良源","佐野城"],"wp":"惣宗寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Soshu-ji_Temple.JPG",2048,1536,"惣宗寺"],["c:8/8e/Tanaka_Shozo.jpg",834,1207,"田中正造"],["c:c/c0/Yoshitoshi_Fujiwara_no_Hidesato.jpg",1263,1869,"藤原秀郷"],["c:9/99/Seated_Jie_Daishi_1.jpg",3264,2448,"良源"],["c:f/fc/Sano_Shiroyama_Park.JPG",2048,1536,"佐野城"]]},{"id":"09_tenmyo","n":"天明鋳物（佐野）","yomi":"てんみょういもの","cat":"産業","rank":"B","y":940,"era":["heian","muromachi","edo"],"sh":"","ad":"佐野市天明町・大橋町ほか（市内各所）","st":"JR・東武佐野駅から歩いて約10分（佐野市郷土博物館へは約15分）","la":36.312,"lo":139.582,"hook":"«西の芦屋、東の天明»。茶人が争って求めた鉄の釜は、佐野の町で生まれた。","lead":"天明鋳物は、佐野の天明（てんみょう）の町でつくられてきた鋳物です。とくに茶の湯の釜 «天明釜» は、九州の «芦屋釜» と並んで室町時代から名品とされました。梵鐘や灯籠、日用品まで、千年近く «火と鉄の町» として続いてきたといわれます。","story":["鋳物とは、溶かした鉄や銅を型に流しこんで形をつくるもの。佐野の伝えでは、平安時代の中ごろ、藤原秀郷が河内国（いまの大阪府）から鋳物師を呼び寄せ、武具などをつくらせたのが始まりとされます。なぜ佐野で？ 近くの川で砂鉄がとれ、型に使うよい砂や粘土、燃料の木にもめぐまれていたからだといわれます。","室町時代になると、茶の湯が武士や町の人々のあいだで広まりました。お湯をわかす «釜» は、茶室の主役の道具です。佐野でつくられた釜は «天明釜» と呼ばれ、ざらりとした素朴な肌、力強い形が好まれました。九州・筑前の «芦屋釜» と並び称され、«西の芦屋、東の天明» といわれるほどでした。","芦屋釜がなめらかで繊細な文様が特徴とすれば、天明釜は荒々しい肌合いと重厚さが持ち味。茶人たちは «どちらが好みか» を語り合ったことでしょう。わび茶の美意識には、飾らない天明の釜がよく合ったともいわれます。","江戸時代には、茶釜だけでなく、寺の梵鐘、灯籠、なべやかまなどの暮らしの道具も数多くつくられ、関東各地へ運ばれました。いまも各地の寺に、天明の鋳物師の名を刻んだ鐘が残っています。","明治以降、工業化で鋳物の仕事は大きく変わりましたが、佐野では工房が伝統の技を受けつぎ、茶釜や風鈴、置物などをつくっています。佐野市郷土博物館では、天明鋳物の歴史と名品に出会えます。"],"tl":[["10世紀（伝）","藤原秀郷が河内の鋳物師を呼び寄せたと伝わる"],["室町時代","茶の湯の広まりとともに «天明釜» が名品として知られる"],["江戸時代","梵鐘・灯籠・日用品が関東一円に出荷される"],["明治以降","工業化の中で規模が縮小、工房が技を受けつぐ"],["現在","栃木県の伝統工芸品として茶釜・風鈴などがつくられる"]],"who":[["藤原秀郷","鋳物師を呼び寄せたと伝わる武将"],["天明の鋳物師たち","茶釜・梵鐘をつくった職人。鐘の銘に名が残る"],["茶人たち","天明釜を芦屋釜と並ぶ名品として愛した"]],"deep":["«天明» は佐野の地名で、年号の «天明（てんめい）» とは読みが異なり «てんみょう» と読みます。","芦屋釜は筑前国芦屋（いまの福岡県芦屋町）で室町時代に栄えた茶釜で、国の重要文化財に指定された名品があります。天明釜と «西と東» で並べて語られました。","天明釜の特徴は «荒肌» と呼ばれるざらついた表面と、力強い形といわれます。一方、芦屋釜は «鯰肌（なまずはだ）» と呼ばれるなめらかな肌に絵のような文様をあらわしました。","鋳物師は «鋳物師職» として朝廷に関わる公家の支配を受けることがあり、その許しを得て各地で営業しました。天明の鋳物師もそうした仕組みの中で活動したと考えられています。","天明鋳物は栃木県の伝統工芸品に指定されています。"],"look":["佐野市郷土博物館の天明鋳物の展示","市内の寺に残る天明の鋳物師銘の梵鐘や灯籠","工房のつくる茶釜や風鈴（見学・購入は各工房に要確認）"],"q":["«西の芦屋、東の天明»。天明と並び称された «芦屋» の茶釜はどこでつくられた？","筑前国芦屋（いまの福岡県芦屋町）。室町時代に名品を生んだ茶釜の産地です。"],"koji":[{"w":"西の芦屋、東の天明","m":"茶釜の二大名産地をたたえた言葉"}],"myth":"藤原秀郷が鋳物師を呼んだという起源は伝承。","img":["鋳物","芦屋釜","茶の湯","佐野市"],"wp":"天明鋳物","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/Outdoor_Tea_Ceremony.jpg",4368,2912,"茶の湯"],["c:a/a0/Soshu-ji_Temple.JPG",2048,1536,"佐野市"]]},{"id":"09_omae","n":"大前神社（真岡）","yomi":"おおさきじんじゃ","cat":"寺社","rank":"B","y":927,"era":["heian","edo","showa"],"sh":"","ad":"真岡市東郷","st":"真岡鐵道北真岡駅から歩いて約10分","la":36.456,"lo":140.007,"hook":"千年以上の歴史を持つ古社に、高さ20mの «日本一» のえびす様がほほえむ。","lead":"大前神社は、平安時代の «延喜式» にも名がのる古い神社です。大国主命と事代主命（えびす様）をまつり、江戸時代の彫刻で飾られた社殿が残ります。境内の大前恵比寿神社には巨大なえびす像が立ち、商売繁盛の神として親しまれています。","story":["真岡の町を流れる五行川のほとり、こんもりとした森の中に大前神社があります。«延喜式» という平安時代の法令集には、全国の大事な神社の名が並べられていますが、そこに下野国芳賀郡の神社として名があがっているのが大前神社です。つまり1000年以上前から、国に認められた神社だったのです。","まつられているのは大国主命と事代主命。大国主命は «だいこく様»、事代主命は «えびす様» として、どちらも福の神の代表です。なぜ田畑の広がる真岡に福の神？ 五行川の水にめぐまれたこの地は、昔から米づくりがさかんでした。豊作と暮らしの安定を願う人々にとって、国づくりと豊かさの神は心強い存在だったのでしょう。","社殿は江戸時代に建て直されたもので、柱や壁にこまやかな彫刻がほどこされています。竜や花鳥、中国の故事をあらわした彫り物は、同じ下野の日光東照宮の華やかさを思わせます。江戸時代、北関東の社寺では、こうした彫刻で建物を飾ることが流行しました。","境内には «大前恵比寿神社» があり、高さ約20mという大きなえびす像が立っています。釣りざおと鯛を持ったにこやかな姿は、遠くからでもよく見え、«日本一のえびす様» として参拝客を迎えています。古い社と現代の巨大像が一つの境内にあるのも、この神社の面白さです。","真岡は江戸時代、白木綿 «真岡木綿» の産地として栄えました。商いでにぎわう町の人々が、えびす様に商売繁盛を願ったことは想像にかたくありません。SLが走る真岡鐵道に乗って、古社をたずねてみるのもおすすめです。"],"tl":[["平安時代","«延喜式» 神名帳に下野国芳賀郡の神社として名がのる"],["江戸時代","社殿が建て直され、彫刻で飾られる"],["江戸時代","真岡木綿で町が栄え、商売繁盛の信仰も集める"],["昭和後期","境内に大きなえびす像がつくられる"],["現在","商売繁盛・五穀豊穣の神社として参拝客が訪れる"]],"who":[["大国主命","まつられる神。国づくりと福の神（だいこく様）"],["事代主命","まつられる神。えびす様として商売繁盛の神"],["江戸時代の彫物師たち","社殿を彫刻で飾った職人"]],"deep":["«延喜式» 神名帳にのる神社を «式内社» と呼びます。下野国には式内社が12座あり、大前神社はそのひとつとされます。","事代主命は «国譲り» の神話で、父の大国主命に代わって国を譲ることを答えた神。釣りをしていたという話から、釣りざおと鯛を持つえびす様と重ねて信仰されました。","社殿の彫刻は江戸時代の北関東の社寺建築らしい作風で、極彩色や彫刻の多用は日光東照宮の造営の影響を受けたとする見方があります。","境内の大えびす像は高さ約20mといわれ、«日本一» をうたっています。","五行川はかつて «大川» とも呼ばれた川で、流域の田を潤してきました。神社が川のそばにあるのは、水の恵みへの感謝とも結びつきます。"],"look":["江戸時代の社殿と彫刻","境内の大前恵比寿神社と巨大えびす像","五行川沿いの鎮守の森"],"q":["大前神社にまつられている «えびす様» は、神話では何という神？","事代主命（ことしろぬしのみこと）。釣りざおと鯛を持つ姿で表されます。"],"koji":[],"myth":"創建の年代ははっきりしない。社殿彫刻の作者や東照宮との関係は諸説。","img":["延喜式神名帳","えびす","大国主","真岡鐵道真岡線"],"wp":"大前神社","rel":{"ev":[],"grave":[]},"ph":[["c:4/40/Oosakijinjya-haiden.jpg",1728,1152,"大前神社"],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"],["c:d/d6/Ebisu_at_Ebisu-jinja_-_Kyoto%2C_Japan_-_DSC07332.jpg",3376,5364,"えびす"],["c:f/ff/%E3%83%A2%E3%82%AA%E3%82%AB14%E5%BD%A2%282023%E5%B9%B48%E6%9C%88%29.jpg",3503,2633,"真岡鐵道真岡線"]]},{"id":"09_mooka_momen","n":"真岡木綿","yomi":"もおかもめん","cat":"産業","rank":"B","y":1810,"era":["edo","showa"],"sh":"","ad":"真岡市荒町ほか（真岡木綿会館など）","st":"真岡鐵道真岡駅から歩いて約10分","la":36.439,"lo":140.012,"hook":"江戸の町人が «真岡» と名前を聞いただけで買った、白くて丈夫な木綿。","lead":"真岡木綿は、江戸時代に真岡とその周りの村でつくられた白い木綿の布です。薄くて丈夫で、肌ざわりがよく、江戸では «真岡» といえば上等な木綿の代名詞になりました。明治以降いったん途絶えかけましたが、昭和の終わりに復興され、いまも手織りが続いています。","story":["江戸時代、人々の着物の素材は麻から木綿へと大きく変わりました。木綿はあたたかく、洗っても丈夫。そのなかで «真岡木綿» は、江戸の呉服屋が争って仕入れる人気の品でした。糸を紡ぐのも、布を織るのも、農家の女性たちの冬の仕事。できあがった布は真岡の町に集められ、問屋が江戸へ送りました。","なぜ真岡の木綿はそんなに評判がよかったのでしょう？ 一つは «さらし» の技です。織った布を水にさらし、日に干すことをくり返して、雪のように白くしました。白い布は染めやすく、ゆかたや手ぬぐい、肌着など、いろいろな用途に向いていました。","最盛期の江戸時代後期には、年に数十万反もの真岡木綿が出荷されたといわれます。真岡の町には木綿問屋が軒を連ね、大きな財をなす商人も現れました。町の中心に残る «岡部記念館 金鈴荘» は、明治時代の木綿問屋・岡部家ゆかりの建物で、当時の豊かさを伝えています。","ところが明治になると、機械でつくった安い綿布や外国の綿製品が入ってきて、手織りの真岡木綿は急速に姿を消していきます。一時はまったくつくられなくなりました。","«ふるさとの布をもう一度»。昭和の終わりごろ、地元の人々が保存会をつくり、糸つむぎから手織りまでの技を復活させました。いまは真岡木綿会館で、機織りの様子を見たり、体験したりできます。一反の布に何日もかかる手仕事の音が、ふたたび町に響いています。"],"tl":[["江戸時代前期","真岡周辺で木綿づくりがさかんになる"],["江戸時代後期","«真岡木綿» が江戸で大人気になり、出荷量が最大になる"],["明治時代","機械製の綿布や輸入品におされて衰える"],["昭和前期〜戦後","生産がほぼ途絶える"],["昭和の終わりごろ","保存会ができ、手織りの真岡木綿が復興される"],["現在","真岡木綿会館で製作・展示・体験が行われる"]],"who":[["真岡の農家の女性たち","糸を紡ぎ、布を織った担い手"],["真岡の木綿問屋","布を集めて江戸へ送り、町を栄えさせた"],["岡部家","明治時代の木綿問屋。金鈴荘ゆかりの家"],["保存会の人々","途絶えた技を復活させた"]],"deep":["«真岡» は江戸で木綿の代名詞となり、ほかの産地の品まで «真岡» と呼ばれることがあったといわれます。いまでも «もおか» の名の入った綿布の呼び名が残っているのはその名残です。","最盛期の出荷量は、文化年間（19世紀初め）に年間30万反をこえたといわれますが、数字は史料によって幅があります。","真岡木綿の特徴は、細い糸で密に織った薄手で丈夫な布と、さらしによる白さとされます。染める前の «白木綿» として出荷されることが多かったのも特徴です。","岡部記念館 «金鈴荘» は、木綿問屋の岡部家ゆかりの明治時代の建物で、真岡市が公開しています。","真岡木綿は栃木県の伝統工芸品に指定されています。近くの物井には、二宮尊徳が農村の立て直しをした桜町陣屋跡（国指定史跡）もあります。"],"look":["真岡木綿会館の機織りと展示","岡部記念館 金鈴荘（木綿問屋ゆかりの建物）","SLの形をした真岡駅舎（おまけ）"],"q":["真岡木綿の白さを生んだ、布を水にさらし日に干すことをくり返す技を何という？","«さらし»。雪のように白くし、染めやすく肌ざわりのよい布にしました。"],"koji":[],"myth":"最盛期の出荷量の数字には史料によって幅がある。","img":["木綿","真岡鐵道真岡線","桜町陣屋"],"wp":"真岡市","rel":{"ev":[],"grave":[]},"ph":[["c:4/40/Oosakijinjya-haiden.jpg",1728,1152,"真岡市"],["c:6/68/CottonPlant.JPG",2100,1500,"木綿"],["c:f/ff/%E3%83%A2%E3%82%AA%E3%82%AB14%E5%BD%A2%282023%E5%B9%B48%E6%9C%88%29.jpg",3503,2633,"真岡鐵道真岡線"],["c:2/28/Ruins_of_Sakuramatchi_Jin%27ya_02.JPG",2048,1536,"桜町陣屋"]]},{"id":"09_kofukuji_kurobane","n":"大雄寺（黒羽藩主大関家の菩提寺）","yomi":"だいおうじ","cat":"墓所","rank":"B","y":1576,"era":["muromachi","azuchi","edo"],"sh":"国の重要文化財（本堂など伽藍の建物）","ad":"大田原市黒羽田町","st":"JR西那須野駅・那須塩原駅から車で約25〜30分（黒羽方面のバスあり・本数少なめ）","la":36.872,"lo":140.126,"hook":"茅ぶき屋根の本堂・禅堂・回廊がぐるりとつながる。山あいの禅寺に、藩主一族が静かに眠る。","lead":"大雄寺は、黒羽藩主・大関家の菩提寺（先祖のお墓をまつる寺）です。曹洞宗の寺で、本堂や禅堂、庫裏などが回廊でつながる茅ぶきの伽藍が残り、国の重要文化財に指定されています。境内の奥には大関家の歴代藩主の墓が並びます。","story":["那珂川を見下ろす黒羽の丘。杉木立の石段を上ると、茅ぶきの大きな屋根が見えてきます。大雄寺は、もともと室町時代に別の場所で開かれた寺で、戦国時代の1576年ごろ、この地を治めた大関高増が、黒羽城を築いたのにあわせて城の近くへ移したと伝わります。","大関氏は那須氏に仕えた «那須七騎» の一つ。戦国の終わり、豊臣秀吉・徳川家康の時代をうまく乗り切り、江戸時代には黒羽藩1万8千石ほどの大名として幕末まで続きました。小さな藩が300年近く同じ家で続くのは、なかなかむずかしいことです。","大雄寺の伽藍の面白さは、本堂を中心に、禅堂・庫裏・経蔵・鐘楼などが回廊でぐるりと結ばれていることです。なぜ回廊で囲むのか？ 禅寺では、修行の場を一つの «閉じた世界» としてまとめる考え方がありました。雨の日でも、僧たちは屋根の下を歩いて修行の場をめぐることができました。","境内の奥の墓所には、歴代の大関家藩主や一族の墓が並んでいます。なかには、学問にはげみ、藩の改革や大部の書物づくりに取り組んだ藩主・大関増業もいます。石の墓の列は、小さな藩の300年の歩みそのものです。","黒羽は、松尾芭蕉が «おくのほそ道» の旅でもっとも長く、十数日間滞在した土地でもあります。芭蕉は黒羽藩の家老の兄弟にもてなされ、近くの雲巌寺などをたずねました。静かな大雄寺の回廊を歩くと、城下町・黒羽の落ち着いた空気が感じられます。"],"tl":[["室町時代","別の地で寺が開かれたと伝わる"],["1576年ごろ","大関高増が黒羽城を築き、寺を現在地へ移したと伝わる"],["江戸時代","黒羽藩主大関家の菩提寺として栄える"],["1689年","松尾芭蕉が黒羽に十数日滞在する"],["江戸時代後期","藩主・大関増業が藩政改革や学問に力を入れる"],["平成","本堂など伽藍の建物が国の重要文化財に指定される"]],"who":[["大関高増","戦国時代の大関氏当主。黒羽城を築き、寺を移した"],["大関増業","江戸時代後期の黒羽藩主。学問好きで知られる"],["松尾芭蕉","黒羽に長く滞在した俳人"],["大関家の歴代藩主","境内の墓所に眠る"]],"deep":["大雄寺の茅ぶきの本堂・禅堂・庫裏・総門・回廊などは、江戸時代の禅宗寺院の伽藍構成をよく残すとして、まとめて国の重要文化財になっています。","«那須七騎» とは、那須氏とその有力家臣（大田原・大関・福原・芦野・伊王野・千本など）を指す呼び名です。","黒羽藩は1万8千石ほどの小藩ながら、大関氏が江戸時代を通じて藩主を務め、改易や国替えがありませんでした。","大関増業は、学問や書物の編さんに熱心で、藩の財政立て直しにも取り組みましたが、改革は家臣との対立も生み、途中で隠居しています。","芭蕉の黒羽滞在は «おくのほそ道» の旅で一か所に最も長くとどまったもので、黒羽藩の城代家老・浄法寺図書（高勝）と弟の翠桃がもてなしました。"],"look":["茅ぶき屋根の本堂と、伽藍をつなぐ回廊","杉木立の参道と総門","大関家歴代藩主の墓所","近くの黒羽城跡・芭蕉の館"],"q":["大雄寺を菩提寺とした黒羽藩主の家は？","大関家。戦国時代から幕末まで黒羽を治めました。"],"koji":[],"myth":"寺の開創年や移転の年は寺伝による。","img":["黒羽藩","大関氏","黒羽城","雲巌寺"],"wp":"大雄寺 (大田原市)","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/Daiouji-soumon.jpg",1824,1216,"大雄寺 (大田原市)"],["c:e/ef/Tozan_Unganji_Temple_02.jpg",6000,4000,"雲巌寺"]]},{"id":"09_furumine","n":"古峯神社","yomi":"ふるみねじんじゃ","cat":"寺社","rank":"B","y":1700,"era":["heian","edo","showa"],"sh":"","ad":"鹿沼市草久","st":"JR日光線・東武新鹿沼駅から «古峰ヶ原» 行きバスで約1時間、終点下車すぐ","la":36.615,"lo":139.577,"hook":"広間の壁いっぱいに、赤い顔の天狗の面。山奥の神社は «天狗の社» と呼ばれてきた。","lead":"古峯神社は、鹿沼市の山あい、古峯ヶ原にある神社です。日本武尊をまつり、天狗が神の使いとして守る社として知られます。江戸時代から «古峯講» という参拝の団体が関東各地にでき、火の用心や開運を願う人々が今も訪れます。","story":["鹿沼の町からバスにゆられて1時間。深い山の奥に、大きな鳥居と社殿が現れます。古峯神社の祭神は日本武尊。神社の伝えでは、東国を平定した日本武尊に仕えた者がこの地に移り住み、尊の霊をまつったのが始まりとされ、その子孫が代々神社を守ってきたといわれます。","この一帯の古峯ヶ原は、日光を開いた勝道上人が修行した場所とも伝わります。山で修行する山伏（修験者）たちが行き来する «行場» でもありました。やがて、山にすむ天狗が神の使いとして人々を守る、という信仰が生まれました。","なぜ天狗なのでしょう？ 天狗は山の不思議な力の化身。高い鼻と赤い顔、羽うちわを持って空を飛び、悪いものを追いはらうと信じられました。古峯神社では «天狗が火事や災いをしずめてくれる» として、特に火防（ひぶせ）の神として信仰を集めます。","江戸時代になると、関東一円の村や町に «古峯講» がつくられました。講の代表が交代で山にお参りし、火防のお札を持ち帰って村に配るのです。わらぶき屋根の家が多かった時代、火事は村全体をのみこむ恐ろしい災害でした。お札は «村を守るお守り» だったのです。","いまの古峯神社では、参拝客が泊まれる «参籠» の建物や、四季の美しい庭園 «古峯園» があり、天狗の絵が描かれた御朱印も人気です。広間に並ぶ天狗の面を見上げると、山の神を頼りにしてきた人々の気持ちが伝わってきます。"],"tl":[["古代（伝）","日本武尊に仕えた者がこの地で尊をまつったと伝わる"],["奈良〜平安時代（伝）","勝道上人が古峯ヶ原で修行したと伝わる"],["江戸時代","関東各地に «古峯講» ができ、火防の信仰が広まる"],["昭和","庭園 «古峯園» がつくられる"],["現在","天狗の御朱印や庭園で多くの参拝客が訪れる"]],"who":[["日本武尊","まつられる神"],["勝道上人","古峯ヶ原で修行したと伝わる日光の開山"],["古峯講の人々","各地の村から参拝し、火防のお札を持ち帰った"],["代々の宮司家","社を守り続けてきた家"]],"deep":["古峯神社の天狗は «神の使い» として位置づけられ、境内には参拝者が奉納した大小の天狗面が数多く掲げられています。","«講» は、同じ信仰を持つ人々がお金を出し合い、代表者が交代で遠くの社寺にお参りする仕組み。伊勢講・富士講・大山講などと同じく、江戸時代の庶民の信仰と旅を支えました。","古峯ヶ原は日光修験の «前日光» の修行の場とされ、日光の山岳信仰と深く結びついています。","古峯神社のお札は «火防» のほかにも、農作物を荒らす害虫や獣を防ぐ «虫除け» などとして受けられてきたといわれます。","神社の起源や祭神にまつわる話は神社の伝えによるもので、史料で確かめられる時期ははっきりしません。"],"look":["大鳥居と、山を背にした社殿","広間に掲げられた天狗の面","庭園 «古峯園»（入園は有料）","天狗が描かれた御朱印"],"q":["古峯神社で神の使いとされる、山にすむといわれる存在は？","天狗。火事や災いをしずめてくれるとして信仰されてきました。"],"koji":[],"myth":"創建や勝道上人の修行、天狗の話は神社の伝え・伝承。","img":["天狗","日本武尊","勝道","鹿沼市"],"wp":"古峯神社","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/%E5%8F%A4%E5%B3%AF%E7%A5%9E%E7%A4%BE_-_panoramio.jpg",3072,2048,"古峯神社"],["c:5/51/YoshitoshiGrabTenguNose.jpg",677,900,"天狗"],["c:3/3e/Yamato_Takeru%28bronze_statue%2COsaka%2901.jpg",768,1024,"日本武尊"],["c:2/2f/Japan-_Nikko_Statue_of_Sh%C5%8Dd%C5%8D_Sh%C5%8Dnin_2008.jpg",1200,850,"勝道"],["c:7/78/Kanumaimamiyayatai.jpg",3264,4928,"鹿沼市"]]},{"id":"09_karasuyama_washi","n":"烏山和紙（程村紙）","yomi":"からすやまわし（ほどむらし）","cat":"産業","rank":"B","y":1600,"era":["nara","edo","showa"],"sh":"","ad":"那須烏山市中央（烏山和紙会館ほか）","st":"JR烏山線烏山駅から歩いて約10分","la":36.652,"lo":140.152,"hook":"卒業証書にも使われる、ふっくら厚い和紙。原料の «那須楮» は日本一ともいわれた。","lead":"烏山和紙は、那須烏山市でつくられてきた和紙です。なかでも «程村紙（ほどむらし）» は厚くて丈夫な紙で、昔から大事な書類や記録に使われてきました。原料の那須楮（なすこうぞ）は質がよいことで知られ、全国の紙の産地にも送られています。","story":["那珂川と山にかこまれた烏山。冬の冷たい川の水で、楮（こうぞ）の皮をさらす光景は、昔からこの土地の冬の風物詩でした。和紙の原料・楮は、クワのなかまの木。その皮の内側の白い繊維をほぐし、水にとかして簀（す）ですくい、一枚一枚紙にしていきます。","烏山の和紙づくりの始まりは古く、奈良時代にさかのぼるという説もあります。江戸時代には烏山藩の保護を受け、藩の大切な産業になりました。なかでも厚手で質のよい «程村紙» は、村の名にちなんだ名前といわれ、江戸でも高く評価されました。","なぜ烏山の紙はよかったのでしょう？ その秘密が «那須楮» です。那須地方の楮は繊維が長く、つやがあり、強くて美しい紙ができます。岐阜の美濃和紙のような名産地でも、那須楮が原料として使われてきたほどです。","程村紙は厚くて丈夫なので、大切な証書や記録、選挙の投票用紙などに使われたこともあると伝わります。いまでも卒業証書の紙として使う学校があり、«一生残る紙» として選ばれています。","明治以降、洋紙におされて紙すきの家は大きく減りましたが、烏山では工房が伝統を受けつぎ、烏山和紙会館で紙の展示や販売が行われています。紙すきを見学できる工房もあり、冷たい水の中で手を動かす職人の姿から、一枚の紙の重みが伝わってきます。"],"tl":[["奈良時代（説）","このころから紙すきが行われたという説がある"],["江戸時代","烏山藩の保護を受け、程村紙が名産になる"],["明治以降","洋紙の広まりで紙すきの家が減る"],["昭和","程村紙の技が国の «記録作成等の措置を講ずべき無形文化財» に選ばれる"],["現在","烏山和紙会館や工房で伝統がつづく"]],"who":[["烏山藩","江戸時代、和紙づくりを保護した"],["紙すき職人たち","冬の冷たい水で紙をすき、技をつないできた"],["那須の楮農家","良質な原料・那須楮を育ててきた"]],"deep":["程村紙は、那須楮を原料とした厚手の生漉き（きずき）和紙で、その製作技術は国の «記録作成等の措置を講ずべき無形文化財» に選択されています。","那須楮は茨城県の大子町周辺を含む那須地方の楮の総称で、ユネスコ無形文化遺産 «和紙» に含まれる本美濃紙などでも原料として使われてきました。","楮は毎年冬に刈り取り、蒸して皮をはぎ、表皮を削って «白皮» にします。その後煮て、ちりを取り、たたいて繊維をほぐす——紙になるまで多くの手間がかかります。","和紙の繊維は長く、からみ合っているため、洋紙より破れにくく、何百年も保存できます。証書や公文書、文化財の修理に和紙が使われる理由です。","烏山は江戸時代に烏山藩の城下町で、烏山城は那珂川を見下ろす山城でした。"],"look":["烏山和紙会館（和紙の展示と販売）","紙すき工房（見学は事前に確認）","冬の紙すきの時期","近くの烏山城跡"],"q":["程村紙の原料として知られる、那須地方の良質な木は？","那須楮（なすこうぞ）。繊維が長く、強くて美しい紙になります。"],"koji":[],"myth":"起源を奈良時代とする説は伝承的なもの。«程村» の名の由来も諸説。","img":["和紙","コウゾ","烏山城","那須烏山市"],"wp":"程村紙","rel":{"ev":[],"grave":[]},"ph":[["c:a/a7/Chiyogami.JPG",1384,1412,"和紙"],["c:f/f0/W_kouzo4061.jpg",800,600,"コウゾ"],["c:1/1d/Ruins_of_Karasuyama_Castle.JPG",2048,1536,"烏山城"],["c:f/ff/2014_Yamaage_Matsuri_04.JPG",2048,1536,"那須烏山市"]]},{"id":"09_nikko_bugyo","n":"日光奉行所跡","yomi":"にっこうぶぎょうしょあと","cat":"大名屋敷","rank":"B","y":1700,"era":["edo","meiji"],"sh":"","ad":"日光市（日光市街地内）","st":"東武日光駅・JR日光駅から歩いて約20分","la":36.751,"lo":139.6,"hook":"東照宮を守り、日光の町を治めた幕府の出先機関。その建物はもう残っていない。","lead":"日光奉行は、江戸幕府が1700年に置いた役職で、日光東照宮などの社寺の警備や修理、日光の町の支配を受け持ちました。奉行所は日光の町に置かれ、幕末まで続きました。いまは建物が残らない «跡» です。","story":["家康をまつる東照宮、家光の眠る大猷院——日光は幕府にとって特別な聖地でした。17世紀の終わり、5代将軍綱吉の時代の1700年、幕府は «日光奉行» という役職をつくります。それまでも日光には幕府の役人がいましたが、なぜわざわざ奉行を置いたのでしょう？ 社寺の数がふえ、建物の修理や警備、参拝客のお世話、町の治安と、仕事がどんどん大きくなっていたからです。","日光奉行は定員2人で、1人が日光に、もう1人が江戸にいて、交代で勤めたといわれます。日光の奉行所では、社寺の修理の監督、火の用心の見回り、町人の争いごとの裁き、年貢の取り立てなどを行いました。","とくに大事だったのが火事の用心です。木でできた社殿は、一度燃えればとり返しがつきません。奉行所の役人は、日光の山内を見回り、火の元に目を光らせました。将軍の日光社参のときには、準備と警備の中心になりました。","1868年、戊辰戦争で幕府が倒れると、日光奉行は姿を消します。新政府は日光に «日光県» を置き、奉行所の建物が県庁として使われたといわれます。けれど日光県はわずか数年で宇都宮県などに合わされ、やがて建物もなくなりました。","いま、奉行所の跡には当時の建物は残っていません。けれど、日光の町のつくりや、社寺を守るための火の見の習慣、山内と町を分ける考え方には、奉行所が治めた時代のなごりが感じられます。"],"tl":[["1617年","家康が日光にまつられる"],["1700年","幕府が日光奉行を置く"],["江戸時代","奉行所が社寺の修理・警備、町の支配を担う"],["1868年","幕府が倒れ、日光奉行がなくなる。日光県が置かれる"],["1871年","日光県が廃止され、宇都宮県に合わされる"],["現在","建物は残らず、跡地として伝わる"]],"who":[["徳川綱吉","日光奉行を置いた5代将軍"],["歴代の日光奉行","旗本から任じられ、日光の社寺と町を守った"],["日光の町人","奉行所の支配のもとで門前町を営んだ"]],"deep":["日光奉行は遠国奉行の一つで、老中の支配下に置かれました。長崎奉行・京都町奉行などと同じく、幕府の «出先機関» の長です。","日光奉行が置かれる前は、日光目代や日光山の僧侶組織（輪王寺門跡のもと）が日光の管理に大きな役割を果たしていました。奉行の設置で幕府の直接の管理が強まりました。","日光奉行の仕事の中心は東照宮などの修理と警備。江戸時代を通じて東照宮の «修復» は何度も行われ、奉行所がその監督にあたりました。","明治元年に置かれた日光県は、日光奉行の支配地などを引きついだ県で、1871年の廃藩置県後の統合で宇都宮県に合わされました。","奉行所があった正確な場所や建物の配置は、残された絵図などから考えられていますが、跡地に大きな遺構は残っていません。"],"look":["日光市街地に残る跡地の案内（あれば）","神橋から東照宮へ向かう道と、町と山内の境目","日光の火の見の文化を伝える町並み"],"q":["日光奉行が置かれたのは何代将軍の時代？","5代将軍・徳川綱吉の時代（1700年）です。"],"koji":[],"myth":"奉行所の建物が日光県の県庁になったとする話や跡地の正確な位置は、資料によって書き方に差がある。","img":["日光東照宮","日光県","徳川綱吉"],"wp":"日光奉行","rel":{"ev":["k_nikko"],"grave":[]},"ph":[["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"],["c:d/d9/Tsunyaoshi.jpg",1655,1500,"徳川綱吉"]]},{"id":"09_aoki_bettei","n":"旧青木家那須別邸","yomi":"きゅうあおきけなすべってい","cat":"近代","rank":"B","y":1888,"era":["meiji"],"sh":"国の重要文化財","ad":"那須塩原市青木（道の駅 明治の森・黒磯）","st":"JR黒磯駅から車で約15分","la":36.957,"lo":140.048,"hook":"那須の原野に建った、白と緑のドイツ風の館。外務大臣・青木周蔵の «夢の農場» の家。","lead":"旧青木家那須別邸は、明治時代の外交官・青木周蔵が那須野が原の農場に建てた別荘です。1888年に建てられ、ドイツで建築を学んだ松ヶ崎萬長が設計しました。左右対称の美しい洋館で、国の重要文化財に指定されています。","story":["明治のはじめ、那須野が原は水の少ない荒れ野でした。政府は開拓を進め、那須疏水をひいて水を通し、有力な政治家や華族が大きな農場をひらきました。その一人が、長州出身の外交官・青木周蔵です。","青木は若いころドイツに留学し、ドイツの貴族の娘エリザベートと結婚しました。ドイツ公使を長くつとめ、のちに外務大臣として条約改正の交渉にあたります。そんな青木が那須で夢見たのは、ドイツ風の農場経営。«日本にも、森と牧場のある豊かな農村を» ——そう考えたのかもしれません。","1888年、農場の中に建てられたのがこの別邸です。設計したのは、青木と同じくドイツで学んだ建築家・松ヶ崎萬長。正面の中央に塔のような部分を置き、左右に同じ形の翼をのばした、きっちりとした左右対称の建物です。外壁には鱗のようなスレート（石の板）がはられ、白い窓枠が映えます。","青木は外交の仕事の合間にこの館を訪れ、家族と過ごしました。なぜ東京から遠い那須に？ 当時、東北本線が通ったことで那須は東京から汽車で行ける土地になり、広い土地で新しい農業を試せる場所でもあったのです。","館はその後、増築や移り変わりを経て、平成のはじめに解体修理され、いまの «道の駅 明治の森・黒磯» の地に復元されました。内部も公開され、明治の外交官の暮らしや那須野が原開拓の歴史を伝えています。"],"tl":[["1880年代","那須疏水が開かれ、那須野が原に華族や政治家の農場ができる"],["1881年ごろ","青木周蔵が那須に農場をひらく"],["1888年","別邸が建てられる（設計・松ヶ崎萬長）"],["1889年","青木周蔵が外務大臣になる"],["1990年代","解体修理され、道の駅の敷地に移築・復元される"],["1999年","国の重要文化財に指定"]],"who":[["青木周蔵","外交官・外務大臣。別邸の持ち主"],["エリザベート","周蔵の妻。ドイツの貴族の出"],["松ヶ崎萬長","ドイツで学んだ建築家。別邸を設計"],["三島通庸","栃木県令。那須野が原の開拓を進めた"]],"deep":["松ヶ崎萬長は公家出身で、ドイツで建築を学んだ明治の建築家。現存する作品が少なく、この別邸は貴重な例とされます。","外壁のうろこ状のスレート張りや、左右対称で中央を強調する構成に、ドイツ建築の影響が見られるといわれます。","那須疏水は1885年に本幹が通水した大きな用水路で、那須野が原の開拓を支えました。安積疏水・琵琶湖疏水と並ぶ «日本三大疏水» の一つとされます。","青木周蔵は外務大臣として条約改正交渉にあたりましたが、1891年の大津事件で辞任しています。のちに再び外務大臣をつとめ、1894年の日英通商航海条約の調印時には駐英公使として交渉にあたりました。","那須野が原には、大山巌・松方正義・山県有朋など明治の有力者が農場をひらき、«華族農場» と呼ばれました。"],"look":["左右対称の正面と、うろこ状の外壁","中央の塔のような部分と窓の配置","内部の展示（明治の暮らし・那須野が原開拓）","道の駅の森の中の散策路"],"q":["旧青木家那須別邸を設計した建築家はどこの国で建築を学んだ？","ドイツ。青木周蔵も長くドイツに関わった外交官でした。"],"koji":[],"myth":"","img":["青木周蔵","松ヶ崎萬長","那須疏水","那須野が原"],"wp":"旧青木家那須別邸","rel":{"ev":[],"grave":[]},"ph":[["c:5/56/Old_Aoki_Shuzo%27s_Nasu_Villa_House-20090503.JPG",2240,1488,"旧青木家那須別邸"],["c:c/ce/Aoki_Shuzo.jpg",1024,1333,"青木周蔵"],["c:2/23/Matsugasakitsumunaga.jpg",1144,1774,"松ヶ崎萬長"],["c:c/c3/Nasu-sosui_canal.jpg",800,600,"那須疏水"]]},{"id":"09_italy_taishikan","n":"イタリア大使館別荘記念公園（中禅寺湖畔）","yomi":"いたりあたいしかんべっそうきねんこうえん","cat":"近代","rank":"B","y":1928,"era":["showa","heisei"],"sh":"","ad":"日光市中宮祠","st":"東武日光駅からバスで約45分 «中禅寺温泉» 下車、歩いて約30分（または近くのバス停から）","la":36.73,"lo":139.483,"hook":"杉の皮で模様を描いた湖畔の館。外交官たちが夏を過ごした «奥日光の国際避暑地» の記憶。","lead":"イタリア大使館別荘記念公園は、中禅寺湖のほとりに1928年に建てられたイタリア大使館の夏の別荘を、栃木県が復元して公開している公園です。設計はチェコ出身の建築家アントニン・レーモンド。杉の皮を市松模様などにはった外壁が特徴です。","story":["明治の半ばから昭和のはじめにかけて、奥日光の中禅寺湖畔には、各国の大使館や外国人の別荘が次々に建てられました。夏になると、東京の蒸し暑さをのがれて外交官や家族がやってきて、湖でヨットを走らせ、社交を楽しみました。«夏は外務省が日光に移る» ——そういわれたほどだったと伝わります。","1928年、イタリア大使館の別荘として建てられたのがこの館です。設計したのは、帝国ホテルの建設でフランク・ロイド・ライトとともに来日し、そのまま日本で活躍したアントニン・レーモンド。彼は日本の伝統的な材料や技術に強い関心を持っていました。","外壁を見ると、杉の皮が市松模様や矢羽根のような模様にはられています。なぜ杉の皮？ 地元の日光でとれる素朴な材料を生かし、自然に溶けこむ建物をつくろうとしたからだといわれます。室内の天井や壁も杉皮や竹で仕上げられ、和と洋がまざり合った独特の空間です。","館は1997年までイタリア大使館の別荘として使われました。その後、栃木県が土地と建物を引きつぎ、調査をしたうえで当時の姿に復元し、2000年に公園として公開しました。湖に面した広い縁側からは、男体山と中禅寺湖が一望できます。","近くには英国大使館別荘記念公園もあり、明治の外交官アーネスト・サトウの別荘を復元したものです。二つの館を歩いてめぐると、奥日光が «国際避暑地» だった時代の空気を感じられます。冬期は閉館するので、訪れる時期に注意しましょう。"],"tl":[["明治中期","奥日光に外国人の別荘や避暑客がふえはじめる"],["1896年","アーネスト・サトウが中禅寺湖畔に別荘を建てる"],["1928年","イタリア大使館の別荘が建てられる（設計：アントニン・レーモンド）"],["1997年","大使館別荘としての使用が終わる"],["2000年","栃木県が復元し、記念公園として公開"],["2016年","近くに英国大使館別荘記念公園が開園"]],"who":[["アントニン・レーモンド","チェコ出身の建築家。別荘を設計"],["イタリア大使館の人々","夏をここで過ごした外交官や家族"],["アーネスト・サトウ","英国の外交官。近くに別荘を建てた"]],"deep":["アントニン・レーモンドは帝国ホテル建設のためにライトの助手として来日し、その後独立して日本で多くの建物を設計しました。日本の近代建築に大きな影響を与えた人物です。","外壁や内装に使われた杉皮張りは、日本の民家や茶室に見られる技法を応用したもの。レーモンドが日本の素材を積極的に取り入れた例としてよく知られます。","中禅寺湖は標高約1,270mにあり、夏でも涼しいことから外国人の避暑地として人気になりました。湖ではヨットレースも行われました。","本邸の復元にあたっては、残っていた部材や図面、写真などを調べ、できるだけ当時の材料と技法で再現したといわれます。","公園内には «国際避暑地» としての奥日光の歴史を伝える展示もあります。冬期（例年12月〜3月ごろ）は休園します。"],"look":["杉皮を模様にはった外壁","湖に面した広縁と、そこからの中禅寺湖・男体山の眺め","室内の杉皮・竹の天井","近くの英国大使館別荘記念公園"],"q":["イタリア大使館別荘を設計した建築家は？","アントニン・レーモンド。帝国ホテル建設のためライトとともに来日したチェコ出身の建築家です。"],"koji":[],"myth":"«夏は外務省が日光に移る» という言い回しは当時の様子を伝える話として語られるもの。","img":["アントニン・レーモンド","中禅寺湖","英国大使館別荘記念公園","アーネスト・サトウ"],"wp":"イタリア大使館別荘記念公園","rel":{"ev":[],"grave":[]},"ph":[["c:7/7a/170825_Italian_Embassy_Villa_Memorial_Park03s3.jpg",6000,4000,"イタリア大使館別荘記念公園"],["c:5/54/%E3%82%A2%E3%83%B3%E3%83%88%E3%83%8B%E3%83%B3%E3%83%BB%E3%83%AC%E3%83%BC%E3%83%A2%E3%83%B3%E3%83%89.jpg",337,436,"アントニン・レーモンド"],["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"中禅寺湖"],["c:9/96/Nikko_Natural_Science_Museum%2C_June_2023.jpg",4608,3456,"英国大使館別荘記念公園"],["c:0/0e/YoungSatow.jpg",607,814,"アーネスト・サトウ"]]},{"id":"09_kanmangafuchi","n":"憾満ヶ淵（化け地蔵）","yomi":"かんまんがふち（ばけじぞう）","cat":"伝承","rank":"B","y":1654,"era":["edo","meiji"],"sh":"","ad":"日光市匠町","st":"東武日光駅・JR日光駅からバスで «総合会館前» 下車、歩いて約20分","la":36.747,"lo":139.588,"hook":"川ぞいに並ぶ赤い前かけの地蔵たち。行きと帰りで数えると、なぜか数が合わないという。","lead":"憾満ヶ淵は、日光の大谷川にある渓谷です。男体山の噴火で流れ出た溶岩が川にけずられてできた岩場で、江戸時代に僧・晃海が不動明王をまつって開きました。川ぞいには «並び地蔵» と呼ばれる地蔵がずらりと並び、数えるたびに数が変わる «化け地蔵» の伝説で知られます。","story":["日光の町から少し西へ。大谷川の流れが、黒くごつごつした岩のあいだを白くしぶきをあげて走ります。この岩は、大昔に男体山が噴火したとき流れ出た溶岩が冷えて固まったもの。長い年月をかけて川がけずり、深い淵をつくりました。","1654年、天海の弟子にあたる僧・晃海が、ここに慈雲寺を建て、淵を見下ろす岩の上に不動明王をまつりました。«憾満» という名は、不動明王の真言（おまじないのような言葉）の最後の «カンマン» という響きからとったといわれます。川の音が真言を唱えているように聞こえた——そう考えると、なんだか神秘的ですね。","川ぞいの道には、赤い前かけをした石の地蔵がずらりと並んでいます。天海の弟子たちなどが寄進したもので、昔は百体ほどあったといわれ «百地蔵» とも呼ばれました。ところが、この地蔵を数えると、行きと帰りで数が合わない。何度数えても同じ数にならない——そこで «化け地蔵» と呼ばれるようになったと伝わります。","なぜ数が合わないのでしょう？ 苔むして形がくずれた地蔵もあれば、似た顔の地蔵がつづく場所もあります。うっかり一体とばしたり、二度数えたりしやすいのかもしれません。でも、昔の人は «地蔵さまが動いた» と考えたのです。","1902年の大洪水では、大谷川があふれて地蔵の一部や、中心にいた «親地蔵» が流されたといわれます。それでも残った地蔵たちは、いまも静かに川の音を聞きながら並んでいます。夏は緑、秋は紅葉が美しく、日光の社寺の喧騒からはなれた静かな散歩道です。"],"tl":[["大昔","男体山の噴火で流れ出た溶岩が川にけずられ、渓谷ができる"],["1654年","僧・晃海が慈雲寺を建て、不動明王をまつって憾満ヶ淵を開く"],["江戸時代","天海の弟子たちなどが地蔵を寄進し «並び地蔵» となる"],["1902年","大洪水で慈雲寺や地蔵の一部が流される"],["昭和","慈雲寺の本堂が再建される"],["現在","遊歩道として整備され、化け地蔵の伝説とともに親しまれる"]],"who":[["晃海","天海の弟子筋にあたる僧。憾満ヶ淵を開いた"],["天海","日光山を再興した僧。その弟子たちが地蔵を寄進したと伝わる"],["日光を訪れる旅人","地蔵を数え、«化け地蔵» の伝説を広めた"]],"deep":["«憾満（かんまん）» は、不動明王の真言 «ノウマク・サンマンダ・バザラダン・センダ・マカロシャダ・ソワタヤ・ウン・タラタ・カンマン» の結びの句に由来するとされます。表記は «含満ヶ淵» と書かれることもあります。","対岸の岩には «かんまん» の梵字が刻まれているといわれ、弘法大師が筆を投げて書いたという伝説もあります（伝承）。","並び地蔵は約70体が残るといわれます。寄進の数や当初の数については «百体» とする伝えがありますが、正確な数は伝承によって異なります。","大谷川は中禅寺湖から流れ出る川で、途中に華厳の滝があります。1902年の洪水は日光に大きな被害を出しました。","地蔵は数がはっきりしないことから «化け地蔵»、ずらりと並ぶことから «並び地蔵» と、二つの呼び名があります。"],"look":["溶岩の岩場を流れる大谷川の淵","ずらりと並ぶ地蔵（数えてみよう）","不動明王をまつった岩の上の «霊庇閣»（あずまや）","慈雲寺と周囲の遊歩道"],"q":["憾満ヶ淵の地蔵が «化け地蔵» と呼ばれるのはなぜ？","数えるたびに数が違う、と伝わるからです。"],"koji":[],"myth":"化け地蔵の話、弘法大師の梵字の話、地蔵の当初の数は伝承。","img":["大谷川","天海","不動明王","男体山"],"wp":"憾満ヶ淵","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/250726_Kanmangafuchi_abyss_Nikko_Tochigi_pref_Japan02s3.jpg",3648,5472,"憾満ヶ淵"],["c:e/e9/Archbishop_Tenkai_statue_at_Kitain_temple.jpg",2136,2848,"天海"],["c:a/a1/Fud%C5%8D_My%C5%8D%C5%8D.jpg",3433,5046,"不動明王"],["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"男体山"]]},{"id":"09_kenchobori","n":"県庁堀（栃木町に県庁があった時代）","yomi":"けんちょうぼり","cat":"近代","rank":"B","y":1873,"era":["meiji","taisho"],"sh":"栃木市指定史跡","ad":"栃木市入舟町","st":"JR両毛線・東武栃木駅から歩いて約20分","la":36.393,"lo":139.728,"hook":"「栃木県」なのに県庁はなぜ宇都宮？ その答えは、町の北に残る四角い堀にある。","lead":"県庁堀は、明治のはじめ、栃木町に置かれた栃木県庁をぐるりと囲んでいた堀です。県庁は1884年に宇都宮へ移りましたが、堀はいまも水をたたえて残っています。«栃木県» という県名が、この町の名前から生まれたことを物語る場所です。","story":["1871年、廃藩置県で全国の藩が県に変わりました。いまの栃木県のあたりには、はじめ «栃木県» と «宇都宮県» の二つが置かれます。栃木県の県庁が置かれたのが、巴波川（うずまがわ）の舟運でにぎわう商人の町・栃木町でした。","1873年、宇都宮県が栃木県に合わされ、ほぼいまの県の形ができあがります。栃木町には新しい県庁の建物がつくられ、そのまわりに四角く堀がめぐらされました。なぜ堀を？ 火事から役所を守るため、そして «ここが県の中心だ» という威厳を示すためだったともいわれます。堀の水は巴波川から引かれました。","ところが1884年、県令（いまの知事にあたる）三島通庸によって、県庁は宇都宮へ移されます。宇都宮のほうが県の中央に近く、鉄道も通る予定だったことなどが理由とされます。栃木町の人々は反対しましたが、決定はくつがえりませんでした。","こうして «県の名前の町» と «県庁のある町» がちがう、いまの形になったのです。県名が «宇都宮県» にならなかったのは、県庁が移ったあとも名前はそのまま残されたから。栃木市の人は、いまも «県名のふるさと» であることを誇りにしています。","県庁の跡には、大正時代に建てられた栃木町役場の洋風の建物が残り、堀にはこいが泳ぎ、春には桜が水面を彩ります。蔵の街・栃木の散歩の途中で、堀をひとまわりしてみると、明治の «県庁所在地» の広さを実感できます。"],"tl":[["1871年","廃藩置県。栃木県が置かれ、栃木町に県庁が置かれる"],["1873年","宇都宮県が栃木県に合わされる"],["1870年代","県庁の建物と周りの堀が整えられる"],["1884年","県令・三島通庸により県庁が宇都宮へ移る"],["1921年","県庁跡に栃木町役場の庁舎が建つ"],["現在","堀が残り、市指定史跡として保存されている"]],"who":[["三島通庸","栃木県令。県庁を宇都宮へ移した"],["鍋島貞幹","初期の栃木県の県令"],["栃木町の人々","県庁移転に反対したが、町は商都として続いた"]],"deep":["«栃木» の地名の由来には、神明宮の千木（ちぎ）が十本に見えた «十千木» 説、トチノキが多かった説など諸説があります。","三島通庸は山形・福島でも県令として道路づくりを強引に進めたことで知られます。栃木では県庁移転と道路整備を進めましたが、自由民権派とも激しく対立しました。","1884年は、栃木・茨城の自由民権派による加波山事件が起こった年でもあり、三島県令の政策はその背景の一つとされます。","県庁堀の水は巴波川から引かれ、堀の一部は今も石垣と水面が残っています。県庁の建物自体は残っていません。","県庁跡に建てられた旧栃木町役場庁舎は大正時代の洋風建築で、栃木市役所別館として使われてきました。"],"look":["県庁堀の水面と石垣","堀にかかる橋と桜並木","旧栃木町役場庁舎（大正時代の洋風建築）","巴波川沿いの蔵の街並み"],"q":["栃木県の県庁が栃木町から宇都宮へ移ったのは何年？","1884年（明治17年）。県令・三島通庸のもとで移されました。"],"koji":[],"myth":"«栃木» の地名の由来には諸説ある。","img":["三島通庸","巴波川","栃木市"],"wp":"栃木県庁","rel":{"ev":[],"grave":[]},"ph":[["c:f/f9/Tochigi_prefectural_office_ac.JPG",2721,3453,"栃木県庁"],["c:2/23/Mishima_Michitsune.jpg",822,1160,"三島通庸"],["c:9/9e/%E6%A0%83%E6%9C%A8%E5%B8%82%E4%B8%AD%E5%BF%83%E9%83%A8%E3%82%92%E6%B5%81%E3%82%8C%E3%82%8B%E5%B7%B4%E6%B3%A2%E5%B7%9D.JPG",1632,1224,"巴波川"],["c:f/fb/Tochigi_City_Montage.jpg",3072,4096,"栃木市"]]},{"id":"09_renga_gama","n":"旧下野煉化製造会社煉瓦窯","yomi":"きゅうしもつけれんがせいぞうがいしゃれんががま","cat":"産業","rank":"B","y":1890,"era":["meiji","taisho","showa"],"sh":"国の重要文化財","ad":"下都賀郡野木町野木","st":"JR宇都宮線古河駅から車で約10分（野木駅から歩いて約30分）","la":36.227,"lo":139.725,"hook":"十六の部屋をぐるぐる火が回る。明治の «れんが工場» の巨大な窯が、ほぼ当時の姿で残る。","lead":"旧下野煉化製造会社煉瓦窯は、野木町に残る明治時代のれんが焼きの窯です。«ホフマン式輪窯» という、休まずにれんがを焼き続けられる仕組みの窯で、1890年に築かれ、昭和の半ばまで使われました。国の重要文化財に指定され、中に入って見学できます。","story":["明治時代、日本は西洋に追いつこうと、れんが造りの建物や工場、鉄道の橋を次々につくりました。そのために大量のれんがが必要になります。1890年、渡良瀬川と思川にはさまれた野木の地に下野煉化製造会社がつくられ、この窯が築かれました。なぜ野木？ 近くの川べりでれんがに向いた良質な粘土がとれ、舟で東京へ運ぶのにも便利だったからだといわれます。","窯の形を上から見ると、十六角形のドーナツのよう。まわりに16の部屋（窯室）がぐるりと並び、真ん中に高い煙突がそびえます。この窯が «ホフマン式輪窯» と呼ばれるのは、ドイツのホフマンという技術者が考えた仕組みだからです。","しくみはこうです。ある部屋で火を燃やしてれんがを焼いている間に、となりの部屋では焼き上がったれんがを冷まし、別の部屋では新しいれんがを並べる。火は部屋から部屋へと順番に移っていき、窯全体をぐるぐる回り続けます。なぜこれがすごいの？ 一回ごとに火を消して冷ますむかしの窯とちがい、熱をむだにせず、一年中休まずにれんがを焼けたのです。","ここで焼かれたれんがは、東京をはじめ各地の建物や工事に使われたと考えられています。窯は形を変えながら、1971年まで使われました。","操業を終えたあと、窯は野木町が引き取り、1979年に国の重要文化財に指定されました。修理を経て公開され、いまはれんがのトンネルのような窯の中を歩くことができます。すすで黒ずんだ壁に手をあてると、80年以上燃え続けた火のぬくもりが想像できます。"],"tl":[["1888年","下野煉化製造会社が設立される"],["1890年","ホフマン式輪窯が築かれ、生産が始まる"],["明治〜昭和","れんがを焼き続け、各地へ出荷する"],["1971年","れんがの生産を終える"],["1979年","国の重要文化財に指定される"],["平成","保存修理を経て、内部が公開される"]],"who":[["フリードリッヒ・ホフマン","ドイツの技術者。輪窯の仕組みを考案した"],["下野煉化製造会社の人々","窯を築き、れんがづくりを担った"],["野木町","窯を引き取り、保存・公開している"]],"deep":["ホフマン式輪窯は19世紀半ばにドイツで考案された連続焼成窯。国内に残るものは少なく、野木のほか、埼玉県深谷市の旧日本煉瓦製造の窯（重要文化財）、京都府舞鶴市、滋賀県近江八幡市にあるものが知られています。","野木の窯は平面が十六角形で、16の窯室がつながった形をしています。円形や長円形のものが多いホフマン窯のなかで、珍しい形とされます。","最盛期の生産量は年間数百万個にのぼったといわれます。","窯は上部から燃料（石炭など）を投げ入れる投炭孔を持ち、火の位置を少しずつ移しながら焼き続けました。","周辺の渡良瀬川・思川流域は良質の粘土がとれ、明治期には北関東でれんが産業が発達しました。"],"look":["十六角形の窯の外観と中央の煙突","窯の中のアーチ型の通路（見学可）","天井の投炭孔の跡","れんがづくりの展示"],"q":["野木の煉瓦窯のように、火が部屋から部屋へ移って休まず焼き続ける窯を何という？","ホフマン式輪窯。ドイツの技術者ホフマンが考えた仕組みです。"],"koji":[],"myth":"","img":["ホフマン窯","煉瓦","野木町","日本煉瓦製造"],"wp":"旧下野煉化製造会社煉瓦窯","rel":{"ev":[],"grave":[]},"ph":[["c:5/5f/Nogi_Nogimati-rengagama_Gaikan_1.jpg",680,453,"旧下野煉化製造会社煉瓦窯"],["c:b/bc/Sumoto_Library_Sumoto_Awaji_Island_Japan08s5.jpg",4800,3200,"煉瓦"],["j:2/27/Tochigi_Nogi_Sunflower_Field_1.JPG",2592,1944,"野木町"]]},{"id":"09_dai14shidan","n":"陸軍第14師団の跡（宇都宮）","yomi":"りくぐんだいじゅうよんしだんのあと","cat":"昭和","rank":"B","y":1908,"era":["meiji","taisho","showa"],"sh":"","ad":"宇都宮市（市北部を中心とした旧軍用地一帯）","st":"JR宇都宮駅からバスで各地へ（遺構は市内に点在）","la":36.575,"lo":139.875,"hook":"宇都宮は «軍都» だった。師団の町の記憶は、道の名前や石の門柱にひっそり残る。","lead":"陸軍第14師団は、日露戦争中に編成され、1908年から宇都宮に司令部を置いた陸軍の部隊です。宇都宮には兵舎や練兵場が広がり、«軍都» と呼ばれました。多くの兵士が大陸や南方の戦場へ送られ、1944年にはパラオ諸島で激しい戦闘に加わりました。","story":["1905年、日露戦争のさなかに第14師団はつくられました。そして1908年、司令部が宇都宮に置かれます。なぜ宇都宮に？ 東京から鉄道で近く、北関東の兵士を集めやすい場所だったからです。広い土地に兵舎や練兵場、病院、倉庫が次々に建てられ、宇都宮の町の姿は大きく変わりました。","師団が来ると、町にはたくさんの兵隊と、その家族や商人が集まりました。兵営へ向かう道はまっすぐ整えられ、商店がならび、町はにぎわいます。宇都宮は «軍都» と呼ばれるようになりました。いっぽうで、町の暮らしは戦争と深く結びついていきます。","第14師団は、シベリア出兵や満州事変など、たびたび大陸へ送られました。1930年代の終わりからは中国大陸での戦いに加わり、やがて満州に置かれるようになります。故郷を遠く離れて戦い、命を落とした人も少なくありませんでした。","1944年、師団は南太平洋のパラオ諸島へ移されました。そこでアメリカ軍との間で、ペリリュー島・アンガウル島の激しい戦いが起こります。守備についた多くの兵士が亡くなりました。ペリリューでは、戦いが終わったことを知らずに、戦後まで洞窟にひそんでいた兵士たちもいました。","1945年7月には宇都宮も空襲を受け、町の多くが焼けました。戦後、軍の土地は学校や住宅、公園などに生まれ変わり、師団の建物はほとんど残っていません。それでも市内には、門柱や記念碑、慰霊碑が点々と残ります。ここから送り出された人々と、戦いで亡くなったすべての人を思いながら、静かに歩きたい場所です。"],"tl":[["1905年","日露戦争中に第14師団が編成される"],["1908年","司令部が宇都宮に置かれる"],["大正時代","シベリア出兵に加わる"],["1930年代","満州事変以降、大陸での戦いに加わる"],["1944年","パラオ諸島へ移り、ペリリュー島・アンガウル島の戦いが起こる"],["1945年7月","宇都宮が空襲を受ける"],["1945年","終戦。師団は解体され、跡地は学校や住宅などになる"]],"who":[["師団の兵士たち","北関東などから集められ、各地の戦場へ送られた"],["宇都宮の町の人々","«軍都» の暮らしと空襲を経験した"],["ペリリュー島の守備隊","第14師団の部隊を中心に、島で戦い多くが亡くなった"]],"deep":["第14師団は日露戦争中に増設された4個師団（第13〜16師団）の一つです。","宇都宮には師団司令部のほか、歩兵連隊や騎兵・砲兵などの部隊、陸軍病院などが置かれ、市の北部から西部にかけて広い軍用地が広がっていました。","ペリリュー島の戦い（1944年9〜11月）は、日本軍が洞窟陣地にこもって長期戦を行った戦いで、日米双方に大きな犠牲が出ました。","戦後、跡地の多くは学校・官公庁・住宅地になり、陸上自衛隊の駐屯地が置かれた場所もあります。","遺構の正確な場所は資料で確かめて訪ねるのがおすすめです。慰霊碑の前では、静かに手を合わせましょう。"],"look":["市内に残る旧軍の門柱や記念碑（場所は事前に確認）","戦没者の慰霊碑","宇都宮空襲を伝える資料や碑"],"q":["第14師団が1944年に移り、激しい戦いに加わった南太平洋の諸島は？","パラオ諸島。ペリリュー島・アンガウル島で戦いがありました。"],"koji":[],"myth":"遺構の位置や旧施設の配置は資料によって記述が異なるため、訪問前に確認が必要。","img":["ペリリューの戦い","宇都宮空襲","軍都"],"wp":"第14師団 (日本軍)","rel":{"ev":[],"grave":[]},"ph":[["c:d/db/Wounded_Marine_on_Peleliu.jpg",640,480,"ペリリューの戦い"]]},{"id":"09_karagosho","n":"唐御所横穴","yomi":"からごしょよこあな","cat":"遺跡","rank":"B","y":650,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"那須郡那珂川町小口","st":"JR烏山駅または西那須野駅から車で約30分（車でないと行きにくい）","la":36.74,"lo":140.128,"hook":"崖に掘られた横穴の中は、まるで «家»。屋根の形まで岩に刻まれている。","lead":"唐御所横穴は、那珂川町の崖に掘られた古墳時代の終わりごろの横穴墓（横穴式のお墓）です。岩をくりぬいた部屋の天井や壁が、家の屋根のような形にていねいに彫られているのが特徴で、国の史跡に指定されています。","story":["那珂川ぞいの小さな崖。その岩肌に、ぽっかりと入り口が開いています。これが唐御所横穴。今から1300年以上前、古墳時代の終わりから飛鳥時代ごろに掘られたお墓だと考えられています。","横穴墓とは、山の斜面や崖に横向きに穴を掘ってつくったお墓のことです。土を盛り上げる古墳とちがい、岩をくりぬいて部屋をつくります。この地域の家族や有力者が、代々葬られたと考えられています。","唐御所横穴のすごいところは、中の部屋が «家» のように彫られていることです。天井は屋根のように傾き、棟（むね）にあたる線まで刻まれています。なぜそんな手間をかけたの？ 亡くなった人が、あの世でも家に住むように——という願いがこめられていたのかもしれません。","«唐御所» という名前は、中国（唐）のような立派な御所、という意味でつけられたといわれますが、名前の由来ははっきりしません。昔の人も、あまりに見事なつくりに «ただのお墓ではない» と感じたのでしょう。","那珂川町の周辺には、那須国造碑（国宝）、侍塚古墳、那須官衙遺跡など、古代の那須の国の歴史を伝える遺跡が集まっています。唐御所横穴は、その時代の人々のお墓づくりの技を伝える大切な史跡です。"],"tl":[["6〜7世紀ごろ","那珂川ぞいで横穴墓がつくられる"],["7世紀ごろ","唐御所横穴が掘られたと考えられる"],["700年","那須国造碑が建てられる（近くの大田原市湯津上）"],["昭和","国の史跡に指定される"],["現在","那須地域の古代史を伝える史跡として保存されている"]],"who":[["那須の古代の有力者","この地域で横穴墓をつくった人々"],["那須国造・那須直韋提","近くの那須国造碑にまつられた人物。同じ時代の那須の首長"],["古代の石工たち","岩をくりぬき、家の形を彫った人々"]],"deep":["横穴墓は6世紀後半から7世紀に東日本で多くつくられたお墓の形で、九州から広まったと考えられています。","唐御所横穴の玄室は、天井を屋根形に彫り、家の形をまねた «家形» のつくりになっている点が特に評価されています。","«唐御所» の名の由来は伝承的なもので、確かなことはわかっていません。","近くの那須国造碑は700年に建てられた日本三古碑の一つで国宝。唐御所横穴と同じ時代の那須の有力者の世界を想像する手がかりになります。","横穴墓の内部は崩れやすいため、見学は外からが基本です。現地の案内に従いましょう。","那珂川流域は、凝灰岩など掘りやすい岩の崖が多く、横穴墓がつくられやすい地形でした。同じ崖に複数の横穴が並ぶ «横穴墓群» として見つかることも多く、一族が何代にもわたって使ったと考えられています。","横穴墓からは、土器や鉄の刀、耳飾りなどの副葬品が出ることがあります。どんな品がおさめられたかは、葬られた人の身分や時代を考える大事な手がかりになります。"],"look":["崖に開いた横穴の入り口","内部の家形に彫られた天井（見学は案内に従う）","周囲の那珂川の風景","近くの那須国造碑・侍塚古墳・なす風土記の丘"],"q":["唐御所横穴の中の部屋は、どんなものの形に彫られている？","家の形。天井が屋根のように傾いて彫られています。"],"koji":[],"myth":"«唐御所» の名の由来ははっきりしない。築造年代は推定。","img":["横穴墓","那須国造碑","侍塚古墳","那珂川町"],"wp":"唐御所横穴","rel":{"ev":[],"grave":[]},"ph":[["c:5/59/Karanogosho_yokoana_kofun.jpg",960,720,"唐御所横穴"],["j:1/18/Yoshimi_Yoshimi-hyakuana_2.JPG",3264,2448,"横穴墓"],["c:3/34/Nasunokuninomiyatsukonohi-2.jpg",865,1298,"那須国造碑"],["c:c/ca/Bato_Hiroshige_Museum_2009.jpg",1024,681,"那珂川町"]]},{"id":"09_nikko_eki","n":"JR日光駅舎（大正の洋風駅舎）","yomi":"じぇいあーるにっこうえきしゃ","cat":"近代","rank":"B","y":1912,"era":["meiji","taisho"],"sh":"","ad":"日光市相生町","st":"JR日光線日光駅すぐ（東武日光駅からも歩いて約3分）","la":36.748,"lo":139.62,"hook":"白い木の壁に、ずらりと並ぶ縦長の窓。大正のはじめ、外国人を迎えるために建てられた «日光の玄関»。","lead":"JR日光駅の駅舎は、1912年に建てられた木造2階建ての洋風建築です。白い外壁と緑の屋根、左右対称の姿が美しく、2階には «ホワイトルーム» と呼ばれたかつての一等客用待合室が残ります。100年以上、日光を訪れる人々を迎えてきました。","story":["日光に鉄道がやってきたのは1890年。宇都宮から日光までの線路が開通し、東京から汽車に乗って日光へ行けるようになりました。明治の日光には、外国の外交官や旅行者も数多く訪れていました。«NIKKO» は、すでに世界に知られた観光地だったのです。","1912年、いまの駅舎が完成しました。明治が終わり大正が始まった年です。白くぬられた木の壁、縦長の窓、中央の玄関をはさんで左右に同じ形がのびる、落ち着いた洋風のデザイン。なぜこんなにおしゃれな駅舎を？ 日光は国際的な観光地。外国のお客さまにはずかしくない «日光の顔» が必要だったのです。","駅舎の2階には、かつての一等客用の待合室があります。天井からシャンデリアがさがり、白い壁の上品な部屋で «ホワイトルーム» と呼ばれてきました。身分の高い人や外国の賓客が、汽車を待つ間ここでくつろいだといわれます。","当時の日光には、皇室の田母沢御用邸もあり、皇族が夏を過ごしました。駅は、そうした特別なお客さまを迎える場所でもありました。やがて東武鉄道が日光まで線路をのばし、すぐ近くに東武日光駅ができると、二つの駅が観光客を奪いあう時代もやってきます。","いまも駅舎は大切に使われ、ホワイトルームは見学できるようになっていることもあります（公開の状況は要確認）。ホームにおりたったら、ふり返って駅舎を見上げてみてください。明治・大正の人々が見た «日光への入口» が、ほとんどそのままの姿で迎えてくれます。"],"tl":[["1890年","日本鉄道の日光線（宇都宮〜日光）が開通"],["1899年","田母沢御用邸がつくられる"],["1906年","鉄道国有化で国の路線になる"],["1912年","いまの駅舎が完成"],["1929年","東武鉄道が東武日光駅まで開業する"],["1987年","国鉄分割民営化でJR東日本の駅になる"]],"who":[["日光を訪れた外国人","外交官や旅行者。駅舎の建設の背景になった"],["皇族","田母沢御用邸へ向かう際に日光を訪れた"],["鉄道の技術者たち","洋風の駅舎を設計・建設した"]],"deep":["駅舎はネオ・ルネサンス様式の要素を取り入れた木造洋風建築とされ、明治の終わりから大正にかけての地方の洋風駅舎の代表例といわれます。","«ホワイトルーム» は旧一等待合室。一等・二等・三等と客車の等級が分かれていた時代の名残で、等級ごとに待合室が分かれていました。","日光線は日本鉄道が建設し、1906年の鉄道国有法で国有化されました。のちに東武鉄道が浅草方面から日光へ直通したことで、JRと東武の競争が長く続きました。","駅舎は関東の駅百選にも選ばれています。","設計者の名前については資料によって扱いが異なり、はっきりしない部分があります。"],"look":["左右対称の正面と白い外壁","縦長の窓とひさしの意匠","2階の旧一等待合室 «ホワイトルーム»（公開状況を確認）","すぐ近くの東武日光駅との位置関係"],"q":["JR日光駅の2階にある、かつての一等客用待合室の愛称は？","«ホワイトルーム»。白い壁とシャンデリアの上品な部屋です。"],"koji":[],"myth":"設計者についてははっきりしない部分がある。","img":["日光線","東武日光駅","田母沢御用邸"],"wp":"日光駅","rel":{"ev":[],"grave":[]},"ph":[["c:d/dd/JRE_Nikko-STA.jpg",5307,3538,"日光駅"],["c:c/c7/Nikko-Line_E131-600-TN6.jpg",3888,2592,"日光線"],["c:e/e1/Tobu_Nikko_Station%2C_ekisha.jpg",5294,3530,"東武日光駅"],["c:b/ba/Tamozawa06.jpg",568,426,"田母沢御用邸"]]},{"id":"09_kaizando","n":"開山堂（勝道上人の墓所）","yomi":"かいさんどう（しょうどうしょうにんのぼしょ）","cat":"墓所","rank":"B","y":817,"era":["nara","heian","edo"],"sh":"国の重要文化財（開山堂）","ad":"日光市山内","st":"東武日光駅・JR日光駅からバスで «西参道» または «神橋» 下車、歩いて約15〜20分","la":36.76,"lo":139.597,"hook":"日光を開いた僧の眠る場所。東照宮の華やかさの奥に、千二百年前の静かな祈りがある。","lead":"開山堂は、日光を開いた勝道上人をまつるお堂です。堂の裏には上人の墓と伝わる塔があり、勝道上人の遺骨がおさめられているといわれます。東照宮や二荒山神社のにぎわいから少し離れた、森の中の静かな場所にあります。","story":["奈良時代の終わり、下野の国に勝道という若い僧がいました。«あの山の頂に登り、仏の世界に近づきたい»。勝道が目指したのは、日光の男体山でした。けれど、その山は誰も登ったことのない神の山。けわしい岩と深い森が、人を寄せつけませんでした。","766年ごろ、勝道は大谷川を渡り、日光の地に小さな寺を建てたと伝わります。川がはげしく流れて渡れなかったとき、深沙大王という神が現れ、2匹の蛇を放って橋にしてくれた——これが神橋の «山菅の蛇橋» の伝説です。","勝道は何度も男体山に挑み、失敗をくり返しました。ついに頂上に立ったのは782年のことと伝わります。最初の挑戦から十数年。なぜそこまで？ 勝道にとって山に登ることは、ただの登山ではなく、仏の道をきわめる修行だったのです。のちに空海が、勝道の業績をたたえる文を書いたと伝わります。","勝道は817年に亡くなりました。弟子たちは上人の遺骨を、この地に葬ったといわれます。開山堂の裏手には、上人の墓と伝わる石の塔があり、近くの岩には仏の姿が刻まれた «仏岩» があります。","いまの開山堂は江戸時代に建てられたもので、国の重要文化財です。そばには «産の宮» と呼ばれる観音堂もあり、安産の信仰を集めてきました。家康がまつられるずっと前から、日光には祈りの歴史が積み重なっていた——そのことを静かに教えてくれる場所です。"],"tl":[["735年","勝道が下野国に生まれたと伝わる"],["766年ごろ","大谷川を渡り、日光に寺を建てたと伝わる（四本龍寺）"],["782年","男体山の頂上に登ったと伝わる"],["814年","空海が勝道の業績をたたえる文を書いたと伝わる"],["817年","勝道が亡くなる"],["江戸時代","いまの開山堂が建てられる"]],"who":[["勝道上人","日光を開いた奈良〜平安時代の僧"],["深沙大王","勝道のために蛇の橋をかけたと伝わる神"],["空海","勝道の事績を文章に残したと伝わる"]],"deep":["勝道の男体山登頂の話は、空海の «沙門勝道歴山水瑩玄珠碑» （«性霊集» に収録）に記されたものがもととされ、古い記録として重視されています。","開山堂の裏の «仏岩» には、勝道上人とその弟子たちの墓と伝わる石塔があります。","神橋の «山菅の蛇橋» の伝説は、神橋の起源を語る話として知られ、深沙大王をまつる祠が神橋のそばにあります。","勝道が建てたとされる四本龍寺は、のちの日光山輪王寺のもとになったと考えられています。","開山堂のそばの観音堂は «産の宮» と呼ばれ、安産を願う人々の信仰を集めてきました。","開山堂の周辺は、二荒山神社から滝尾神社へ向かう «滝尾古道» の途中にあたります。石畳の古道には古い石仏や碑が点在し、東照宮ができる前の日光山の信仰の道をしのばせます。","男体山は二荒山神社の御神体で、毎年夏には山頂の奥宮へ登る «登拝» の行事が行われます。勝道の登頂は、この山岳信仰の出発点とされています。"],"look":["森の中の開山堂","堂の裏の勝道上人の墓塔と «仏岩»","観音堂（産の宮）","近くの二荒山神社や滝尾神社への古道"],"q":["勝道上人が初めて頂上に登ったと伝わる、日光の神の山は？","男体山。何度も挑戦し、782年に登頂したと伝わります。"],"koji":[],"myth":"蛇橋の話や、墓塔が勝道の遺骨をおさめたものという話は伝承。登頂年などは古い記録による。","img":["男体山","神橋","日光山輪王寺"],"wp":"勝道","rel":{"ev":["basho"],"grave":[["ieyasu","徳川家康"],["iemitsu","徳川家光"]]},"ph":[["c:2/2f/Japan-_Nikko_Statue_of_Sh%C5%8Dd%C5%8D_Sh%C5%8Dnin_2008.jpg",1200,850,"勝道"],["c:8/8a/Mount_nantai_and_lake_chuzenji.jpg",2592,1944,"男体山"],["c:a/a2/Shinkyo_Sacred_Bridge_%2811284693104%29.jpg",4573,3049,"神橋"],["c:f/f7/JP-Nikko-Sanbutsu-do.JPG",1600,1063,"日光山輪王寺"]]},{"id":"09_jigendo","n":"慈眼堂（天海僧正の墓）","yomi":"じげんどう（てんかいそうじょうのはか）","cat":"墓所","rank":"B","y":1643,"era":["azuchi","edo"],"sh":"国の重要文化財","ad":"日光市山内","st":"東武日光駅・JR日光駅からバスで «西参道» 下車、歩いて約15分","la":36.758,"lo":139.596,"hook":"家康を «神» にした僧が、その神のそばに眠る。100歳をこえて生きたとも伝わる天海の墓所。","lead":"慈眼堂は、江戸時代のはじめに徳川家康・秀忠・家光の3代に仕えた僧・天海をまつるお堂です。天海は家康を日光にまつることを進め、日光山を大きく立て直しました。1643年に亡くなり、この地に葬られました。のちに «慈眼大師» の名を贈られています。","story":["天海は謎の多い僧です。生まれた年ははっきりせず、100歳をこえて生きたとも伝わります。若いころのことはほとんどわかっていません。けれど、晩年の天海は、徳川家康の相談役として、宗教や政治に大きな力を持っていました。","1616年、家康が亡くなると、どのように神としてまつるかで意見が分かれました。天海は «山王一実神道» という天台宗の考え方で家康をまつることを主張し、これが採用されます。家康は «東照大権現» という神の名を与えられ、翌年、日光に移されてまつられました。天海がいなければ、いまの日光東照宮はなかったかもしれません。","天海は日光山の貫主（トップ）として、荒れていた日光の寺々を立て直しました。江戸では上野に寛永寺を開き、江戸を守る «東の比叡山» としました。«なぜ上野に？» 江戸城から見て北東、鬼が出入りするといわれる «鬼門» の方角を守るためだったといわれます。","1643年、天海は江戸で亡くなりました。遺言により、日光の、家康が眠る東照宮にほど近いこの地に葬られます。5年後、朝廷から «慈眼大師» という大師号が贈られました。慈眼堂は、天海の墓所をまつるお堂です。","慈眼堂は輪王寺の境内にあり、杉木立の中にひっそりと建っています。華やかな東照宮とは対照的な、落ち着いたたたずまい。天海のそばには、のちの輪王寺門跡の墓も並んでいます。家康を神にした男は、いまも神のそばで日光を見守っているのです。"],"tl":[["16世紀前半","天海が生まれたと伝わる（生年は諸説）"],["1613年","天海が日光山の貫主となる"],["1616年","家康が亡くなる"],["1617年","家康が日光にまつられる（東照社）"],["1625年","天海が江戸・上野に寛永寺を開く"],["1643年","天海が亡くなり、日光に葬られる"],["1648年","朝廷から «慈眼大師» の号が贈られる"]],"who":[["天海","家康・秀忠・家光に仕えた天台宗の僧"],["徳川家康","天海が神としてまつることを主張した"],["徳川家光","天海を深く信頼し、日光を大きく造り替えた"]],"deep":["天海の生年は1536年とする説が有名ですが確かではなく、没年齢も100歳をこえるとする説から異なるものまであります。","«山王一実神道» は天台宗の山王信仰を基礎にした神道の考え方。家康の神号をめぐっては、«明神» を主張した金地院崇伝らと «権現» を主張した天海が対立し、天海の案が採られたとされます。","天海が監修した «寛永寺版大蔵経»（天海版）は、日本で初めての木活字による大蔵経の刊行として知られます。","慈眼堂の名をもつ天海の廟所は日光のほか、滋賀県大津市坂本にもあり、天海ゆかりの地を結んでいます。","日光の慈眼堂は拝殿・廟塔などが国の重要文化財に指定されています。"],"look":["杉木立の中の慈眼堂","天海の墓塔（廟塔）","並んで建つ輪王寺の歴代門跡の墓","近くの大猷院（家光の廟所）"],"q":["天海が亡くなったあと、朝廷から贈られた大師号は？","«慈眼大師»。これにちなんで墓所のお堂が «慈眼堂» と呼ばれます。"],"koji":[],"myth":"天海の生年や前半生は不明な点が多い。«天海は明智光秀だった» という俗説があるが、史料による裏づけはない。","img":["日光山輪王寺","寛永寺","日光東照宮"],"wp":"天海","rel":{"ev":["basho"],"grave":[["ieyasu","徳川家康"],["iemitsu","徳川家光"]]},"ph":[["c:e/e9/Archbishop_Tenkai_statue_at_Kitain_temple.jpg",2136,2848,"天海"],["c:f/f7/JP-Nikko-Sanbutsu-do.JPG",1600,1063,"日光山輪王寺"],["c:0/0d/Kaneiji_2012.JPG",2165,1500,"寛永寺"],["c:b/b5/Nikko_Toshogu_Yomeimon_Gate_2024.jpg",4080,3072,"日光東照宮"]]},{"id":"09_kamitsunushi","n":"上神主・茂原官衙遺跡","yomi":"かみこうぬし・もばらかんがいいせき","cat":"遺跡","rank":"B","y":700,"era":["asuka","nara","heian"],"sh":"国指定史跡","ad":"河内郡上三川町上神主・宇都宮市茂原町","st":"JR宇都宮線石橋駅または雀宮駅から車で約15分（車でないと行きにくい）","la":36.499,"lo":139.884,"hook":"瓦に刻まれた、千三百年前の «名前»。古代の役所の跡から、無数の人の名がよみがえった。","lead":"上神主・茂原官衙遺跡は、奈良時代ごろの下野国河内郡の役所（郡家）の跡と考えられる遺跡です。お米を納める倉（正倉）などの建物跡が見つかり、国の史跡に指定されています。人の名前を刻んだ瓦がたくさん出たことでも知られます。","story":["奈良時代、日本は «国» の下に «郡» を置いて地方を治めていました。郡には «郡家（ぐうけ）» と呼ばれる役所があり、税を集め、人々を戸籍で管理しました。上神主・茂原官衙遺跡は、下野国の «河内郡» の郡家の跡と考えられています。","発掘でわかったのは、大きな建物の柱の跡がきちんと並んでいることでした。役人が仕事をする建物（郡庁）や、税として納められた稲をしまう «正倉» がずらりと並んでいたと考えられます。いまは畑や林の中ですが、昔はここに大きな倉庫群が並ぶ «地方の中心» があったのです。","この遺跡の一番の宝物は、瓦です。出土した瓦の中に、人の名前が刻まれたものがたくさんありました。«なぜ瓦に名前を？» 瓦をつくったり寄付したりした人、あるいは瓦を納めた村の人の名前だと考えられています。役人や貴族ではない、ふつうの人々の名前が、千三百年たってよみがえったのです。","近くには、下野国の国府（国の役所）や、日本三戒壇の一つ下野薬師寺もありました。都と東北を結ぶ «東山道» もこの地域を通っていました。上神主・茂原の郡家は、そうした古代の大きなネットワークの一部として働いていたのです。","遺跡は宇都宮市と上三川町にまたがり、いまは史跡公園として一部が整備されています。広々とした空の下、柱の跡を示す標示を見ながら、倉の並ぶ古代の風景を想像してみてください。"],"tl":[["7世紀後半","このころから役所の建物がつくられはじめたと考えられる"],["8世紀","河内郡の郡家として正倉などが整えられる"],["8〜9世紀","人名が刻まれた瓦が使われる"],["9世紀ごろ","役所としての役目を終えたと考えられる"],["平成","発掘調査が進み、国の史跡に指定される"],["現在","史跡公園として一部が整備されている"]],"who":[["河内郡の役人たち","郡家で税や人々の管理を行った"],["瓦に名を刻まれた人々","瓦づくりや寄進に関わったと考えられる古代の人々"],["下野国司","国府から郡家を監督した国の役人"]],"deep":["人名文字瓦は数多く出土しており、古代の地方の人名を大量に伝える資料として全国的にも注目されています。","正倉は税として集めた稲（租）を保管した倉で、高床の倉がずらりと並ぶのが郡家の特徴です。火災に備えて建物どうしの間隔をあけて配置されました。","上神主・茂原官衙遺跡は2003年に国の史跡に指定されました。","«官衙（かんが）» は古代の役所を指す言葉です。郡家（郡衙）は国府の下で地方行政の実務を担いました。","近くの下野薬師寺は、奈良の東大寺・筑紫の観世音寺と並ぶ «天下の三戒壇» の一つ。地方の郡家と中央の仏教が同じ地域で結びついていました。"],"look":["史跡公園に示された建物跡の位置","正倉が並んでいた区域","人名文字瓦の展示（地元の資料館などで確認）","周囲に広がる平野の眺め"],"q":["上神主・茂原官衙遺跡から多く出た、珍しい瓦の特徴は？","人の名前が刻まれていること。古代の人々の名前を伝える貴重な資料です。"],"koji":[],"myth":"人名瓦の名前が誰のものか（瓦をつくった人か寄進者か）は諸説。","img":["郡衙","下野薬師寺","下野国府跡","東山道"],"wp":"上神主・茂原官衙遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Historical_Government_Buildings_Site_of_Kamikonushi_%26_Mobara_02.jpg",4608,3456,"上神主・茂原官衙遺跡"],["j:2/2c/%E4%B8%8B%E9%87%8E%E8%96%AC%E5%B8%AB%E5%AF%BA_%E5%BE%A9%E5%85%83%E5%9B%9E%E5%BB%8A.JPG",3648,2736,"下野薬師寺"]]},{"id":"09_ashikaga_orimono","n":"足利織物（足利銘仙）","yomi":"あしかがおりもの（あしかがめいせん）","cat":"産業","rank":"B","y":1930,"era":["edo","meiji","showa"],"sh":"","ad":"足利市（市内各所・織姫神社は足利市西宮町）","st":"JR両毛線足利駅・東武足利市駅から歩いて約10〜20分","la":36.34,"lo":139.448,"hook":"大正・昭和の女学生があこがれた、大胆な色と柄。«足利銘仙» は日本じゅうの町を彩った。","lead":"足利は、古くから織物の町として知られます。江戸時代には絹や綿の織物の産地として栄え、大正から昭和のはじめには、手ごろな値段で華やかな «足利銘仙» が全国で大流行しました。町を見下ろす山には、織物の神をまつる織姫神社があります。","story":["足利の周辺は、渡良瀬川の水に恵まれ、養蚕も行われた土地でした。江戸時代には絹や木綿を使った織物づくりがさかんになり、隣の桐生とともに «織物の町» として知られるようになります。","明治になると、足利の織物は外国への輸出品にもなりました。織物の工場が町にたくさん建ち、機（はた）の音が町じゅうに響いたといわれます。そして大正時代、足利から全国を席巻する大ヒット商品が生まれました。それが «銘仙» です。","銘仙は、丈夫でふだん着にぴったりの絹織物。足利銘仙の人気のひみつは、大胆な柄と鮮やかな色でした。«ほぐし織» という技法で、先に糸に模様を染めてから織るので、柄の輪郭が少しにじんだような独特の味わいになります。«なぜそんなに流行したの？» 絹なのに値段が手ごろで、モダンなデザインが大正ロマンの時代の空気にぴったりだったからです。","女学生や働く女性たちは、バラや幾何学模様の銘仙を着て町を歩きました。足利銘仙は昭和のはじめにかけて全国でも指折りの生産量をほこり、ポスターなどの宣伝にも力を入れたといわれます。","戦後、洋服の時代になると銘仙はしだいに姿を消しました。それでも足利の町には、古い織物工場ののこぎり屋根や、織姫神社の朱色の社殿が残ります。織姫神社は «縁結び» の神としても人気で、夜には社殿がライトアップされ、織物の町の歴史を今に伝えています。"],"tl":[["江戸時代","絹・木綿の織物の産地として栄える"],["明治時代","織物が輸出品となり、工場が増える"],["1937年","織姫神社の現在の社殿が建てられる"],["大正〜昭和初期","足利銘仙が全国で大流行する"],["戦後","洋装化で銘仙の生産が減る"],["現在","銘仙の再評価が進み、展示やイベントが行われる"]],"who":[["足利の織物職人たち","銘仙などの織物をつくった"],["大正・昭和の女性たち","銘仙を着て流行をつくった"],["織物商人","製品を全国に売り広めた"]],"deep":["«ほぐし織（解し織）» は、たて糸を仮に織って模様を型染めし、その仮のよこ糸をほぐしながら本織りする技法。柄の輪郭がかすれたような独特の風合いになります。","銘仙は伊勢崎・秩父・足利・桐生・八王子などが産地として知られ、«五大銘仙» と呼ばれることがあります。","足利織物の起源は古く、奈良時代には足利から «絁（あしぎぬ）» が納められていたともいわれますが、確かな史料との対応には注意が必要です。","足利市内には、のこぎり屋根の旧織物工場がいくつも残り、屋根の北向きの窓から安定した光を取り入れて作業した工夫がうかがえます。","織姫神社は機織りの神をまつる神社で、市街地を見下ろす山の中腹にあります。"],"look":["織姫神社の朱色の社殿と、市街地の眺め","市内ののこぎり屋根の旧織物工場","銘仙の展示（開催時期を確認）","近くの足利学校・鑁阿寺"],"q":["足利銘仙で使われた、先に糸に模様を染めてから織る技法を何という？","«ほぐし織（解し織）»。柄の輪郭がにじんだような味わいになります。"],"koji":[],"myth":"足利織物の起源を奈良時代とする話は伝承的。銘仙の生産量の順位は資料によって異なる。","img":["足利織姫神社","足利学校","鑁阿寺"],"wp":"銘仙","rel":{"ev":[],"grave":[]},"ph":[["c:b/b8/Khalili_Collection_of_Kimono_K034.jpg",2500,3066,"銘仙"],["c:6/65/Ashikaga_Orihime-jinja%2C_Worship_Hall_and_Main_Sanctuary_001.jpg",3264,2448,"足利織姫神社"],["c:e/e8/Ashikaga_Ashikaga-School_School_Gate_2.JPG",3160,2394,"足利学校"],["c:8/8e/%E9%91%81%E9%98%BF%E5%AF%BA_%E8%B6%B3%E5%88%A9_-_panoramio_%283%29.jpg",4912,3264,"鑁阿寺"]]}];
